VALUES (1, 53, 'SPY×FAMILY Season 3',
        'animations/1/images/f0f3c969-6701-40f8-b545-0585de366dc2.webp',
        '人はみな　誰にも見せぬ自分を　持っている―― 世界各国が水面下で熾烈な情報戦を繰り広げていた時代。 東国（オスタニア）と西国（ウェスタリス）は、十数年間にわたる冷戦状態にあった。 西国の情報局対東課〈WISE（ワイズ）〉所属である凄腕スパイの〈黄昏（たそがれ）〉は、 東西平和を脅かす危険人物、東国の国家統一党総裁ドノバン・デズモンドの動向を探るため、 ある極秘任務を課せられる。 その名も、オペレーション〈梟（ストリクス）〉。 内容は、“一週間以内に家族を作り、デズモンドの息子が通う名門校の懇親会に潜入せよ”。 〈黄昏（たそがれ）〉は、精神科医ロイド・フォージャーに扮し、家族を作ることに。 だが、彼が出会った娘・アーニャは心を読むことができる超能力者、妻・ヨルは殺し屋だった！ 3人の利害が一致したことで、お互いの正体を隠しながら共に暮らすこととなる。 ハプニング連続の仮初めの家族に、世界の平和は託された――。',
        4, 0, 0, 0, '2025-10-04'),
       (2, 32, '僕のヒーローアカデミア FINAL SEASON',
        'animations/2/images/1cb83f0d-c666-42fc-be8e-147721b09ef8.webp',
        '原作：堀越耕平（集英社 ジャンプ コミックス刊）。超常能力“個性”が当たり前の世界で、“無個性”の少年・緑谷出久“デク”は“平和の象徴”オールマイトに内なるヒーローの資質を見出され、“個性”ワン・フォー・オールを継承する。人々を笑顔で救ける“最高のヒーロー”を目指し、デクはクラスメイトたちと成長していく。 ヒーローと敵＜ヴィラン＞は最終決戦に突入。日本各地で死闘が繰り広げられる中、ワン・フォー・オールを全開にしたデクと、史上最凶の敵＜ヴィラン＞となった死柄木弔の戦いが遂に決着へ！果たして、デクの「僕たちが最高のヒーローになるまでの物語」はフィナーレで成し得るのか…！？ヒロアカ、いよいよ最終章！',
        8, 0, 0, 0, '2025-10-04'),
       (3, 38, 'とんでもスキルで異世界放浪メシ2',
        'animations/3/images/8d8e9d42-12f8-4ae9-8465-4988cb8f5ee0.webp',
        'ある日突然異世界へと召喚された 普通のサラリーマン、向田剛志。 彼は固有スキル『ネットスーパー』で 取り寄せた現代の調味料で料理を作って食べて、 伝説の魔獣フェル・スライムのスイとともに 異世界生活を堪能していた。 新たな仲間も加わり、 美味しい旅が再び始まる！！',
        2, 0, 0, 0, '2025-10-07'),
       (4, 191, 'グノーシア', 'animations/4/images/dff518d9-57b2-4ee4-b7d7-573d07637ad7.webp',
        '物語の舞台は漂流する宇宙船。 “人間に化けて人間を襲う未知の敵”─── 「グノーシア」が船内に紛れこんだことを受けて、 乗員たちは疑心暗鬼の中、毎日1人ずつ疑わしい者を投票で選び、コールドスリープさせることを決める。 グノーシアを全てコールドスリープさせることができれば人間の勝利。 逆にグノーシアを当てられなければ、乗員たちは襲われてしまう。 正しい選択が求められる中、なんと主人公・ユーリは、 どのような選択をしても、最初の1日目にループする事態に。 はたして乗員たちは正しい選択をすることができるのか？ タイムリープに隠された秘密とは？ そして明らかになる、乗員たちの隠された素顔とは──？ わずかな時間を繰りかえす、一瞬にして永遠のような物語が、いま、幕を開ける。 ──それでは、良い旅を。',
        NULL, 0, 0, 0, '2025-10-11'),
       (5, 17, 'ワンパンマン 第3期',
        'animations/5/images/0cfe0012-4af2-476d-bf55-c05ac7e4ff76.webp',
        '趣味でヒーローを始めた男、サイタマ。3年間の特訓により無敵のパワーを手に入れ、あらゆる敵を一撃（ワンパン）で倒すヒーローである。ひょんなことから弟子となったジェノスと共にヒーロー協会で正式なヒーロー活動を開始する。\n突如現れた怪人協会に幹部の子供を人質に取られてしまったヒーロー協会。S級ヒーロー達が集まり、人質奪還のために怪人協会のアジトへの突入作戦が練られる。一方、人間怪人ガロウは怪人協会のアジトで目を覚ます。',
        3, 0, 0, 0, '2025-10-05'),
       (6, 38, 'チェンソーマン 総集篇',
        'animations/6/images/4777faea-e79a-47f5-a79f-2250596bf5d9.webp',
        '「チェンソーの悪魔」ポチタと共にデビルハンターとして暮らす少年デンジ。 親が遺した借金返済のため、貧乏な生活を送る中、裏切りに遭い殺されてしまう。薄れる意識の中、デンジはポチタと契約し、悪魔の心臓 を持つもの 「 チェンソーマン 」として蘇る。',
        NULL, 0, 0, 0, '2025-09-05'),
       (7, 29, '最後にひとつだけお願いしてもよろしいでしょうか',
        'animations/7/images/28cd9fb3-312f-4f89-91ea-76c60ba10e4b.webp',
        '舞踏会での婚約破棄。 それはよくある“悪役令嬢”への断罪シーンとなるはずでした ―― 舞踏会の最中、婚約をしていた第二王子・カイルから、 いきなり理不尽な婚約破棄を告げられた公爵令嬢・スカーレット。 さらには“新しい婚約者”がいると告げられ、ありもしない罪まで着せられてしまう。 幼少期から続いていたカイルの数々の嫌がらせにも “婚約者”ということで耐え続けてきたが、ついに我慢の限界を迎えてしまい… 「私の最後のお願いです。 このクソアマをブッ飛ばしてもよろしいですか？」 見目麗しき公爵令嬢スカーレットが“拳”を握り、舞い踊る！！ シリーズ累計200万部突破の人気作がTVアニメ化！ 武闘派令嬢のスカッと痛快ファンタジー、ここに開幕！',
        NULL, 0, 0, 0, '2025-10-03'),
       (8, 48, '藤本タツキ17-26', 'animations/8/images/d2ae1d29-b55f-4397-a688-f0aa86400a51.webp',
        '『チェンソーマン』を生んだ藤本タツキが17歳から26歳までに描いた短編8作品が、6つのスタジオと7名の監督により待望のアニメ化。漫画賞初投稿作『庭には二羽ニワトリがいた。』から、『予言のナユタ』『妹の姉』まで、思春期の恋、暴走、狂気、絆を描いた多彩な物語が、今鮮やかに映像となって動き出す。\n11月8日(土)よりプライムビデオで世界独占配信中',
        NULL, 0, 0, 0, '2025-11-08'),
       (9, 26, '素材採取家の異世界旅行記',
        'animations/9/images/e522dcd7-4d4f-480b-b257-507e9a7ad125.webp',
        '異世界へと転生したごく普通のサラリーマン・神城タケル。剣と魔法の世界である『マデウス』で新たな人生をスタートさせる事となった彼には多くの能力が備わっていた！　身体能力強化にトンデモ魔力、そして、価値のあるものを見つけ出せる『探査能力』――与えられたチート級の力を駆使して、タケルの異世界大旅行が幕を開ける!!',
        NULL, 0, 0, 0, '2025-10-06'),
       (10, 82,
        '『ディズニー ツイステッドワンダーランド ザ アニメーション』 シーズン1「エピソード オブ ハーツラビュル」',
        'animations/10/images/189cadb2-e2cc-437b-a516-121b1f5ed570.webp',
        '＜ツイステッドワンダーランド＞、ここは魔法が存在する世界。\nこの世界で伝説として語り継がれてきた偉⼤なる存在が＜グレート・セブン＞。\nハートの⼥王、百獣の王、海の魔⼥、砂漠の魔術師、美しき⼥王、死者の国の王、茨の魔⼥。\nそして＜ツイステッドワンダーランド＞において、名⾨魔法⼠養成学校として君臨し、\nこれまで優秀な魔法⼠を多く輩出してきたのが「ナイトレイブンカレッジ」。\n学園⻑の下には「グレート・セブン」に倣った7つの寮が存在し、それぞれを7⼈の寮⻑が束ねている。\n７寮⻑の⼀⼈が＜ハートの⼥王＞の厳格な精神に基づく・ハーツラビュル寮の寮⻑・リドル・ローズハート。\n“真紅の暴君”・リドルは、寮⽣たちを“ハートの⼥王の法律”によって厳格に⽀配し苦しめていく。\nリドルはなぜ“暴君”となってしまったのか、彼が囚われているものとはーーー\nディズニープラスで2025年10⽉29日より独占配信中',
        1, 0, 0, 0, '2025-10-29'),
       (11, 389, '野原ひろし 昼メシの流儀',
        'animations/11/images/63acd6b2-c41d-4a9d-9f23-ed3bc86d422c.webp',
        '国民的キャラクター漫画「クレヨンしんちゃん」の公式スピンオフアニメとして、父・野原ひろし（35）の束の間の息抜き＝昼メシを、限られたお小遣いと時間の中でこだわりにこだわり抜く姿を描く。普段はあまり見ることのできない働く男・野原ひろしの昼ドキの顔！ はたして、どんな「昼メシ」が登場するのか！？そして、ひろしが大事にする「流儀」とは・・・',
        NULL, 0, 0, 0, '2025-10-03'),
       (12, 136, '不滅のあなたへ Season3',
        'animations/12/images/659964bf-971a-46a1-916b-7694dc792d1a.webp',
        '不滅の存在であるフシ。 それに対抗するのは人間を襲い滅ぼそうとする敵対勢力、「ノッカー」。 攻防の末にノッカーとの戦いには勝利したが、フシはまだ人々を守り続ける必要があった。 自らの体を広げ、樹木のごとく抵抗の根を張り巡らせた。 数百年後、そこは現代世界。 かつてないほどの平和な世界。 新しい友人・・・新しい家・・・ 全てが満ち足りた世界でフシは幸せを謳（おう）歌できると思っていた。 しかし不穏な影が、再びフシに迫る。 その影は、人の心の隙間に分け入る宿敵。 そして、自分を生み出した観察者の真の目的。 フシに与えられる新たな試練。彼に大いなる選択の時が迫る。 不死身のフシの物語、「現世編」が幕を開ける。',
        3, 0, 0, 0, '2025-10-04'),
       (13, 17,
        '信じていた仲間達にダンジョン奥地で殺されかけたがギフト『無限ガチャ』でレベル9999の仲間達を手に入れて元パーティーメンバーと世界に復讐＆『ざまぁ！』します！',
        'animations/13/images/50483fb7-d013-4e35-83cd-c7de16cb0fe2.webp',
        'かつて女神が創りし９つの種族。その中でもっとも弱く、嘲笑される存在──人種（ヒューマン）。\n人種（ヒューマン）の少年・ライトは幸運にも９つの種族で編成されたパーティー『種族の集い』に迎えられ、幸せなひと時を過ごしていた。\nしかし、それは儚い幻想だった。\n彼を待っていたのは、世界最大最悪のダンジョン『奈落』での裏切り。\n奈落の底で生き延びたライトは、そこで己の恩恵（ギフト）『無限ガチャ』の真の力を知る。\n絶望の果てから這い上がり、ライトが築くのは最強の王国。\n唯一無二の恩恵（ギフト）『無限ガチャ』を手に、世界を揺るがす復讐劇が幕を開ける!!',
        NULL, 0, 0, 0, '2025-10-03'),
       (14, 38, 'らんま1/2 第2期', 'animations/14/images/bcef004b-12fe-444c-a8c1-0ad637293b21.webp',
        '天道道場の主、早雲は娘の許婚になる約束の早乙女乱馬親子が帰るのを知り大喜び。しかし、天道家に現れたのは可愛い中国娘とドでかいパンダ。実は「呪泉郷」という池の呪いにかかり、乱馬は水を被ると女に、父の玄馬はパンダに変身してしまうのだった・・・。そして早雲の娘であるあかねと同じ風林館高校へ通うことになった乱馬。だが、女のらんまに恋をした久能帯刀や永遠のライバル宣言をした響良牙など、学園中はすったもんだの大パニック・・・。',
        2, 0, 0, 0, '2025-10-04'),
       (15, 27, 'キングダム 第6シリーズ',
        'animations/15/images/b8b7375b-0390-4835-8cc9-eee7e57f6214.webp',
        '紀元前、中国西方の秦国（しんこく）。「天下の大将軍」を目指す元・下僕の信（しん）は、誰も成し遂げたことのない「中華統一」による乱世の終結を願う秦王・嬴政（しんおう・えいせい）と志を同じくし、秦軍所属の「飛信隊（ひしんたい）」隊長として戦場に身を置いていた。 一方、政敵であった相国・呂不韋（りょふい）から国の実権を取り戻した嬴政は、軍総司令・昌平君（しょうへいくん）や法家・李斯（りし）らの協力のもと、中華統一による新たな「法治国家」建国の実現に向け動き始める。 進攻を目論む秦軍は、新拠点「黒羊丘（こくようきゅう）」から趙国（ちょうこく）西部の攻略を狙う。しかし、秦国による中華統一の動きを危険視し、いち早く対策を講じた趙国の天才軍師・李牧（りぼく）の戦略により計画を阻まれることになる。 これに対し昌平君は、趙国王都・邯鄲（かんたん）近くの都市・鄴（ぎょう）を攻める奇策を提案。 李牧に対抗するため、優れた軍略家である王翦（おうせん）、そして、桓騎（かんき）、楊端和（ようたんわ）率いる三軍による連合軍が結成される。 さらに、大きな期待を寄せられた新世代・信「飛信隊」、蒙恬（もうてん）「楽華隊（がくかたい）」、王賁（おうほん）「玉鳳隊（ぎょくほうたい）」が独立遊軍としてこれに加わる。 鄴をめぐる熾烈な戦いがいよいよ幕を開ける！',
        6, 0, 0, 0, '2025-10-04'),
       (16, NULL, 'ハズビン・ホテルへようこそ シーズン2',
        'animations/16/images/06216975-f1d2-43bd-85e0-3ad0ca5b5653.webp',
        '天使軍との戦いにチャーリーが勝利したことで、ホテルには新たな客が殺到する。しかし、チャーリーの期待とは裏腹に、客は贖罪ではなく復讐を求めるばかり。一方その頃、チームヴィーは天国と地獄との間で緊張が高まっていることに乗じて、あることを画策し始め…。\nPrime Videoで10月29日（水）より配信中',
        NULL, 0, 0, 0, '2025-10-29'),
       (17, 17, '父は英雄、母は精霊、娘の私は転生者。',
        'animations/17/images/e96c6a3b-6dfe-43bf-907e-6946c6e60217.webp',
        '現代日本から転生した、精霊の少女エレン。 精霊界で暮らす8歳の少女・エレンは、元々現代日本で科学者をしていた転生者。 物質を化合させたり、構造配列を好きに変えられるというチートスキルを持つ。 そして、父・ロヴェルは国を救った伝説の英雄、 母・オリジンは元始の母にして精霊の女王！ 一家は、精霊界で穏やかな日々を過ごしていたが、 ロヴェルとエレンが修行のために人間界を訪れた事をきっかけに、 王家の陰謀に巻き込まれてゆく―― 精霊の力を手中に収めようとするラヴィスエル王子の策略に、 エレンは前世の知識と圧倒的チートで対抗する！ 「腹黒さんの宣戦布告ですね。受けて立ちましょう！」 最強才女の痛快舌戦ファンタジー！',
        NULL, 0, 0, 0, '2025-10-05'),
       (18, 29, '東島丹三郎は仮面ライダーになりたい',
        'animations/18/images/0900dc05-c7a9-4a17-8370-873ea3abbfa2.webp',
        '40歳になっても本気で「仮面ライダー」になろうとしていた東島丹三郎。だが、その夢を諦めかけた時、世間を騒がす「偽ショッカー」強盗事件に巻き込まれ…。『エアマスター』『ハチワンダイバー』の柴田ヨクサルが魂で描く、「仮面ライダー」を愛しすぎるオトナたちによる“本気の仮面ライダーごっこ”ここに開幕！',
        NULL, 0, 0, 0, '2025-10-04'),
       (19, 24, '青のオーケストラ Season2',
        'animations/19/images/095c21b4-4d57-4570-b86b-9c4260d338f9.webp',
        '演奏することをやめていた元天才ヴァイオリニスト・青野が出会った高校のオーケストラ部の世界。個性豊かな仲間たちが情熱を音楽にのせて織りなす、青春のアンサンブルドラマ。 夏の定期演奏会を終えて3年生が引退。2年生が中心となったオーケストラ部は全国コンクールに向けて始動する。それぞれのモチベーションの温度差や演奏曲のイメージをめぐって不協和音が鳴り響く中、今自分たちにしか出せない音を作り上げようと奮闘する部員たち。青野自身の音楽との向き合い方、そして仲間たちとの関係も変化していく。',
        2, 0, 0, 0, '2025-10-05'),
       (20, 264, '私を喰べたい、ひとでなし',
        'animations/20/images/0d353e63-135e-46df-b190-b12efc78c815.webp',
        '「私は君を喰べに来ました。」 突如現れた人魚の少女・汐莉は 海辺の街に独り暮らす比名子の手を取り、優しく語りかける。 比名子の持つ血肉は、特別に美味しいという。 それは数多の妖怪を惹きつけるほどに…。 汐莉は、成熟し、最高の状態を迎えるまで比名子を守り “いずれ自分が喰べる”と約束する。 比名子の胸には 「このひとなら私の願いを叶えられるかもしれない」 という切なる想いが浮かび―。',
        NULL, 0, 0, 0, '2025-10-02'),
       (21, 185, '終末ツーリング', 'animations/21/images/82297eda-9076-408b-bfe9-1b01ebb62e94.webp',
        '誰もいない終末世界を旅する少女、ヨーコとアイリ。 名所の風景ふたりじめで写真を撮ったり、自然いっぱいな街中でキャンプをしたり。 オフロードバイク・セローにタンデムで走る2人の旅は、 渋滞もなければ信号にも止められない、 いまだかつてない自由なツーリング旅！ 2人の少女と1台のセローが滅んだ日本を駆け回る、 異色のツーリングコミックがテレビアニメ化！ 世界も終わったし、バイクに乗って旅に出よう！',
        NULL, 0, 0, 0, '2025-10-04'),
       (22, 247, '羅小黒戦記', 'animations/22/images/576183b8-2a01-402e-887c-a404eb1a9a99.webp',
        '黒猫の妖精・シャオヘイは、重傷を負い、\n路頭に迷っていたところをロシャオバイ（羅小白）という少女に拾われる。\n少女の姓をとり「ロシャオヘイ（羅小黒）」と名付けられ、共に暮らすことに。\n少女と黒猫の出会いは、\nさまざまな“不思議”を巻き起こしていく——。',
        NULL, 0, 0, 0, '2025-10-05'),
       (23, 106, 'キミと越えて恋になる',
        'animations/23/images/9375ca02-5d17-4eb2-bad0-14e043e7110a.webp',
        '20XX年、人間社会にほんの少し混じる獣人という生き物。 そんな獣人と人間が共存する町に住む高校生・万理のクラスに、獣人の特例生・繋がやって来た。 初めて接する獣人という存在に戸惑いながらも、クラスメイトとして一緒に過ごすうち、優しくて純粋な繋に惹かれていく万理。繋も万理の発する「甘いニオイ」に魅了されながら、その美しさと強さに心奪われていく。 でも、獣人が壁の向こうに隔てられているこの世界では、人間と獣人が親しくするだけで好奇の目が向けられる。ましてや恋愛なんて…… 人間と獣人。種族を越えたふたりの恋の行方はどうなる──？',
        NULL, 0, 0, 0, '2025-10-14'),
       (24, 284, '笑顔のたえない職場です。',
        'animations/24/images/035ae636-4614-4051-aac2-4dc06c9c09b1.webp',
        '双見は駆け出しの少女漫画家。 クールな担当編集や、頼もしいアシスタントらの 力を借りて、念願の将棋漫画『昴へ』の連載を、 ようやくスタートさせることができたけど…… ストレスでお腹をやられて、1話から締切を延ばしてもらったり。 ネームが進まず、深夜まで机にかじりつく羽目になったり。 夜食で太っちゃったり、 よからぬ妄想が止まらなかったり…… 前途多難な漫画家ライフ、笑顔で謳歌できるのか――！？',
        NULL, 0, 0, 0, '2025-10-06'),
       (25, 94, '太陽よりも眩しい星',
        'animations/25/images/285e37f0-aca0-4de4-8b1b-2ff1706becc5.webp',
        '「俺物語！！」（作画：アルコ）「高校デビュー」「先生！」と多くの作品でメディアミックス化されている河原和音の最新作。 平均より少し頑丈な女の子・岩田朔英と、か弱い男の子・神城光輝。 小学生の頃、神城の笑顔にひとめぼれした朔英だったが、 細くて小さかった神城は、中学生になると、爽やかイケメンに成長。遠い存在になってしまった。 そんな中、中学最後の体育祭で一緒になり、心の奥にしまってきた初恋が動き出す。 どんなに遠くなっても、私の眩しい星はずっと君――。きらめく初恋ストーリーが始まる！',
        1, 0, 0, 0, '2025-10-02'),
       (26, 70, '悪食令嬢と狂血公爵',
        'animations/26/images/bac8cb52-047a-4895-977f-0dfbbac1d1d3.webp',
        '「食べるからには美味しくいただきたいですし！」 伯爵家の娘・メルフィエラは、誰にも理解されない趣味を持っていた。 それは、人間に害をもたらす魔物を美味しくいただくこと！ そうしてついたあだ名は「悪食令嬢」――。 ある日のこと、婚約者を探すために参加していた遊宴会で狂化した魔獣に遭遇してしまう。 絶体絶命な状況に思わず身をすくめるメルフィエラだが、そこに「狂血公爵」と恐れられるガルブレイス公爵が姿を現す。 振り下ろされる剣 倒れる魔獣 金色に光る瞳 その圧倒的な強さと美しさに息を飲むメルフィエラだったが、公爵の顔に滴る魔獣の血が気になってしまい……！？ 魔物を美味しく調理する「悪食令嬢」と 心優しき「狂血公爵」が織りなす 美味しくて胸キュンな異食（異色）グルメファンタジー！ ――極上の物語を召し上がれ！',
        NULL, 0, 0, 0, '2025-10-02'),
       (27, 143, 'ウマ娘 シンデレラグレイ 第2クール',
        'animations/27/images/457a8ce2-9cd4-4eff-9c11-182601d03fe6.webp',
        '地方から現れた、常識破りの異才。\n中央の強敵を次々と打ち破った、その名は「怪物」オグリキャップ。\n彼女の前に立ちはだかるは、「最強」タマモクロス。\nそして、海を越えた「世界」のウマ娘たち。\nやがて一つの「時代」を作る灰被りの少女が、今、新たな領域へ踏み込む――。\n熱き夢“奔る”シンデレラストーリー、続けて出走!!',
        2, 0, 0, 0, '2025-10-05'),
       (28, 170, '味方が弱すぎて補助魔法に徹していた宮廷魔法師、追放されて最強を目指す',
        'animations/28/images/9b42e309-5fe7-4b6a-aba4-7cc732870bc9.webp',
        '突然の“追放宣告”をきっかけに、再び運命の歯車が廻りだす——\n王太子 レグルス・ガルダナを陰で支える宮廷魔法師 アレク・ユグレット。\n弱すぎるレグルスを守るため「補助魔法」に徹していたはずが、突然の追放宣告で職を失ってしまう。\nそんなアレクの前に現れたのは、魔法学院時代にかつて“伝説”と謳われたパーティー「ラスティングピリオド」で共に戦った仲間のヨルハ・アイゼンツだった。\n「キミの力が必要なんだ！」\n伝説のパーティーが再集結し、新たな物語が幕をあける——\n始めよう、新しい伝説を。あの日の続きを。\n終わりなき日々(ルビ：ラスティングピリオド)を！',
        NULL, 0, 0, 0, '2025-10-04'),
       (29, 372, 'SEALOOK（シールック）',
        'animations/29/images/6018f8f8-8d45-446e-8c94-b4012213b536.webp',
        'ある日ちょっと変わった行動をするアザラシたちに番号がついたタグを付けて、観察を始めた。没入型3D観察アニメーション『SEALOOK（シールック）』。のんびり揺れるアザラシたちの癒し系コメディ。忙しい日常に優しい癒しを届けます。',
        NULL, 0, 0, 0, '2025-10-01'),
       (30, 44, '千歳くんはラムネ瓶のなか',
        'animations/30/images/7da5379c-6ee6-4953-b0f1-ab7d285c8787.webp',
        '県内随一の進学校・藤志高校に通う千歳朔。 勉強、運動、コミュ力すべてがハイレベルで、 良くも悪くも注目を集める彼の周りには、 誰もが羨む華やかな仲間たちが集っていた。 新たなクラスで迎えた2年生の春。 朔は、ひとりの引きこもり生徒の更生を頼まれることに——。',
        NULL, 0, 0, 0, '2025-10-07'),
       (31, 290, '3年Z組銀八先生', 'animations/31/images/498398d9-4d15-4735-a876-2de7f5810713.webp',
        'だらしなく着た⽩⾐、銀髪の天然パーマに死んだ⿂のような⽬がトレードマークの⾼校教師・坂⽥銀⼋。彼が担任する「銀魂⾼校3年Z組」は、ドルオタ、ゲロイン、ストーカー、マヨラー、ドＳ、ヤンキー（以下略）なぜかクセが強めな⽣徒ばかりが集められ、毎⽇がトラブル三昧︕\n滅茶苦茶なことばかりの⽇々に銀⼋は頭を抱えて――なんてことはなく、とぼけた顔で問題を解決したりしなかったり。\nそして個性豊かな⽣徒たちは、さまざまな経験を通してやがて⼀つになって――なんてことはやっぱりなく、みんな好き勝⼿に暴れ回る︕\nおいィィィ︕3Z、⾃由すぎるんですけどォォォォ︕︖\nいつもやる気がなさそうで何を考えているのかわからないけれど、肝⼼な時にはビシッと決める。\nそんな型破りな教師と、3Zの⽣徒たちによる笑いあり、涙あり、なんでもありなスクールライフ・コメディ︕\n陽キャも陰キャも関係ない、銀魂流の⻘春がここにある︕︕',
        NULL, 0, 0, 0, '2025-10-06'),
       (32, 290, 'しゃばけ', 'animations/32/images/b06a17bd-5cf2-434d-9f23-4a8326d8393e.webp',
        '時は江戸。日本橋有数の大店である長崎屋の若だんな“一太郎”は、生まれた時から身体が弱く外出もままならない。そんな一太郎の身の周りには白沢や犬神といった妖たちが仕え、常に守られていた。\n或る夜、周囲の目を盗んで出かけた一太郎は人殺しを目撃してしまう。\nその日をきっかけに江戸では猟奇的な殺人事件が次々と起こり始め……。\n妖たちの助けを借り、一太郎の下手人さがしが始まる——！',
        NULL, 0, 0, 0, '2025-10-03'),
       (33, 71, '嘆きの亡霊は引退したい 第2クール',
        'animations/33/images/8686d47c-9de9-4e08-83e3-6ba31d42f65f.webp', NULL, 2, 0, 0, 0,
        '2025-10-06'),
       (34, 85, '矢野くんの普通の日々',
        'animations/34/images/13b4c2b0-35b0-413b-9fa3-d20a2f640574.webp',
        '人よりちょっと心配性なクラス委員・吉田さんは、隣の席に座る矢野くんが心配で仕方がない。 毎日ケガまみれで学校にやってくる「超・不運体質」の矢野くん。 そんな矢野くんの手当てをしているうちに、吉田さんの中には特別な想いが芽生えてきて…。 個性的な友人たちに囲まれながら、少しずつ距離を縮めていく二人。 果たして、吉田さんの恋はどこに辿り着く？ そして、矢野くんに『普通の高校生活』は訪れるのか？ 心配性女子とケガまみれ男子の、ピュアラブコメディが今、始まります――',
        NULL, 0, 0, 0, '2025-09-30'),
       (35, 35, '魔法少女まどか☆マギカ 始まりの物語／永遠の物語 TV Edition',
        'animations/35/images/a0ab29df-777c-42d4-9f18-2fa7f367fdae.webp', NULL, NULL, 0, 0, 0,
        '2025-10-12'),
       (36, 123, 'ポーション、わが身を助ける',
        'animations/36/images/03580c4b-5a9b-4374-bc53-bf063de7fdf9.webp',
        '普通の女子高生・カエデは、 見覚えのない路地裏で目を覚ました。 そこは獣人やエルフ、ドラゴンのいる不思議な異世界。 カエデは持っていたリュックサックに 見覚えのない本があることに気がつく。 それは「生成」と唱えるだけで ポーションが出来てしまう不思議な本だった！ 異世界に放り出されたカエデにとって、 生成されたポーションは生活を支える糧になった。 いつか日本へ帰ることを望みながら 女子高生の異世界での奮闘は続いていく―',
        NULL, 0, 0, 0, '2025-10-02'),
       (37, 81, '百姓貴族 3rd Season', NULL, NULL, 3, 0, 0, 0, '2025-10-03'),
       (38, 20, 'ワンダンス', 'animations/38/images/332ecac6-4562-4b27-8dbe-72d735cb8b80.webp',
        '自分の気持ちを上手く表現できない、吃音（きつおん）症の高校生・小谷花木（カボ）。\nそんな彼が惹かれたのは、周りの目を気にせずダンスを追い求める同級生・湾田光莉（ワンダ）。\n“なんか、自由になれる感じがするー”音楽によって引き出される、感情、生い立ち、コンプレックスー\n言葉の要らない“フリースタイル“な表現を求めて、未経験のダンスの世界に挑む！',
        NULL, 0, 0, 0, '2025-10-08'),
       (39, 110, 'SANDA', 'animations/39/images/df4d378b-f9d7-4648-a3ba-aa86538891dc.webp',
        '舞台は、超少子化時代を迎えた近未来の日本。\n国の宝として扱われ、大人たちによって全寮制の学園で管理・保護される子どもたち。\nそして、子どもに夢や希望を与えるサンタクロースは危険人物とみなされ、\n排除の対象とされていた―。\n中学生の三田一重は、雪の降る12月25日にクラスメイトの冬村四織から命を狙われる。\n彼女は、三田がサンタクロースの末裔であることを知り、\n願い事を叶えてもらおうとしていたのだった。\nサンタさん、友達を探してください\n冬村の願いは、行方不明になった親友・小野一会を見つけ出すこと。\n子どもたちを守るため、三田はサンタクロースとなって大人と戦うことを決意するー！',
        NULL, 0, 0, 0, '2025-10-03'),
       (40, 159, '友達の妹が俺にだけウザい',
        'animations/40/images/e590e217-dd33-48ad-80fe-3eff99c5a4b2.webp',
        '馴れ合い無用、彼女不要、青春の一切を非効率と切り捨てる高校生・大星明照。 彼の家には、なぜか親友の妹・小日向彩羽が入り浸っている。 占拠されるベッド！突然の寸止め色仕掛け！吹き荒れるウザ絡みの嵐！！ 学校では清楚な優等生として大人気の彩羽は、明照にだけやたらとウザい。 そんなハイテンション系ウザかわ女子・彩羽に振り回される明照の前に、塩対応女子・真白が出現。 それをきっかけに、明照、彩羽、そして仲間たちの日常は激変し――！？ ウザかわ女子が（頼んでないのに）寄ってくる！ 悶絶必至のいちゃウザ青春ラブコメ、開幕★',
        NULL, 0, 0, 0, '2025-10-04'),
       (41, 18, '忍者と極道', 'animations/41/images/9ffc082b-41c0-4173-9633-2f8e9a6260f4.webp',
        '陰に忍んで悪しき闇を討たんとする、“忍者”(にんじゃ)。\n孤立した者の居場所となり悪事を重ねる、“極道”(ごくどう)。\n江戸時代、明暦の大火の裏で刻まれた忍者(にんじゃ)と極道(ごくどう)の因縁(カルマ)が、現代に再び燃え盛ろうとしていた――。\nトラウマにより笑顔を失った忍者(にんじゃ)・多仲忍者(たなかしのは)と、\n表向きはエリート会社員ながら裏社会(ウラ)を取り仕切る極道(ごくどう)・輝村極道(きむらきわみ)。\n女児向けアニメの話題で意気投合した二人は、互いの正体を知らぬまま友情を深めていくのだが……。\n忍者(にんじゃ)と極道(ごくどう)、両者の戦争が激化する中、その“運命”(さだめ)が交錯する。\n決めようか、忍者と極道、何方(どちら)が生存(いき)るか死滅(くたば)るか!!!',
        NULL, 0, 0, 0, '2025-10-07'),
       (42, 444, 'ある日、お姫様になってしまった件について',
        'animations/42/images/bcfd1244-b6c1-4f20-af9e-d79ea4a14d70.webp',
        '『バッドエンド回避の糸口は冷酷なパパのハートをゲットすること！？』 魔法の国・オベリア帝国に生まれた皇女アタナシア。 彼女は自分の未来を夢で見ることができる不思議な力を持っていた。 生まれたころから父親である皇帝クロードに冷遇され、 ルビー宮でひとり育てられてきたアタナシアは、 ある日夢のなかで、18歳の誕生日に自分が父の手で追放されてしまう未来を知る。 「そんな未来絶対受け入れなーーい！！」 運命を変えるため、アタナシアは小さな体で決意を胸に立ち上がるのだった。 小さなお姫様の運命書き換えファンタジーが今、始まる―！',
        NULL, 0, 0, 0, '2025-10-01'),
       (43, NULL, 'マーベル・ゾンビーズ',
        'animations/43/images/bf41efa5-7900-45df-aa00-f0142a3d295e.webp',
        'アベンジャーズがゾンビの疫病に侵されてしまった後、絶望的な状況の中で生き残った者たちは、超能力を持つアンデッドを終わらせる鍵を発見する。彼らは荒廃した世界を駆け抜け、命を懸けて世界を救おうとする。',
        NULL, 0, 0, 0, '2025-09-24'),
       (44, 261, '野生のラスボスが現れた！',
        'animations/44/images/8706544f-e98b-4695-9e6b-e1a5f912e923.webp',
        'ミズガルズ暦2800年、\n\"黒翼の覇王\"と人々から恐れられた「ルファス・マファール」は、「七英雄」と呼ばれる勇者たちとの最終決戦による激闘の末、その覇道に終焉を迎える。\n覇王の封印によって安寧の時代が訪れるかに思われたが･･･、力の均衡が崩れた事で、世界は魔神族の脅威にさらされるのであった。\nそれから200年後──、\n魔神族に対抗すべく人類は新たな勇者の召喚を試みる。\nしかしそこに現れたのは、長き封印から目覚めた覇王ルファスの姿だった！',
        1, 0, 0, 0, '2025-10-04'),
       (45, 18, '転生悪女の黒歴史',
        'animations/45/images/f5244f18-8dfb-4ba6-bbcb-32904bde0e74.webp',
        '自分の名をつけた主人公『コノハ・マグノリア』が可憐に活躍する、 恋と魔法の冒険ファンタジー。 自らが中学生の時に執筆した物語の世界に転生した佐藤コノハは、 なりたかった主人公『コノハ』ではなく、 その妹で稀代の悪女『イアナ・マグノリア』に転生してしまう。 思い出したくもない【黒歴史（自分の描いた物語）】のよりによって 悪役に転生してしまったイアナの運命は！？ 自分の考えたキャラクターたちを見守りながら、 平和な生活を手にすることができるのか！？',
        NULL, 0, 0, 0, '2025-10-08'),
       (46, 255, '機械じかけのマリー',
        'animations/46/images/095f38cb-e3be-4319-808a-2b92cbdd29c1.webp',
        '「ついに完成いたしました。機械人形（ロボットメイド）のマリーです」 元天才格闘家の少女・マリーは人間としての身分を隠し、人間嫌いの大財閥の御曹司・アーサーの屋敷に“機械人形（ロボットメイド）”として働くことになったが・・・ ──正体がバレれば即処刑！？ “機械人形（ロボットメイド）”として、持ち前の無表情を活かして職務を全うし、アーサーの命を狙い襲い来る暗殺者から彼を守るため奮闘する。 しかし、マリーを溺愛するアーサーに人間だとバレるピンチも訪れ、日々ヒヤヒヤ、ドキドキ！ 嘘から始まる主従関係が、やがて思いがけない恋へと発展していく。',
        NULL, 0, 0, 0, '2025-10-05'),
       (47, 383, '龍族Ⅱ -The Mourner''s Eyes-',
        'animations/47/images/e696712a-8a94-4b75-8c7f-3e7a2f2ee051.webp',
        '青銅と炎の龍王討伐に成功したルー・ミンフェイは、 次なる四大君主、大地と山脈の龍王との戦いに身を投じていく―― ルー・ミンフェイがカッセル学院に入学して早くも1年が経過し、2年目では学院最強の龍殺しの一人、チュー・ズーハンとタッグを組むことに。 信国での任務を終えカッセル学院へと戻る道中、二人は学院の新入生でA級血統を持つ少女シャー・ミーと出会い仲間となる。 新たにチームを組んだ三人は蘇る大地と山脈の龍王討伐のために壮絶なミッションに挑む。',
        2, 0, 0, 0, '2025-10-08'),
       (48, 51, '永久のユウグレ', 'animations/48/images/170d94fc-8c8b-4127-987b-038184421508.webp',
        '悠久の眠りから目覚めた世界で求婚してきたのは、最愛の彼女にそっくりのアンドロイドだった……。 コールドスリープから目覚めた男子高校生・姫神アキラの目の前には、信じられない光景が広がっていた。 戦争によって荒廃した街。国は廃れ、OWELと呼ばれる統一機構によって管理される人々。 結婚とはまた違う新しい“エルシー”と呼ばれる制度。 かつて自身が生きていた世界からあまりにも様変わりする人々。 そんな未来に置き去りにされ愕然とするアキラの前に、彼女は現れた。 「トワサ！？」思わず口に出してしまったその存在は、最愛の彼女に酷似したアンドロイド・ユウグレだった。 彼女は、微笑みながら願うように自身の想いを口にする。 「アキラ……。私と結婚して下さい」 アンドロイドからの突然の求婚に困惑しながらも、アキラはユウグレと共に旅へ出ることを決意する。 世界のどこかにいるはずのトワサと再会できると信じて……。 これは新時代を生きる×××と×××が愛を見つける物語。',
        NULL, 0, 0, 0, '2025-09-25'),
       (49, 16, '暗殺者である俺のステータスが勇者よりも明らかに強いのだが',
        'animations/49/images/d67f74a6-e1a2-4dc2-acff-bddc7ad43f12.webp',
        'クラスメイトと共に異世界に召喚された高校生・織田 晶。\n召喚によってクラスメイト全員にチート能力が付与される中、\n彼は生来の影の薄さからか平凡な“暗殺者”の能力を得る。\nだが、ただの“暗殺者”のはずなのにステータス値が、\n最強の職業“勇者”すら軽々と凌駕していて——!?\nそして、召喚の首謀者である国王の言動に疑念を抱いた晶は、\n自分の存在をひた隠しその陰謀を暴くも、逆にあらぬ罪を\n着せられ追われる立場に追い込まれてしまう。\n国王への復讐を誓った彼は、逃げ込んだ前人未踏の迷宮深層で\nエルフの少女アメリアと邂逅を果たす——…。\nこれは“暗殺者”の能力を得た少年が、エルフの少女と出逢い\n真の“暗殺者”へと至るまでの物語。',
        NULL, 0, 0, 0, '2025-10-06'),
       (50, 137, '無職の英雄 ～別にスキルなんか要らなかったんだが～',
        'animations/50/images/54b51028-067f-4749-8914-d18b44681bbc.webp',
        'それは、女神から授けられる職業とスキルが人生を大きく左右する世界――。 『剣姫』と『魔導王』の息子として生まれた主人公・アレルはどんな職業を授かるかと期待されるなか、『無職』の烙印を押されてしまう。 周囲の人々からの失望と同情。しかし、アレルは努力を重ねることで、次々と新たな力を手に入れていく。そして、その力はやがて天賦の才であるスキルをも上回るのだった。 これはスキルを持たない『無職』がたゆまぬ努力の結果『英雄』と呼ばれ、さらなる力を求めてゆく物語――。',
        NULL, 0, 0, 0, '2025-10-01'),
       (51, 393, '顔に出ない柏田さんと顔に出る太田君',
        'animations/51/images/0e678d4f-6986-4550-9377-51b5b48c0a0d.webp',
        '何があっても顔に出ない女子中学生・柏田さんと、めちゃくちゃ顔に出てしまう同級生の太田君。 正反対の二人は、きっと両思い…？柏田さんと太田君と、クラスメイトたちのほのぼのラブコメ。',
        NULL, 0, 0, 0, '2025-10-04'),
       (52, 31, 'かくりよの宿飯 弐',
        'animations/52/images/e147ce7c-93ae-4c1b-b4ee-634b47a30012.webp',
        '南の地の宿〈折尾屋〉での試練を越え、〈夕がお〉へと帰ってきた葵。 しかし、穏やかな日々は束の間――〈天神屋〉に、 かつてない危機が迫っていた。 守りたい居場所がある。信じてくれる仲間がいる。 幾多の出会いと絆に育まれ ――物語は再び、動き出す。',
        2, 0, 0, 0, '2025-10-01'),
       (53, 19, 'DIGIMON BEATBREAK',
        'animations/53/images/f914d288-bd5a-42de-bdd4-d007540bd81a.webp',
        '人間の思考や感情から生まれる「e-パルス」は、AIサポートデバイス「サポタマ」のエネルギー源として活用されていた。目覚ましい発展を遂げるその陰で、恐るべき怪物が現れる。e-パルスを喰らい、進化する生命体「デジモン」である。 天馬トモロウは、サポタマから誕生したゲッコーモンとの出会いをきっかけに、非日常へと巻き込まれていく。 賞金稼ぎを生業とするチーム「グローイングドーン」の沢城キョウたちとの共同生活を送るなかで、トモロウは決意を新たにする。 人間とデジモンが描く新しい未来とは──',
        NULL, 0, 0, 0, '2025-10-05'),
       (54, 246, 'デブとラブと過ちと！',
        'animations/54/images/7b76c5c5-698f-4613-9ba3-193c6296a990.webp',
        'お菓子メーカーに勤める夢子は、事故をきっかけに記憶喪失になってしまう。 コンプレックスの塊で自分が嫌いで仕方のなかった夢子は、目が覚めると超ポジティブで自己肯定感MAXな性格になっていた。 元の性格とは正反対な夢子に、周りは戸惑いを隠せずにいたが、夢子のポジティブでまっすぐな姿に少しずつ変化が訪れて――。 恋に、仕事に、友情に！ちょっとだけ事件の香りも……？ドタバタ・オフィスラブコメディー！',
        NULL, 0, 0, 0, '2025-10-06'),
       (55, NULL, 'ギルティホール',
        'animations/55/images/9e015a6b-d0ec-471b-8a4a-392208e2d6d0.webp',
        '「お好きな教え子をお選びください…」\n残業続きの教師・佐々木の前に現れたのは『ギルティホール』。\n指名パネルに変わった下駄箱を前に、さすがに夢だと思い冗談で一人の教え子を指名すると、\n真夜中の教室に現れた彼女は、悪態をつきながら恥ずかしそうにこちらを見つめてきて…\n「さっさと終わらせるから。我慢するとか無しな。」\n教師と教え子、禁断のカンケイ…。\n全てが許される『ギルティホール』へようこそ――',
        NULL, 0, 0, 0, '2025-10-05'),
       (56, 193, 'さわらないで小手指くん',
        'animations/56/images/02557f6b-e768-44d0-8857-902ea4213197.webp',
        '小手指向陽・高校1年生。\n特技は、気持ちよくさせすぎちゃう超絶マッサージ！！\n学費を稼ぐため、スポーツ強豪校・星和大付属高校の寮の管理人となった向陽。\nそこで出会ったのは、曲者揃いの美少女アスリート達だった！\n医学部特待生をＧＥＴするため、向陽は彼女達の「心身のケア」に勤しむことに！\n過激すぎるのに、尊すぎる……！？\n新時代のマッサージラブコメ、ここに悶絶！！',
        NULL, 0, 0, 0, '2025-10-05'),
       (57, 42, 'うごく！ねこむかしばなし',
        'animations/57/images/baa08857-5de8-4473-8203-bd39fcb7c9cf.webp',
        '「もしも、ねこがあの物語に登場したら…?」\n有名な昔話や童話にねこが加わると、\n癒したっぷりでシュールな新展開が繰り広げられてしまう…!?\nキジトラ、チャトラ、ミケにシロネコ、\n多種多様なねこ×昔話で全人類癒され必至!\n可愛いねこコメディーがはじまる!',
        NULL, 0, 0, 0, '2025-10-15'),
       (58, 561, 'ガングリオン', 'animations/58/images/8f40be14-2be4-49c9-a09b-4eec276f7890.webp',
        '2000年代初頭の東京。世界征服を目論む「株式会社ガングリオン」の戦闘員・磯辺。彼の職場は戦場だ。タイツ一枚で「東京スギ花粉作戦」や「富士山爆破作戦」に臨むも、ヒーロー・ホープマンの正義という名の一撃にあっさり惨敗。コンプラ黎明期、上司の無茶にもひたすら耐えて奮闘する…すべてのはたらく人々に捧ぐ、“お仕事”ドラマ。どこか人ごとではない、哀しきサラリーマン戦闘員の物語。',
        NULL, 0, 0, 0, '2025-10-03'),
       (59, NULL, 'ヘルヴァ・ボス シーズン1',
        'animations/59/images/2fbd2d72-4b0b-437d-bae9-70efa29e96e5.webp',
        'この大人向けアニメーション･コメディでは、「即殺プロフェッショナルズ」（通称ＩＭＰ、地獄に住む悪魔が営む暗殺請負会社で、地上の人間を殺すことが生業）における、災難、騒動、人物間の関わり合いが描かれる。\nPrime Videoで9月10日（水）より配信中',
        1, 0, 0, 0, '2025-09-10'),
       (60, 22, 'Let''s Play クエストだらけのマイライフ',
        'animations/60/images/b3430710-4e3e-4416-871a-e24d7b47636b.webp',
        '累計閲覧数9億回以上、 北米の若者に人気を誇るWEBコミックが2025年TVアニメ化決定！ 舞台はアメリカ・ロサンゼルス―――。 ゲームクリエイターを夢みる22歳のサム・ヤングは 男性との深い関わりを避けながら生きてきたが、 3人の男性と急接近し、次第に心の殻を破っていく…。 迷いながらも前に進もうとするサム役は 子役として芸能活動を始め声優へと転身し、 今もなお活躍の幅を広げる花澤香菜が演じる。 恋愛・仕事・友人・家族・将来の夢・過去のトラウマ… 様々な経験を通して、時に選択をし、そして成長していく。 彼女の成長物語から目が離せない！ 恋愛未経験のサムによる“大人のラブストーリー”が開幕する―――',
        NULL, 0, 0, 0, '2025-10-01'),
       (61, 199, 'SI-VIS: The Sound of Heroes',
        'animations/61/images/3a10e574-f4bd-4491-8f60-08bab8231775.webp',
        '圧倒的人気を誇る音楽ユニット「SI-VIS」。\nそのリーダー・YOSUKE に憧れてオーディションを受けるため上京した主人公・キョウヤは、初めて訪れた渋谷の街で不思議な少女・凪に出会い、「SI-VIS」の新曲プロモーションの世界に誘われる。\nそこで目にしたのは、世界を壊す謎の現象ミラージュに立ち向かうという、「SI-VIS」の真実の姿だった。\n表向きはアーティストとしてライブ活動をする「SI-VIS」は、地球を守るために戦うヒーローでもあった。\nミラージュを食い止めることができなければ、その地域は存在ごと消滅してしまう――世界の恐ろしい真実を知ったキョウヤは、「SIVIS」の一員として命を懸けて戦うことになるが……。',
        NULL, 0, 0, 0, '2025-10-05'),
       (62, 178, 'アルマちゃんは家族になりたい',
        'animations/62/images/6943a5ce-2730-41ce-9891-455e52773f6f.webp',
        'かわいらしい少女の外見に高い戦闘力を兼ね備えたボディ。 人間以上の学習能力と判断力を有するAI。 完全無欠の学習型自立戦闘ロボット「アルマ」を造り出した、不遇の若き天才科学者エンジとスズメの才能は世界に認められる――はずだった！？ 自分たちを「おとうさん」「おかあさん」と呼ぶアルマに、エンジとスズメは大混乱。 それでもアルマの高性能AIを育て、最高のロボットにするため、みんなで家族として生活することに。 見るもの、触れるもの、全てが「はじめて」のアルマは何でも興味深々。 最強の学習機能と行動力でエンジやスズメたちを振り回しながら、世界をどんどん広げていく。 ニュースタイル・アットホームコメディ（！？）開幕！！',
        NULL, 0, 0, 0, '2025-10-05'),
       (63, 44, 'ちゃんと吸えない吸血鬼ちゃん',
        'animations/63/images/671128f0-afcb-4174-b231-992f6546bf92.webp',
        '転校生の石川月菜は吸血鬼。 ミステリアスな雰囲気と圧倒的な存在感を放つ彼女はクラスの人気者。 モブ的存在の大鳥は、月菜と関わることはないと思っていたのだが、 ある日、彼女の秘密を知ってしまい……。 勉強も運動もできるカッコいい吸血鬼の月菜は、 実は血を吸うのがめっちゃ下手！？ あなたもきっと、“ママ”になる――新感覚甘やかし餌付けコメディ！',
        NULL, 0, 0, 0, '2025-10-12'),
       (64, NULL, '破産富豪 The Richest Man in GAME',
        'animations/64/images/29c922b1-14da-4bf7-97ab-256cfc6a622a.webp',
        'パッとしないサラリーマン、ペイ・チェンは、ある日上司からの命令で深夜まで残業を強いられていた。すると突然、スマホの画面が光りだし、気が付くと学生時代へとタイムリープしてしまう。 何が起こったのか混乱するチェンの前に、財産変換システム・通称「リッチェスト」を名乗る謎のキャラクターが現れ、チェンに資金を提供して金持ちになるチャンスを与えると提案する。 “社畜人生”を抜け出し、金持ちになれると大喜びするチェン。 しかし、リッチェストが示したルールは極めて特殊で、金持ちになるためには“ある条件”を満たす必要があった――。',
        NULL, 0, 0, 0, '2025-10-01'),
       (65, NULL, 'ヘルヴァ・ボス シーズン2',
        'animations/65/images/0601bdac-a98f-415f-8fee-1546317ff5f7.webp',
        'Prime Videoで9月10日（水）より配信中', 2, 0, 0, 0, '2025-09-10'),
       (66, 82, 'モンスターストライク デッドバースリローデッド',
        'animations/66/images/3d1bc008-4e01-4bab-900a-a086451d1931.webp',
        '他者の顔が見えない少女「リンネ」。\n怪異の調伏を生業とする家に生まれたリンネは\n初めての御役目に向かうものの、\n予想を超えた異質な敵と遭遇。危機に陥ってしまう。\n謎の男「ジュゲム」によって助けられた後、\nリンネは、自分が生きる世界を含むすべての世界、\n通称「ストライク・ワールド」が脅威に晒されていると知る。\nジュゲムと共に終わりゆく世界の数々を旅する中で、\n少女は絆を結んでゆく──',
        NULL, 0, 0, 0, '2025-10-21'),
       (67, 102, '異世界かるてっと3',
        'animations/67/images/22bbb689-4ce6-439f-918f-0a9914eaafc2.webp',
        '異世界転移から学園に戻ってきたアインズ、カズマ、スバル、ターニャ、尚文達。2くみは新たな転校生のオットー、ガーフィールを迎え、再び平和な学園生活に戻る……かと思いきや、何やら不穏な雰囲気が。1くみに現れた謎の転校生たち、あちこちで起きる奇妙な事件、そしていつも通り唐突に発表されるイベントの数々。学園生活の行く末やいかに！？',
        3, 0, 0, 0, '2025-10-13'),
       (68, 356, 'シンデレラ・シェフ〜萌妻食神〜 第1期',
        'animations/68/images/aa46e773-2183-43c9-9d93-6b4e84402d02.webp',
        '現代でグルメ雑誌の編集者として働く料理一家の娘・葉佳瑶（イエ・ジアヤオ）は、ある日突然、ひょんなことから大昔へとタイムスリップ。 目を覚ますと、なんと山賊・夏淳于（シア・チュンユー）の“花嫁”になっていた――。 正体不明の花嫁に警戒する夏淳于。だが、葉佳瑶の突き抜ける明るさとスゴ技から繰り出される絶品料理が、少しずつ彼の心をほどいていく。',
        NULL, 0, 0, 0, NULL),
       (69, 435, '元祖！バンドリちゃん',
        'animations/69/images/8cf38126-a270-4f90-a525-5042ea9ca8d3.webp',
        'ガールズバンド世界を席巻したあの「バンドリちゃん」が帰ってきた！？ ポップでキュートなバンドメンバー大集結、 アバンギャルドな魅力いっぱいの痛快ガールズバンドコメディ！ こっちにおいでよバンドリちゃん 君も私もバンドリちゃん！',
        NULL, 0, 0, 0, '2025-10-02'),
       (70, 198, 'コアラ絵日記', 'animations/70/images/fc9f92fc-4732-4444-895d-3f05b5882d75.webp',
        'コアラさんの綴る日常は優しくて、温かくて――。\n失敗して落ち込んだり上手にできた自分に喜んだりひとつひとつの出来事はほんのちっぽけなことだけど。\nうまくいった日も、うまくいかなかった日も特別な記念日も、何気ない日常もすべての日々が愛おしい。\n今日もいい日、明日もいい日。',
        NULL, 0, 0, 0, '2025-10-02'),
       (71, 29, 'キャッツ♥アイ', 'animations/71/images/28cf92f1-8937-45b4-b3d5-40a621b97f44.webp',
        '美術品を狙う謎の三人組の怪盗\nキャッツアイ。\n警視庁捜査一課に所属する刑事 内海俊夫は怪盗キャッツアイを逮捕することに情熱を燃やす。\nしかし、彼とキャッツアイには彼が知らない事実がある。\nそれは、キャッツアイの正体である三姉妹の次女 来生瞳が恋人であること。\nディズニープラス「スター」で2025年9月26日(金)より独占配信',
        NULL, 0, 0, 0, '2025-09-26'),
       (72, 224, '不器用な先輩。', 'animations/72/images/2b8e2127-b3cd-4d4d-8774-b1eeb113c6be.webp',
        '会社内の評価は「せっかく綺麗なのに、厳しい怖い。キツイ。」のOLの鉄輪。 人付き合いが苦手な鉄輪は、今年入社した新入社員亀川の教育係に任命される。 亀川の為に、教育係として一生懸命振舞う鉄輪だったが… 素直になれないけど、伝えたい気持ちがある…！ 「不器用な年上上司×新入社員」のドギマギ working＆love？コメディ！スタート！',
        NULL, 0, 0, 0, '2025-10-02'),
       (73, 222, '結婚指輪物語Ⅱ', 'animations/73/images/6aa2b3a8-46e7-4fe8-b008-f666f5da9ad1.webp',
        '5 つの指輪を集め深淵王との決戦に挑んだサトウとヒメ達は、あと一歩のところまで深淵王を追い詰めるが、サトウが力尽きてしまい窮地に追い込まれた。間一髪をアラバスタに救われ、一行は一時態勢を整えることに。そこにヒメの妹・モーリオンが突然現れる。\n再び深淵王に立ち向かうため、サトウと姫達はそれぞれが力を付け、絆を深める修行――すなわち「花嫁修業」をすることになった。様々な試練を課され、サトウとヒメは更に仲を深め、ネフリティス・グラナート・サフィール・アンバルとの関係も進展していく。\nサトウ達は次こそ深淵王を破り、平和を掴み取ることができるのか！？\n世界の命運を懸けた「花嫁修業」――異世界新婚ファンタジーが再び始まる',
        2, 0, 0, 0, '2025-10-04'),
       (74, NULL, 'スター・ウォーズ：ビジョンズ Volume 3',
        'animations/74/images/4d98a091-5254-4e41-b928-abd3daf2c69f.webp',
        '10月29日(水)よりディズニープラスにて独占配信中', 3, 0, 0, 0, '2025-10-29'),
       (75, 123, '陛下わたしを忘れてください',
        'animations/75/images/6c93b915-06fe-4b49-829e-981112f4c4f8.webp',
        '「あなたに愛されなくても助けたかった」 ペルセポネー伯爵家の令嬢・ルーニアは、父に疎まれ、異母兄からも道具扱いされ、孤独な日々を送っていた。 そんな中、神官からクロノア公爵家の当主ハーデュスとの婚約者として選ばれ、呪われた公爵家に嫁ぐことを決める。 “冥王”と恐れられるクロノア公爵家には皇帝が選ぶ花嫁と結ばれないと短命になるという呪いがかかっていた。 しかし、ハーデュスはルーニアを愛するつもりはないと告げる。 私は呪いを解くためだけに存在する… ルーニアはハーデュスを生かすため、ハーデュスを騙して一夜を共にし、彼の子を身ごもったとも知らず姿を消した―。 7年後、ハ―デュスはなぜかルーニアを探し出し、子供と一緒に連れ帰ろうとして……',
        NULL, 0, 0, 0, '2025-10-07'),
       (76, NULL, 'スプリンターセル: デスウォッチ',
        'animations/76/images/2053f4f8-91f9-48a8-aa8e-357aade665f8.webp',
        'かつての若さはなくとも、誰もが恐れる戦闘本能は今もなお健在。ベテラン工作員サム・フィッシャーが若きエージェントに協力し、百戦錬磨の経験を武器に世界を襲う危機に立ち向かう。\nNetflixシリーズ『スプリンターセル: デスウォッチ』10月14日(火)より独占配信',
        NULL, 0, 0, 0, '2025-10-14'),
       (77, 91, 'アニラとココラ', 'animations/77/images/19380d3b-7885-4002-ae1a-fbcc2041853e.webp',
        'かつては日本中の水族館や動物園で飼育され、一世を風靡したラッコたち。\nしかし、現在では飼育数はどんどん減っており、日常の中でラッコに触れ合う機会も激減。\nあの愛くるしいラッコの姿を心に刻み、心の中で元気に生きてもらいたいという願いを込めて、なんとラッコの擬人化アニメが登場！アニラとココラという仲良しラッコ兄弟が織りなす、カッコよさとかわいさが同居する癒しの水族館ライフをぜひ覗き見してください！',
        NULL, 0, 0, 0, '2025-10-02'),
       (78, NULL, 'ホーンテッド・ホテル',
        'animations/78/images/f6562459-fd99-4c8a-b445-b6c3b2b0aa7a.webp',
        '亡くなった兄からホテルを相続し、経営することになったシングルマザー。そこには善良な兄の幽霊と、永遠にチェックアウトすることのない面倒な宿泊客たちが住んでいた...。\nNetflixシリーズ『ホーンテッド・ホテル』9月19日(金)より独占配信',
        NULL, 0, 0, 0, '2025-09-19'),
       (79, 79, '科学×冒険サバイバル！ 第2シリーズ',
        'animations/79/images/ec15fdc4-f2fc-4843-8061-0c8f213581ef.webp',
        '大人気の「科学漫画サバイバル」シリーズがテレビアニメ化！ どんな困難に立たされても「絶対にあきらめない！」と奮闘する、“サバイバルの達人”ジオたちと、“サバイバルの天才”ダイヤたちが、仲間とともに“勇気”と“科学”でピンチに立ち向かう！',
        2, 0, 0, 0, '2025-10-04'),
       (80, 343, 'シルバニアファミリー フレアのワンダーデイズ',
        'animations/80/images/20a6be3e-9d91-4675-a06c-f6621bc3dafa.webp',
        '物語の舞台は世界のどこかにある”シルバニア村”。\nほがらかでみんなと過ごすのが大すきなショコラウサギの女の子「フレア」と、頭脳明晰でやさしいペルシャネコの女の子「ライラ」、元気いっぱいで忍者に憧れているくるみリスの男の子「ラルフ」の3にんや、赤ちゃんたちが村の中や森の中、ゆうえんちなどで大活躍します！\nシルバニアファミリーの世界で起こるさまざまな出来事を通して、夢や希望をたいせつにする主人公フレアと個性豊かなシルバニアの仲間たちによる心温まるお話をお届けします。',
        NULL, 0, 0, 0, '2025-10-02'),
       (81, NULL, 'マイティ・ナイン',
        'animations/81/images/d8fe4a2b-0250-4b0f-a60a-b02d3fe33909.webp',
        '現実世界をゆがめる力を持つ魔法の遺物が悪の手に渡り、はみ出し者、のけ者、犯罪者が集まって大陸を救うことに。\n11月19日（水）からPrime Videoで独占配信中',
        NULL, 0, 0, 0, '2025-11-19'),
       (82, 173, 'MUZIK TIGER In the Forest 第2期',
        'animations/82/images/a7ba2156-22eb-40aa-8c87-947704e958fd.webp',
        'きれいな湖のあるMUZIK FOREST（ムジークフォレスト）。\nそこにはトラのトフィー、ティフィー、テフィー、ネズミのウィリー、さらに⽉から来たウサギのポルミ、クマのクミ、⼦猫のソピィーやMUZIK FORESTの超⼈気スターのラインオン・サザなど個性豊かな動物たちが暮らしている。\n仕事をしなくてものんびり前向きなトフィーは、今⽇も⾃由気ままに、仲間たちと楽しくも不思議な⽇々を過ごしていく。',
        2, 0, 0, 0, '2025-10-01'),
       (83, 123, '2200年ねこの国ニッポン',
        'animations/83/images/d30ec7bd-c6a5-4a49-a95b-9dab504fbb8e.webp',
        '「2200年、人類の少子化が進んだこの国は――猫の国になりました。」\nこれは猫も話し、学び、働くようになった近未来で暮らす、女子高生と飼い猫の物語。女子高生・麦島さんの飼い猫・ソラは、「麦島さん」と飼い主を苗字・さん付けで呼ぶ。理屈っぽいソラだけど、猫らしく気まぐれなところもあって振り回される麦島さん。でも、人より猫な世界で暮らすのは、思ったより幸せです!!',
        NULL, 0, 0, 0, '2025-10-07'),
       (84, 386, '地球のラテール', 'animations/84/images/32429408-133e-45dd-859d-129efcb257cd.webp',
        NULL, NULL, 0, 0, 0, '2025-09-05'),
       (85, 24, 'SHIBUYA♡HACHI 第4クール', NULL, NULL, 4, 0, 0, 0, '2025-10-04'),
       (86, 52, 'JOCHUM シーズン2',
        'animations/86/images/90d8b101-c13c-4038-88bd-624e9b8bd7c1.webp',
        '人気ショートアニメシリーズ「JOCHUM」のシーズン2が始まります！それぞれの夢を抱いた11にんの仲間たちによる、「ジェオチャムハウス」でのほのぼのとした毎日。時には、奇想天外な出来事も起き、仲間たちの新たなる意外な一面が明らかに。今回もきっと、個性豊かな11にんのキャラクターたちが、あなたを癒してくれるはず！',
        2, 0, 0, 0, '2025-10-04'),
       (87, NULL, 'ミッキーのおっかなびっくりストーリー',
        'animations/87/images/8d050d97-27af-43a0-8d23-7a537b3ca531.webp',
        'ミッキーと仲間たちが楽しいハロウィーンの物語を披露する。\nディズニープラスで10月1日（水）より見放題独占配信中。',
        NULL, 0, 0, 0, '2025-10-01'),
       (88, NULL, 'LEGO マーベル／アベンジャーズ ストレンジ・テイルズ',
        'animations/88/images/feb39908-c780-4ae7-bd5e-40262bc6681e.webp',
        'LEGO マーベルシリーズの新シリーズが登場！ホークアイとアベンジャーズは、簡単に世界を救う姿見せてきた。しかし今、彼らはこれまでで最も手強い脅威に直面している――それはソーシャルメディア。世界を救うために、ヒーローたちは新たなチームを結成しなければならない。彼らが立ち向かうのは、破滅的な影響力を持つインフルエンサーだ。',
        NULL, 0, 0, 0, '2025-11-14'),
       (89, NULL, 'ジュラシック･ワールド/サバイバル・ミッション: シーズン4',
        'animations/89/images/7ee2a9c2-2117-49e0-bdab-4be65684b64b.webp', 'Netflixで配信中', 4, 0,
        0, 0, '2025-11-20'),
       (90, NULL, 'トゥームレイダー: レジェンド・オブ・ララ・クロフト シーズン2',
        'animations/90/images/0025725b-208a-4985-ba88-c9aac276e04d.webp',
        '古代アフリカの遺物を追って世界を駆け巡るララ・クロフト。遺物の力で神の座を狙う強敵を前に、世界を救えるのか!?\nNetflixで2025年12月11日より配信中',
        2, 0, 0, 0, '2025-12-11'),
       (91, NULL, 'ミッキーとミニーの クリスマス・キャロル',
        'animations/91/images/98563f5c-6f2d-4ff3-869d-b57816aba883.webp',
        'ミッキーとミニーのホリデーアニメーション。この季節はミッキー、ミニー、サンタ、そして彼らの仲間たちと共に陽気なストップモーション短編で歌って楽しもう！最高の５人組がホリデー気分を盛り上げる。\n「ジングル･ベル」でそりを楽しみ、「デック･ザ･ホールズ」に合わせてミッキーのキャビンを飾りつけ。町のツリーを囲んで「ウィ･ウィッシュ･ユー･ア･メリー･クリスマス」を歌い、サンタのワークショップで「12 デイズ･オブ･クリスマス」をパフォーマンス。そして北極のディスコ･パーティーで彼らを象徴する「ホットドッグ！クリスマス」を思いきり踊って締めくくる。\nディズニープラスにて12月3日（水）より独占配信開始',
        NULL, 0, 0, 0, '2025-12-03'),
       (92, NULL, 'ワンダラ シーズン3',
        'animations/92/images/e900fd5f-ad1f-4a83-9449-a909555dcf0b.webp', NULL, 3, 0, 0, 0,
        '2025-11-26'),
       (93, NULL, 'バッドガイズ: いざ侵入',
        'animations/93/images/495d9974-624d-41aa-9688-f91ca58419f7.webp',
        'そもそも、バッドガイズはいかにしてワルの世界に足を踏み入れたのか? 人気映画シリーズでは語られなかった原点を描く、とにかく笑える前日譚(たん)アニメシリーズ。\nNetflixで2025年11月6日より配信中',
        NULL, 0, 0, 0, '2025-11-06'),
       (94, NULL, 'スター・ウォーズ：ヤング・ジェダイ・アドベンチャー シーズン3',
        'animations/94/images/a5155932-d552-41ad-8a89-c3e87ea3c129.webp',
        '「ファントム・メナス（エピソード 1）」の数百年前の銀河系を舞台に、若きジェダイたちの大冒険を描くアニメーション・シリーズのシーズン 3！フォースの使い方を学び、海賊団の暴動を阻止した仲良し３人組のカイ、リス、ナブス。彼らは銀河の冒険を続け、新たにドロイドの仲間たちとチームを組み、厄介で優れたドロイド職人のレクと対決する！\nディズニープラスにて12月8日（月）より独占配信中',
        3, 0, 0, 0, '2025-12-08'),
       (95, NULL, 'ちびっこホートンのだいぼうけん',
        'animations/95/images/651df438-5629-4db1-b5e5-c1f511e93476.webp',
        '「ちびっこホートンのだいぼうけん」は、子ゾウのホートンと小鳥の親友サムソンの物語。ジャングルヌールの仲間の力になるために、ウキウキワクワクの冒険へ出発だ!\nNetflixで2025年10月6日から配信中',
        NULL, 0, 0, 0, '2025-10-06'),
       (96, NULL, '銀河特急 ミルキー☆サブウェイ',
        'animations/96/images/4a009922-34cc-43d2-9e7e-a94cafbedc94.webp',
        '銀河道路交通法違反で逮捕された強化⼈間のチハルとサイボーグのマキナ。\n同じタイミングで警察に捕まった、強化⼈間のアカネとカナタ、サイボーグのカートとマックスらクセのあるコンビを集め、警察官・リョーコが全員に課したのは、奉仕活動として惑星間⾛⾏列⾞・通称\"ミルキー☆サブウェイ\"の清掃をすること。\n簡単な任務だったはずが、突如暴⾛し始める\"ミルキー☆サブウェイ\"︕⾞内で慌てふためくメンバーたちは、やがて⼤事件に巻き込まれていってしまう︕\n意図なし︕主義なし︕主張なし︕\nノリで乗り切る前代未聞のスペーストレインスペクタクル︕︕',
        NULL, 0, 0, 0, '2025-07-03'),
       (97, 482, 'タコピーの原罪', 'animations/97/images/c47c7f1f-a8ef-445d-91c9-65b4f75e0576.webp',
        'ハッピーを広めるため地球に降り立ったハッピー星人のタコピーは人間の女の子しずかと出会う。 ピンチを救ってもらったタコピーはしずかの笑顔を取り戻すため不思議な力を持つハッピー道具で奔走する。 しかし、しずかはおうちと学校で何か事情を抱えているようで…。 これは、ぼくときみの最高にハッピーな物語――',
        NULL, 0, 0, 0, '2025-06-28'),
       (98, 143, '光が死んだ夏', 'animations/98/images/93396c96-0baa-42e5-b0a9-67eeb0881d45.webp',
        'とある集落で幼い頃からずっと一緒に育ってきた同い年のよしきと光\n照りつける太陽耳にこびりつくクマゼミの声帰り道に食べるアイス\n他愛もないことで笑い合ういつもと変わらない夏のある日\n「……お前、やっぱ光ちゃうやろ」\n半年前、山で行方不明になった光は一週間後ふらりと帰ってきた声も姿も光に見えるモノその中に蠢いていたのは――\n「光はもうおらんのや……それやったら」\n友人の姿をした〝ナニカ〟と歩みだす、“いつもと変わらない”日常だが、時を同じくして奇怪な事件が集落を襲い始める\n未知の〝ナニカ〟へ墜ちていく青春ホラー物語の幕が、今、上がる――',
        1, 0, 0, 0, '2025-07-05'),
       (99, 58, '薫る花は凛と咲く',
        'animations/99/images/cae7830c-5631-462a-acde-5899601c121e.webp',
        '─カーテンの向こう側。 俺には一生関係ない世界だ─ バカが集まる底辺男子校・千鳥は、由緒正しきお嬢様校・桔梗女子に嫌われている。 常にカーテンが閉まり、隣り合う校舎の教室は一度も見たことがない。 千鳥に通う紬凛太郎はいつも見かけで怖い人だと判断され、敬遠されることからいつしか人と距離を取るようになっていた。 ある日、実家のケーキ屋を手伝い中にお客として来ていた薫子と出会う。 「凛太郎くんを怖いって思ったこと、一回もなかったですよ？」 凛太郎に偏見を持たず接する薫子との時間を戸惑いつつも心地よく感じ始める凛太郎だったが、彼女は桔梗の生徒で……。 “近くて遠い”二人が織りなす、鮮やかな青春彩る学園物語。',
        NULL, 0, 0, 0, '2025-07-05'),
       (100, 32, 'ガチアクタ', 'animations/100/images/9e9c5301-5d30-4ee4-93ed-cf8ab80e3deb.webp',
        '『ガチアクタ』は犯罪者の子孫たちが暮らすスラム街に生まれた孤児の少年・ルドを主人公にしたバトルアクション。 スラム街で生きる人間たちは、境界線の向こうの人々から“族民”とさげすまれ差別を受けながら生活している。 そんな世界でルドは、育ての親であるレグトとともに、“ゴミ場荒らし”と呼ばれながらも常人離れした身体能力を武器に生計を立てていた。 だがある日、身に覚えのない罪を着せられ、誰もが恐れる「奈落」へと落とされてしまう。',
        NULL, 0, 0, 0, '2025-07-06'),
       (101, 21, 'SAKAMOTO DAYS 第2クール',
        'animations/101/images/5f82b471-d4c1-4a6f-8bce-368c48a50274.webp', NULL, 2, 0, 0, 0,
        '2025-07-14'),
       (102, 37, '夢中さ、きみに。',
        'animations/102/images/18c1ad07-f283-4a07-b04d-2c757eab3d0b.webp',
        '中高一貫の男子校に通う江間譲二は、体育祭がきっかけで風変わりなクラスメート・林美良から変な絡まれ方をされるようになる。 共学高校に通う目高優一は、校内で忌み嫌われている不気味キャラ・二階堂明が後ろの席になり、憂鬱な気分を抱えていた……。 思春期ならではの人間模様が織りなすオムニバス・ストーリー。',
        NULL, 0, 0, 0, '2025-08-21'),
       (103, 110, 'ダンダダン 第2期',
        'animations/103/images/6a96793b-353a-49d4-8528-a939eef3ddfe.webp',
        '霊媒師の家系に生まれた女子高生・モモ＜綾瀬桃＞と、同級生でオカルトマニアのオカルン＜高倉健＞。 モモがクラスのいじめっ子からオカルンを助けたことをきっかけに話すようになった2人だったが、「幽霊は信じているが宇宙人否定派」のモモと、「宇宙人は信じているが幽霊否定派」のオカルンで口論に。 互いに否定する宇宙人と幽霊を信じさせるため、モモはUFOスポットの病院廃墟へ、オカルンは心霊スポットのトンネルへ。 そこで2人は、理解を超越した圧倒的怪奇に出会う。 窮地の中で秘めた力を覚醒させるモモと、呪いの力を手にしたオカルンが、迫りくる怪奇に挑む！ 運命の恋も始まる！？ オカルティックバトル＆青春物語、開幕！',
        2, 0, 0, 0, '2025-07-03'),
       (104, 45, '桃源暗鬼', 'animations/104/images/55db3282-f7f2-4bd7-a019-ea13dc1b0e6f.webp',
        '「お前は鬼の血を継いでいる……」　 一部の人間に脈々と受け継がれる「鬼」と「桃太郎」の血。 はるか昔、自らの凶暴性を自覚するが故にひっそりと暮らしていた「鬼」だったが、 そこに「桃太郎」が攻め入った。 それぞれが「桃太郎機関」「鬼機関」を組織し、抗争すること何千年。 突然の“桃太郎”の襲撃で、自分が“鬼”だと知る主人公・一ノ瀬四季。 自らの血に棲む“鬼”と出逢った四季の宿命とは———。 ———新世代ダークヒーロー鬼譚、ここに開幕！',
        NULL, 0, 0, 0, '2025-07-11'),
       (105, 21, 'Dr.STONE SCIENCE FUTURE 第2クール',
        'animations/105/images/aae42abc-bf6a-4138-8336-db66564e6da6.webp',
        '人類石化の黒幕・ホワイマンが月にいると突き止めた千空は、全ての謎を暴くため『月面着陸計画』を始動！\nこので、ゼロから宇宙船を作るビックプロジェクトへと乗り出した。\n早速、世界中から宇宙船の素材を集めるため、大海原へと飛び出した千空たち。\n最初の目的地・アメリカに降り立つと、そこには Dr.ゼノ率いる高度な科学王国が存在していた！\n互いにリーダーを狙いあう科学 vs.科学の速攻戦で、Dr.ゼノを捕らえたクロムたち。\nスタンリーの猛追をかわしながら、次に目指すのは、あの忌まわしき石化光線の発信源――南米大陸‼\n石化装置“メデューサ”の秘密に挑みながら、全力クラフトでアマゾンを駆け抜ける千空たち。\nスタンリー部隊の魔の手が迫る中、千空と科学王国の仲間たちは、科学の灯を繋ぎ、ついにメデューサの核心に迫る――!!',
        6, 0, 0, 0, '2025-07-10'),
       (106, 58, 'その着せ替え人形は恋をする Season 2',
        'animations/106/images/976cd397-c54c-4688-89ad-621b3f5e7e52.webp',
        'ある日の出会いをきっかけに、コスプレを通して交流を深めていく喜多川海夢まりんと五条新菜わかな。\nまだまだやりたいコスプレ、作りたい衣装はいっぱい。\nクラスメイトたちとの交流や、新しいコスプレ仲間たちとの出会いの中で、\n海夢と新菜の世界はさらに広がっていく。\nそして、新菜にドキドキのとまらない海夢の恋に進展はあるのか―！？',
        2, 0, 0, 0, '2025-07-05'),
       (107, 25, '怪獣８号 第2期', 'animations/107/images/2ad8faca-d3c4-41d0-99d9-90ba0da70d22.webp',
        '防衛隊長官・四ノ宮功の判断により兵器化を免れるも、身柄を拘束されたままの日比野カフカ。 異動命令が下った第３部隊の新人たちがそれぞれの任務先へ向かうなか、彼の前に現れたのは、第１部隊を率いる防衛隊最強の男・鳴海弦だった。隊員としてのカフカを必要としない鳴海に対し、自身の力を認めさせるため「怪獣８号」の強大すぎる力と向き合うことになるカフカ。 しかしその陰では、「怪獣９号」の脅威が迫っていた…。継承される意志と力、新たな識別怪獣兵器（ナンバーズ）適合者の誕生、そして防衛隊を襲う史上最大の危機が訪れる――。',
        2, 0, 0, 0, '2025-07-19'),
       (108, 68, 'サイレント・ウィッチ 沈黙の魔女の隠しごと',
        'animations/108/images/3d622cce-77fe-4899-92b0-80eb7163029c.webp',
        '人類は詠唱をなくして、魔術を使うことができない。 ところが、その不可能を可能にしてしまった、ひとりの少女がいた。 リディル王国における魔術師の頂点・七賢人がひとり〈沈黙の魔女〉モニカ・エヴァレット。 史上、初めて無詠唱魔術を生み出した若き天才である。 しかし… 極度の人見知りであがり症の彼女は、使い魔の黒猫と山奥に引きこもり、 数式の本に囲まれて、ひっそりと魔術の研究に打ち込んでいた。 そんな彼女のもとに、七賢人の同僚である〈結界の魔術師〉ルイス・ミラーが訪ねてくる。 戸惑う彼女にルイスはひとつの王命を告げた。 それは――貴族の集う名門校に潜入し、第二王子を護衛する極秘任務だった……。 魔術と数字を偏愛する〈沈黙の魔女〉モニカのひそやかな活躍が始まる！',
        NULL, 0, 0, 0, '2025-07-04'),
       (109, 37, 'カラオケ行こ！', 'animations/109/images/33bfaa84-35b3-4644-8842-f2ee98f8d9e2.webp',
        '合唱部の部長・岡 聡実は、突如現れたヤクザ・成田狂児から声をかけられる――「カラオケ行こ！」。 彼の組では恒例のカラオケ大会があり、そこで歌ヘタ王になると組長に微妙な刺青を入れられる掟があった。 狂児に歌唱指導を頼まれ、仕方なく練習に付き合わされる聡実。 カラオケで繋がった二人の奇妙な関係の行方は……！？',
        NULL, 0, 0, 0, '2025-07-24'),
       (110, 198, 'わたしが恋人になれるわけないじゃん、ムリムリ！（※ムリじゃなかった!?）',
        'animations/110/images/42a7a7ca-429e-4469-95d6-7d7fce50d1d1.webp',
        '「勝ち取るんだ最高の学園生活を！」 ぼっちな中学生時代から変わるため、高校デビューを果たした甘織れな子。 しかし根が陰キャ気質のせいで、憧れの陽キャ生活に馴染めず窒息寸前に…。 現役モデルの完璧美少女、王塚真唯 優しくてふわふわ天使の、瀬名紫陽花 いつもクールな黒髪美人、琴紗月 賑やかなムードメーカー、小柳香穂 憧れの人たちに近づくために、きょうもがんばる甘織れな子。 だったはずが──。 「君に恋をしてしまったんだ…」 「待って！ 友達どこいった！？」 友達？ 恋人？ 揺れ動く気持ちの間で、笑い、悩み、そして進め！ 乙女たち。 ノンストップ・青春ガールズラブコメディ、ここに開幕！',
        1, 0, 0, 0, '2025-07-07'),
       (111, 58, '青春ブタ野郎はサンタクロースの夢を見ない',
        'animations/111/images/4d64e47e-47cd-47a1-8331-c0d38ce73b4a.webp',
        '思春期症候群―― 不安定な精神状態によって引き起こされると噂の不思議現象。 高校時代に様々な思春期症候群を発症した少女たちに出会ってきた“梓川咲太”も大学生になった。 国民的人気女優であり、恋人の“桜島麻衣”と共に金沢八景にある大学に進学した彼は、校内で季節外れのミニスカサンタを見つけた。 驚いた。わたしのこと見えてるんだ。 どこかで聞いたような台詞。 思春期症候群をプレゼントしていると話すミニスカサンタは、咲太に告げる。 ……わたしはね、霧島透子って言うの SNSで流行する予知夢、正体不明のネットシンガー、ポルターガイスト、謎めく現象と共に、心揺れる少女たちとの不可思議な物語が再び始まる。 思春期は終わらない――',
        NULL, 0, 0, 0, '2025-07-05'),
       (112, 29, 'よふかしのうた Season2',
        'animations/112/images/9075b28f-2d47-4dfd-94e0-6f1372bdaa8d.webp',
        '「夜はまだ終わらない」 吸血鬼になることへの戸惑いを乗り越え、ナズナを“好き”になることを決めたコウと、コウに“惚れさせる”決意をしたナズナ。「恋」が一体なんなのか、わからないまま二人の夜は加速していく。 吸血鬼を殺そうと企む探偵・鶯餡子の手が、すぐそこまで迫る。吸血鬼の弱点は「人間時代に思い入れの強かったもの」。その弱点を予め処分しようとするが、ナズナには人間時代の記憶が一切ない。ナズナの隠された過去とは？なぜ餡子は吸血鬼を殺すようになったのか？ そして、ナズナと餡子に交錯する“秘密”とは――？ コウ、ナズナ、餡子…… 楽しい「よふかし」では終わらない、新たな“夜”がはじまる！',
        2, 0, 0, 0, '2025-07-04'),
       (113, 166, '瑠璃の宝石', 'animations/113/images/091dcd90-c0cc-4131-bbf0-b50b479592f2.webp',
        'キラキラしたものが大好きな女子高生・谷川瑠璃（タニガワルリ）は、「自分でも見つけられるかも！」と水晶を探しに山へと向かう。そこで鉱物学を専攻する大学院生・荒砥凪（アラトナギ）と出会い、一緒に鉱物採集をすることに。 ある時は水晶を探して山道を歩き、ある時はガーネットを拾いに川に浸かり、またある時は見知らぬ鉱物を顕微鏡で覗き――ルリはナギに導かれ鉱物採集の世界に飛び込んでいく。 「私だって、採れるはず」 それは、誰しもが抱いたことのある夢。 本格サイエンスアドベンチャー始動！',
        NULL, 0, 0, 0, '2025-07-06'),
       (114, 71, 'ぐらんぶる Season 2',
        'animations/114/images/5776a5fc-dcad-4459-9fa6-030182319ad4.webp',
        '俺たちの夏は終わらない！ 北原伊織が伊豆で大学生活を始めて早三ヶ月― 居候しているダイビングショップ「グランブルー」ではかわいい従妹の古手川千紗と一つ屋根の下。そこに従姉の古手川奈々華、オトナの色気がたまらない浜岡梓、同級生の吉原愛菜も加わって、順風満帆な青春のキャンパスライフを過ごしていた！ ……というのは一面で、大学生活の大半は全裸野郎どもとの狂乱騒ぎ！ というのも、伊織が入ったダイビングサークル「Peek a Boo（ピーカブー）」は、ダイビングはそこそこに屈強な男達が全裸になって酒を酌み交わすバカ騒ぎを日常としており、伊織はイケメンだが真性オタクの今村耕平と共に、すっかりサークルに染まっていたのだ。 そんな中、沖縄でのダイビングライセンス講習を終え、伊豆へと戻ってきた伊織の元に妹・栞からの手紙が届く…… 妹の襲来、青梅女子大の学園祭、肝試しにデートに無人島キャンプ！ 愛すべき全裸野郎どもに囲まれた伊織の大学生活が再び始まる！！',
        2, 0, 0, 0, '2025-07-07'),
       (115, 21, '彼女、お借りします 第4期',
        'animations/115/images/ff6d5b1b-9e3f-4ef7-a66e-70b40d1958d1.webp',
        '清楚可憐な“レンタル”彼女（レンカノ）・水原千鶴のことを 家族にも友人にも“本当”の彼女だと紹介してしまった、 ダメダメ大学生・木ノ下和也。 嘘だと言い出せないまま“偽り”の関係を続ける和也は、 さまざまなイベントを一緒に乗り越えるなかで、 次第に千鶴への“本物”の想いを募らせていく。 映画制作のクラウドファンディングを無事成功させ、 ついに和也は千鶴への“覚悟”を決める。 一方、やや強引なところがある彼女（仮）・更科瑠夏が、 これまで以上に超積極的に和也に迫る……！ さらに、和也と千鶴の“本当”の関係を知る小悪魔的な元カノ・七海麻美が 千鶴に急接近する、緊迫した事態も発生！？ 周囲を巻き込み、物語はますますヒートアップ！ そして、舞台はハワイアンズへ！！',
        4, 0, 0, 0, '2025-07-04'),
       (116, 165, '雨と君と', 'animations/116/images/ef55084f-6e73-428e-abb0-7390cfb3b746.webp',
        'ずぶ濡れの帰り道、藤は少し変わった「犬」に出会う。 犬はフリップを使って「拾ってください」とアピールし、 藤に折り畳み傘を差し出す。 でもこの犬、変わっているというよりも……？ なんてことない毎日に現れたちょっとおかしな相棒 一緒に四季を感じながら 食べたり、おでかけしたり、おしゃべり（？）したり… “あともうちょっと”がほっこり尊い 1人と1匹のたぶん、なかよしなふたり暮らし。',
        NULL, 0, 0, 0, '2025-07-05'),
       (117, 274, '転生したら第七王子だったので、気ままに魔術を極めます 第2期',
        'animations/117/images/70c75e65-dd66-4fde-92d4-038c26563d34.webp',
        '魔術に大切なものは、“家柄”・“才能”・“努力”……。\n魔術を深く愛しながらも、血筋と才能に恵まれずに非業の死を遂げた“凡人”の魔術師。\n死の間際に「もっと魔術を極め、学びたかった」と念じた男が転生したのは、\n強い魔術の血統を持つサルーム王国の第七王子・ロイドだった。\n過去の記憶はそのままに、完璧な血筋と才能を備えながら生まれ変わった彼は、\n前世では成しえなかった想いを胸に、\n桁外れの魔力で“気ままに魔術を極める”無双ライフをエンジョイする！\nロードスト領でのギザルムとの戦いで見事勝利したロイド達。\n魔術への探求心が止まらないロイドが次に目を付けたのは『神聖魔術』！\n神聖魔術を習うため、教会を訪れるロイド達だが……？',
        2, 0, 0, 0, '2025-07-09'),
       (118, 30, 'ブスに花束を。', 'animations/118/images/f978668e-d863-42fa-a09a-2e56f37ce032.webp',
        '甘酸っぱい少女漫画みたいな恋はきっと私には訪れない… なぜなら私は―― 自分の容姿に自信がない非モテな女子高校生・田端 花。 少女漫画のような恋愛に憧れている花だったが、 ネガティブ思考全開な彼女は、いつも教室の片隅でひっそりと過ごしていた。 そんな彼女の高校生活は、 早朝の教室でスクールカースト最上位のイケメン・上野陽介に “恥ずかしい姿”を目撃されたことで変化が！ 教室での一件を機に陽介、さらにクラスメイトたちと交流することになり、 花の周囲は次第に賑やかに！ ボッチ喪女JKに春が訪れる……予感！？ ギャグのちギャグ、たまに胸キュンの 新型スクールラブコメディ、開校！！',
        NULL, 0, 0, 0, '2025-07-04'),
       (119, 396, 'My Melody & Kuromi',
        'animations/119/images/8be75300-f6e5-407a-8258-024869c72916.webp',
        'マリーランドでケーキ屋を開いたマイメロディ。森でハートに出会ってから、マイメロディの周りでは不思議なことが起こるようになっていた。\n一方、マイメロディのお店の向かいにあるクロミの和菓子屋はいつもガラガラ。クロミはマイメロディのケーキの秘密を探りたがっている。人気パティシエのピスタチオが審査をするスイーツコンテストに向けて張り切るマイメロディとクロミ。マリーランドの運命を揺るがす出来事が起こるとは誰も知らずにーー\nNetflixシリーズ「My Melody & Kuromi」7月24日（木）より世界独占配信',
        NULL, 0, 0, 0, '2025-07-24'),
       (120, 126,
        '勇者パーティーを追放された白魔導師、Sランク冒険者に拾われる ～この白魔導師が規格外すぎる～',
        'animations/120/images/6e1f0d86-8336-4d57-969e-dd5826548198.webp',
        '「実力不足の白魔導師は要らない」 白魔導師であるロイドはある日突然クビを言い渡され、勇者パーティーを追放されてしまう。 途方に暮れていたロイドだったが、たまたま白魔導師を探していたSランク冒険者のパーティーと出会い、クエストに同行することになる。 この時はまだ、勇者パーティーが崩壊し、ロイドが名声を得ていくことを知る者はいなかった――。 これは、自分を普通だと思い込んでいる、規格外の支援魔法の使い手が冒険者になり、無自覚に無双する物語。',
        NULL, 0, 0, 0, '2025-07-10'),
       (121, 154, 'カッコウの許嫁 Season2',
        'animations/121/images/778d7fe5-3efa-4e69-b531-cc664cd48036.webp',
        '海野凪と天野エリカ。同じ日に生まれた二人は、赤ちゃんの頃に取り違えられた子ども同士。 定食屋の息子とホテル王の娘として育った二人は、育てと生みの両親たちのススメで、許嫁関係となることに。 ひとつ屋根の下で同居を始めた二人の生活は、クラスメイトの瀬川ひろや兄を追って来た海野幸たちも巻き込んでいく。 許嫁、想い人、血の繋がらない妹。凪を巡るちぐはぐな“四角関係”へ、今度は初恋の幼なじみがやって来る！？ 人生とラブが大交錯！「取り違え子」から始まる“五角関係”ラブコメディー！ この夏に、運命はさらに大きく動き出す！',
        2, 0, 0, 0, '2025-07-08'),
       (122, 68, '自動販売機に生まれ変わった俺は迷宮を彷徨う 2nd season',
        'animations/122/images/da0cfb35-f3cc-47da-a9bb-b7b2298121c0.webp',
        '俺が転生したのは……なんと「自動販売機」！？ 前代未聞のあったか～い自販機アニメが、波乱の新章へ突入！ 圧倒的な力を持つ冥府の王を前に、 なんとか生き延びた自動販売機「ハッコン」たちは、 ハンター協会の会長たちとともに冥府の王を討伐するべく立ち上がった。 冥府の王と再び対峙した時、 悲劇が起きるーー。 元・自販機マニアの知識と、 新しい仲間との出会い、新しいフォルムチェンジの力で、 ハッコンたちは冥府の王を倒すことができるのか！？',
        2, 0, 0, 0, '2025-07-02'),
       (123, 56, '地縛少年花子くん２ 後編',
        'animations/123/images/0f273dd8-9c6b-4fa7-8951-0995fa7a7833.webp',
        'ねえ、知ってる？\nかもめ学園の七不思議、七番目の噂話。\n旧校舎3階の女子トイレ。\nそこには花子さんがいて、何かひとつを代償に呼び出した人の願いを叶えてくれる。\n呼び出し方はノックを3回。\nそして――\n「花子さん、花子さん、いらっしゃいますか？」\n七不思議七番目『トイレの花子さん』こと“花子くん”と縁を結んだ少女・八尋寧々。祓い屋の少年・源 光。\n2人は花子くんと共に、改変された七不思議や怪異たちの噂を元に戻すため、日々奔走していた。\n七不思議『三人の時計守』から端を発したトラブルや、『美術室のシジマさん』が創造した偽物の世界からの脱出を経て\n寧々は自身の寿命について、真実を知る。\n混沌とした気持ちのまま、かもめ学園の伝統行事である宿泊学習に参加することに。\n誰にも聴こえない笛の音…眠る人の魂を掴まえにくる死神の噂…\n新たな七不思議とともに、再び物語は動き出す――。',
        3, 0, 0, 0, '2025-07-06'),
       (124, 36, '出禁のモグラ', 'animations/124/images/d49bdfb3-4f3e-40ca-9c2f-aea4db2ee983.webp',
        '「俺 あの世から出禁くらってるから 死なねぇんだ」 あることから、あの世から出禁をくらっており、あの世に還ることを目指し幽霊が持つ「灯」をカンテラに集めている怪しい“自称仙人”モグラ＜百暗桃弓木＞。 彼と出会うと妙なものが見えるようになるらしい―。 「鬼灯の冷徹」の江口夏実が、「人」と「霊」が交わる“この世”の不可思議を怪しくおかしく描き出す。 世にも不死議な物語の幕が開く！',
        NULL, 0, 0, 0, '2025-07-07'),
       (125, 281, 'Turkey!', 'animations/125/images/495efb2a-1b0d-43a6-8216-57410d9d9c9a.webp',
        '──あなたは信じてくれるかな？不思議で、愛しくて、切なくて、大切な、 楽しいだけじゃ語れない、私達の物語── Turkey（ターキー）……ボウリング用語で、3回連続でストライクを取ること。 一刻館高校ボウリング部の部長、高校2年生の麻衣は、試合に勝てない天才。 Turkeyを取ると、なぜかそのあと必ず、難攻不落のスプリット、スネークアイを出してしまう。 そんな麻衣に、唯一の1年生部員、利奈が言った。「わざとでしょ」 「部長は勝つことから逃げてる。私は勝ちたい。勝つ気がないなら退部する」── これは、麻衣、利奈、さゆり、希、七瀬……5人の一刻館高校ボウリング部員たちが、負けて戦い、負けて戦い、そして勝つまでの、夏の終わりの物語。',
        NULL, 0, 0, 0, '2025-07-08'),
       (126, 61, '盾の勇者の成り上がり Season 4',
        'animations/126/images/23885098-821e-4620-939b-9eb57f9ffe72.webp',
        '復活間近の四霊「鳳凰」との戦いに備える盾の勇者・岩谷尚文は、 反目し合う四聖勇者の力を合わせるべく、 三勇者と対峙し、そして和解へと至った。 しかしラフタリアが、 誤解から王位を継承する意識ありと認識され… クテンロウという国の刺客に命を狙われてしまう。 尚文はクテンロウと話をつけるため、 唯一連絡船の出ている、亜人の国シルトヴェルトを訪れる。 盾の勇者を信仰する亜人たちに熱烈に歓迎されるが、 シルトヴェルトも一枚岩ではなく、尚文一行を歓迎しない者もいた。 そして、クテンロウもまた政情不安を抱え、 ラフタリアが革命の旗印に祭り上げられていく。 混迷を極める情勢の中、 尚文は仲間を導く光となるか――。',
        4, 0, 0, 0, '2025-07-09'),
       (127, 51, '帝乃三姉妹は案外、チョロい。',
        'animations/127/images/c4568103-9b88-4484-8e57-0da053fe9752.webp',
        '文武芸、3つの才能を併せ持つ国民的大女優、綾世昴。 彼女を母に持った息子、綾世優はなにをやっても平均以下の凡人だった！ 勝手に期待されて、勝手にがっかりされる……。 そんな人生を歩んできた優は、 唯一の家族だった母が亡くなり、知人の家に預けられることに。 その家には、芸能科・体育科・進学科が備わる超名門・才華学園で、 各学科トップの成績を修め『三帝』と呼ばれている帝乃三姉妹が！？ 天才三姉妹との同居生活をスタートさせるも、優をポンコツ呼ばわりし見下す三姉妹。 しかし「幸せな家族を作って」という母からの最期の願いを叶えるべく努力する優の姿に、 三姉妹は次第に心を動かされ――。 一つ屋根の下、天才・帝乃三姉妹と凡人・綾世優が“家族”になるまでのお話。',
        NULL, 0, 0, 0, '2025-07-09'),
       (128, 135, '水属性の魔法使い',
        'animations/128/images/67ca9911-1971-4ca1-8613-25c60cc9e09d.webp',
        '「＜水よ来たれ！＞」異世界に転生した青年・涼のコップ一杯の水から始まるスローライフ――それは常に死と隣り合わせの日常だった！？ 首なし騎士との剣戟、アサシンホークの襲撃、ドラゴンとの邂逅と慌ただしい日々を過ごしながら気づけば二十年、いつしか人類最高峰の魔法使いに到達！やがて、天才剣士アベルとの出会いが涼を歴史の表舞台へと引き上げていく……。 マイペースすぎる最強水魔法使いの気ままな冒険譚、開幕！',
        NULL, 0, 0, 0, '2025-07-03'),
       (129, 227, 'フードコートで、また明日。',
        'animations/129/images/644b587e-1e6f-443f-928e-b1e4add130fb.webp',
        '話しかけ難い雰囲気を漂わせる和田と、 ギャルのような見た目で周囲から恐れられている山本。 クラスではそれぞれ一人きりで過ごす和田と山本は、 別々の高校に通っているものの、 毎日のようにショッピングセンターのフードコートに集まっている。 と言っても、何をするでもなく、ただただ、たわいもない話をして、 笑ったり、泣いたり、怒ったり…… 。 そんな二人のゆるい放課後を、少し覗いてみませんか？',
        NULL, 0, 0, 0, '2025-07-07'),
       (130, 22, 'ニャイト・オブ・ザ・リビングキャット',
        'animations/130/images/a1927316-6b48-4eb5-a3b5-c3b73b5ba676.webp',
        '逃げろ、可愛い猫が来た。 20XX年、世界は猫に支配された。 猫に触れた人間を猫に変えてしまうウィルスにより、全世界で“ニャンデミック”が発生。 人々は猫にモフられ、次々と猫になっていく。 果たして人類は猫に触りたい誘惑に抗い、猫だらけの世界を生き抜くことができるのか。 すべてが猫になる――。衝撃のサバイバル・ネコメディ開幕！',
        NULL, 0, 0, 0, '2025-07-07'),
       (131, 75, 'ぬきたし THE ANIMATION',
        'animations/131/images/d7fe62bf-64d6-4d8e-8c17-fe2882ec8b64.webp',
        '常夏の孤島・青藍島（せいらんとう）。\nこの島に生家のある橘淳之介は、両親の死をきっかけに妹・橘麻沙音と共に帰島することになった。\nしかし青藍島は人口減少に待ったをかけるべく施行されたドスケベ条例によって、島中どこでもドスケベセックスが許可・推奨されており、「性産的行為」を拒否すると犯罪に等しい処罰を受けることになってしまう狂気の島であった。\n誇り高き童貞にして処女厨であった淳之介はこの条例に疑問を持ち、自身と愛する妹の純潔を守るべく、反交尾勢力・NLNS(No Love No Sex)を立ち上げ、ドスケベ条例の破壊を目指して動き始める――！\n「俺が…ドスケベ条例をぶっ潰す！」',
        NULL, 0, 0, 0, '2025-07-18'),
       (132, 301, 'おそ松さん 第4期',
        'animations/132/images/acdf5885-6971-413d-9b30-56b80f606667.webp',
        '赤塚不二夫生誕90周年記念作品 TVアニメ「おそ松さん」10周年突入！ 6つ子、4度目の大暴走！！ 2015年、赤塚不二夫生誕80周年記念作品として、赤塚不二夫の名作ギャグ漫画「おそ松くん」を原作に、大人になった6つ子たちを描いたTVアニメ「おそ松さん」。 20歳を過ぎてもクズでニートで童貞… だけどどこか憎めない彼らが繰り広げる予測不能な日常を描き、気付けば日本一有名な6つ子となってしまった！ あの衝撃の放送開始から今年で10周年。 新たな仲間？新たな騒動？ そして、新たな6つ子の一面も…？ 4度目の大暴走を見届ける方も、初めての方も、どうしようもない彼らと、また笑おう。 10年分の笑いと愛を込めて、「おそ松さん」第4期、ここに開幕！',
        4, 0, 0, 0, '2025-07-08'),
       (133, 160, 'ずたぼろ令嬢は姉の元婚約者に溺愛される',
        'animations/133/images/f1fe6445-9160-40db-a163-2c9fd1290e99.webp',
        'ずたぼろの服をまとい、両親から召使のように扱われている貧しい男爵家の次女・マリー。 それでも素直で優しい心を持ち続け、彼女は家族に尽くしていた。 ある日、マリーのバースデーパーティが開かれる。 ところが、主役はお姫さまのような姉のアナスタジア。 会場の外で哀しそうに佇むマリーは、偶然にも大富豪のキュロス・グラナド伯爵に遭遇する。 お互いに惹かれ合い、マリーにひと目惚れしたグラナド伯爵だったが、ある勘違いからマリーではなく、アナスタジアに求婚してしまう！ 急速に進んでいく、グラナド伯爵と姉との婚約。 しかしアナスタジアが事故死してしまい、代わりにマリーが伯爵家へ嫁ぐことになり……！？ 勘違いから始まる“ずたぼろ令嬢”のシンデレラストーリー、開幕！',
        NULL, 0, 0, 0, '2025-07-04'),
       (134, 195, '公女殿下の家庭教師',
        'animations/134/images/c1c20084-3ebe-4b76-a9e2-89b958e95762.webp',
        '——王宮魔法士の試験に落ちてしまった。世の中は厳しい。 実家に帰ろうにも、先立つものがない。 仕事を探すアレンに舞い込んだのは、公爵家御息女、すなわち公女殿下の家庭教師の仕事。 どうも胡散臭いが、あの『腐れ縁』ほど大変な生徒じゃないだろう。 そう高を括っていた矢先、彼を待っていたのは魔法を一切使うことができない少女だった？！ 彼女の魔法を妨げているものとは一体…？ アレンの常識を覆す授業が、少女の未来をやさしく照らす―。',
        NULL, 0, 0, 0, '2025-07-05'),
       (135, 50, 'CITY THE ANIMATION',
        'animations/135/images/e5be7937-f842-41cd-861e-44fb51997b40.webp',
        'この街、ただの街にあらず。\n笑いあり（プププッ）　ラブあり（キュンキュン♡）　ホロリあり（ホロリホロリ）\n住人たちが織りなす予測不能な平凡ライフ！\nワクワクが連鎖する　CITYへようこそ。',
        NULL, 0, 0, 0, '2025-07-06'),
       (136, 29, 'まったく最近の探偵ときたら',
        'animations/136/images/388a39de-618b-46ca-93a5-dc4ce8a9261d.webp',
        'かつて輝かしい実績を築き、名声を欲しいままにした名探偵がいた。 どんな事件も即解決！彼に解けない謎はない！ 高校生探偵、名雲桂一郎！ ......だったのは10年以上も前のこと。 腰痛に老眼、知覚過敏。すまほとは？JKとは？ 輝いていた高校生名探偵も、今となっては時代に取り残されたおじさんに... 『才能が枯れたんじゃない――ただ少し、若さを失っただけさ。』 そんなある日、名雲探偵事務所に若さあふれる女子高生、 真白が助手になりたいと押しかけてくる。 どうやら探偵を目指しているそうで......！？ おじさん探偵と個性派美少女（自称）JK助手の、 動悸動悸（ドキドキ）が止まらない日常が今、始まる',
        NULL, 0, 0, 0, '2025-07-01'),
       (137, 412, '強くてニューサーガ',
        'animations/137/images/6a85af33-f280-4427-808c-104f85f58c5b.webp',
        '魔族が仕掛けた大規模な戦争「大侵攻」によって、 人族が滅亡寸前にまで追い込まれた世界。 戦乱の中で青年・カイルは、かけがえのない存在と故郷を失う。 復讐のため、魔法剣士として立ち上がった彼は、 激戦の末に魔王討伐を果たすのだが… 勝利の代償はあまりにも大きく、 瀕死の重傷を負った自身も力尽きようとしていた……。 その時…… 深紅の宝石が放つ光に包まれ、 次に目覚めると、なんとそこは既に滅んだはずの故郷だった！ 4年もの時を遡り、失った家族、友人、恋人と再会を果たしたカイルは、 二度と同じ悲劇を繰り返さぬよう、前世の記憶と経験を武器に2周目の人生に挑む！ 今、世界を救うための“ニューサーガ”が始まる！',
        NULL, 0, 0, 0, '2025-07-03'),
       (138, 371, '追放者食堂へようこそ！',
        'animations/138/images/f083a3af-f24f-4aa6-bbf5-3091a80dd9c2.webp',
        '超一流冒険者パーティーを追放されたデニスは、元奴隷の美少女アトリエと出会い、夢であった自分の食堂を開店することに。しかし、その扉を叩くのはなぜか問題を抱えたクセ者ばかりだった！お人好しのデニスは、“至高の料理”でお客の腹を満たし、“最強の料理スキル”で彼らの抱える問題の解決に挑むのだが……。 肉切り包丁で悪党をなぎ倒し、中華鍋で仲間を守る！？ ここは、心もお腹も満たされる場所――『冒険者食堂』！！',
        NULL, 0, 0, 0, '2025-07-03'),
       (139, 191, 'フェルマーの料理',
        'animations/139/images/0bd322f9-ae3b-4960-9910-bfd28897a4d9.webp',
        '私立ヴェルス学園の進学科に通う少年・北田岳は、数学でこの世の真理を見出す偉大な数学者になることを夢見ていた。だが岳は、数学オリンピックで大きな挫折を味わい、数学者になる道を諦めてしまう。 数学オリンピック日本代表になれず特待生でなくなった岳は、アルバイトとして学生食堂で働くなか、まかないでつくったナポリタンをきっかけに若き天才シェフ・朝倉海と出会う。 数学への熱意を失い、数学コンテストにも挑戦しないという岳に侮辱されたと感じた理事長は、岳に退学と奨学金の即時返済を通告。窮地に陥った岳は、理事長の会食の料理人として招かれていた海に起死回生の“ある選択”を迫られる。 美味しい料理を解として、計算するようにレシピを組み立てる岳。 海は「数学的思考は料理のためにある」と言い、岳を料理の世界へ誘う…。 “数学的思考”を駆使した料理で、岳は再び“真理の扉”に挑む！！',
        NULL, 0, 0, 0, '2025-07-05'),
       (140, 49, 'ふたりソロキャンプ',
        'animations/140/images/ae86bbe8-939e-4730-b846-da4b7db67eeb.webp',
        '樹乃倉厳、34歳。 独りを愛する孤高のキャンパーである厳は いつものようにソロキャンプを楽しんでいた。 だが、ひょんなことから超初心者キャンパー、草野雫と遭遇する。 厳は嫌々ながらも、雫とふたりでソロキャンプをやることに！？ 厳の静かなキャンプライフはどうなってしまうのか……',
        NULL, 0, 0, 0, '2025-07-10'),
       (141, 80, 'ブサメンガチファイター',
        'animations/141/images/28a9a5f9-74aa-494e-b3f5-450dbdf3407f.webp',
        '冤罪によって無職の引きこもりになってしまった吉岡しげる（34）は、 異世界でもブサメンを貫く事で膨大なステータスを入手。 チート級の能力値で“絶対神”として第2の人生を歩み始める。 同時に異世界にきた3人の男女――聖華、誠司、リーズと行動を共にする事になるが、 しげるには「女の子に触れるだけでHPが減ってしまう」という弱点が……。 危険回避のため早々にパーティーを離脱して一人旅をと思うしげるだったが――？',
        NULL, 0, 0, 0, '2025-07-06'),
       (142, NULL, 'アイズ・オブ・ワカンダ',
        'animations/142/images/b5ca059c-fd90-4569-8460-93152f44f843.webp',
        'ワカンダの戦士たちはヴィブラニウム製の遺物を回収するために歴史のあらゆる時代を通じて危険な任務に赴く。\nディズニープラスにて8月1日（金）より独占配信中',
        NULL, 0, 0, 0, '2025-08-01'),
       (143, NULL, '長くて短くて、短くて長い',
        'animations/143/images/ecef310c-1d8a-457c-bd2b-a35089fcf87e.webp',
        'シュウーパー家の子供たちの幼少期から成人になるまでの時代を行き来しながら、彼らが味わってきた成功や落胆、喜びや妥協を描き出す。\nNetflixで2025年8月22日配信中',
        NULL, 0, 0, 0, '2025-08-22'),
       (144, NULL, 'フィニアスとファーブ シーズン5',
        'animations/144/images/d3c987a6-4c8a-4c58-9474-cda74d7ebb4b.webp', NULL, 5, 0, 0, 0,
        '2025-08-09'),
       (145, 114, 'New PANTY ＆ STOCKING with GARTERBELT',
        'animations/145/images/d38ecd57-3e85-40e2-95bd-8ce399062651.webp',
        '神と悪魔の狭間の街、ダテンシティ。 今日も人知れず恐ろしい悪霊＜ゴースト＞たちが街を蝕む。 そんな時、人々の欲望や怨念の魂たる悪霊＜ゴースト＞を、人知の及ばぬ光をもって消し去る者達がいた。 その名は、天使パンティ＆ストッキング！！ 地上に蔓延る闇を祓う使命を託された堕天使姉妹。 その正体は果たして神の使いか…悪魔の僕（しもべ）か…。',
        NULL, 0, 0, 0, '2025-07-09'),
       (146, 94, '地獄先生ぬ～べ～',
        'animations/146/images/1c827e33-d0ec-4e8f-8b5c-acb0b1603f1c.webp',
        '不可解な怪奇現象が多発している童守町。子どもたちを守るため、童守小学校に一人の教師が赴任してきた。5年3組担任の鵺野鳴介、通称ぬ～べ～。\n普段は優しく、ちょっと抜けている彼には、日本でただ一人の霊能力教師という、もう一つの顔があった。その左手には鬼が宿るという噂も！？\n生徒たちを襲う学園七不思議、妖怪や悪霊に、地獄からきた正義の使者が立ち向かう！オカルティックヒーローアクション開幕！',
        1, 0, 0, 0, '2025-07-02'),
       (147, 340, '神椿市建設中。',
        'animations/147/images/54b26480-44b5-410a-a17b-ad2df688e5a9.webp',
        '歌は、魔法――世界も運命も変えられる。 7年前に発生した大災害で、人類文明が壊滅的打撃を受けた世界。 先端科学の研究学園都市であった神椿市は、それらの技術を駆使することで、奇跡的な復興を遂げつつあった。 しかし、繁栄の裏では、人の悪意と欲望から生まれる怪物『テセラクター』が街に怪異を引き起こしていた。 悪意から生まれる怪物に抗えるのは、「魔女の娘」と呼ばれる五人の少女たちの歌声だけ。 彼女たちは街の平穏を守るべく、魔法の歌声を武器にテセラクターに挑む。 壊れた世界に残された街で、運命にあらがう少女たちの物語が始まる！',
        NULL, 0, 0, 0, '2025-07-03'),
       (148, 98, 'ばっどがーる', 'animations/148/images/908768a2-3e43-427a-8e93-26ecdef51eef.webp',
        '鋭い目つきに大きなピアス。\nそしてド派手なツートンヘアーの高校生 1 年生・優谷 優\n彼女は誰もが道を空ける名の知れた不良娘（ばっどがーる）\n……ではない。\n根は超絶良い子である優の頭の中はいつも学園のマドンナ・水鳥亜鳥のことでいっぱい。風紀委員長を務める亜鳥\nの気を引きたい優は、優等生を辞めて‟ワルい不良″を目指すことに！\nワルぶってるけど全然ワルくない？？\n自称・不良でちょっぴりおバカな少女の奮闘を描く学園コメディ、開校（スタート）！！',
        NULL, 0, 0, 0, '2025-07-05'),
       (149, NULL, 'リヴァイアサン',
        'animations/149/images/0ec11d74-4b6a-43d4-9e5c-94773e62e2cd.webp',
        '1914年、ヨーロッパではふたつの勢力が拮抗していた。遺伝子操作された動物を基盤とする、英国などの〈ダーウィニスト〉と、蒸気機関やディーゼル駆動の機械文明を発達させたドイツら〈クランカー〉。両者の対立は深まり、オーストリア大公夫妻の暗殺につながった……。両親を殺した一派に追われる公子アレックと、空への憧れから男装し英国海軍航空隊に志願した少女シャープ。運命に導かれ、遺伝子操作で作り出された巨大飛行獣リヴァイアサンに共に乗り込んだふたりは、戦争、忠誠、そしてアイデンティティに関するすべての認識を揺るがす、世界を変える冒険に乗り出す。\n壮大なアクション、上空で繰り広げられる戦闘、感情豊かなストーリーテリングを融合させた「リヴァイアサン」は、崩壊寸前の世界で、ふたりの若者がどのようにして歴史を書き換えることができるかを探求する。\nNetflixシリーズ「リヴァイアサン」2025年7月10日(木)より世界独占配信中',
        NULL, 0, 0, 0, '2025-07-10'),
       (150, 169, '9-nine- Ruler''s Crown',
        'animations/150/images/e5ff9256-039d-4773-b67a-618af9ed13d4.webp',
        '白巳津川市。 学園都市であること以外になんの特色もない街。 観光客を呼び込もうと町興しに励んでいるが、どれも不発。 しかし、予期せぬ出来事により世間の関心を集めることに。 異変は、突如として訪れた。 白蛇九十九神社の神器が破損したことにより、 平穏な学生生活を送っていた、主人公・新海翔の日常が一変する。 並行世界から所有者に特殊能力を授ける装飾品「アーティファクト」が流入し、異能に目覚める少年少女たち。 なんの特色も無い街に住む、なんの変哲もない平凡な学生のはずだったが、 異能者たちが巻き起こす数奇な運命に巻き込まれていく―—',
        NULL, 0, 0, 0, '2025-07-05'),
       (151, 122, '異世界黙示録マイノグーラ～破滅の文明で始める世界征服～',
        'animations/151/images/19993b94-d527-4a8f-9721-0aa524e22038.webp',
        'ファンタジー世界を舞台にした国家運営シミュレーションゲーム、『Eternal Nations』。\nそこでユーザーランキング一位を獲得した伝説のプレイヤー、伊良拓斗は、入院中に意識を失う。\n気が付くと拓斗は、まるでゲームの中のような世界、イドラギィア大陸に降り立っていた――。\nそこに現れたのは、『Eternal Nations』で拓斗が最も愛用していたユニット、《汚泥のアトゥ》。\nそこで拓斗は、ある決心をする。\n「――僕たちの国を作ろう。僕と、君だけの王国を」\nアトゥと共に、邪悪な国家である《マイノグーラ》を設立することを決めた拓斗。\n個性豊かなダークエルフや英雄を国民とし、\nこの世界ではチートとも言えるゲームシステムを利用しながら、\n大好きな内政に励むのだった。',
        NULL, 0, 0, 0, '2025-07-06'),
       (152, 210, 'うたごえはミルフィーユ',
        'animations/152/images/5d3addff-b216-4e05-b2ec-6e7c0695237f.webp',
        '高校1年生、小牧嬉歌（こまきうた）。 苦手なもの、たくさん。 好きなもの、歌うこと。 人並みの青春を目指して、 高校デビューで軽音部への入部を試みるも 臆病な性格が災いし大失敗。 失意の中、ウタが出会ったのは 人間の声だけで作られる音楽【アカペラ】だった。 歌声を重ね合わせることでしか繋がれない 少女たちの不格好な青春がそこにはあった。',
        NULL, 0, 0, 0, '2025-07-17'),
       (153, 86, 'ゲーセン少女と異文化交流',
        'animations/153/images/7c5b88d8-faf3-4f24-8b80-046d45d1aa1a.webp',
        'ゲームセンターでアルバイト中の青年・草壁蓮司が目にしたのは、 バレンタインデーにひとりクレーンゲームに熱中する英国少女・リリー。 何度挑戦しても景品を手にできず涙目の彼女に、思わず蓮司は手を貸す。 無事にぬいぐるみを手にしたリリーから後日渡されたのは、思わぬメッセージカード―― “Be My Valentine！”私の恋人になって！ キュートで天真爛漫な英国少女との出会い。 勘違いから始まる、ゲーセンでの異文化交流！',
        NULL, 0, 0, 0, '2025-07-06'),
       (154, 387, '渡くんの××が崩壊寸前',
        'animations/154/images/4edd9c9d-8802-4cea-9cdc-da123c766b2a.webp',
        '渡直人は、妹の鈴白と叔母の家で暮らす高校2年生。両親を亡くしてから、恋愛も部活もバイトもせず友だち付き合いも断って、妹を最優先に生活していた直人。だがある日、幼なじみの館花紗月が転校してきて、直人の平穏な日常は一変する。紗月はかつて、直人と一緒に育てていた畑を突然めちゃくちゃにした“畑荒らし”だった！紗月の起こした波紋は、直人を巡る人間関係に嵐を巻き起こし、崩壊へ向かって暴走していく……！？',
        NULL, 0, 0, 0, '2025-07-04'),
       (155, 18, '美男高校地球防衛部ハイカラ！',
        'animations/155/images/7ca69c5c-0aa8-44ce-a1bd-b14e2959b547.webp',
        '時は大正――浪漫の香り満ち、人々の心、いまだ情け知る。 眉難高校に通う、雲仙、酸ヶ湯、卯花、長万部、阿蘇は“何にもしない部”地球防衛部の部室でダラダラ過ごしながら、学生寮・黒玉寮で共に生活をするごく普通（？）の男子学生。 ある日5人が黒玉寮で朝風呂していると、湯船の中になにやらヌルっと動くものが。 やっとの事で捕まえると、それはしゃべるマヌルネコ・ヌルだった！ 遠い遠い未来から重大な使命を帯び、地球に滅亡の危機が迫っていることを伝えに来たというヌル。 守りたい…この地球をと言いながらも、自分は危機を知らせにきただけで地球のために戦うかどうかは自由意志で……5人で決めてほしいという。 これって責任逃れじゃない…？怪しむ防衛部たち。 「どっちでもいいなら俺はやるぜ！そっちの方がハイカラだからな！」と張り切る雲仙。 自由な心で自ら戦うと決めた5人をヌルは猫科学でハイカラ浪漫団に変身させるのだった。 その一方…暗躍する謎の3人組蛮（ばん）華（か）羅（ら）新鋭隊（しんえいたい）。 地球征服を企む輩だった。',
        NULL, 0, 0, 0, '2025-07-07'),
       (156, 262, 'デキちゃうまで婚',
        'animations/156/images/b6cc5924-d7f4-450e-9f9f-6b3964b90150.webp',
        '婚活パーティに参加した大河は会場で出会った\n子供が欲しい医者の絢乃と意気投合する。\nだが、肝心のカップル成立タイムを前にして、\nEDが原因でフラれた過去を思い出して逃げてしまう...\n後日、ED治療の為に訪れた病院の担当医はまさかの絢乃で...！？\nしかも、大河のアレは彼女にだけ元気な反応を示し――\n誰にも言えない”デキちゃうまでの契約婚”を結ぶ事になった二人のお話。',
        NULL, 0, 0, 0, '2025-07-06'),
       (157, 123, '学校では教えてくれない大切なこと',
        'animations/157/images/86a4e2eb-201d-40cd-9ad8-2019805aea16.webp',
        '片づけてもすぐ散らかる\n宿題をつい後回しにしちゃう\nテストの点が…上がらない\nそんなキミへ、ちょっとしたコツを教えちゃう。\n部屋がスッキリすれば、いいこといっぱい♪\n時間を上手に使えば、勉強だってぐんぐん進む♪\n「学校では教えてくれない大切なこと」が\nギュッと詰まったワクワクの物語。\n知ればきっと、毎日が変わる！\nさあ、一緒に始めよう！',
        NULL, 0, 0, 0, '2025-07-05'),
       (158, 108, 'クレバテス-魔獣の王と赤子と屍の勇者-',
        'animations/158/images/0ba6a3b6-f27a-4b93-aea9-c3523de9fe2b.webp',
        '幼い頃から勇者に憧れていたアリシアは、王に選ばれし13人の勇者の1人となる。 伝説の剣を携え魔獣王クレバテスの討伐に赴く勇者たち。 だがその蛮勇は、エドセア大陸全土の人属を滅ぼしかねない最悪の危機を招いてしまう。 世界に唯一残された希望は、魔獣王に託された一人の赤子だった――。',
        1, 0, 0, 0, '2025-07-02'),
       (159, 135, 'ハイガクラ', 'animations/159/images/89afd9fd-de34-4e57-bb4b-9afd4f527a78.webp',
        '仙界。 神仙と人間が暮らすその世界は、崩壊の危機に瀕していた。 その鍵を握る凶神・四凶を探し求める歌士・一葉と従神・滇紅。 二人はそれぞれの目的を秘めながら四凶を探していた。 囚われた家族と失った過去。 大切なものを取り戻すため、一葉と滇紅は世界中を駆け巡る――',
        NULL, 0, 0, 0, '2025-07-03'),
       (160, 98, 'ホテル・インヒューマンズ',
        'animations/160/images/bd6c77fe-7054-46c3-b516-5529c7d30df9.webp',
        'そのホテルの…「お客様は殺し屋様」。 最高のホテルには条件がある。 「極上の食事」、「至高の癒やし」、「魅惑の娯楽」… そして、“最新の武器手配”、“安心の身元詐称”、“完璧な死体処理”――！？ 死の境界線で 、 決して『NOと告げない』二人のコンシェルジュ、生朗と沙羅が応える殺し屋達の願いとは―― いざ、鮮烈のキリング・ホテル・ドラマ…開幕！',
        1, 0, 0, 0, '2025-07-06'),
       (161, 3, '転生宗主の覇道譚 〜すべてを呑み込むサカナと這い上がる〜',
        'animations/161/images/a969da6f-7425-4fad-8e37-f1abbe23b50f.webp',
        '自らの霊獣に呑み込まれ、非業の死を遂げた男―― 転生して新たな命を得た彼は、再び天下一を目指す',
        NULL, 0, 0, 0, '2025-07-02'),
       (162, 68, 'ネクロノミ子のコズミックホラーショウ',
        'animations/162/images/df502bba-65a9-490b-bd57-d0c23f568128.webp',
        'あなたは新作VRゲーム『カダス』のテストプレイヤーに選ばれました！ うだつの上がらない底辺ライバー（＝配信者）、黒廼ミコは苦悩していた。 最近発生した、人気ライバーたちが生配信中に意識を失う原因不明の怪事件。 相方の舞夢坂舞由も被害を受け入院し、再生数もまったく伸びない現状・・・ 「今を変える突破口が必要だ！」 そんなミコのもとに届いた、新作VRゲームへの招待。 それは、人類滅亡を目論むクトゥルフら邪神たちが仕掛けたデスゲームだった！？ ミコたちはそれぞれの思惑を胸に、この逃げられない戦いから生き残れるのか。 戦慄のコズミックホラーショウ、ついに始まる！',
        NULL, 0, 0, 0, '2025-07-01'),
       (163, 346, 'BULLET/BULLET',
        'animations/163/images/ef9aed0b-2d6b-4865-a615-ef4d5a9a9840.webp',
        '文明が崩壊し、荒野となった近未来の世界。人々は旧時代の遺物を活用し、貧しいながらも日々を暮らしていた。少年ギアはジャンク屋で働く裏で、４つの人格を持つロボット Qu-0213、ギャンブル狂のシロクマとチームを組み、不当に奪われた品を取り返す”盗み屋”を営んでいた。ある日、殺し屋に追われる謎の少女ノアからの依頼をきっかけに、荒野の武装集団や、凶悪な殺し屋たちに追われることに。どうやらギアが盗んだのは、この世界を揺るがす「秘密」のようで—。',
        NULL, 0, 0, 0, '2025-07-16'),
       (164, 65, '陰陽廻天 Re:バース',
        'animations/164/images/ef3db6a1-bcc0-449a-b26b-54395e558dda.webp',
        '絶対ェ助け出す！異世界だろうが！何度死のうが！\n誰ともつるまず1人孤独に喧嘩に明け暮れるヤンキー高校生・業平 猛 （なりひら たける）は、夢に何度も現れる謎の少女・ツキミヤに想いを募らせる日々を過ごしていた。\nそんなある日、タケルは不慮の事故で崖から転落。\n意識を取り戻すと目の前に広がっていたのは、テクノロジーが高度に進化を遂げた平安京・《電祇平安京(でんじへいあんきょう)》。そこは、最強の陰陽師・安倍晴明（あべのせいめい）が守護しており、憧れのツキミヤが現実に存在する別世界だった！\n夢にまで見た運命的な出会いに舞い上がるタケルだったが、突如発生した黒い霧《闇薫（やみかおる）》の中で《怨人(おに)》と呼ばれる化け物によってツキミヤもろとも命を落としてしまう。\n――しかし、次の瞬間、タケルは再び電祇平安京で目を覚ます。\nやがて自身がタイムリープしたことに気づいたタケルは、ツキミヤが命を落とす未来に抗うため、安倍晴明から陰陽術を習得し、陰陽師として戦うことを決意する――！',
        NULL, 0, 0, 0, '2025-07-02'),
       (165, 123, '傷だらけ聖女より報復をこめて',
        'animations/165/images/271d1135-adf7-4a3e-b0f6-ea4082b773f3.webp',
        '治癒の力を持つ聖女候補のルーア。 しかし彼女の能力には欠点があり、症状を自分に移して治癒するため、自身に痛みや苦しさが伴うものだった。 時に「欠陥聖女」と蔑まれたが、いつも庇ってくれる親友アリアンの存在に助けられていた。 だがアリアンには隠された“裏の顔”があり、ルーアを絶望に陥れる。 「私はもう誰も癒したりしない」 そう誓ったルーアの元に、突然第二王子スウェンが現れ、「一緒に復讐をしないか？」と持ちかけてきて――。 彼女は隠していたもうひとつの能力を使い、スウェンと手を組んで“聖女”ではなく“悪女”として新しい人生を始める…！！',
        NULL, 0, 0, 0, '2025-07-09'),
       (166, 157, 'アークナイツ【焔燼曙明/RISE FROM EMBER】',
        'animations/166/images/aa562805-5e82-4047-806b-c8870d118884.webp',
        '“彼女”は希望の灯となるはずだった。 その怒りが、憎しみが、戦火となって人々を飲み込もうとしている。 レユニオン・ムーブメントの暴走とその背後にある陰謀を阻止できるのは、中立組織であるロドスのみ。 アーミヤたちは龍門に迫りくるチェルノボーグ中枢区画へと向かう。 彼女らを待ち受ける運命とは――',
        NULL, 0, 0, 0, '2025-07-04'),
       (167, 144, '気絶勇者と暗殺姫',
        'animations/167/images/c2c1b825-23df-4ee8-a104-5ee1ade7a2f3.webp',
        '勇者トトは、実力はあるが極度の人見知りのためパーティーが組めず、はじまりの町でくすぶっていた。そんな中、3人の美女――シエル、アネモネ、ゴアから突然パーティーへと誘われる！念願の旅立ちにやる気に満ちるトトだが、彼女たちはその勇者を“殺る気”でいっぱいだった！？女性耐性が無さすぎてちょっとドキドキしただけで気絶してしまう極度の人見知り勇者と、それぞれの目的の為に勇者の命を狙う3人のハーレムデスラブコメディ！！',
        NULL, 0, 0, 0, '2025-07-12'),
       (168, 173, 'ぷにるはかわいいスライム 第2期',
        'animations/168/images/c594d514-11f4-4306-ab74-9c0aa62de5c5.webp', NULL, 2, 0, 0, 0,
        '2025-07-06'),
       (169, 2, '人妻の唇は缶チューハイの味がして',
        'animations/169/images/73866326-7758-49a0-acd3-90ba41361fa7.webp',
        'もしも、人妻の『あの人』と、二人きりでストロング系の缶チューハイを心ゆくまで飲む機会が訪れたら…\n自堕落な生活を送る大学生のツヨシ。前向きになろうと手を伸ばした先には缶チューハイ。そんなツヨシの前に訳アリで魅力的な人妻が現れ、一緒にお酒を酌み交わす。だんだん近づく二人の距離。触れ合う肌と肌。そして何も起きないわけがなく...\n「人妻×ストロング系缶チューハイ」が織りなす、背徳のオムニバス！',
        NULL, 0, 0, 0, '2025-07-01'),
       (170, 95, '闇芝居 十五期', 'animations/170/images/a3fc7796-0cfa-4474-8698-3ea4b3a50b8d.webp',
        NULL, 15, 0, 0, 0, '2025-07-13'),
       (171, NULL, 'ソーセージ・パーティー ～理想郷 フードトピア～ シーズン2',
        'animations/171/images/17b03447-eb2d-4eba-9b46-7b78242badcb.webp',
        '地元から追放されたフランク、バリーとサミーは食品、そして人間にとっても優れたユートピアであるニュー・フードランドに行き着く。だが輝く冷蔵庫とはじけるような笑顔の裏には、意識を持つ食品たちの社会を脅かすくらい秘密が隠されていた。',
        NULL, 0, 0, 0, '2025-08-13'),
       (172, 81, 'ちびゴジラの逆襲 第3期',
        'animations/172/images/3b7c6e01-489e-4a57-97c8-47a69a36806d.webp', NULL, 3, 0, 0, 0,
        '2025-07-02'),
       (173, 61, 'カードファイト!! ヴァンガード Divinez デラックス決勝編',
        'animations/173/images/6a092f78-9506-4078-805e-7ff702523e7c.webp',
        '第三回デラックスはついに佳境へ！ 白熱した予選も終わり、いよいよ決勝トーナメントの火蓋が切られる！ 明導アキナ、八雲カゲツ、呼続スオウ、明星エリカ、大倉メグミ、御薬袋ミレイ、廻間ミチル そして美夜呼ルカ。 ヴァンガードの最強を掴むのは、一体―—！？',
        9, 0, 0, 0, '2025-07-05'),
       (174, 200, 'ぷにるんず ぷに３',
        'animations/174/images/b13d6e7e-a40d-40bc-8890-0c578327c4c2.webp',
        'ぷにるんず……それは、ぷにっとやわらかい『ぷしぎ』ないきもの。 みんな、ぷにぷにされるのが大（だい）すき。 まいにち楽（たの）しく ぷにっとくらしています。 そんなぷにるんずのまえに、あたらしい『ぷにとも』があらわれました。 キラキラかがやく宝石（ほうせき）をのせた じゅえるん です。 じゅえるんは、あいるんにおねがいします。 「いっしょに来（き）てほしい」と。 やってきたのは、すべてがカチコチでできたぷしぎなばしょ、『カチコチランド』。 しかも、じゅえるんもあいるんも、体（からだ）がカチコチに大（だい）へんしん！ カチコチランドにあるというたからもの、 12この『ぷにすたるのかけら』をさがすため、 ぷにるんずのぼうけんが今（いま）はじまります！',
        3, 0, 0, 0, '2025-07-05'),
       (175, NULL, 'ミラキュラス レディバグ＆シャノワール シーズン6',
        'animations/175/images/aa02990a-ec37-4849-8f75-dd086b403f20.webp',
        'パリを守るヒーローの正体は、ごく普通の高校生——でも、彼らには誰にも言えない秘密があった。マリネットとアドリアン。学校ではただのクラスメイト、一方では不思議なパワーを持った妖精・クワミの力を借り、「レディバグ」と「シャノワール」として、邪悪なアクマから人々を救う使命を背負って戦う正義のヒーロー。\nしかし、学生生活でマリネットがアドリアンに、ヒーローの時はシャノワールがレディバグに片思いしており、その想いはすれ違うばかり…。そんな切ない恋心にも変化が訪れ、ついに恋人同士になったふたり。しかし、すぐさまトラブルが発生⁉\n新たな敵、新たな謎、そして新たなミラキュラスの持ち主の登場。ヒーローであることと恋を両立させようとするマリネットは、デートの最中でも使命を果たそうとレディバグに変身して奔走する。\nそして、謎多き少女マヤが「イラストへイター」というヴィランへと変貌したとき、マリネット（レディバグ）は危険を顧みず真実に近づこうとするのだった。\n愛と秘密、そしてヒーローとしての責任が交錯する中、2人の運命はどこへ向かうのか——。『ミラキュラス　レディバグ＆シャノワール』、待望の新シーズン開幕！',
        6, 0, 0, 0, '2025-06-28'),
       (176, 52, '忍ばない！クリプトニンジャ咲耶 参ノ巻',
        'animations/176/images/388bb8c7-95dd-4edd-a540-0340c8536b29.webp',
        'かつて、この国で忍者たちによる大きな戦いがあった。\n生き残った甲賀、伊賀、風魔、雑賀の4つのクランは、それぞれが巨大な力を持つと言われる「クリプト絵巻」\nを持つことで、互いの均衡を保っていた。\n時は流れ、現代。\n舞台は甲賀忍者の住む街、甲賀シティ。\n鬼道衆のたくらみを阻止した咲耶、ネム、シャオランの三人は、シノビマートでバイトして過ごす、平和な日常を送っていた。\nしかし、そこに突如謎の来客が…。そして明かされる衝撃の真実…\n新たな脅威に咲耶たちが立ち向かう！',
        NULL, 0, 0, 0, '2025-07-07'),
       (177, NULL, 'アイアンマンとさいこうのなかまたち',
        'animations/177/images/b31e2480-aac7-4aef-818a-93846d1c55de.webp',
        '若き天才発明家トニー・スタークと親友で天才の仲間たち 3人で大小さまざまな問題を解決しながら、街を守る冒険を描く。彼らは専用のアイアンスーツで、空を飛んだり、パワーを使って大活躍。\nディズニープラスで8月12日(火)より見放題独占配信中',
        NULL, 0, 0, 0, '2025-08-12'),
       (178, 91, 'ネコこのゴロ～天下統一編～',
        'animations/178/images/75ceebdc-50ef-4943-9356-75e591e7e111.webp',
        '大人気ネコさんさんとゴロにゃん達が戦国時代で大暴れ！？？鹿児島の城の当主猫として各地の戦国武将と戦い？ゆるいゆるい日本統一を目指す？',
        NULL, 0, 0, 0, '2025-07-03'),
       (179, NULL, 'パトリック・スター・ショー シーズン2',
        'animations/179/images/72aab686-9573-4e90-b334-de9c62bd3614.webp',
        '7月1日(火)よりParamount+にて独占配信開始予定', NULL, 0, 0, 0, '2025-07-01'),
       (180, NULL, '僕とたい焼き～夢、焼きあがりました～',
        'animations/180/images/80bc165f-f8ae-4cb6-878f-6025594dd60a.webp',
        '生計を立てるために、たい焼きの屋台を始めたアイドル練習生のホスと、突如ホスの前に現れた元気いっぱいな料理の天才たい焼きのドクタービーパン！ただのたい焼きが、ただたい焼き店を始めたアイドル練習生ホスと一緒にソウルのグルメ横丁で料理王になり一緒に夢を叶えていく話。',
        NULL, 0, 0, 0, '2025-06-29'),
       (181, NULL, 'カタチの島 シーズン2',
        'animations/181/images/2ced6d00-734a-4602-a4ef-410b21f107b5.webp',
        'ステキな島に暮らすシカクさんとサンカクさんとマンマルさん。互いの違いを受け入れながら、冒険をして、仲を深めていく。世界中でベストセラーとなった、マック・バーネットとジョン・クラッセンによる絵本に基づく物語。\nApple TV+にて8月29日（金）より配信中',
        2, 0, 0, 0, '2025-08-29'),
       (182, NULL, '全力！プラウドファミリー シーズン3', NULL,
        'ハッとするようなテーマ性とドタバタな展開満載の最新エピソードで贈る『全力！プラウドファミリー』シーズン３。ペニー・プラウドと彼女の仲間たちが繰り広げる、世界を股にかけた追走劇やワイルドな冒険物語。楽しく愛溢れるファンタスティックな旅が始まる！\nディズニープラスで８月６日(水)より独占配信',
        3, 0, 0, 0, '2025-08-06'),
       (183, NULL, 'ミッキーマウス クラブハウスプラス',
        'animations/183/images/76096091-f1b9-4715-87c1-c8ad73fdf066.webp',
        'ミッキー、ミニーとその仲間たちと一緒に新しい冒険に参加しよう！', NULL, 0, 0, 0,
        '2025-07-30'),
       (184, NULL, 'ライリーの箱じゃないハコ',
        'animations/184/images/520b92c9-670d-404a-a78c-4254f56ae606.webp',
        '瞳輝くウサギのライリーと一緒に想像してみよう。ひとつの箱から空想の世界を作るのが大好きなライリーが、新しいおともだちとすてきな冒険をします。原作はアントワネット・ポーティスの受賞歴のある絵本シリーズ。',
        NULL, 0, 0, 0, '2025-06-13'),
       (185, NULL, 'あざらしのえるあ～る',
        'animations/185/images/d3177ce3-97d1-4275-9b4a-e2b530877287.webp',
        'あざらしの”える”と”あ～る”　優しく暖かい二人の日常を描いたほっこりアニメ。何気ない毎日の中で、大切なものを見つけてほしい。',
        NULL, 0, 0, 0, '2025-07-01'),
       (186, 16, '機動戦士Gundam GQuuuuuuX',
        'animations/186/images/e5947cc5-8d68-49f0-86dd-47188fbce7e4.webp',
        '宇宙に浮かぶスペース・コロニーで平穏に暮らしていた女子高生アマテ・ユズリハは、少女ニャアンと出会ったことで、非合法なモビルスーツ決闘競技《クランバトル》に巻き込まれる。エントリーネーム《マチュ》を名乗るアマテは、GQuuuuuuX ジークアクス を駆り、苛烈なバトルの日々に身を投じていく。同じ頃、宇宙軍と警察の双方から追われていた正体不明のモビルスーツ《ガンダム》と、そのパイロットの少年シュウジが彼女の前に姿を現す。そして、世界は新たな時代を迎えようとしていた。',
        NULL, 0, 0, 0, '2025-04-08'),
       (187, 38, 'LAZARUS ラザロ',
        'animations/187/images/3885fd70-1a7e-42b7-8e60-f9c24864b1a7.webp',
        '西暦2052年。 世界はかつてない平和な時代を迎え、脳神経学博士スキナーの開発した鎮痛剤「ハプナ」が大きく貢献していた。 副作用がない「奇跡の薬」として世界中に広まり、人類を苦痛から解放したハプナ。 しかし、その開発者であるスキナーは突如姿を消し、その行方は誰も知らなかった。 ――3年後、彼は世界を破滅に導く悪魔として再び現れる。 ハプナは服用者を3年後に発症させ死に至らしめる薬で、仕掛けられた罠だった。 「あと30日。それまでに私の居場所を見つけだせば、人類は生き延びられる。」 スキナーが持つたったひとつのワクチンを使用するしか、助かる道はない。 そして、これが欲しければ私を見つけ出せと言う。 スキナーの陰謀に対抗すべく、世界中から集められた5人のエージェントチーム「ラザロ」。 彼らは、人類を救うことができるのか？そしてスキナーの真の目的とは――？',
        NULL, 0, 0, 0, '2025-04-06'),
       (188, 203, '九龍ジェネリックロマンス',
        'animations/188/images/10f913c1-e4df-45cd-9b61-001d77e3a089.webp',
        '懐かしさで溢れる街「九龍城砦（くーろんじょうさい）」の不動産屋で働く鯨井令子は、先輩社員である工藤発に心惹かれていた。その恋を自覚した令子はある日、1枚の写真から工藤にはかつて婚約者がいたことを知るのだが、その婚約者は自分と全く同じ姿をしていた。もう一人の鯨井令子の存在が自分に過去の記憶がないことを気づかせる。妖しくも美しい九龍の街で繰り広げられる日常。記憶がないのに懐かしく感じる風景。そして、止められない恋心。過去・現在の時間軸が交錯する中、恋が、秘密を解き明かす――。',
        NULL, 0, 0, 0, '2025-04-05'),
       (189, 65, '炎炎ノ消防隊 参ノ章 第1クール',
        'animations/189/images/afd36080-ccb7-43b9-8086-2c3f7dff5bad.webp',
        '「柱」を巡る激戦や“地下（ネザー）”調査作戦を経て、 世界の大いなる秘密へと近づいたシンラたち。 彼らの奮闘に応え、他の特殊消防隊も協力する姿勢を示し、 全ての特殊消防隊は大災害を阻止すべく1つになった。 今、世界を守る“シンラ（ヒーロー）”と消防官たちの 最終決戦が開幕！',
        3, 0, 0, 0, '2025-04-04'),
       (190, 290, 'ロックは淑女の嗜みでして',
        'animations/190/images/49350fdf-8c28-49c6-9a97-8b667a1666f5.webp',
        '一流の淑女だけが在籍を許される「桜心女学園高等部」に通う鈴ノ宮りりさ。学園で最も栄誉と誇りある称号「高潔な乙女（ノーブルメイデン）」を手に入れるべく精進し、周囲からも一目置かれるほどのお嬢様だが、実は一年前に母親の再婚で鈴ノ宮家に入った「元・庶民」だった。母親の期待に応えるため、本心を押し殺し、大好きだったロックやギターを捨て、お嬢様として振るまうりりさ。ある日、学園の憧れの的である黒鉄音羽と出会い、ひょんなことからドラムを叩く音羽を目撃し…。お嬢様×ロック！？“本音”がぶつかる青春ロックアニメ、開幕！',
        NULL, 0, 0, 0, '2025-04-03'),
       (191, 150, 'ウィッチウォッチ',
        'animations/191/images/d52733e4-4e12-44c1-a80e-460e582ad834.webp',
        '鬼の力を持つ高校生・乙木守仁は、 魔女修行中の幼馴染・ニコの使い魔として同居することに！ 幼馴染との再会にときめくニコだったが、 守仁には予言された災いからニコを守る使い魔としての使命があり…。 ニコの魔法が引き起こす予測不能なトラブル、年ごろの男女の二人暮らし… 前途多難で摩訶不思議な日々が始まる！',
        1, 0, 0, 0, '2025-04-06'),
       (192, 52, 'えぶりでいホスト',
        'animations/192/images/28da0db4-243a-493d-92c4-c82b737b2869.webp',
        '関口（後のハジメ）は、職場で色々あって気を病んでいた所、求人チラシに書かれていた「アットホームな職場です(^o^)」という言葉に釣られ、ホストクラブ「クラブ・ワン」へ転職。\nそこには、ホスト歴20年以上の弟系ホスト、元アイドルの色恋系ホスト、ソシャゲ中毒のオラオラ系ホストなど、異次元の個性派ホストが所属していた！\n自分にホストなんて向いていないと思っていたハジメだが、ホスト達に振り回されるうちに、段々と居心地がよくなっていく。',
        NULL, 0, 0, 0, '2025-04-04'),
       (193, 58, 'WIND BREAKER Season 2',
        'animations/193/images/7afcaefe-1811-434e-952e-c432e9c5dfda.webp',
        '人を傷つける者、物を壊す者、悪意を持ち込む者\n何人も例外なくボウフウリンが粛清する――！\n偏差値は最底辺、ケンカは最強。超不良校として名高い、風鈴（ふうりん）高校。\nその「てっぺん」を獲るため、街の“外”からやってきた高校 1 年生・桜遥。\nしかし、現在の風鈴高校は“防風鈴”（ボウフウリン）と名付けられ街を守る集団となっていた。\n仲間や街の人々との触れ合いを通して、少しずつ「てっぺん」のあり方が変わり始めた桜。\n新たな仲間、新たな敵との出会い――\n級長として“守るために闘う”桜の英雄伝説、次なるステージへ！',
        2, 0, 0, 0, '2025-04-03'),
       (194, 23, 'リコリス・リコイル Friends are thieves of time.',
        'animations/194/images/7d095fc5-00b5-46ca-bef9-6be7cf0d54d9.webp', NULL, NULL, 0, 0, 0,
        '2025-04-16'),
       (195, 163, '小市民シリーズ 第2期',
        'animations/195/images/466b4ad3-53fc-4160-9833-6f73ec893f7c.webp',
        'わたし、知りたかったの。\n恋とはどんなものかしらって。\nたがいに助け合う“互恵関係”を解消した、高校二年の小鳩くんと小佐内さん。\n小佐内さんは、新聞部一年の瓜野くんとつきあいはじめる。瓜野くんは在学した証しを残し、小佐内さんにいいところを見せるため、市内で起きた放火事件を学内新聞で取り上げようと奮闘する。\n一方、小鳩くんはクラスメイトの仲丸さんとつきあいはじめる。平穏な日々を過ごすなか、河川敷で放火現場に遭遇し……。小鳩くんと小佐内さんの小市民としての再出発は、はたしてどうなるのだろうか。',
        2, 0, 0, 0, '2025-04-05'),
       (196, 165, 'コウペンちゃん',
        'animations/196/images/07310b8f-806c-478f-b1b4-3d03564722ec.webp', NULL, NULL, 0, 0, 0,
        '2025-04-06'),
       (197, NULL, 'ゴリラの神から加護された令嬢は王立騎士団で可愛がられる',
        'animations/197/images/6741434f-8b1b-47cf-b0d6-e424eb6b631d.webp',
        '16歳になると、さまざまな動物神から加護を得られる世界―― 気弱な伯爵令嬢ソフィア・リーラーは戦闘系最強と言われる『ゴリラの神』を引き当ててしまう。 平穏な学生生活を送りたいと悩む一方、その希少な力を求められ、王立騎士団から従騎士のスカウトを受ける。 圧倒的な力を隠しきれず一目置かれる中、同じ学校に通う年上の従騎士ルイ・スカーレルをはじめ、有望な若手騎士たちはソフィアをやさしく見守ってくれて―― ゴリラの力から予想外の胸キュンラブコメ！',
        NULL, 0, 0, 0, '2025-04-06'),
       (198, 559, 'TO BE HERO X', 'animations/198/images/93b6ad3c-766a-4dcb-a285-5b7d3a71e1b9.webp',
        '異彩を放つヒーローたちが喝采を浴びる世界。 ここでは、「信頼」がスーパーヒーローを生み出す。 人々が「彼は空を飛べる」と信じれば、その男は飛行する能力を手に入れる。 逆に特殊な力を持つヒーローでも、信頼を失えば能力もまた失われる。 信頼はデータとして集計され、その数値によってヒーローのランキングが変動する。 2年に一度、トップランクのヒーローたちが集い繰り広げるヒーロートーナメント。 そこでのパフォーマンスによって「信頼値」が更新され、ランキングは再構築される。 ランキングの頂点に立つ絶対的なヒーロー、 人はそれを「X」と呼ぶ――',
        NULL, 0, 0, 0, '2025-04-06'),
       (199, 143, 'ウマ娘 シンデレラグレイ',
        'animations/199/images/fff6c7a7-7102-41be-86c3-81035477c5ee.webp',
        '寂れた地方のカサマツトレセン学園。そこに1人のウマ娘が現れる。\n名は、オグリキャップ。\nその圧倒的な走りは、あらゆる常識を覆していく。\nやがて「怪物」と呼ばれる灰被りの少女が、今、新たな伝説を刻む――。\n青春“駆ける”シンデレラストーリー、遂に出走!!',
        1, 0, 0, 0, '2025-04-06'),
       (200, 107, '鬼人幻燈抄', 'animations/200/images/43fad67e-010e-43a6-aeb2-2c8ec0916596.webp',
        '時は天保十一年（1840年）。大飢饉により人心が乱れた世において、鬼が人の姿に化け、戯れに人をたぶらかすようになっていた。 江戸の街から遠く離れた山間の集落・葛野（かどの）。この集落に、甚太と鈴音という兄妹が暮らしていた。幼い頃に、ある理由から葛野に来たよそ者の二人だったが、皆に受け入れられ仲睦まじく日々を過ごしていた。 集落には、「いつきひめ」と呼ばれる巫女がおり、成長した甚太は巫女の護衛役を務めるように。そしてある日、甚太は鬼の討伐に赴いた森で、遥か未来を語る不思議な鬼に出会う―― 巫女の護衛役として死と隣り合わせの甚太、その身を心配しつつも健気に明るく兄を送り出す鈴音、巫女「いつきひめ」として責務を果たす中、鬼に命を狙われる白夜。三人の運命の歯車が重なり、そして狂う時。人と鬼、長きに渡り時代をも巻き込む大きな災いが降り注ぐ。 江戸から平成へ。刀を振るう意味を問い続けながら百七十年という途方もない時間を旅する鬼人の物語を描く、和風大河ファンタジー。',
        NULL, 0, 0, 0, '2025-03-31'),
       (201, 32, 'ヴィジランテ -僕のヒーローアカデミア ILLEGALS-',
        'animations/201/images/830ff978-88a6-423d-b010-dfa46f552fa2.webp',
        '灰廻航一（はいまわりこういち）は、ヒーローに憧れながらも夢を諦めた冴えない大学生。 そんな彼の密かな楽しみは、オールマイトのコスプレ姿で街を徘徊し、プロヒーローを気取って人助けに勤しむことだった。 平凡な毎日を送っていた航一だったが、無許可でゲリラライブを行う自称アイドル・ポップ☆ステップ、「クズ専門の“掃除屋”」を名乗る謎の覆面男・ナックルダスターに出会い、「ヴィジランテ」の活動に巻き込まれていく。 非合法に人々を救ける彼らは、秩序を乱す犯罪者か、正義の自警団か。 “非合法ヒーロー”「ヴィジランテ」の物語が幕を開ける―！',
        1, 0, 0, 0, '2025-04-07'),
       (202, 217,
        '一瞬で治療していたのに役立たずと追放された天才治癒師、闇ヒーラーとして楽しく生きる',
        'animations/202/images/5797ac83-1b26-40a7-9d14-995266b44708.webp',
        '冒険者パーティから役立たずと言われ、追放された治癒師の青年ゼノス。 貧民の生まれで、自己流の治癒魔法を使うゼノスは治癒師のライセンスも持たない。 行く先をなくしたゼノスは瀕死のエルフの少女リリと出会い… 貧民街の外れに開業した治療院を舞台に、無免許天才治癒師による無自覚最強ファンタジーが始まる―。',
        NULL, 0, 0, 0, '2025-04-03'),
       (203, 72,
        '勘違いの工房主～英雄パーティの元雑用係が、実は戦闘以外がSSSランクだったというよくある話～',
        'animations/203/images/18693dff-48a6-4d6f-bcca-e623aecabfa6.webp',
        '英雄パーティで雑用係として働く心優しい少年・クルトは、 ある日突然「役立たずだから」とパーティを追い出されてしまった。 さらに、戦闘に関するあらゆる適性が最低ランクだと判明。 クルトは生計を立てるため、さまざまな仕事を手伝うことに。 すると、行く先々で人間業とは思えぬ驚異の才能で大活躍！ 実はクルトは、戦闘以外のあらゆる分野の適性が最高のSSSランクだったのだ…！ しかし肝心の本人はまったくそのことに気づいておらず、“よくある話”と勘違い。 無自覚な行動で人を、町を、果ては国まで救ってしまうことに！？ 英雄パーティをクビになった少年が途方に暮れて旅をする。 ──これは、そんな“よくある（？）話”。',
        1, 0, 0, 0, '2025-04-06'),
       (204, 51, '日々は過ぎれど飯うまし',
        'animations/204/images/59c2af87-d98b-460d-8e68-47591fbb4a8f.webp',
        '大学一年生の河合まこは、できるだけ周りに波風を立てず毎日を淡々と暮らしていた。そんなある日、まこの目の前に現れたのは小川しのん。しのんと友達の比嘉つつじ、古舘くれあに誘われ「食文化研究部」へ入部することに。この出会いが、まこたちの大学生活に変化をもたらし始める――。星ななも新たに入部し5人になったサークルで、みんなと一緒に楽しい思い出いっぱいつくりたい！',
        NULL, 0, 0, 0, '2025-04-12'),
       (205, 20, '謎解きはディナーのあとで',
        'animations/205/images/75e6db0d-e80e-4497-9201-e3ddf23e90c0.webp',
        '国⽴署の新⽶刑事、宝⽣麗⼦は世界的に有名な「宝⽣グループ」のお嬢様。「⾵祭モータース」の御曹司である⾵祭警\n部の下で、数々の事件に奮闘中。⼤豪邸に帰ると、地味なパンツスーツからドレスに着替えてディナーを楽しむ麗⼦\nだが、難解な事件にぶちあたるたびに、その⼀部始終を相談する相⼿は“執事兼運転⼿”の影⼭。\n「お嬢様の⽬は節⽳でございますか？」――暴⾔すれすれの毒⾆で麗⼦の推理⼒のなさを指摘しつつも、影⼭は鮮や\nかに事件の謎を解き明かしていく。\n毒⾆執事×令嬢刑事コンビの⼤⼈気ミステリが、アニメとなって華麗に開幕。',
        NULL, 0, 0, 0, '2025-04-04'),
       (206, 53, '真･侍伝 YAIBA', 'animations/206/images/96a928d1-bc4d-4bbb-8081-78b9e5905551.webp',
        '真のサムライを目指し、ジャングルで修行に励んでいた鉄刃（くろがね やいば）。 ひょんなことから日本に戻り、父・剣十郎と縁のある峰家に身を寄せることに。 峰家の娘・さやかは破天荒な刃に戸惑いながらも暮らし始める。 そんなある日、さやかの学校に訪れた刃は、剣道の実力者・鬼丸猛（おにまる たけし）と運命的な出会いを果たす。 その後、刃と鬼丸は衝突を繰り返し、強さを求めた2人に呼応するかのように古の力が目覚める。 「雷神剣」と「風神剣」― 古来より天地を揺るがしてきた魔剣が今再び目覚め、真の物語が幕を開ける―',
        1, 0, 0, 0, '2025-04-05'),
       (207, 132, '完璧すぎて可愛げがないと婚約破棄された聖女は隣国に売られる',
        'animations/207/images/3c048462-4092-4532-89a8-d573234f673d.webp',
        'この世界には、魔物から 国の守護を担う『聖女』が存在している。 ジルトニア王国で聖女を代々輩出する家系に生まれたフィリアは、 厳しい教育により「歴代最高」と評される程の実力を身につけ、日々お務めに励んでいた。 しかし、あまりの隙の無さに「完璧すぎて可愛げがない」と周囲には疎まれ、婚約者の第二王子ユリウスからは婚約破棄されてしまう――。 さらにはお金と資源を対価に聖女不在で苦しむ隣国パルナコルタ王国に売られて、故郷から旅立つことに。 悲惨な待遇を覚悟して隣国へと向かうフィリアだったが、 そこで待っていたのは予想外の大歓迎で………！？',
        NULL, 0, 0, 0, '2025-04-09'),
       (208, 193, '俺は星間国家の悪徳領主！',
        'animations/208/images/2ae2fdf9-f6d1-4cd1-a57a-f0a329a68ed4.webp',
        '星間国家アルグランド帝国の辺境を治める伯爵家に生まれ、 幼くして当主となった転生者リアム。 善良さ故に奪われ続けた前世を反省した彼は、 今度は奪う側である「悪徳領主」となり民を虐げようと決意！ せっかくのSF世界なのだからロボットにだって乗りたい！ 最強の剣術だって習得して、傍若無人に振る舞いたい！ ゆくゆくはハーレムを作って、酒池肉林も楽しみたい！！ ──しかし。 リアムなりに「悪徳領主」らしく振る舞っているはずが、 なぜか民からは感謝されて好感度は上がりっぱなし……！？ 魔法ありロボットありの星間国家を舞台に、 超銀河スケールでお贈りする勘違い領地経営譚が堂々開幕！！',
        NULL, 0, 0, 0, '2025-04-05'),
       (209, 44, 'Summer Pockets',
        'animations/209/images/fa666825-acba-4b67-9dde-d9724f7fc40d.webp',
        '亡くなった祖母の遺品整理のために夏休みを利用して、鳥白島にやってきた主人公の鷹原羽依里。祖母の思い出の品の片付けを手伝いながら、初めて触れる「島の生活」に戸惑いつつも、順応していく。海を見つめる少女と出会った。不思議な蝶を探す少女と出会った。思い出と海賊船を探す少女と出会った。静かな灯台で暮らす少女と出会った。島で新しい仲間が出来た――この夏休みが終わらなければいいのにと、そう思った。',
        NULL, 0, 0, 0, '2025-04-07'),
       (210, 75, '片田舎のおっさん、剣聖になる',
        'animations/210/images/5144c375-420a-48d3-b541-6729b72539cb.webp',
        '片田舎で道場を構えるしがない剣術師範の中年、ベリル・ガーデナント。\n剣士としての頂を目指した日々は遠く過ぎ去り、自身の実力に気持ちの折り合いをつけてのんびり過ごしていた彼のもとへ\n今や王国騎士団長にまで出世した元弟子の一人、アリューシアが十年の時を経て来訪する。\n「先生を騎士団付きの特別指南役として推薦し、無事承認されました」\nこのまま田舎暮らしで静かに生涯を終える、それでも構わないと割り切っていた\nベリルの運命が、大きく変わる──！\n都会での生活。大きく成長した元弟子たちとの再会。新たな仲間、そして強敵との巡り会い。\n「俺みたいな峠を過ぎたおっさんには、荷が重すぎるよ……」\nそう思うベリルだが、長きにわたり実直に鍛え続けた剣の腕は\n”片田舎の剣聖”と称されるほどの凄まじい領域に達していて──',
        1, 0, 0, 0, '2025-04-05'),
       (211, 378, 'mono', 'animations/211/images/9d51fe61-fa4b-4f5b-b853-d4c622c363dd.webp',
        '高校の写真部員・雨宮さつきは大好きな部長の卒業により意気消沈していたが、親友でもう1人の部員の霧山アンからの激励により、再び部活動を頑張る決心をする。 しかし、さつきが意気込んでオークションで購入した360°カメラが届かない。 アンが出品者を調べると学校のすぐ傍に住んでいるらしい……。 さつきとアンが出品者の住所を訪れるとそこには駄菓子屋が。 2人はそこで漫画家の秋山春乃と出会い、「マンガのモデルになって欲しい」という依頼を受ける。 元映画研究部の敷島桜子を加え写真部と合併した「シネフォト研究部」は、春乃の取材に協力することになるが……？',
        NULL, 0, 0, 0, '2025-04-12'),
       (212, 541, '前橋ウィッチーズ',
        'animations/212/images/5cc6ec25-bd2c-4af8-8811-6a857a51496e.webp',
        '地元（まえばし）で魔女ってエモエモじゃない！？群馬県前橋市。高校1年生・赤城（あかぎ）ユイナの“普通にまぁ”な物足りない日常は……「じゃあ君、魔女になってみてよ」謎のカエル、ケロッペの登場で一変！部屋のクローゼットは不思議な空間に繋がっていて――新里（にいさと）アズ「アンタには魔女になる本気度が足りない！」北原（きたはら）キョウカ「……喧嘩はやめて、お客さんの願い叶えない？」 三俣（みつまた）チョコ「夢が見れるって素敵だよ！ハピハピチョコちゃんだよ！」 上泉（かみいずみ）マイ「私、長いものには巻かれろタイプなの♪」うん、5人だとなんか楽しいことが起きる気がする！！最高に刺激的な魔女、私たち前橋ウィッチーズが、あなたの願いを叶えます。赤城ユイナ「ここは、あなただけのお花屋さん。心の奥にある、あなたのお花、咲かせる場所」歌って踊る、魔法の花屋、ミラクルに本日開店！',
        NULL, 0, 0, 0, '2025-04-06'),
       (213, 72, 'ある魔女が死ぬまで',
        'animations/213/images/44c7e848-f1a1-4f2d-9497-9696491dd6fb.webp',
        '「お前、あと一年で死ぬよ」 十七歳の誕生日を迎えた見習い魔女のメグ・ラズベリーは、魔法の師匠であり、魔法界トップの七賢人に名を連ねる『永年の魔女』・ファウストから、突如として余命一年であることを告げられる。 メグは『死の宣告』の呪いにかかっていたのだ。 呪いによる死を免れる方法はただ一つ。 手にした者に不死をもたらす、『命の種』を生み出すこと。 そして、『命の種』の材料となるのは、感情の欠片――人が喜んだ時に流す、嬉し涙。 「それで、一体どれくらい涙を集めればいいんですか？」 「千人分だ」 「……はい？」 こうして、メグは嬉し涙を集めるため、様々な人たちと関わっていく。 幼馴染みで大親友のフィーネ。 ファウストと同じ七賢人の一人――『英知の魔女』・祈。 メグと同い年にして七賢人に名を連ねる天才少女、『祝福の魔女』・ソフィ。 これは、余命一年を宣告された未熟な魔女、メグ・ラズベリーが起こす、奇跡の物語。',
        NULL, 0, 0, 0, '2025-04-01'),
       (214, 58, '黒執事 -緑の魔女編-',
        'animations/214/images/53ec105b-8e94-4a0a-9ada-e43f3c894b9d.webp',
        '19世紀英国―― 名門貴族ファントムハイヴ家の執事セバスチャン・ミカエリスは13歳の主人シエル・ファントムハイヴとともに“女王の番犬”として裏社会の汚れ仕事を請け負っていた。 女王の命により、ドイツで起こる不可解な死亡事件の調査へ赴くセバスチャンとシエル。 足を踏み入れただけで呪い殺されるという“人狼（ヴェアヴォルフ）の森”について真相を探る二人におぞましい呪いが降り注ぐ――。',
        NULL, 0, 0, 0, '2025-04-05'),
       (215, 18, '増田こうすけ劇場 ギャグマンガ日和GO',
        'animations/215/images/64d77790-4905-47a3-85d2-d17067682d44.webp', NULL, NULL, 0, 0, 0,
        '2025-04-07'),
       (216, 22, '宇宙人ムームー',
        'animations/216/images/b1db37fc-b419-45c3-9dfb-6818d544568d.webp',
        '遠い宇宙から地球にやってきた猫型異星人・ムームー。 その目的は、自らの種族が失ったテクノロジーを取り戻すため、地球で家電の技術を学ぶこと。 主人公・桜子の平凡な大学生活は、ムームーの登場で一変！ 予想外の同居が始まり、次々と起こる騒動に巻き込まれることに。 ムームーとの化学反応が巻き起こす、 スーパースペクタクル×家電あれこれ×にゃんコメディ。',
        NULL, 0, 0, 0, '2025-04-09'),
       (217, NULL, 'スライム倒して300年、知らないうちにレベルMAXになってました ～そのに～',
        'animations/217/images/720ae67e-6ed5-4ea6-bdb9-5551e938ac3b.webp',
        '女神様の計らいで不老不死の魔女となって異世界に転生したアズサ。 過労死した前世の反省からスローライフを願い、生活費の足しにと日課でスライムを倒すこと300年――。 気づけばレベルMAXの世界最強になっていた！ 最強の噂は広まり、静かだった高原の家に事情を抱えたドラゴン娘やスライムの精霊、エルフや幽霊といった娘たちが押しかけてくる。 彼女たちの悩みやおかれた状況を見過ごせないアズサは奔走し事態を解決、家族として迎え入れ、みんなとの新しいスローライフを始めることにする。 しかしその新生活は、スローライフというには少し賑やかなもので――！？ レッドドラゴンの故郷に行って温泉に入ってみたり、魔族の国の式典に行ってみたり、 世界樹と呼ばれる巨大ダンジョンを攻略したり。 今日も楽しい一日が始まります！',
        2, 0, 0, 0, '2025-04-05'),
       (218, 30, 'キミと僕の最後の戦場、あるいは世界が始まる聖戦 Season Ⅱ',
        'animations/218/images/21b8f2b6-de9b-41b2-9618-f13e79c7c36f.webp',
        '科学技術が発達した、機械仕掛けの理想郷「帝国」。 超常の力・星霊術を駆使し、“魔女の国”と恐れられる「ネビュリス皇庁」。 二国は長きにわたる戦争を続けてきた――。 帝国の最高戦力イスカと皇庁の王女にして“氷禍の魔女”アリスリーゼは、 激闘の中で互いの素顔に触れ、その生き方と理想に惹かれ合う好敵手となった。 独立国家アルサミラで帝国と皇庁の謀略を打ち砕いた二人は、再会を誓ってそれぞれの道へと進むが、意外な形でその約束を果たす。 アリスの妹シスベルと取り引きを交わし、護衛として皇庁に潜入するイスカ。 シスベルの捜索隊として皇庁の都市リースバーテンを訪れるアリス。 偶然の再会は二人の心をさらに燃え上がらせるが…… 同時に皇庁内では帝国の内通者「純血種・被検体E」が暗躍し、帝国の「特務・女王捕獲計画」が動き出そうとしていた。 否応なく引き裂かれようとするイスカとアリスは、その運命に抗うことができるのか――。',
        2, 0, 0, 0, '2025-04-10'),
       (219, 143, 'アポカリプスホテル',
        'animations/219/images/8be9b8f8-2263-4485-beac-79f4db31f4f7.webp',
        '人類がいなくなり、長い年月が流れた地球。 日本の首都・東京の銀座にあるホテル『銀河楼』では、 ホテリエロボットのヤチヨと従業員ロボットたちが、 オーナーの帰還と、再び人類のお客様を迎える時を待っていた。 が――100年ぶりにやってきたお客様は、地球外生命体だった。 次々に訪れる彼らの目的は、宿泊か、侵略か、はたまたどちらでもないのか…… 『銀河楼』の威信をかけたヤチヨたちのおもてなしが、今、始まる――',
        NULL, 0, 0, 0, '2025-04-08'),
       (220, 217, 'ざつ旅-That''s Journey-',
        'animations/220/images/3fcb8da5-c28f-4674-9e9a-020a2b80a958.webp',
        '漫画賞の新人賞を受賞した漫画家志望の女子大生・鈴ヶ森ちかは、ある日、編集部に新作のネームを3本持ち込んだものの全ボツを食らってしまう。 心が折れそうになったとき、唐突に胸の中に溢れてくるものがあった。 「どこか、旅にでたい…」 面白半分でSNSにて旅先のアンケートを取ってみると、まさかの大きな反響があり、引くに引けない状態に…！ でも、旅にでたい気持ちは本物。 覚悟を決めたちかは、アンケート頼りの行き当たりばったりな旅を始めることに。 時に一人で、時に友人たちと――。 「ざつ」だからこそ思いがけない出会いが待っている、“ざつ旅”へ出発！',
        NULL, 0, 0, 0, '2025-04-07'),
       (221, 17, '男女の友情は成立する？（いや、しないっ!!）',
        'animations/221/images/fad9cc24-b4e4-43a2-9ea5-dad0f00080fe.webp',
        'とある田舎の中学校で、ある男女が永遠の友情を誓い合った。１つの夢に向かい運命共同体（しんゆう）となった二人の仲は――特に進展しないまま２年の歳月が過ぎる……！未だに初恋がこない陽キャ女子・犬塚日葵と、花を愛する植物系男子・夏目悠宇は、高校２年生になっても変わらず、二人だけの園芸部で平和に親友をやっていた。ところが、悠宇が過去の初恋相手と再会したことで、突如二人の歯車が狂い出す!?果たして恋を知った日葵は〈理想の友だち〉脱却なるか？',
        NULL, 0, 0, 0, '2025-04-04'),
       (222, 181, 'アン・シャーリー',
        'animations/222/images/797f2a47-da3f-44cf-b9d6-4cb4c75e87f0.webp',
        '孤児院から老兄妹マシュウとマリラが住むグリーン・ゲイブルズにやってきた11歳の赤毛の少女アン・シャーリー。豊かな想像力と明るさとまっすぐな心で周囲を変えていく。',
        NULL, 0, 0, 0, '2025-04-05'),
       (223, 37, '紫雲寺家の子供たち',
        'animations/223/images/2ae90d93-3acb-46cd-bf2d-f9aa9810de71.webp',
        '東京都世田谷区の高級住宅街に豪邸を構える「紫雲寺家」。 ここに住む7人の兄弟姉妹は、才色兼備として知られ、 なかでも年子の5姉妹は全員が美少女だと評判だった。 誰もが羨む美人姉妹との一つ屋根の下。 しかし、長男・新は個性的な5姉妹に振り回され、姉妹以外の女子には及び腰になっていた。 家族を大切に思いながらも、5姉妹のいない別の人生を妄想する新だが……。 「実は君達は本当の兄弟姉妹ではない」 ある日、父親から衝撃の事実を告げられ、運命は一変する！ いつまでも変わらないと信じた家族の繋がりも、変化の兆しを見せはじめ――。 この愛が行き着く先は、家族、兄弟姉妹、それとも？ 運命が繋ぐワケあり家族の“禁断×純愛”ラブコメディが開幕！',
        NULL, 0, 0, 0, '2025-04-08'),
       (224, 139, 'Devil May Cry シーズン1',
        'animations/224/images/5533f982-f30a-42cb-a900-3926a2bd7691.webp',
        '若きデビルハンターが、世界の運命をその首にかけて悪魔との戦いに挑む。カプコンの名作ゲームから生まれたアニメシリーズ。Netflixで2025年4月3日配信中',
        1, 0, 0, 0, '2025-04-03'),
       (225, 126, '阿波連さんははかれない season2',
        'animations/225/images/06ec9068-dfe9-47df-94ba-c5e38414eed5.webp',
        '小柄で物静かな女の子、 阿波連れいなさん。 人との距離をはかるのが少し苦手。 そんな彼女の隣の席に座るライドウくんは、 阿波連さんとの間に距離を感じていた。 だが、ある日、阿波連さんが落としてしまった消しゴムを ライドウくんが拾ったことをキッカケに、ふたりの距離は急接近！！ 学校生活を送る中で「遠すぎたり」と「近すぎたり」を繰り返し、 付き合い始めた阿波連さんとライドウくん。 それから迎えた新学期、 今度は転校生との距離がはかれない！？ 色んな意味で、『はかれない』密着系？ 青春ラブコメディの幕が再び上がる！！',
        2, 0, 0, 0, '2025-04-07'),
       (226, NULL, 'ラブ、デス＆ロボット シーズン4',
        'animations/226/images/a16e6a78-a24e-4a8e-81d7-a1deae735ef1.webp',
        'Netflixシリーズ「ラブ、デス＆ロボット」シーズン4：5月15日（木）世界独占配信中', 4, 0, 0, 0,
        '2025-05-15'),
       (227, 157, '戦隊大失格 2nd season',
        'animations/227/images/c85bdf5e-15ad-4f8a-9602-39b0d43d909c.webp',
        '敗け続けの人生に終止符を打つため一人「打倒大戦隊」を掲げた 悪の怪人軍団の下っ端“戦闘員 D”\n桜間日々輝に擬態した D は入隊試験を見事突破！\n大戦隊への本格潜入が始まる！\n怪人幹部ぺルトロラに阻まれたもののブルーキーパー討伐に成功。\n極秘ミッションを遂行するグリーン部隊に配属された D、無論\n次の標的はグリーンキーパー！\n一方、ブルーキーパーを失った大戦隊内には疑念が立ち込め、徐々に一般市民の信頼を落としていたー\n大戦隊の闇が迫るセカンドシーズンがついに開幕！',
        2, 0, 0, 0, '2025-04-13'),
       (228, NULL, 'この恋で鼻血を止めて',
        'animations/228/images/c00a0035-b4ae-468c-9e17-17feb63801b6.webp',
        '時は未来。 どこにでもいる平凡な女性のモカは刺激のない退屈な日々を送っていた。 しかしある日、彼女が働くオフィスがエイリアンの戦いに巻き込まれてしまう。 モカを助けたスーパー宇宙人のヤーセンだったが、 彼が捕獲していた心原虫（しんげんちゅう）という寄生虫が誤ってモカに寄生してしまった。 その虫に寄生された者は「退屈すると死んでしまう」という！ 日々死の脅威にさらされるモカと、彼女を救いたい不器用でまっすぐなヒーロー、ヤーセンの運命は……！？',
        NULL, 0, 0, 0, '2025-04-02'),
       (229, 30, 'プリンセッション・オーケストラ',
        'animations/229/images/7864cc1d-cd2c-4694-9375-1bd9c6ebfcbc.webp',
        'アリスピア――そう呼ばれる不思議の国は、今よりもずっと昔から世界のどこかに存在していた。 そこには楽しいことが大好きな住民アリスピアンたちが暮らしていたが、いつしか謎の怪物ジャマオックが現れるようになり、穏やかだったアリスピアの平和は、少しずつ脅かされるようになっていった。このままではアリスピアからキラキラとした輝きが失われてしまう――。 そんなピンチにあっても、胸に歌を忘れない『プリンセス』たちの冒険を描いた物語。 勇気と元気がたくさん詰まった、ポップソング・ファンタジア――プリンセッション・オーケストラ！',
        NULL, 0, 0, 0, '2025-04-06'),
       (230, 156, 'クラシック★スターズ',
        'animations/230/images/ff31cb6a-d447-4fed-a14c-1a02ed09dff3.webp',
        '音楽・芸術・スポーツ、あらゆるエンターテインメント分野で 未来を嘱望された若者たちが集う【私立グロリア学園】。 その音楽科では、偉大な音楽家たちの「才能（可能性）」に適合した者が 【ギフト】を体内に移植され、その音楽家の名前で呼ばれることになる。 ケガをきっかけに適合性を見出された青年・ベートーヴェンもその一人。 学園に編入したベートーヴェンは、異なるギフトを受け継ぐ仲間たちと出会い 音楽の魅力に触れながら、コンテストでの優勝を目指すことに──。 偉大な音楽家の意思を未来へ紡ぐ夢のプロジェクト 音楽（エモージョン）とVR空間（ビジュアライズ）が織りなす 奇跡のシンフォニー がここに開演！',
        NULL, 0, 0, 0, '2025-04-05'),
       (231, NULL, 'リック・アンド・モーティ シーズン8',
        'animations/231/images/5bf487d5-54e6-4120-9289-397f056f0729.webp', NULL, NULL, 0, 0, 0,
        '2025-05-26'),
       (232, 53, 'ムーンライズ', 'animations/232/images/486822f1-0806-4841-947c-75f05f11fcaa.webp',
        '舞台はTS西暦2XXX年―。人類は\"緩やかな世界政府\"を樹立。全ては国際AIネットワーク〈サピエンティア〉に委ねられ、人々はその合理的判断に従って生活を送っていた...。しかし〈サピエンティア〉が進めた\"月開拓事業\"は、汚染物や犯罪者を月に送ることで平和を保つ地球と、貧困な生活を強いられる月の格差を生み、独立戦争の火種となりつつあった。ある日、爆破テロに巻き込まれた主人公のジャックは、地球からの解放を企てていた月の反乱軍によって家族を奪われる。復讐を誓ったジャックは、地球軍の調査兵として仲間と共に月へ向かうことを決意する―。\nNetflix シリーズ「ムーンライズ」2025年4月10日（木）より世界独占配信中',
        NULL, 0, 0, 0, '2025-04-10'),
       (233, 137, '最強の王様、二度目の人生は何をする？',
        'animations/233/images/dbe7afea-27e9-4caf-ba8a-e22f977b1e2d.webp',
        '史上最強の王様・グレイ。比類のない力・富・名声すべてを持つ一方、冷酷無情な彼に寄り添う者はおらず、彼もまた信頼できる者は誰一人いなかった──。 ある日、グレイ王は突然の死を遂げてしまい、無力な赤子・アーサーとして魔法世界に転生してしまう。 そこでは自身を愛してくれる家族や仲間に囲まれ、再び赤子から成長していく日々に、前世とは異なる喜びを覚えていくアーサー。そんな時、旅の途中で家族が盗賊に襲われてしまい……。 愛と冒険に満ちた“二度目の人生”が始まる──！',
        1, 0, 0, 0, '2025-04-02'),
       (234, 164, 'ユア・フォルマ',
        'animations/234/images/f66b2909-2509-4c74-8b79-4a0b3ac8004b.webp',
        '脳の縫い糸、通称〈ユア・フォルマ〉。 1992年に起きたウイルス性脳炎のパンデミックから人々を救った医療技術は、 今や日常に不可欠な脳侵襲型情報端末へと進化をとげていた。 見たもの、聞いたこと、そして感情までも——。 全てが記録される世界で、重大犯罪事件の捜査は、 記録の集合体〈機憶〉にダイブできる特別捜査官「電索官」の仕事になっていた。 世界最年少で電索の任についた天才少女、エチカ・ヒエダ。 その才能ゆえに孤立する彼女にあてがわれた新しい相棒は、金髪碧眼のヒト型ロボット〈アミクス〉のハロルドだった。 最強の二人の前に、秘密は全て暴かれる——！',
        NULL, 0, 0, 0, '2025-04-02'),
       (235, 35, '忍者と殺し屋のふたりぐらし',
        'animations/235/images/ec60cb8b-c158-49b6-8ce0-a6039ee38bde.webp',
        '忍びの里から抜け出したくノ一さとこは、 街で行き倒れていたところを通りすがりの女子高生このはに救われる。 だがそれも束の間、さとこは里からの追手に見つかってしまう。 しかしそんな追手をあっさりと返り討ちにするこのは。 …なんと彼女の正体は殺し屋だったのだ！ 世間知らずのくノ一と殺し屋女子高生の危ない共同生活がスタート！',
        NULL, 0, 0, 0, '2025-04-10'),
       (236, 209, '中禅寺先生物怪講義録 先生が謎を解いてしまうから。',
        'animations/236/images/21b8a997-f2a8-47ec-9fde-45203764b58d.webp',
        '舞台は戦後間もない昭和23年、東京。 新制高校の二年生に進級した日下部栞奈は、国語の新任講師・中禅寺秋彦と出会う。 栞奈の周囲では、怪異にまつわる奇々怪々な事件が次々と発生。今日もまた、栞奈は助けを求め、仏頂面の中禅寺先生が待つ図書準備室の扉を開けるのだった――。',
        NULL, 0, 0, 0, '2025-04-07'),
       (237, 72, 'ボールパークでつかまえて！',
        'animations/237/images/2bfb58ad-98e1-44d3-b8eb-59bf0dfcb67b.webp',
        '「お兄さん、私のことタイプなんだ〜？」 ある日の球場で、ギャルなビール売り子に絡まれた！？ でもこの子、実は超絶ウブな純情ガールで…… 舞台は、とあるプロ野球の球場！ 日々たくさんの人が集まり、働き、笑い合い、人間ドラマが生まれるこの場所は、 まるで一つの「町」のよう！ さあ、あなたもボールパークの「住人」になりませんか！？ プロ野球に携わるすべての人々に捧ぐ 笑顔と涙の球場愛コメディー！！',
        NULL, 0, 0, 0, '2025-04-01'),
       (238, 29, '履いてください、鷹峰さん',
        'animations/238/images/a339cfe4-3820-4639-88b7-859900a93132.webp',
        '「私にパンツを履かせなさい」 ⽣徒会⻑の鷹峰さんはスクールカーストのトップオブトップ、神！ 対して、友達も存在感も皆無の⽩⽥くんは、 ある⽇鷹峰さんの⽣おっぱいを⾒てしまったことで スクールライフが変わり始める…。 なんと鷹峰さんは “未だ穢れ知らぬ⼄⼥（エターナル・バージンロード）” という能⼒でパンツを脱いで時をかける⼄⼥だった。 ノーパンではいられない鷹峰さんのクローゼットとして ⽩⽥くんは鷹峰さんにモモ⾊おねだりをされ続けるハメに…。 そんなとき思わず⾔っちゃう、 「履いてください、鷹峰さん」！ TVアニメでもたっぷりモモ⾊おねだり炸裂します！',
        NULL, 0, 0, 0, '2025-04-02'),
       (239, 78, 'GUILTY GEAR STRIVE: DUAL RULERS',
        'animations/239/images/a36950b7-81bd-4355-a7e0-23bd47c96e73.webp',
        '隆盛を極めた科学技術が衰退し、法力という新たなエネルギーが動かす時代。 人類は、禁断の生体兵器「ギア」を生み出した。 生まれてきたギア達は、やがて人類に反乱を起こすこととなる。 のちに聖戦と呼ばれる生存戦争は、辛うじて人類が勝利を得るも、その犠牲は大きく、終結から十数年の時が流れても人々の心の傷が癒えきることはなかった。 人とギアの間に生まれた子――シン＝キスクは、父カイと母ディズィーの結婚式に向かっていた。 それは禁忌の中の禁忌であった人とギアとの結婚。平穏な世でも長い時をかけて実現に至った式であった。 多くの感情が交錯するも、祝福に包まれていた結婚式。そこに突如、謎の少女が現れる―― ギアの血を継ぐ宿命の子。そしてギアを憎む謎の少女。 両者の邂逅は、世界に激震をもたらすのであった。',
        NULL, 0, 0, 0, '2025-04-05'),
       (240, 45, '未ル わたしのみらい',
        'animations/240/images/8d06a4f8-db63-4ce2-bfc0-8b31e03e86db.webp',
        '遠い先の未来に人類によって作られたロボット「MIRU」。武器を持たず、時空を超えタイムリープし、様々な時代に訪れる。時代も場所もパラレルな世界でありながら、どの時代にもいる、必死に生きている人達に出会い、その人々の悩み、苦しみに寄り添い、新たな人生への一歩を後押しする。\n人類は「MIRU」と出会う事で、希望に向かって歩き始める。\nなぜそのロボットは作られたのか、ディストピアに向かう地球の未来を救えるのか？「MIRU」そのものも完璧ではなく、人との出会いによって悩み、学んでいく。\n人類は新たな友「MIRU」を得て明るい未来への一歩を踏み出していく、歩幅の小さい一歩だが、その一歩が「バタフライエフェクト※」のように大きな変化を生み、再生に向けた一歩になっていく。\n「未来は自分たちの手でつくれる」\nそんな思いを込めたアニメです。\n※バタフライエフェクト：「非常に小さな出来事が、最終的に予想もしていなかったような大きな出来事につながる」ことを意味する言葉',
        NULL, 0, 0, 0, '2025-04-02'),
       (241, 108, '#コンパス2.0', 'animations/241/images/cdc08b0a-4c59-43c6-8c50-c047fbd3396d.webp',
        'アニメ『#コンパス2.0』では、Voidollによって幾多の世界から集められたヒーローとプレイヤーがパートナーを組み、エナジーを#コンパスの世界へ供給するため日々バトルを行っています。また、ヒーローたちはバトル以外でもその世界で快適な時を過ごしています。そんな中、13(サーティーン)はパートナーも探さずバトルもせず、ついには#コンパスから追放寸前！しかし、ある事件をきっかけに彼には他のヒーローにはない特殊な能力を持っていることがわかり…。',
        NULL, 0, 0, 0, '2025-04-07'),
       (242, 70, '神統記（テオゴニア）',
        'animations/242/images/08da1dde-9561-4bfd-a52b-a6488c5a6ec1.webp',
        '人族の土地に攻め入る灰猿人（マカク）族、豚人（オーグ）ら亜人種との戦が続く戦乱の時代。ラグ村の少年・カイは村を守るため日々戦いに明け暮れていた。\n「加護持ち」と呼ばれる強大な力を持った者たちにより厳しい戦いを強いられ次々と仲間が倒れていく中、 突如、自身が経験した事がないはずの「不思議な記憶」を思い出す。 それはこの世界より文明が進んだ技術や人々の生活の知識だった。  そして、一人の村人に過ぎなかったカイだが、やがて大きな試練に巻き込まれていくことになり…。  過酷な世界で一人の少年の戦いと成長を綴る壮大なファンタジーがここに始まる。',
        NULL, 0, 0, 0, '2025-04-11'),
       (243, NULL, 'スター・ウォーズ：テイルズ・オブ・アンダーワールド',
        'animations/243/images/a56db51d-f8ad-42bd-bb29-8b25c17b4712.webp',
        '「テイルズ・オブ・ジェダイ」、「テイルズ・オブ・エンパイア」に続くアニメ短編シリーズ第 3 弾。銀河の危険な裏社会に足を踏み入れた、2 人のヴィランの冒険を描く。元暗殺者で賞金稼ぎのアサージ・ヴェントレスは、新たな人生のチャンスを手に入れるが、思いがけない新たな仲間と共に逃亡生活を余儀なくされる。一方、無法者のキャド・ベインは、法を守る側についた旧友と対峙し、己の過去と向き合うことになる。\n5月4日(日)よりディズニープラスで独占配信中',
        NULL, 0, 0, 0, '2025-05-04'),
       (244, 42, '白豚貴族ですが前世の記憶が生えたのでひよこな弟育てます',
        'animations/244/images/3a1decd7-07fb-4087-ba0a-9f6b99aa918d.webp',
        'もっちもちほっぺに、まんまるお腹。わがまま放題に育った5歳児、菊乃井鳳蝶に生えたのは、前世――料理と裁縫と歌をこよなく愛す「オトメン」な俺――の記憶だった。\nきらきらファンタジーな現世には、優雅で美しいものや不思議なものがいっぱい！見目麗しいエルフに、人智を越えた存在の神々に、魔術の力まで！そして何より、ふわふわ「ひよこ」で「にぃにが大好き」な弟のレグルスくん。\nでも、見えないところでは、伯爵である菊乃井家内部の軋轢や、帝国貴族の腐敗が進んでて……。\n前世のスキルに、神々やエルフ、ときどき魔術の力を借りながら、幼い兄弟が挑戦する領地経営ファンタジー！',
        NULL, 0, 0, 0, '2025-04-20'),
       (245, 24, 'あらいぐま カルカル団',
        'animations/245/images/5d72d7e4-59b1-4d8a-834c-133999031fb2.webp',
        '「秘密結社カルカル団」、\nそれは全世界人気企業ランキング\n不動の１位の組織である。\n彼らの目標は世界征服！\n選ばれしエリート達はボスの指令を日々遂行している。\nそして、ここは東京都多摩——\n東京都にありながら大自然に囲まれたこの地に\n「秘密結社カルカル団」の多摩支部がある。\n振るわない営業成績、上がらない給料…。\nそれでも彼らは今日も一生懸命任務に励むのだ！',
        NULL, 0, 0, 0, '2025-04-03'),
       (246, 29, 'ばいばい、アース 第2シーズン',
        'animations/246/images/c7dd1b92-c64a-4204-a16c-c064ebd18758.webp',
        'アドニスとのいさかいや＜悪＞との激しい戦闘以来、部屋に引きこもっていたベルだったが、仲間の献身に癒やされ、＜旅の者＞になることを再び強く決意する。\n＜理由の少女＞としてこの世界の大いなる謎に迫っていくベル。\n一方、深い絶望の中、＜飢餓同盟＞に迎え入れられたアドニスは、\nベルの師匠シアンと＜飢餓同盟＞の闇に住まうドランブイによって＜懐疑する者＞として鍛えられ、世界の滅びを望む。\n「俺を、斬れるか……？俺や神を止揚することができるのか？」\nシアンの2人の教え子、ベルとアドニスの戦いが意味するものとは。\nそして、すべての戦いの先にベルが見いだした\nこの世界の＜理由＞とは。',
        2, 0, 0, 0, '2025-04-04'),
       (247, 333, 'かくして！マキナさん!!',
        'animations/247/images/f22d6c95-a356-4cd2-bbcb-c1d8da9f7a72.webp',
        '阿久津栄太（あくつ えいた）は、ぼっちで陰キャのメカオタク。\nそんな彼にも、心ひそかに憧れる女の子がいた。\n超美人で明るい人気者のギャル・我妻マキナ（あがつま まきな）である。\nそのマキナが、ある夜、栄太の家の玄関に現れる。\n何やら様子のおかしい彼女が、いきなり裸をあらわにしてみせると……\nそこにあったのは、人間とは異なる機械の体だった！\nエッチのために作られながら、アダルト情報にアクセス制限をかけられたAIロボのマキナ。\n女性には潔癖症で、どこまでもお人好しな童貞の栄太。\n二人のメカバレ厳禁な同居生活が始まる！',
        NULL, 0, 0, 0, '2025-04-06'),
       (248, 216, '華Doll*-Reinterpretation of Flowering-',
        'animations/248/images/b83b5f92-4c6d-48a3-a7e0-898757cd14ab.webp',
        '『華人形プロジェクト』のオーディションを受ける少年たち。 彼らは皆、暗然たる過去を胸に臨んでいた。 秘密を有していたのは彼らだけではない。 主催のプロダクションは、合格の条件に、完璧なアイドルとして「開花」を促すべく人生と引き換えに特殊な「種」を体内に埋め込む手術を受ける契約にサインを求める。拒否する者などいない。 何を代償にしようと、必ず『夢』を叶えてみせる――果たして、彼らの覚悟は華を咲かせるのか。',
        NULL, 0, 0, 0, '2025-04-09'),
       (249, 349, 'ちょっとだけ愛が重いダークエルフが異世界から追いかけてきた',
        'animations/249/images/5f3dd1bd-1885-4ce0-87ed-cd2ab1ea5622.webp',
        '異世界に転移し、勇者となった春原日向。 ダークエルフのマリアベル、亜人族のメイ、神官のセシルと共についに魔王を討伐。役目を終えた日向は現世へと帰還を果たし元の生活に戻る、はずだったが…… それから1カ月、マリアベルが日向の住むマンションにやって来る。目的は日向と結ばれるため！？ 同級生の持田咲良も巻き込んで、ちょっとだけ（？）愛が重いマリアベルとの甘くて刺激的な逆異世界同棲ラブコメが幕を開ける！',
        NULL, 0, 0, 0, '2025-04-06'),
       (250, 103, 'やたらやらしい深見くん',
        'animations/250/images/8317b1ea-054e-40c3-880b-acd187f2375f.webp',
        '完璧なこの俺が…なんで地味男なんかに興奮してるんだ…!?\n外面は良く人気者だが、内心では他人に点数をつけて見下してきた梶。\n自分に釣り合う最高のネコはいないかと、理想を追い求め続けていた。\nそんなある日、冴えない同僚・深見と一緒に泊まりの出張へ行くことに。\nこいつとだけは無人島で2人になってもヤるわけない――\nそう思っていたのに、風呂上がりの深見は見違えるように可愛くて…色っぽい!?',
        NULL, 0, 0, 0, '2025-04-06'),
       (251, 99, 'GAMERA -Rebirth- 新編集版', NULL,
        '最後の夏。友達。そして怪獣——。\n1989年夏、小学6年生のボコ、ジョー、ジュンイチは、小学生最後の夏休みを迎えていた。\nそんな日常を切り裂くように、怪獣ギャオスが東京を襲撃する。\n廃墟となった町でギャオスに狙われる少年たちの前に、新たな怪獣が現れた。\nその名はガメラ。ガメラは傷つきながらもギャオスと戦う。\nそれが少年たちの「怪獣の夏」の始まりだった。',
        NULL, 0, 0, 0, '2025-04-05'),
       (252, 91, 'おいでよ魔法少女村（不法占拠）',
        'animations/252/images/787dc605-e05a-4ce5-8259-e965cc68eac7.webp', NULL, NULL, 0, 0, 0,
        '2025-04-03'),
       (253, 52, 'すみっコぐらし ここがおちつくんです',
        'animations/253/images/5d41ba42-c84b-4d5b-b34f-a6b1e47e631d.webp',
        '電車に乗ればすみっこの席から埋まり、\nカフェに行ってもできるだけすみっこの席を確保したい…。\nすみっこにいるとなぜか“落ちつく”ということがありませんか？\nさむがりの“しろくま”や、自信がない“ぺんぎん？”、\n食べ残し(?!)の“とんかつ”、はずかしがりやの“ねこ”、\n正体をかくしている“とかげ”など、ちょっぴりネガティブだけど\n個性的な“すみっコ”たちがいっぱい。\nすみっこが好きな方、すみっこが気になる方、あなたもすみっコなかまになりませんか？',
        NULL, 0, 0, 0, '2025-04-04'),
       (254, 389, 'かいじゅうせかいせいふく',
        'animations/254/images/18496764-1a91-4877-ada1-20fb972e0355.webp',
        '東京の真ん中あたりの立川市に住んでいる28歳OLの『ぬし』が、 ひょんなことから4ひきのちっちゃなかいじゅうたちと暮らすことになりました。 このかいじゅうたち、なんと、はるか宇宙のかなたから地球を『せいふく』にやって来たらしいのです。 4ひきは、かわいらしい火をふく『めら』、どこでも寝られる『ぐーすか』、 面倒見が良い『あにき』、甘いもの好きの『しゅがー』 ……って、それだけでどうやって地球をせいふくするつもりでしょう！？ それは見てのお楽しみ。 他にも個性たっぷりのかいじゅうたちや、さまざまな人たちと出会い、 かいじゅうたちは『ぬし』とともに、四季折々の暮らしを満喫するのです。 『ぬし』とかいじゅうたちは思っています。 笑って暮らしているだけなんだが！',
        NULL, 0, 0, 0, '2025-04-05'),
       (255, 581, 'ンめねこ', 'animations/255/images/b72d4391-4900-438b-b987-773f605a7bae.webp',
        '話題のSNSマンガ「ンめねこ」がTVアニメ化！ 毎日のんびり暮らす猫たち。 楽しいことだけして生きていきたい。 そんな猫たちの面白おかしい日常を描いた物語がスタートします！',
        NULL, 0, 0, 0, '2025-04-03'),
       (256, 200, '最強王図鑑 ～The Ultimate Tournament～',
        'animations/256/images/757370d7-7bcc-42cc-92ee-924f643fa58e.webp',
        '四方を海に囲まれた不思議な島「最強島」では最強の中の最強「最強王」の称号をかけ動物、絶滅動物、昆虫、恐竜といった各種属の猛者たちによる壮絶なトーナメント戦が行われている。\nさらには「我こそが最強！」と名乗りを上げた水棲生物やドラゴンたちがこのトーナメントとは別の戦いを繰り広げているのだ。\n新たな「最強王」の称号を手にするのははたして誰なのか？\n「最強島」で行われる驚天動地の大バトルから目を離すな！',
        NULL, 0, 0, 0, '2025-04-06'),
       (257, NULL, '＃１ハッピーファミリーUSA',
        'animations/257/images/52a7caa0-8e02-4045-9d07-4cd03ebf19da.webp',
        'クリエイターのラミー・ユセフによる「＃１ハッピーファミリーＵＳＡ」は、底抜けに陽気なフセイン一家を描いた大人向けのアニメシリーズだ。彼らは9.11後の“アムリーカ”で最も愛国的で平和的で全く怪しくないイスラム教徒の家族である。このアニメは風刺と不条理を交えながら、恐怖に怯える隣人たちの監視下で2000年代初頭を生き抜く彼らの姿を通して、苦難の中にユーモアを見いだすことの意味を問い直している。',
        NULL, 0, 0, 0, '2025-04-17'),
       (258, 173, 'MUZIK TIGER In the Forest',
        'animations/258/images/a9fdfffa-3832-44b6-ad73-2decf5583cdf.webp',
        'きれいな湖のある MUZIK FOREST（ムジークフォレスト）。\nそこにはトラのトフィー、ティフィー、テフィー、ネズミのウィリー、さらに月から来たウサギのポルミなど個性豊かな動物たちが暮らしている。\n仕事をしなくてものんびり前向きなトフィーは、今日も自由気ままに、仲間たちと楽しくも不思議な日々を過ごしていく。',
        1, 0, 0, 0, '2025-04-02'),
       (259, NULL, 'ビッグマウス シーズン8',
        'animations/259/images/8fcacf26-9353-4d65-8a7d-ca6794df20ca.webp',
        'ついに迎える最高のハッピーエンド\n揺れ動く気持ち。変わりゆく体。抑えきれない本能。思春期ならではの\"性春\"と苦悩をやりたい放題に描いた、ありのまますぎて笑える下ネタ満載のコメディ。\nNetflixシリーズ『ビッグマウス シーズン8』独占配信中',
        8, 0, 0, 0, '2025-05-23'),
       (260, 24, 'SHIBUYA♡HACHI 第3クール',
        'animations/260/images/d596ff81-3d91-4f25-a6dc-a9903ea55dc1.webp', NULL, NULL, 0, 0, 0,
        '2025-04-05'),
       (261, NULL, 'ハーレイ・クイン シーズン3',
        'animations/261/images/7662aabe-1387-4a0f-b6d8-f44d5333839c.webp',
        'カップルになったハーレイとアイビー。世界を植物で埋めるというアイビーの夢を、ハーレイが手伝うと誓う。ところが研究の途中でカギであるフランクがさらわれてしまう。犯人の目的は何か。荒れていくゴッサム・シティをまとめるのは一体誰か。',
        3, 0, 0, 0, '2025-03-07'),
       (262, 5, 'ぷちきゅあ～Precure Fairies～',
        'animations/262/images/623c4449-3319-4da8-8b43-c257b0d08dd2.webp',
        'プリキュアのちいさななかまたちが「ぷちきゅあ」になっちゃった！\nなんでもかなっちゃう「ふしぎなゆうえんち」に、みんながだいしゅうごうして、\nおもいおもいに楽しくすごしているよ。\nお菓子を食べたり乗り物で遊んだり、とっても楽しそう！\nでも、ふしぎなことも起きていて…？\nプリキュアのなかまたちが、おやすみモードでほっとひといき♪\n「きゅあ～♡」なぷちきゅあのすがたに、きっといやされちゃう！\n毎週のおはなしをお楽しみに♡',
        NULL, 0, 0, 0, '2025-04-03'),
       (263, 249, '全力ウサギ シーズン2',
        'animations/263/images/3ca70bb5-e15b-402c-8db1-f9096a3166a6.webp', NULL, NULL, 0, 0, 0,
        '2025-04-09'),
       (264, 19, 'おしりたんてい シーズン9',
        'animations/264/images/1d51bced-e52c-400c-b083-e32f567cb6c5.webp', NULL, 9, 0, 0, 0,
        '2025-04-05'),
       (265, NULL, 'ハーレイ・クイン シーズン4', NULL,
        'ハーレイはバットファミリーの一員となって悪党退治に明け暮れ、アイビーはリージョン・オブ・ドゥームの新しいCEOとして悪事を取りしきる。立場が違えば、隠し事やすれ違いも生まれてしまう。２人はお互いの活動を尊重しながら、愛を育み続けられるのか？',
        4, 0, 0, 0, '2025-03-21'),
       (266, NULL, 'BE@BRICK', 'animations/266/images/7e2c26dd-6237-40b4-a70b-0e84e47bbe60.webp',
        '舞台はみんなの未来が最初から決められている街。シンガーソングライターを目指す主人公とバンド仲間は夢を叶えるために突き進み、まわりの人たちも少しずつ変わっていく。Apple TV＋にて 3 月 21 日（金）より全世界同時配信予定！',
        NULL, 0, 0, 0, '2025-03-21'),
       (267, NULL, '銀河系で2番目にイケてる病院 シーズン2',
        'animations/267/images/4a7488d4-2a9c-4f09-90c8-bfce209a8186.webp',
        '「銀河系で２番目にイケてる病院」シーズン２では、スリーチとクラックの両医師が手にした名声を楽しむが、サイボーグのジャーナリストがスリーチの過去を探り始めたことで雲行きが怪しくなる。',
        NULL, 0, 0, 0, '2025-05-27'),
       (268, NULL, 'スーパーキティ ニャンダフル・アドベンチャー',
        'animations/268/images/9ec8ce88-c0be-4aaa-bf3f-34d00c11a5f8.webp',
        'にゃんこたちが悪と戦うスーパーキティに大変身！可愛くも勇敢なアクション満載の人気アニメーションの短編シリーズ。キティデールの街に住む 4 匹の子猫、ジニー、スパークス、バディ、ビッツィ。誰もがただのかわいい子猫だと思っているけれど、ひとたび事件が起こるとスーパーキティに変身！そんな彼らの“スーツのひみつ”や”バディに子守りを任せたらどうなる？”などスーパーキティのことをもっと知れちゃう小さな大冒険が満載。\n5月7日(水)よりディズニープラスで独占配信',
        NULL, 0, 0, 0, '2025-05-07'),
       (269, 485, 'アステリックスとオベリックス: 史上最大のバトル',
        'animations/269/images/d6cd26da-e285-4e11-b9b1-f058192043a2.webp',
        'ローマ軍は最後までその支配を逃れていた古代ガリアのある村を征服しようと必死になっていた。アステリックスと相棒オベリックスの故郷であるその村の秘策はなんと魔法の薬。そうして戦いを有利に進めていたガリア軍だったが、薬を調合する僧が記憶を失ってしまうことで、村人たちは自分たちの力だけでローマ軍の勢力に立ち向かうことになる。\nNetflixシリーズ『アステリックスとオベリックス: 史上最大のバトル』4月30日(水)より独占配信中',
        NULL, 0, 0, 0, '2025-04-30'),
       (270, NULL, 'ハーレイ・クイン シーズン5', NULL,
        'ハーレイとアイビーがメトロポリスで新生活を始めた。街を守ってきたスーパーマンは休暇中。街に緑を増やしたいとレナ・ルーサーに依頼されるが、彼女には別の思惑があるようで…？宇宙から来たブレイニアックや恋人ができたブルース・ウェインにも注目！',
        5, 0, 0, 0, '2025-04-04'),
       (271, 99, 'メダリスト', 'animations/271/images/a44a5c34-9199-4469-916c-cc633c0c6335.webp',
        'スケーターとして挫折した青年・明浦路司が出会ったのは、 フィギュアスケートの世界に憧れを抱く少女・結束いのり。 リンクへの執念を秘めたいのりに突き動かされ、司は自らコーチを引き受ける。 才能を開花させていくいのりと、指導者として成長していく司。 タッグを組んだ二人は栄光の“メダリスト”を目指す――！',
        1, 0, 0, 0, '2025-01-04'),
       (272, 21, 'SAKAMOTO DAYS', 'animations/272/images/8194c247-1bb9-4690-aa56-7bf3a8c5a126.webp',
        '最強の殺し屋がいた その名も坂本太郎――。 全ての悪党が恐れ、全ての殺し屋が憧れたその男は――ある日、恋をした！！ コンビニで働く葵に一目ぼれした坂本は、あっさりと殺し屋を引退。 結婚、娘の誕生を経て、のどかな街で個人商店を営む坂本は、 かつての面影が無いほどに……太っていた！！ 愛する家族との平和な日常を守る為、 元・伝説の殺し屋が、次々と迫りくる刺客に挑む。 日常×非日常のソリッドアクションストーリー、ここに開幕！！',
        1, 0, 0, 0, '2025-01-11'),
       (273, 22, '薬屋のひとりごと 第2期',
        'animations/273/images/e6deadf8-28de-4b3d-9506-5d991c39659f.webp',
        '帝の寵妃・玉葉妃の妊娠判明により、猫猫は翡翠宮の毒見役に復帰。妃、そして帝の御子を狙った事件が再び起きないよう警戒をしながら、日々を送っていた。先帝時代からの重臣を父にもつ新たな淑妃・楼蘭妃の入内、壬氏の命が狙われた、前代未聞の未解決事件、そして消えた容疑者・翠苓。不穏な空気が晴れない中、外国からの隊商、さらには無理難題な要求をする特使も来訪。宮中にはさらなる暗雲が立ち込め始めていた。猫猫と壬氏を待ち受ける新たな難事件。それらは、やがて国をも巻き込む一大事件へと発展していくー',
        2, 0, 0, 0, '2025-01-10'),
       (274, 23, '俺だけレベルアップな件 Season 2 -Arise from the Shadow-',
        'animations/274/images/393e69c6-7472-49c9-979c-651fb37459fb.webp',
        '世界各地に異次元と現世界を結ぶ通路“ゲート”が出現して⼗数年。\n“ハンター”と呼ばれる超⼈的な⼒に覚醒した⼈間たちと、\nゲート内のダンジョンに存在するモンスターとの戦いは絶え間なく続いている。\n本来、ハンターの能⼒は覚醒時から成⻑せず、そのランクも変わることはない。\nしかし、⼈類最弱兵器と呼ばれていた低ランクハンターの⽔篠旬は、\n⼆重ダンジョンでのレイド中に⾃分だけが「レベルアップする」⼒を⼿に⼊れ、戦いの中で能⼒を⾼めていく。\n転職クエストをクリアして、影の兵⼠を従わせることができる職業『影の君主』を⼿に⼊れた旬は、\n病気の⺟を治す可能性のある「命の神⽔」の素材を求めて新たな戦いに⾝を投じていくのだった。',
        2, 0, 0, 0, '2025-01-04'),
       (275, 80, 'Re:ゼロから始める異世界生活 3rd season 反撃編',
        'animations/275/images/6dd3bb23-d3e9-4c57-ac97-0278d13f8679.webp', NULL, 5, 0, 0, 0,
        '2025-02-05'),
       (276, 21, 'Dr.STONE SCIENCE FUTURE',
        'animations/276/images/154646e9-ec53-47bb-86d0-4c932fd94f48.webp',
        '宝島での激戦を終え、無事に科学王国へと帰還した千空たち。手に入れた石化装置で、コールドスリープしていた司を復活させることに成功。司は科学王国の仲間となった! そして、人類石化の黑幕・ホワイマンの本拠地が“月”であることを突き止めた千空たちは、月を目指す!このストーンワールドで、ゼロから宇宙船を作るビッグプロジェクトへと乗り出した。早速、世界中から宇宙船の素材を集める為、ペルセウス号で大海原へと飛び出した千空たち。復活液の原料となる大量のコーンを求め、最初の目的地・アメリカ大陸を目指す。勇気、結束、科学力、全てが試される大航海の先に、千空たちを揺るがす脅威が待ち構えていた――!!\n遂に、千空たちの冒険は世界、そして宇宙へ向けて動き出す!人類の未来を救う為、千空は仲間と共に全力で科学の道を切り拓いていく!!',
        5, 0, 0, 0, '2025-01-09'),
       (277, 19, 'キミとアイドルプリキュア♪',
        'animations/277/images/8c836f3a-6c14-402c-bcee-4475ca2296b8.webp',
        '主人公【咲良うた】は、歌うのが大好きな中学2年生。\nある日、伝説の救世主【アイドルプリキュア】を探しにきた妖精【プリルン】と出会う！\nプリルンは、ふるさとの【キラキランド】が、【チョッキリ団】のボス【ダークイーネ】によって、真っ暗闇にされてしまったのだ。\nそんな中、街の人のキラキラがチョッキリ団によって奪われ…大ピンチ！\n「キラッキランランにしたい！　私の歌で！」\nうたの決意が結ばれ、伝説の救世主《キュアアイドル》に変身！\n歌って踊ってファンサして！\nどんな真っ暗闇でも、キミをキラッキランランにしちゃうよ！',
        NULL, 0, 0, 0, '2025-02-02'),
       (278, 289, 'デッドデッドデーモンズデデデデデストラクション アニメシリーズ',
        'animations/278/images/5debf5f2-f0f4-4534-a221-1b5393da424d.webp',
        '東京でハイテンションな女子高生ライフを送る、小山門出と“おんたん”こと中川凰蘭。ふたりが暮らす街の上空には、3年前の8月31日、突如宇宙から出現し未曽有の事態を引き起こした巨大な〈母艦〉が浮かんでいた。非日常が日常に溶け込んでしまったある夜、仲良しクラスメイトに悲劇が起こる。衝撃と哀しみに打ちのめされるふたり…。その後、大学に入学した門出と凰蘭は竹本ふたば、田井沼マコトと意気投合、尾城先輩がいるオカルト研究会に入り浸り、大学生生活を謳歌するが…一方、宇宙からの〈侵略者〉は東京のそこかしこで目撃され、上空の母艦は傾き、煙を立ちのぼらせている。政府転覆を狙い〈侵略者〉狩りを続ける過激派グループ・青共闘が暗躍し、世界が終わりに向かうカウントダウンが刻まれる中、凰蘭は、不思議な少年・大葉に遭遇する―',
        NULL, 0, 0, 0, '2024-12-04'),
       (279, 417, 'ババンババンバンバンパイア',
        'animations/279/images/3585306c-0f22-47c2-9d2c-cb7e98f0abd1.webp',
        '創業60年の老舗銭湯「こいの湯」で住み込みバイトをしている森蘭丸。 彼は、人の生き血を啜る正真正銘のバンパイアだった。 蘭丸の目的は、自分の命を救ってくれた「こいの湯」の4代目・立野李仁への恩返し。 そして… 彼の「18歳童貞の血」を味わうこと…！ 現在15歳の李仁が熟すまで、あと3年。 しかし入学早々、李仁は同級生の女子に一目惚れしてしまう。 はたして蘭丸は、念願の「18歳童貞の血」を守り通すことができるのか…！？',
        NULL, 0, 0, 0, '2025-01-11'),
       (280, 62, '天久鷹央の推理カルテ',
        'animations/280/images/3b2161a1-5402-4dbe-ae17-4f4b2f0d9a27.webp',
        'シリーズ累計発行部数350万部突破！！ 現役医師のベストセラー作家・知念実希人と、 珠玉のイラストレーター・いとうのいぢが紡ぐ、 最注目の医療ミステリー逆転劇、 待望のテレビアニメ化決定！！ 天医会総合病院、統括診断部。 ここには他の医師が「診療困難」とした患者たちが集められる。 さらには、警察すら手に負えない原因不明の「殺人」や「謎」も……。 天才医師・天久鷹央が解き明かす、 摩訶不思議な「病」に秘められた驚愕の真実とは……！ 「その病気（ナゾ）、私が診断を下してやろう――！！」 第1話／第2話は原作・知念実希人書き下ろし完全新作エピソード！！ 大きな獣に足を食いちぎられた、青い血の男に隠された秘密とは──？',
        NULL, 0, 0, 0, '2025-01-01'),
       (281, 61, 'わたしの幸せな結婚 第二期',
        'animations/281/images/eddf21d8-5a85-408e-a906-0211eb44a1a6.webp',
        '「異能」の名家に生まれながらも その才を持たず、家族から虐げられて育った少女・美世は、これまでに数多の婚約者たちが逃げ出し“冷酷な軍人”と噂される久堂家当主・清霞のもとへ嫁ぐ。 始まりは、誰もが不幸な結末を予測する政略結婚だった。 だが、清霞は美世の偽りない純粋さに心解かれ、美世もまた、そんな清霞の芯にある優しさに心温められていく。 「旦那さまの力になりたい」――。 そう願うようになった美世は、亡き母の深い愛のもとに封印されていた「夢見の力」を開花させ、ついには清霞の危機を救う。 ふたりはお互いの存在によって幸せを知り、末永く寄り添い合って生きていくことを誓うのだった。 しかし、来春にも挙式を予定し、穏やかな日々を過ごすふたりに思わぬ出来事が訪れる。 清霞の父・正清に招待され、隠居先の屋敷へ向かったふたりを待ち受けていたのは、清霞の母・芙由の激しい罵倒。 美世は「久堂家の嫁」として認められるべく、奮闘する。 そこにまとわりつく怪しい視線の理由も知らず……。 ときを同じくして、屋敷の付近で相次いでいた 「鬼」の目撃情報を調査していた清霞は 国家転覆を企てる「異能心教」と交戦し……。 「厄災が来る」――。 帝都の平和を揺るがす、新たな事件の幕が開ける。 ふたりは、祝福された未来へ辿り着くことができるのだろうか？',
        2, 0, 0, 0, '2025-01-06'),
       (282, 85, '悪役令嬢転生おじさん',
        'animations/282/images/007161ad-4700-407a-a606-7d5a496f2156.webp',
        '52歳の真面目な公務員、 屯田林憲三郎は交通事故で死んだ。 ……はずだったが 目を覚ますとなんと彼は娘がハマっている 乙女ゲーム「マジカル学園ラブ＆ビースト」の世界に転生していた！！ 転生した人物はゲームの主人公、アンナ・ドールの恋路を邪魔する 悪役令嬢、グレイス・オーヴェルヌ。 そこで本来のグレイス同様、悪役令嬢として立ち振る舞おうとする グレイス＝憲三郎。 だが、自身の経験値からアンナを包み込むような親目線発言と 庶民的な言動を優雅なものに自動変換する能力【優雅変換】（エレガントチート）が 相まって自身の評価が爆上がり！ さらに意図せずゲーム攻略対象のイケメンたちとフラグが立ちまくりで！？ 異世界で生き抜くための武器は剣！？魔法！？ いいえ、社会で培ったおじさんスキルです！！ おじさん×異世界転生×悪役令嬢でお届けするほのぼのコメディ、堂々開幕（スタート）',
        NULL, 0, 0, 0, '2025-01-09'),
       (283, 135, 'どうせ、恋してしまうんだ。',
        'animations/283/images/b66bc862-dc3f-4bef-8693-d4f5f5d05648.webp',
        '2020年7月1日。高校2年生の水帆は、最悪な17歳の誕生日を迎えていた。 憧れの先輩に近づくチャンスはなくなるし、 親には誕生日をすっかり忘れられているし……。 しかも未知の感染症の流行で、部活の大会や修学旅行も中止になって、 「私には“キラキラした青春”なんてない」――そう思っていた。 しかしそんな矢先、幼なじみの輝月が、 突然、“彼氏候補宣言”をしてきて――。 家族のように育った4人の幼なじみの男の子と、 主人公の西野水帆との恋愛模様を描いた学園青春ストーリー。',
        1, 0, 0, 0, '2025-01-09'),
       (284, 150, '君のことが大大大大大好きな100人の彼女 第2期',
        'animations/284/images/c28b616a-9809-4349-ab85-14f8779b6415.webp',
        '中学で失恋 100 回を達成した愛城恋太郎は、⾼校でこそ彼⼥を︕と願い訪れた神社で、現れた恋の神様から「⾼校で出会う運命の⼈は 100 ⼈いる」と告げられる。\nしかし神様いわく、運命の⼈と出会った⼈間は、その相⼿と愛し合って幸せになれなければ死んでしまうという……。\n次々に待ち受ける運命の⼈との出会いーーどうする恋太郎︖どうなる 100 ⼈の彼⼥︕︖',
        2, 0, 0, 0, '2025-01-12'),
       (285, 58, 'ギルドの受付嬢ですが、残業は嫌なのでボスをソロ討伐しようと思います',
        'animations/285/images/e62f09af-5095-4306-a141-089f3ad478d1.webp',
        '〈ギルドの受付嬢〉。 業務内容は絶対安全。公務だから立場も安定。可愛い制服に身を包み、カウンター越しに笑顔で冒険者たちをご案内。 受付時間が終わったら、のんびりと事務作業を済ませて定時に帰宅。愛しの我が家でくつろいで、さあ、明日も元気に働こう――。 アリナ・クローバーは、そんな理想の職業に就いたはずだった。 しかし。その実態は、理想とは程遠かった―。めんどくさい対応を求める冒険者もちらほら。 顔で笑って心で泣いて、厄介な顧客をやり過ごしても、今度は大量の書類仕事が待っている。 やる気は残ってないけれど、明日に回せばなおしんどい。おかげで来る日も来る日も残業地獄…。 ああ、もう我慢の限界！！ アリナが不満を爆発させると、隠し持った一面が顔を出す。 チームで挑むことすら危険なダンジョンにソロで乗り込み、銀に輝く大鎚【ウォーハンマー】で、強大なボスを叩き伏せる――。 何を隠そう彼女こそ、正体不明、神出鬼没、街で噂の凄腕冒険者〈処刑人〉その人だったのだ！！ でも、そのことは絶対に隠し通さなければならない。 なぜなら受付嬢は副業禁止で、バレたら即刻クビだから…。 アリナの平穏な暮らしは、守られるのか！？ 第27回電撃小説大賞《金賞》受賞作、待望のアニメ化！',
        NULL, 0, 0, 0, '2025-01-10'),
       (286, 17, 'ハニーレモンソーダ',
        'animations/286/images/121ea8ca-7c4c-4243-9f58-5dbc0ca42253.webp',
        '中学時代“石”と呼ばれていた石森羽花は、自分を変えるため、自由な校風の八美津高校に入学した。同じクラスで隣の席になったのは、レモン色の髪をした、クールで自由奔放な「レモンソーダ男子」の三浦界。実は羽花は中学時代に一度だけ界に会い、そのひと言をきっかけに高校を決めた。 羽花にとっては、人気者の界は遠い存在。そんな界が、なぜか羽花の世話を焼くようになる。 界が背中を押してくれることで、少しずつクラスに溶け込んでいく羽花だったが・・・。 羽花の世界はどんどん、界の存在によって変わっていく―――。',
        NULL, 0, 0, 0, '2025-01-08'),
       (287, 56, '地縛少年花子くん２',
        'animations/287/images/993ec406-83ec-450c-9c66-3b66f5a6dd25.webp',
        'ねえ、知ってる？ かもめ学園の七不思議、七番目の噂話。 旧校舎3階の女子トイレ。 そこには花子さんがいて、何かひとつを代償に呼び出した人の願いを叶えてくれる。 呼び出し方はノックを3回。 そして―― 「花子さん、花子さん、いらっしゃいますか？」 七不思議七番目『トイレの花子さん』こと“花子くん”と縁を結んだ少女・八尋寧々。祓い屋の少年・源 光。 2人は花子くんと共に、改変された七不思議や怪異たちの噂を元に戻すため、日々奔走していた。 ある日、花子くんは言う。 七不思議の中に裏切り者がいる、と。 寧々たちは裏切り者を炙り出すため、七不思議の依代を破壊していく。 二番目『ミサキ階段』、五番目『16時の書庫』を壊し、残る七不思議は『トイレの花子さん』を含めると五つ…… 一方、その裏で花子くんの弟・つかさは、七峰 桜、日向夏彦、 そして新たに七不思議三番目『カガミジゴク』となったミツバと共に、 寧々たちがまだ見ぬ七不思議に近づいて――',
        2, 0, 0, 0, '2025-01-12'),
       (288, 21, '名探偵コナン 2025年',
        'animations/288/images/784a6dc0-cb9c-47a1-8760-1194fcf90458.webp', NULL, NULL, 0, 0, 0,
        '2025-01-04'),
       (289, 35, '五等分の花嫁＊', 'animations/289/images/6c7b74bd-2b2a-45b5-8d68-ed6afc23e716.webp',
        'ファン待望の新婚旅行エピソードを、春場ねぎ原案＆完全監修のもと映像化。 大人になった風太郎と五つ子の日常をお届けします！ 「落第寸前」「勉強嫌い」の美少女五つ子を、 アルバイト家庭教師として見事「卒業」まで導いた風太郎。 それぞれの道へと歩み夢を叶えた五つ子だったが、何か悩みを抱えている様子で...。 そんな中、風太郎と五つ子はハネムーンを兼ねたハワイ旅行を計画する。 順調に準備が進んでいた矢先、ある事件が発覚し大慌ての事態に！！ さらには旅行先のハワイでもトラブルに巻き込まれて…！？',
        4, 0, 0, 0, '2024-12-23'),
       (290, 190, 'アラフォー男の異世界通販',
        'animations/290/images/a4798e6a-8c96-4784-988c-8b19d39cebd0.webp',
        'アラフォーの独身男・ケンイチは、突如として異世界に転移してしまう。 わけもわからず危険な森をさまよう中で、 巨大ネット通販サイト「シャングリ・ラ」が使えることに気づく。 それは異世界のアイテムを換金し、現代日本の商品を購入できる“チート能力”だった！ 能力を駆使して商売を始めたケンイチは、瞬く間に商人として頭角を現していく。 「目指すは、異世界でのスローライフ！」 街はずれの森で自由気ままな自給自足の生活を送ろうとするが……。 才気溢れるケンイチに惹かれた少女たちが押し寄せ、 さらには次々とトラブルに巻き込まれ―― アラフォー男は、念願のスローライフを実現できるのか！？ 異世界ファンタジーここに開幕！！',
        NULL, 0, 0, 0, '2025-01-09'),
       (291, 68, 'クラスの大嫌いな女子と結婚することになった。',
        'animations/291/images/dc76ab28-6ade-4de5-8913-4f5710370247.webp',
        '高校生の北条才人はクラスメイトと結婚した。それも学校一苦手な、天敵のような女子・桜森朱音とである――。\n「私と結婚してること、クラスのみんなに言ったら殺すから」「俺だって結婚を知られたくはない。なんのメリットもない」\n普段から嫌い合う二人の新婚生活が上手くいくはずもなく、なにかと衝突ばかり。しかし、日々の暮らしの中で歩み寄ることで距離が縮まっていき、一緒にいて楽しい時間が増え、少しずつお互いを理解していく。才人は今まで知らなかった朱音の可愛い素顔を知り、朱音は心の中に秘めていた想いに段々と気づき始め……。\n素直になれそうでなれない二人が送る胸キュン新婚生活、ここに開幕――！',
        NULL, 0, 0, 0, '2025-01-03'),
       (292, NULL, 'UZUMAKI: Animated TV Series',
        'animations/292/images/a8299b34-78da-49dd-9ecf-e45a9cc1d728.webp',
        '女子高生の五島桐絵と恋人の斉藤秀一が暮らす町が、異様なうずまきに汚染され始める。町の誰もがうずまきの呪いに侵されるなか、桐絵と秀一は果てしない恐怖と絶望にのみ込まれてゆく。',
        NULL, 0, 0, 0, '2024-12-20'),
       (293, 42, 'いずれ最強の錬金術師？',
        'animations/293/images/907fc954-3262-4ba3-b866-fe8026ea8fa2.webp',
        '勇者でもないのに勇者召喚に巻き込まれてしまったアラフォーサラリーマン、入間 巧。 間違って呼ばれて元の世界に戻ることもできなくなってしまったタクミは、 「巻き込んだお詫びに」と女神ノルンから手厚すぎるほどの加護と過保護なサポートを受け、 剣あり魔法ありのファンタジー世界『ミルドガルド』で人生をリトライすることに。 「戦闘職は絶対合わない」と地味な生産職を希望し、 バトルとは無縁の穏やかで慎ましい異世界ライフを希望――のはずが 与えられたスキル『錬金術』は、聖剣から空飛ぶ船まで何でも作れる超最強スキルだった……！ ひょんなことから手にしたチートスキルで、商売ではボロ儲け、バトルでは無双状態に！？ 「第10回アルファポリスファンタジー小説大賞」読者賞受賞、 シリーズ累計発行部数120万部突破、コミカライズも絶好調の大人気作が、待望のアニメ化！ 望んでいないのに最強になってしまった錬金術師の、ほのぼの（？）異世界冒険譚が幕を開ける！！',
        1, 0, 0, 0, '2025-01-08'),
       (294, 78, 'BanG Dream! Ave Mujica',
        'animations/294/images/e7653331-6d8c-4e0d-8bfd-3793990beb9b.webp',
        '「言ったでしょう？残りの人生、わたくしに下さいと」 豊川祥子がメンバーを招き入れたバンド・Ave Mujicaは、 ライブやメディア露出など、商業的な成功を収めていた。 運命をともにすると誓った仲間も、生まれ育った家も失った少女。 彼女は何のために他人の一生を背負い、バンドを続けるのか。 過去も素顔も仮面で覆い隠し、今宵も完璧な箱庭に降り立つ。 ――これからご覧にいれますのは、秘密を抱えた、彼女の話。',
        NULL, 0, 0, 0, '2025-01-02'),
       (295, 49, '黒岩メダカに私の可愛いが通じない',
        'animations/295/images/044896ab-4c9b-422a-a08b-ff7700279cde.webp',
        '容姿端麗！スタイル抜群！川井モナは、息をするようにモテる女！！ しかし、そんな彼女に見向きもしない転校生・黒岩メダカの登場で、 モナの学校生活は一変する！「今までずっと、チヤホヤされて生きてきたのに！！」 あの手この手でメダカをオトそうと大奮闘！時にはちょっぴりカゲキなことも！？　 モテ女子×禁欲男子のラブコメディ、大勃発――！！',
        1, 0, 0, 0, '2025-01-06'),
       (296, 115, 'もめんたりー・リリィ',
        'animations/296/images/8f2c6f83-1a54-4038-9a03-aff6f545082d.webp',
        'ある日、空から機械仕掛けの侵略者“ワイルドハント”が現れ、あらゆる生命体を消滅させた。 荒廃した無人都市を放浪する、記憶を失った少女「れんげ」。 彼女は侵略者に対抗するための、ある大きな“力”を有していた。 街を彷徨う中、れんげは自分と同じ“力”を持つ5人の少女と出会う。 出会った仲間たちと日々過ごす中、日常を突如壊す侵略者と命がけで戦っていく。 やがて世界の謎を追いかける中で、僅かに残った人類や家族たちと再会した時、れんげは大きな謎に直面する。 そして自身の持つ“力”にまつわる、大きな謎に迫っていく。',
        NULL, 0, 0, 0, '2025-01-02'),
       (297, 150, 'グリザイア：ファントムトリガー',
        'animations/297/images/7017b1c7-45c5-4d16-90ee-18edc9447a10.webp',
        '『グリザイアの果実』から数年後…かつて少女たちの箱庭だった「美浜学園」は国防を担う人材を育てるSORD(ソード)訓練校へと生まれ変わった。拳銃を使用するレナ＆マキ、狙撃を得意とするトーカ＆グミ、爆弾と情報処理のクリス、諜報活動担当の忍者ムラサキ。彼女たちは、警察や自衛隊には解決できない事件にあたり、危険な活動を繰り返す。これは、血と硝煙に彩られた少女たちの物語──',
        NULL, 0, 0, 0, '2025-01-01'),
       (298, 75, '異修羅 第2期', 'animations/298/images/742f52f5-6eff-454d-b107-5f28a991fafb.webp',
        '“本物の魔王”の死後、恐怖の時代は終わったかに見えたが、 単独で世界を変革しうる“最強”たちが新たな脅威となった。 黄都からの独立を宣言したリチア新公国は、 この力をもって覇権国家である黄都との全面戦争を開始。 この二つの国が引き起こした新魔王戦争は、圧倒的な力を振るう修羅たちの激突によって、 凄惨な破滅という結末を迎えた。 しかし、世界にはまだ時代を変革しうる逸脱の存在がある。 あらゆる能力や種族の頂点を極めた修羅たちと、 それを利用すべく謀略を巡らす者たちが一点に集うとき、 宿命と凶兆は交差し、すべてを塵に帰す大いなる災厄が訪れる。',
        2, 0, 0, 0, '2025-01-08'),
       (299, 25, 'キン肉マン 完璧超人始祖編 Season 2',
        'animations/299/images/bd0ea2c1-589f-4e21-acb9-ceeb7624b26f.webp', NULL, 4, 0, 0, 0,
        '2025-01-12'),
       (300, 38, '全修。', 'animations/300/images/38b34cf5-0b53-49d1-96fd-8eb00aad0ffa.webp',
        '広瀬ナツ子は、高校卒業後アニメーターとなり才能を開花させ、あっという間に監督デビューを果たす。初監督作品は社会現象になる大ヒット。新進気鋭の天才監督と世間でも評価され、次回作は初恋をテーマにした劇場ラブコメ作品に決定！しかし、人を好きになったことがないナツ子は初恋がよくわからず、コンテが描けなくなり映画制作が行き詰る。そんなある日、コンテ作業中に意識を失い、目が覚めるとそこは、子供の頃に夢中になったアニメ映画『滅びゆく物語』の世界だった。',
        NULL, 0, 0, 0, '2025-01-05'),
       (301, 134, 'BEASTARS FINAL SEASON Part1',
        'animations/301/images/4ee7ae43-4db0-4078-8d4d-dd1ee5e9e60c.webp',
        'リズとの対決を経て自主退学を選択したレゴシは、コーポ伏獣での一人暮らしを開始。一方、青獣ビースターを辞退し卒業したルイは、父・オグマに向き合う決意を固める。キャンパスライフを謳歌するハルにも悩みは尽きず…。その頃、現役ビースター・ヤフヤは、殺獣に快楽を求める凶悪犯・メロンを追っていた。レゴシとメロン、交わるはずのなかった運命を結びつけたのは、レゴシの家族が秘めたある秘密だった…。',
        3, 0, 0, 0, '2024-12-05'),
       (302, 166, '花は咲く、修羅の如く',
        'animations/302/images/26bc467e-5e14-4d21-903a-6067521bfa8f.webp',
        '人口600人の小さな島・十鳴島（となきじま）に住む春山花奈（はるやまはな）は、島の子供たちに向けて朗読会を行うほど朗読が好きだった。花奈の“読み”に人を惹きつける力を感じた薄頼瑞希（うすらいみずき）は、自身が部長を務める放送部へ誘う。 「お前の本当の願いを言え、アタシが叶えてやる」 「私、放送部に入りたいです」 入部を決意した花奈は、たくさんの“初めて”を放送部のメンバーと共にし、大好きな朗読を深めていく…。',
        NULL, 0, 0, 0, '2025-01-07'),
       (303, 60, 'スパイダーマン：フレンドリー・ネイバーフッド',
        'animations/303/images/59939cdb-87f6-4d0d-b4f2-8bdf931acde8.webp',
        'ピーター・パーカーはヒーローになるための道を歩んでいるが、その道のりは平凡ではない。\nディズニープラスにて1月29日(水)より独占配信中',
        NULL, 0, 0, 0, '2025-01-29'),
       (304, 169, '誰ソ彼ホテル', 'animations/304/images/4504ba52-dcaf-49d4-a753-aa115ec7ed0e.webp',
        '本当のあなたは誰ですか？ 昼も夜もなく、一日中夕暮れに染まっている「黄昏ホテル」。 それは、あの世に行くか現世に戻るか、 行き先を決めかねている魂たちが羽を休めるために存在する生と死の狭間のホテル。 主人公塚原音子は、自分が何者なのかどうしてここにいるのか、記憶を想い出せないまま「黄昏ホテル」に彷徨いつく。 従業員の先導で、宿泊部屋に案内されることに。 「部屋にはお客様の記憶にまつわる品があるはずです。それを手がかりにお客様の記憶を取り戻すことができるかもしれません。」 現世に帰るために探索し自分を想い出していく中、とある事件に直面するーー',
        NULL, 0, 0, 0, '2025-01-08'),
       (305, 168, 'クリーチャー・コマンドーズ',
        'animations/305/images/60864b69-4be1-4584-b769-dd2462a63d31.webp', 'U-NEXT にて独占配信中',
        NULL, 0, 0, 0, '2024-12-05'),
       (306, 29, '魔法使いの約束',
        'animations/306/images/211f582b-af9c-42d2-b3aa-e5de3ce388b5.webp',
        '初めまして、賢者様。ようこそ、壊れかけの世界へ\n風が強くて、猫が騒ぐ満月の夜。平凡な日常を送っていた真木晶が迷い込んだのは、\n魔法使いと人間が共存する世界。\n五つの国で形成されたその世界では、〈大いなる厄災〉と呼ばれる巨大な月が、年に一度、襲来する。\nその月と戦い、押し返す使命を持つ『賢者の魔法使いたち』——彼らを束ねる『異世界からの賢者』として、\n晶はこの世界に召喚されたのだ。\n月と戦い、世界を救うため。そしてそれ以上に、人間と魔法使いの架け橋となるために。\n悠久の時を生き、自分の心に従い魔法を使う魔法使いたちに、寄り添い、心を繋ぐ努力をする晶。\n「いつか、あなたと友人になれたなら」。\n美しく恐ろしい壊れかけの世界で、魔法使いたちとの忘れがたい不思議な日々が始まる——。',
        NULL, 0, 0, 0, '2025-01-06'),
       (307, 72, '妃教育から逃げたい私',
        'animations/307/images/ec85bfb2-3d9a-4955-912f-d4b8d7bdb579.webp',
        'アスタール王国の王子クラークの婚約者として、 幼少から厳しい妃教育を受けてきたレティシア。 でも、本当は魚を釣って、木登りをして、自由に暮らしたい！ 「婚約破棄」を願うレティシアは、 ある日の舞踏会で見知らぬ女性をエスコートするクラークを目撃。 王子の心変わりに胸を躍らせ、別れを告げるのだが…… クラークは結婚を諦めていなかった！ 妃教育から逃げて自由に生きたいレティシア。 彼女を必ず追いかけ、まっすぐな愛情表現をするクラーク。 婚約破棄したい妃候補VS結婚したい王子のドタバタ胸キュンバトル開幕！！',
        NULL, 0, 0, 0, '2025-01-05'),
       (308, 70,
        '外れスキル《木の実マスター》 ～スキルの実（食べたら死ぬ）を無限に食べられるようになった件について～',
        'animations/308/images/197facf1-6fe7-40da-95ef-4131105b778f.webp',
        '“スキルの実”を食べることで、特別な能力を1つ授かることができる世界。 そこで史上最高の冒険者を目指す少年・ライトが手に入れたのは、 戦闘能力皆無、木の実栽培に特化した外れスキル《木の実マスター》だった……。 “スキルの実”はふたたび食べると必ず死ぬため、やり直しはできない。 一方、「一緒に冒険者になる」と約束した幼馴染・レーナは 史上最速でSランクになり、差が開いていく。 農作業と剣の修行に打ち込む日々を送るライトだが ある日偶然、2つ目の“スキルの実”を食べてしまい―― 「なんで死んでないんだ……！？」 死亡フラグを回避したライトは、《木の実マスター》の真の力を知ることになる。 それは何回でも“スキルの実”を食べられるという驚愕の能力だった！ 食べるたびに能力が無限追加されるハイパーチート！！ 最下位スキルは最上位スキルだったのだ！！！ 最強へのサクセスファンタジーが、ついに待望のアニメ化！ 冒険者になれないと言われた男による、歴史に名を残す冒険が、いま始まる……！',
        NULL, 0, 0, 0, '2025-01-07'),
       (309, NULL, 'ウィン OR ルーズ',
        'animations/309/images/2d687fb7-b0ae-4ee7-85b9-2a9b5235c555.webp',
        'ピクサー初のオリジナルシリーズは、８人の異なるキャラクターがそれぞれ、ソフトボール選手権大会の大一番に向け、様々に関わっていく様子を描く。不安定な子供たち、干渉しすぎる両親、恋多き審判員など、それぞれのキャラクター目線での感情を、非常に面白く、表情豊かに、ユニークなアニメーションで明らかにしていく。 本シリーズは、キャリー・ホブソンとマイケル・イェーツが監督・脚本・製作総指揮を、デイビッド・ラリーがプロデューサーを務める。',
        NULL, 0, 0, 0, '2025-02-19'),
       (310, 128, 'サラリーマンが異世界に行ったら四天王になった話',
        'animations/310/images/f7471e67-ae2c-4e86-a16d-c0cc81e65f7d.webp',
        '異世界に君臨する魔王軍の四天王。 その最後の一席に選ばれたのは…… 冴えないサラリーマン、ウチムラデンノスケだった！ 魔王軍からヘッドハンティングを受けたウチムラに用意されていたのは、 役員レベルの好待遇—— だが魔王軍の業務は、命がけの厳しいミッションの連続で……！？ 特別な能力は何も無いウチムラは、 この異世界の難題にサラリーマンの経験と知恵で立ち向かっていく！ すべての働く人たちに贈る異世界転職譚！',
        NULL, 0, 0, 0, '2025-01-06'),
       (311, 159, 'この会社に好きな⼈がいます',
        'animations/311/images/9763c4fb-2eed-443a-84e8-a11e84b955ff.webp',
        'お菓子メーカーに入社した、 経理部に勤める生真面目アラサー男子・立石真直と 企画部で働く勝気な同期女子・三ツ谷結衣。 周囲からは「犬猿の仲」だと認識されている 性格が正反対の2人だが、 実はお互い惹かれていて……？！ 秘密厳守の ピュア社内恋愛ストーリー”が開幕！',
        NULL, 0, 0, 0, '2025-01-06'),
       (312, 18, 'マジック・メイカー　～異世界魔法の作り方～',
        'animations/312/images/a3e9b47f-5410-4572-bf49-8ebe32aa20fc.webp',
        'リスティア国の片田舎の領地を治める下級貴族、オーンスタイン家。そこには、二人の姉弟がいた。 姉のマリーは、父から剣術の稽古を受けるのが大好きな活発な女の子。 弟のシオンは、部屋に籠もって本を読むのが大好きな内気な男の子。 性格は正反対の二人だが、優しい両親に見守られながら、仲睦まじく暮らしていた。 そんなある日、シオンは『まほう』というものがこの世界に存在するか、父に尋ねる。 しかし、貴族としてそれなりの教養がある父でも、『まほう』という言葉自体を知らなかった。 ましてや、シオンが言う「火とか水とか風とか光とか、何もないところからいろんなものを出したりする」現象など、この世には存在するはずもなく……。 その日から、シオンは目に見えて落ち込んでしまう。 シオンを励ましたいと、幼馴染みで農家の娘のローズに話すマリー。 すると、湖で不思議な現象を目の当たりにして―― この異世界、魔法がない！？ そんな世界に転生した主人公の少年シオンが紡いでいく、ロマン求める魔法開発ファンタジースタート。',
        NULL, 0, 0, 0, '2025-01-08'),
       (313, 99, 'Unnamed Memory Act.2',
        'animations/313/images/54e73ffd-520c-47de-86ea-2eb73bd2e1bf.webp',
        '400年前――魔法士ラナクの裏切りにより魔力を暴走させ、魔法大国トゥルダールを一夜にして滅ぼしたティナーシャ。その忌まわしい過去はオスカーによって改変され、世界は“⻘き月の魔女”が存在することのない新たな時を刻み始めた。ティナーシャはトゥルダールの女王に即位し、やがて⻑い眠りにつく。すべての苦しみから自身を救い、愛を告げて消滅していったオスカーと遠い未来で再び出会うために......。そして、400年後――書き換えられた世界のオスカーがトゥルダールを訪れる。目覚めたティナーシャとの間に、共に過ごしてきた思い出は何ひとつない。消え去った世界で結ばれたことさえ知らぬ二人は、ここからどんな物語を紡いでいくのか――。',
        2, 0, 0, 0, '2025-01-07'),
       (314, 28, 'ドラえもん 2025年', NULL, NULL, 21, 0, 0, 0, '2025-01-04'),
       (315, NULL, 'テイルズ・オブ・ザ・ミュータント・タートルズ',
        'animations/315/images/0dea8770-0120-4b4b-9137-8d66d5e96873.webp',
        '12月6日（金）よりParamount+にて独占配信開始', NULL, 0, 0, 0, '2024-12-06'),
       (316, 106, '沖縄で好きになった子が方言すぎてツラすぎる',
        'animations/316/images/c3a83bd6-779f-4c3b-8994-08290d6cd091.webp',
        '沖縄に転校した中村照秋（てーるー）は、同じクラスの喜屋武さんを好きになった。 これで夢の高校生活が始まる…！と思いきや、彼女の話すうちなーぐち（方言）がさっぱり理解できない！！ そんな彼女の方言を訳してくれる比嘉さんには、いつも助けられてばかりいるのだが…… 実は比嘉さんは、てーるーに片想い中!? 東京とはまったく違う南の島で、ちょっぴり変わった異文化恋愛スタート!!',
        NULL, 0, 0, 0, '2025-01-04'),
       (317, 59, 'Aランクパーティを離脱した俺は、元教え子たちと迷宮深部を目指す。',
        'animations/317/images/f3e3b010-116a-44a1-af85-fbf99275a24d.webp',
        '「抜けさせてもらう!」―― 赤魔道士のユークはそう啖呵を切って、5年間在籍したAランクのパーティ「サンダーパイク」を離脱した。\n彼は、他のメンバーから過小評価、否、バカにされていたことに耐えきれず、ついにその地位を捨てたのだ。 パーティを探していたユークはマリナ、シルク、レインという元教え子3人と再会し、彼女たちのパーティに加入した。「先生」と慕ってくれる彼女たちに励まされ、ユークはその規格外の魔法力とスキルを存分に発揮し、マリナたちの能力を見事に引き出すことで次々にクエストを達成。\nそして、配信用魔法道具(アーティファクト)「キャメラット君」による“冒険配信”を通じて、パーティ「クローバー」は世間に名を馳せていく。 そんな「クローバー」の夢は最難関迷宮【無色の闇】の踏破。それを叶えるため、様々な迷宮(ダンジョン)に挑戦するが、徐々に世界を揺るがす混沌へと巻き込まれていく――',
        1, 0, 0, 0, '2025-01-11'),
       (318, NULL, 'シークレット・レベル シーズン1',
        'animations/318/images/a76220da-bb15-4cfa-9805-a405fd4d2e5c.webp',
        '「シークレット・レベル」は、世界中で愛されるビデオゲームの世界を舞台にオリジナルストーリーを描く大人向けのアンソロジーアニメシリーズ。「ラブ、デス＆ロボット」のクリエイターによる15話から成る各エピソードは、ゲームとゲーマーへの賛歌だ。\n12月10日（火）よりPrime Videoで独占配信中',
        1, 0, 0, 0, '2024-12-10'),
       (319, NULL, 'ホワット・イフ…？ シーズン3',
        'animations/319/images/cd021815-83e4-45c3-8b7e-10080a8459d7.webp',
        'もしもアベンジャーズたちに別の運命が待っていたとしたら…？マーベル・スタジオ実写映画製作陣が贈る、マーベル・シネマティック・ユニバースのヒーローたちの想像を超えた“もしもの世界”の物語を描くアニメーション・シリーズ最終シーズン！前シーズンから引き続き、“ウォッチャー”と呼ばれる男をガイド役に、ヒーローたちの驚くべき“ありえたかもしれない”ストーリーへと導く。',
        3, 0, 0, 0, '2024-12-22'),
       (320, 157, '空色ユーティリティ',
        'animations/320/images/3c70cf4f-2adb-4cef-b777-5ac5fccfd2aa.webp',
        '「このままじゃ、ただの村人Aで卒業しちゃう！」 青羽美波は悩んでいた。 得意なこともやりたいことも特にナシ。 花の女子高生活、こんなモブキャラで終わっていいのか！？ 学校を飛び出し、自分だけの“スペシャルな特別”を探す美波。 偶然たどり着いたのは近所のゴルフ練習場。 アルバイトの茜遥に声をかけられ、ゴルフクラブ―――“ユーティリティ”を握る美波。 それが、美波とゴルフの出逢いだった。 プレーして勝つことだけがゴルフじゃない！ ゴルフにまつわるすべてのことが楽しいのだ！ 天才肌ゴルファーの遥、インフルエンサーを目指す星美彩花とともに、 自分が「主人公」になれる瞬間を求めて！ スーパー初心者・美波は、今日もクラブを振り上げる。',
        NULL, 0, 0, 0, '2025-01-03'),
       (321, 34, '戦隊レッド 異世界で冒険者になる',
        'animations/321/images/4cd1edef-4713-467f-8aa2-0733084f226d.webp',
        '真っ赤なヒーロー、異世界に立つ！ 世界征服を企む悪の組織《秘密結社ゼツエンダー》。 その野望に立ち向かう、絆で結ばれた5人の戦士たちがいた。 そのヒーローの名は、《絆創戦隊キズナファイブ》！！ キズナファイブの5人は、遂にゼツエンダーとの最終決戦へ。 壮絶な戦い中で傷付いていく仲間たち。 4人の想いを背に、《キズナレッド》は単身《絶縁王》へと挑む。 激戦の果てに敵と相打ちになるキズナレッド。 命を落とした―――かに思われたのだが、気が付くとそこは《未知の世界》だった！ 異世界でも困った人々を救うため、真っ赤なヒーローは冒険者となり今日も戦う！ 《異世界×戦隊ヒーロー》でおくる、絆の最強英雄譚！！',
        NULL, 0, 0, 0, '2025-01-12'),
       (322, 34, '想星のアクエリオン Myth of Emotions',
        'animations/322/images/67d8506a-294f-4803-9997-dba83d92bb3b.webp',
        '「思い出して、翅（はね）があったころのことを」 1万2千年前の想いに応え、繋がったのは欠けたこころ。 太陽と月と火星が出会うとき、新たな合体の調べが流れる――！ 湘南の海に浮かぶ小島、江の島。 美しくのどかなその浜辺に、〈私立江ノ島学園〉はある。 学園には、全国から優秀な子どもが集められ、 最新の機器を使った英才教育が施されていた。 特殊強化クラスの生徒〈エレメント〉に選ばれたサッコ、リミヤ、トシは、感情の力で動く戦闘機〈ベクターマシン〉の操縦を命じられ、謎の侵略兵器〈神話獣〉との戦いを余儀なくされる。 戦いのさなか、不可思議なヴィジョンに導かれ、サッコは叫ぶ――。 「想星合体！GO、アクエリオン！」 繰り返される輪廻の果てに、現れた機械天翅アクエリオン。 宿命を背負った少年少女は、得体のしれない団体〈宇宙たまごの会〉や大人たちの思惑が交錯する中、この宇宙の真実と向き合っていくことになる……。 これは、おのれの感情と宇宙の存亡を賭けて紡がれる、壮大な愛の神話。',
        NULL, 0, 0, 0, '2025-01-09'),
       (323, 18, '没落予定の貴族だけど、暇だったから魔法を極めてみた',
        'animations/323/images/e94d0cdc-7963-456f-8b6c-042fe4bcd2a4.webp',
        '晩酌を楽しんでいた男は、気づけば貴族の五男・リアムの肉体に乗り移っていた。 憧れの魔法を練習する気楽な日々をおくっていたが、 属性魔法の習得はもとより精霊を召喚したり、強力な使い魔を得たり、 どんなに難しい魔法もマスターしていく！ 没落予定だった実家からの独立を目指して冒険者になった彼は、 いつのまにか世界屈指の魔術師に成り上がっていくのだった！ 最強貴族による自由気ままな魔法ファンタジー開幕！',
        NULL, 0, 0, 0, '2025-01-06'),
       (324, 34, 'Übel Blatt～ユーベルブラット～',
        'animations/324/images/153cd144-56d5-4a04-8c7d-37fd15fd8c8a.webp',
        '神託歴3968年、闇の異邦（ヴィシュテヒ）の侵略を封じるため、皇帝は14人の若者たちに使命と聖なる槍を与えて送り出した。\n3人は旅の途中で命を失い、4人は敵に寝返り皇帝を裏切ったとされ討たれた。\nだが、それは栄誉を我が物にしようとした7人の仲間の裏切り行為であった。\n帝都に凱旋した彼らは“七英雄”と称され、帝国の民の尊敬を集め栄華の座に上りつめたが、一方で、武勲を奪われ“裏切りの槍”の汚名を着せられた。\n一人の剣士・アシェリートが、妖精の血肉を食らい生き延びていた。\n容姿を少年に、名をケインツェルに変え、20年の時を経て、七英雄への復讐の旅が今はじまる— ！',
        NULL, 0, 0, 0, '2025-01-10'),
       (325, 154, '不遇職【鑑定士】が実は最強だった',
        'animations/325/images/0343fa43-f9b0-4fe2-a2d2-4e8f05b582a1.webp',
        'なろうサイトで人気の原作！3,300万PVを誇る原作が、小説・漫画・そしてアニメへ！ 【鑑定】することしかできない最弱職で不遇職の【鑑定士】アイン。 仲間からは『ゴミ拾い』呼ばわりされ、ひどい扱いを受け、そんな自分が好きになれず、卑屈な日々を送っていた。 そんなアインの運命は【世界樹】の精霊ユーリとその守り手で賢者であるウルスラと出会ったことで、大きく変わっていく。 ユーリから【精霊の義眼】をもらい、それを使いこなすためにウルスラから特訓を受け、どんどん力をつけていくアインは、「世界樹の他の姉妹達に会いたい」というユーリの願いを叶えるために、旅を始めることになる。 持ち前の優しさと、新たに加わった勇気を胸に様々な出来事を乗り越えていくのだった。',
        NULL, 0, 0, 0, '2025-01-09'),
       (326, 357, 'RINGING FATE', 'animations/326/images/111db0b0-6244-4043-bc33-759b228bff02.webp',
        '心に強い執着を持つ人は、死の間際に、生と死の狭間にある「崆」という世界へ導かれる。その世界では、メカを操縦して戦う“運命のリング”と呼ばれるものがあり、優勝者には生き返るチャンスが与えられる。無邪気な少女・要（かなめ）は「崆」に落ちるが、そこで偶然に最凶のヘルメット・サブロ ーと出会い、二人で手を組み“運命のリング”で生き残る道を探り始める。「過去（きおく）がなきゃ、今までの人生の意味がない。私は未来を取り戻すために闘うー」',
        NULL, 0, 0, 0, '2025-01-08'),
       (327, 71, '日本へようこそエルフさん。',
        'animations/327/images/a9d46893-a736-43c4-922c-d0f6a487df6d.webp',
        '社会人の北瀬一廣の趣味はとにかく寝ること。彼は、幼い頃からいつも夢で見る不思議な異世界で、胸躍る冒険をしていた。ある時、仲良くなったエルフの少女と古代遺跡を探索していた時に、運悪く出くわした魔導竜にブレスで焼かれてしまう。夢から覚めると、部屋にいるはずのないエルフの少女が隣で眠っていて――',
        NULL, 0, 0, 0, '2025-01-10'),
       (328, NULL, '『インサイド・ヘッド』の世界より：ライリーの夢の製作スタジオ',
        'animations/328/images/68f51483-6e8d-4e4b-b17d-e3954f2c0962.webp',
        'ライリーの頭の中にあるスタジオで、夢監督が悪夢に直面する。次のヒット作を作らなければならないのだ。\n12月11日(水)よりディズニープラスで独占配信中',
        NULL, 0, 0, 0, '2024-12-11'),
       (329, 193, 'ニートくノ一となぜか同棲はじめました',
        'animations/329/images/b09245f2-6827-456b-83c4-8d3af276b3d2.webp',
        '平凡なサラリーマン・安海政（あつみつかさ）を妖魔から守護するべく、居候を条件に主従契約を結んだ天才くノ一・出浦白津莉（いでうらしづり）。颯爽と妖魔を倒す姿とは裏腹に、しづりはゲーム三昧のオタクニートであった。 政に甘やかされ、ぐうたら同棲生活を送るしづりのもとにクセつよくノ一たちも集結し…。',
        NULL, 0, 0, 0, '2025-01-04'),
       (330, 287, '魔神創造伝ワタル',
        'animations/330/images/ae8e16a3-b927-4862-911e-67c03ad531f6.webp',
        '小学4年生の主人公「星部ワタル」は動画配信でスーパースターを目指すリューチューバー。ある日突然、迷いこんだのはトンデモ異世界な「宙部界」。そこでは、迷惑系なヤカラたちが人々を困らせていた。ラスボス「エンジョーダ」を倒し、人々の笑顔を取り戻すためワタルは救世主としてブロックで創った魔神「龍神丸」とともに戦うことになる。いま、ワタルと仲間たちとの大バズリな冒険バトルが秒ではじまる！',
        NULL, 0, 0, 0, '2025-01-12'),
       (331, 18, '魔法つかいプリキュア！！～MIRAI DAYS～',
        'animations/331/images/42939c89-0ab2-4000-b7ac-872f39b54b21.webp',
        '好奇心が旺盛で不思議なことが大好きな朝日奈みらいは、中学2年生になる春休み、\n魔法つかいの少女・リコと出会う。\n奇跡と魔法に導かれて、リコと共に伝説の魔法つかい「プリキュア」に変身！\nみらいが大切にしているクマのぬいぐるみのモフルンや、\n「リンクルスマホン」から生まれた妖精のはーちゃんとも手を取り合って、\n「魔法界」と「ナシマホウ界（人間界）」というふたつの世界に迫った混沌を退ける。しかしそれはみんなの別離を伴うものだった。\n数年後に奇跡的な再会を果たしたみらいたちは、それぞれの世界で、それぞれの未来へ向かって歩み始める。\nみらいはナシマホウ界で大学生に。魔法界に戻ったリコは、魔法学校の先生に。\nモフルンは変わらずみらいの隣に。\nそして、はーちゃんは遠いところから世界を見守る存在に――。\nだが、そんななか、魔法界とナシマホウ界に新たな災いが現れて……？\n新たな災いの兆しをきっかけに、数か月ぶりの再会を果たしたみらいとリコ。\n謎の敵を退ける一方で、ふたりは自分たちの過去、そして未来と向き合うことになるのだった――。\n「キュアップ・ラパパ！」の魔法の言葉で、ワクワクもんの物語がいま再び動き出す！',
        NULL, 0, 0, 0, '2025-01-11'),
       (332, 71,
        'Sランクモンスターの《ベヒーモス》だけど、猫と間違われてエルフ娘の騎士（ペット）として暮らしてます',
        'animations/332/images/430ce969-4d88-4a6b-b29a-19ba81cbff97.webp',
        '迷宮都市・リューイン。 モンスターはびこる迷宮があるこの町には、数多くの冒険者たちが集まっていた。 命を落とし転生した主人公は、迷宮の中で目を覚ます。 その外見は、どう見ても仔猫！？ しかし正体は――災害級のSランクモンスター《ベヒーモス》の幼体だった！ 彼が出会ったのは、駆け出しのDランク冒険者・アリア。 仔猫と勘違いしたアリアは、重傷を負っていた彼を連れ帰って手当てし、「タマ」と名付けてペットにする。 その優しさに心を打たれたタマは、アリアを守る騎士となることを誓うのだった。 Sランクの力を活かし、アリアと共に迷宮を冒険するタマ。 個性豊かな仲間たちと出会い、時に溺愛されながら、騎士（ペット）としての日々が始まる！',
        NULL, 0, 0, 0, '2025-01-04'),
       (333, 98, 'FARMAGIA', 'animations/333/images/9afaeae0-2118-4162-8d96-cd2f9d744df9.webp',
        '魔界フェリシダ――。 そこには「魔界人」と呼ばれる人々が、モンスターたちと共生していた。 ５大陸の１つ、アウリオン大陸に住む少年・テンもその一人であった。 彼は、モンスターたちを種から育て収穫し、使役する「ファーマギア」であり、 各大陸を治める領主・竜顎六柱将（オラシオンセイス）になるため 最強のモンスターの種を育てていた。 そんなある日のこと……、 突如としてもたらされた「魔王・ディルクロム」の死によって 世界は一変する――。 人々の悲しみも束の間、 新魔王となった竜顎六柱将（オラシオンセイス）の一人、グラーザによる支配が始まるのだった。 大切な人たちを守るため、 最強のファーマギアになるため…… テンは仲間のファーマギアとモンスターと共に竜顎六柱将（オラシオンセイス）に立ち向かう！',
        NULL, 0, 0, 0, '2025-01-10'),
       (334, NULL, 'インビンシブル ～無敵のヒーロー～ シーズン3',
        'animations/334/images/15acb934-58e4-4663-970f-203c6ec678cf.webp',
        'さまざまな変化の中、マークは自らの過去と未来に向き合うことを強いられ、愛する人々を守るためにどこまでやるべきかを知る。',
        NULL, 0, 0, 0, '2025-02-06'),
       (335, 271, '悪魔城ドラキュラ －キャッスルヴァニア－: 月夜のノクターン シーズン2',
        'animations/335/images/7c9d50a1-7ede-4b4e-a9b3-9dc95d154f61.webp', NULL, 2, 0, 0, 0,
        '2025-01-16'),
       (336, 262, '「1分間だけ触れてもいいよ…」シェアハウスの秘密ルール｡',
        'animations/336/images/23b44677-af9e-4418-87c1-68e908b9e02e.webp',
        '一つ屋根のした、１分間だけ、夢のようなひと時――\n大学進学を機にシェアハウスに入居した遼太。\nそこには超絶美人のシェアメイト・桃香と奏が暮らしていた。\n男女3人が暮らしていく中で取り決められる『秘密のルール』\nそれは、“１分間だけ、ぜんぶが許されちゃうタッチポイント”\nドキドキとトキメキがとまらない、美味しいシェアライフがはじまった――',
        NULL, 0, 0, 0, '2025-01-05'),
       (337, 58, 'UniteUp! -Uni:Birth-',
        'animations/337/images/8656b41a-9eee-4499-bd15-cb7243486166.webp',
        'ついにCDデビューを果たしたPROTOSTARは\n「新人メンズアイドルフェス」で優勝し、順風満帆なアイドル生活を送っていた。\nそんな3人に事務所の代表である凛、真音から告げられたのは、\n同じsMiLeaプロダクション所属アイドルのLEGIT、JAXX/JAXXと\n新曲のリリースで競うリリースバトルだった。\nリリースバトルをきっかけに様々な困難にぶつかるアイドル達。\n彼らに待っている結末とは...?!',
        2, 0, 0, 0, '2025-01-11'),
       (338, NULL, '聖女なのに国を追い出されたので、崩壊寸前の隣国へ来ました',
        'animations/338/images/d1cc9051-91e1-4a96-ac15-211e72533c92.webp',
        '聖女リーシャは、婚約者のバーズーデン国王ダルエストに、新しい婚約者ができたからという理由で突然国から追放されてしまう。\nそんなリーシャを助けたのは、隣国メートポリスの国王ラオウハルトだった。\nリーシャは助けてくれたお礼にと、聖女の力で荒れていたメートポリスを復興していく。次第にラオウハルトは、国のため尽力する健気なリーシャに惹かれていくのであった…。\n一方で、聖女の力を失ったバーズーデン国は、日に日に様子がおかしくなり――！？',
        1, 0, 0, 0, '2025-01-10'),
       (339, 102, '夜は猫といっしょ Season3',
        'animations/339/images/de0bd259-7f92-48a2-a328-2adbff2e8a72.webp',
        '突然、猫・キュルガといっしょに\n暮らすことになったフータくん。\nキュルガとの生活は不思議なことや\n楽しいことがたくさん！\n猫とのリアルな日常を描いた\n最注目の猫アニメが、\n2024年12月、第3期配信決定‼',
        3, 0, 0, 0, '2024-12-04'),
       (340, 95, '闇芝居 十四期', 'animations/340/images/c4b22777-845d-402a-8eca-7dff14c88959.webp',
        NULL, 14, 0, 0, 0, '2025-01-05'),
       (341, NULL, 'ジェントリー・チャウvs魔界のモンスター',
        'animations/341/images/71f73167-d929-4e6c-9aaf-9d6ef5947d9d.webp',
        '本シリーズの主人公ジェントリー・チャウ (声: アリ・ウォン) は、テキサスの小さな町に住む中国系アメリカ人の高校生。生まれてこの方ずっと封印してきた自分の超能力を魔王が狙っていると知ったジェントリー。高校生活だけでもホラーだというのに、武器エキスパートの大おばさん、そして推定年齢千年以上のキョンシー (ピョンピョン跳ねる中国の吸血鬼) の助けを借りて、闇の世界のモンスターたちを丸ごと敵に回して戦うはめに!',
        NULL, 0, 0, 0, '2024-12-05'),
       (342, NULL, 'ARK：アニメーションシリーズ',
        'animations/342/images/2e652a88-e157-4fc1-93eb-459bd2fb18c8.webp',
        '12月20日（金）よりParamount+にて独占配信中', NULL, 0, 0, 0, '2024-12-20'),
       (343, 17, 'Duel Masters LOST ～月下の死神～',
        'animations/343/images/441cd3ad-ff8f-4af9-9e0a-8e51fbe88326.webp',
        '斬札ウィンは命懸けのデュエルの果てに謎の少女クリスタから「クリスタルカード」を託される。\nそれが失われた記憶と関係があると知ったウィンは、二イカと共にカードに秘められた謎を調べるため、とあるカードショップへと向かう事に。\n一方その頃、都内では「人々の心臓が抜かれる」という怪事件が巻き起こる。\nその裏には「黒き死神」と呼ばれる男──黒城凶死郎の姿があった。\nクリスタルカードの正体とは。\n黒城凶死郎が操る禁忌の力「同化」とは。\nそして彼の真の目的とは。\n記憶とクリスタルカードを巡り、ウィンの運命が廻り出す。',
        2, 0, 0, 0, '2024-12-21'),
       (344, NULL, '0歳児スタートダッシュ物語 シーズン2',
        'animations/344/images/929c5e81-0437-40c9-81e5-dcd69d4b1e5e.webp', NULL, NULL, 0, 0, 0,
        '2025-01-05'),
       (345, 61, 'カードファイト!! ヴァンガード Divinez デラックス編',
        'animations/345/images/21595ffb-8f81-45f9-9467-06fc3777ceae.webp',
        '宿命決戦を終え、平和な日々を過ごすアキナへ届いた一通の招待状。\nそれはヴァンガードの最強を決める大会「デラックス」への参加権利だった！\n熱き戦いの火蓋が、再び切られる！\nさらに、ナオから師匠と呼ばれる男が現れ――\n「君は、何のためにヴァンガードをやっているんだ？」',
        NULL, 0, 0, 0, '2025-01-11'),
       (346, NULL, 'ハーレイ・クイン シーズン1', NULL,
        'ジョーカーの恋人として有名なハーレイ・クイン。何度もジョーカーに裏切られ、ついに彼と決別して、ポイズン・アイビーやドクター・サイコといった新しい仲間たちと一緒に自分の道を切り開いていこうとする。本当にジョーカーと縁を切れるのか!?',
        1, 0, 0, 0, '2025-02-21'),
       (347, 372, 'ミニミニ minini',
        'animations/347/images/440e134f-d0b0-47c5-9f81-ac6964e0011b.webp', NULL, NULL, 0, 0, 0,
        '2025-01-04'),
       (348, NULL, 'ザ・シンプソンズ シーズン36',
        'animations/348/images/ea9e342f-a537-4c2b-9557-6f90a46853e2.webp',
        '数々の賞に輝き、世界 70 カ国以上で放送されているアメリカのテレビ史上最長寿の型破りなアニメーション・シリーズ待望のシーズン 36！架空の街スプリングフィールドに住むホーマー、マージ、バート、リサ、マギーのシンプソン一家が繰り広げる奇想天外な日常生活を描いた爆笑コメディ。スプリングフィールドの何気ない日常を描くエピソードはもちろん、超大物スターのゲスト出演、映画のパロディ、社会問題などを反映させたエピソードなども繰り広げられる。\n2 月 12 日（水）よりディズニープラスの「スター」で独占配信開始',
        36, 0, 0, 0, '2025-02-12'),
       (349, NULL, 'ハーレイ・クイン シーズン2', NULL,
        'ジョーカーを倒したハーレイはゴッサム・シティを分割してそれぞれに支配領地を作ろうとするペンギンたちヴィランを退け、街の支配を目指す。バットマンの行方は？アイビーとカイトマンの交際は順調だが、あることをきっかけにハーレイの心が揺らぎ始める。',
        2, 0, 0, 0, '2025-02-28'),
       (350, NULL, 'パトリック・スター・ショー',
        'animations/350/images/8a54e680-8349-4430-9f5e-a5c70b670c1f.webp',
        '1月17日（金）よりParamount+にて独占配信開始', 1, 0, 0, 0, '2025-01-17'),
       (351, NULL, 'とーがね！クロニクル 再編集版', NULL,
        '千葉県東金市にお祭りが復活してから数年。\n東金で生まれ育ち、鴇金高校に通う１年生「時坂めぐる」は、地元は嫌いではないものの、少し飽きてきていた。\n興味もあまり持てずに悶々と過ごしていたある日、由緒正しい日吉神社の巫女「神代すばる」と出会う。\n数年前に復活した夏祭りが、すばるを含む自分たちの高校の先輩達によるものだと知って驚くめぐる、そしてその友人「湖西もも」と「城野ひめこ」。\n後輩たちが東金に興味を持ちつつある事に喜ぶすばるは、とある行動に出る。\nそれはめぐるたちにとって思いもよらない出来事でーーーーー',
        NULL, 0, 0, 0, '2025-01-09'),
       (352, 20, 'チ。 ―地球の運動について―',
        'animations/352/images/9ee1757e-61ca-4447-8682-fee97a989c1f.webp',
        '舞台は15世紀のP王国。教会が人々の心や科学までも支配している時代で、教会の教えのなかで最も大切なひとつが、地球が宇宙の中心でその周りを惑星が動いているとする『天動説』だった。『天動説』がこの世の真理だとされ、その教えに背く者は『異端者』というレッテルを張られ、激しく弾圧された。 この時代を生きているのが、飛び級で大学への進学を認められた神童・ラファウ。彼は周囲の期待に応え、当時最も重要とされていた神学を専攻すると宣言。が、以前から熱心に打ち込んでいる天文への情熱は捨てられずにいた。ある日、彼はフベルトという謎めいた学者と出会う。異端思想に基づく禁忌に触れたため拷問を受け、投獄されていたというフベルト。彼が研究していたのは、宇宙に関する衝撃的な『ある仮説』だった――。',
        NULL, 0, 0, 0, '2024-10-05'),
       (353, 110, 'ダンダダン 第1期',
        'animations/353/images/61ffa9c5-70b9-4cc2-a94a-aec966f002aa.webp',
        '霊媒師の家系に生まれた女子高生・モモ＜綾瀬桃＞と、同級生でオカルトマニアのオカルン＜高倉健＞。 モモがクラスのいじめっ子からオカルンを助けたことをきっかけに話すようになった2人だったが、「幽霊は信じているが宇宙人否定派」のモモと、「宇宙人は信じているが幽霊否定派」のオカルンで口論に。 互いに否定する宇宙人と幽霊を信じさせるため、モモはUFOスポットの病院廃墟へ、オカルンは心霊スポットのトンネルへ。 そこで2人は、理解を超越した圧倒的怪奇に出会う。 窮地の中で秘めた力を覚醒させるモモと、呪いの力を手にしたオカルンが、迫りくる怪奇に挑む！ 運命の恋も始まる！？ オカルティックバトル＆青春物語、開幕！',
        1, 0, 0, 0, '2024-10-03'),
       (354, 55, 'ブルーロック VS. U-20 JAPAN',
        'animations/354/images/95d8413f-8ac2-4c4f-b2a7-6fbf88fcfad7.webp',
        '日本を W 杯優勝に導く世界一のストライカーを育てるため、\n日本フットボール連合は“ブルーロック（青い監獄）”プロジェクトを立ち上げる。\nプロジェクトに招待されたのは 300 人の高校生。\nしかも全員 FW（フォワード）。\n脱落すれば将来、サッカー日本代表へ入る資格を失うという極限状態の中、\n選ばれし才能の原石たちは、ストライカーとしてのエゴを次々と覚醒させていく。\n時に他人を蹴落とし、時に自らの進化を以て、過酷なセレクションを生き残ったのは 35 人。\nエゴが渦巻く熱狂のサバイバルを乗り越えた彼らは、“ブルーロック（青い監獄）”プロジェクトの存続を賭けて、\nU-20 日本代表との史上最もイカれた大一番(ビッグマッチ)へと挑む！\n今、己のエゴを世界に刻むため、自らの手で運命を変えるため、史上最もアツい戦い（試合）が始まる。',
        2, 0, 0, 0, '2024-10-05'),
       (355, 83, 'アオのハコ', 'animations/355/images/717e1aaa-1f4e-4c40-99ed-99127c67fda8.webp',
        '毎朝一番に会いたい人がいる―― 中高一貫のスポーツ強豪校・栄明高校に入学する、男子バドミントン部の一年生・猪股大喜。 大喜は毎朝、朝練で顔を合わせる一つ上の先輩、鹿野千夏に恋をする。 千夏は女子バスケットボール部のエースで、校内外問わず人気の高嶺の花。 部活に恋に勉強に、大喜にとって忙しい高校生活がはじまる、そんなある日―――',
        1, 0, 0, 0, '2024-10-03'),
       (356, 18, '来世は他人がいい',
        'animations/356/images/5f822e2c-aa63-405a-b290-b877e780ab9a.webp',
        '染井吉乃は祖父である、関西最大の暴力団「桐ヶ谷組」直系「染井組」組長・染井蓮二が決めた縁談相手、 深山霧島の住む、関東最大の暴力団「砥草会」直系「深山一家」のもとで暮らすことになる。 吉乃を優しく迎え入れる霧島は、爽やかで人当たりのよい、ヤクザの家系を思わせない好青年。 慣れない土地に不安を抱えていた吉乃は胸をなでおろす。 ……しかし！！ ある事件をきっかけに、吉乃は霧島の本当の姿を目の当たりにすることになる。',
        NULL, 0, 0, 0, '2024-10-07'),
       (357, 80, 'Re:ゼロから始める異世界生活 3rd season 襲撃編',
        'animations/357/images/a35e961e-a06e-4528-b0d9-cf5a8e1e4359.webp',
        '襲い来るエルザたちの猛攻を退け、大兎との戦いでベアトリスとの契約を果たした「聖域」の解放から1年が過ぎた。 王選に臨むエミリア陣営は一致団結、充実した日々を送っていたナツキ・スバルだったが、平穏は使者によって届けられた一枚の書状によって終わりを告げる。 それは王選候補者の一人、アナスタシアがエミリアへ宛てたルグニカの五大都市に数えられる水門都市プリステラへの招待状だった。 招待を受け、プリステラへ向かうスバルたち一行を待っていたのは様々な再会。 一つは意外な、一つは意図せぬ、そして一つは来るべき。水面下で蠢く悪意の胎動と降りかかる未曾有の危機。 少年は再び過酷な運命に立ち向かう。',
        4, 0, 0, 0, '2024-10-02'),
       (358, 38, 'らんま 1/2', 'animations/358/images/6fcafdf7-a12f-4b3b-8181-d8f10ebcd96c.webp',
        '早乙女乱馬と、天道道場三女の天道あかねは親が決めた許婚同士。\nしかし乱馬にはある悩みが…。\n中国での修行中、伝説の修行場「呪泉郷」に落ちてしまい、\n水をかぶると女に、お湯をかぶると男に戻るという、不思議な体質になってしまっていた！？\n乱馬とあかね、そして個性豊かなキャラクターたちが繰り広げるドタバタ格闘ラブコメディー、ここに開幕！',
        1, 0, 0, 0, '2024-10-05'),
       (359, 19, 'ドラゴンボールDAIMA',
        'animations/359/images/2aaaef87-e58f-4759-a2f4-367e66cf3a29.webp',
        '平和な日常を送っていた悟空たちは、突如、ある陰謀によって小さな姿に！その理由が「大魔界」と呼ばれる世界にあるらしきことを突き止めた一行のもとに、ミステリアスな少年魔人、グロリオがあらわれる！',
        NULL, 0, 0, 0, '2024-10-11'),
       (360, 199, '青の祓魔師 雪ノ果篇／終夜篇',
        'animations/360/images/c436bf48-bf3a-43a6-ac20-6adaafb89a8a.webp',
        '運命と対峙する霧隠シュラのエピソードや、正十字騎士團の闇が浮かび上がる「雪ノ果篇」。\n奥村燐・雪男の出生の秘密――〝青い夜〟の真実に迫る「終夜篇」。\n物語はいよいよ「青の祓魔師」の核心を暴き出す――',
        4, 0, 0, 0, '2024-10-05'),
       (361, 71, '嘆きの亡霊は引退したい',
        'animations/361/images/745acfc5-7875-4ab8-be60-d348667cab14.webp',
        'トレジャーハンターになろうぜ 目指すはただひとつ、世界最強の英雄だ かつてそんな誓いを交わした六人の中でひとりだけ 圧倒的に才能がなかった少年がいた。 ある日挫折を口にした彼に、幼馴染は言った。 「クライ、お前、特に役割ないんだからリーダーやれよ」 才能があり過ぎる怪物達（＝幼馴染達）で結成されたパーティ《嘆きの亡霊（ストレンジ・グリーフ）》は 数年にしてその名を帝都中に轟かせ、 そのてっぺんに据えられた彼は あれよあれよという間に最強パーティのリーダーとして祭り上げられた。 跳ね上がる周囲からの期待により 彼の言動はいつだって勘違いされ、事態は予想もしない展開に…。 これは、最強パーティのリーダーにして 最強のクランマスターとして名を馳せるクライ・アンドリヒの 栄光と苦悩に満ちた英雄譚である！',
        1, 0, 0, 0, '2024-10-01'),
       (362, 122, '青のミブロ', 'animations/362/images/98e7f4eb-951f-4439-86af-31013571c4a4.webp',
        '黒船の来航により、動乱が巻き起こる幕末の京都。団子屋で働く心優しい少年「ちりぬ にお」は、のちに新選組となる「壬生（みぶ）浪士組（ろうしぐみ）」、通称“ミブロ”の土方歳三、沖田総司と出会う。 金も土地も命すら理不尽に奪われる時代。自らの正義を胸に、京の街を守る“ミブロ”の面々との出会いをきっかけに、ふつうの13歳の運命が、大きく動き出す！ 命懸けの“ド青春”新選組、開幕！',
        1, 0, 0, 0, '2024-10-19'),
       (363, 17, '株式会社マジルミエ',
        'animations/363/images/b3f38792-ec35-44e8-a2d5-d86f57c9ae61.webp',
        '「魔法少女――それは強くて、格好良くて、しなやかで。誰もが憧れて、高給取りで、人気が高い、立派なひとつの職業だ」\n内定がもらえず就職活動に苦戦中の女子大生・桜木カナ。「自分は社会に必要とされていない」と自信を喪失していた彼女は、ある日、面接先で“怪異”と呼ばれる自然災害に巻き込まれてしまう。\nその窮地を救ってくれたのは、ヤンキー気質の魔法少女・越谷仁美――。\n持ち前の記憶力で、“怪異”と戦う越谷を手助けしたカナは、魔法少女としての才能を見出され、ベンチャー企業・株式会社マジルミエに新卒入社！\n人の命と仕事への責任を胸に抱き、社会人として、そして魔法少女としての一歩を踏み出すのだった――',
        1, 0, 0, 0, '2024-10-04'),
       (364, 198, '転生貴族、鑑定スキルで成り上がる 第2期',
        'animations/364/images/a0904cc3-d675-40b3-90cb-adce5557bc0b.webp', NULL, 2, 0, 0, 0,
        '2024-09-29'),
       (365, 126, 'MFゴースト 2nd Season',
        'animations/365/images/60af97cb-42ef-4805-861e-e565e16b1329.webp',
        '『MFゴースト 2nd Season』#13-24で描かれたレースバトルを中心に再編集。 TVアニメ本編には使用されていないユーロビート音源も使用した、白熱のバトルダイジェスト映像！',
        NULL, 0, 0, 0, '2024-10-06'),
       (366, 170, '魔王様、リトライ！R',
        'animations/366/images/17363538-fadd-4339-8d30-9cbc877ea260.webp',
        '大野晶は自身が運営する「GAME」内のラスボス「魔王・九内伯斗」にログインしたまま異世界へと飛ばされてしまう。 そこで出会った片足が不自由な少女と旅を始めるが、 圧倒的な力を持つ「魔王」の存在を周囲が放っておくことはなかった。 魔王を討伐しようとする国や聖女から狙われ、一行は行く先々で様々な騒動を巻き起こすことに・・・！',
        2, 0, 0, 0, '2024-10-05'),
       (367, 152, '夏目友人帳 漆',
        'animations/367/images/7198ea6c-4bec-4dde-a86d-ffe3fa969f53.webp',
        '小さい頃から妖怪を見ることができた少年・夏目貴志は、祖母レイコの遺産「友人帳」を受け継ぎ、 自称用心棒のニャンコ先生と共に、そこに名を縛られた妖怪たちに名を返す日々を送る。 妖と、そこに関わる人との触れ合いを通して、自分の進むべき道を模索し始めた夏目は、想いを共有できる友人たちにも助けられながら、大切な日々を守るすべを見つけていこうとする。',
        7, 0, 0, 0, '2024-10-07'),
       (368, 301, 'BLEACH 千年血戦篇-相剋譚-',
        'animations/368/images/a57b56fe-8ff6-46a2-92c8-79b2211ef183.webp',
        '三界の存亡を賭けた戦いに、流れるのは血か涙か―― 《見えざる帝国》の第二次侵攻により 《影の領域》へと変貌した瀞霊廷で、死神と滅却師の戦いは続く。 奪われた卍解を取り戻し、反撃の狼煙を上げた護廷十三隊は、 次々と星十字騎士団の聖章騎士たちを撃破していく。 そんな中、霊王宮での修業を終えて、新たな力を得た阿散井恋次、朽木ルキア、 そして――黒崎一護が瀞霊廷に帰還する。 再びユーハバッハに挑まんとする一護の前に立ちはだかったのは石田雨竜。 引き絞った弓を向ける友の真意を問う一護に、 雨竜が返したのは訣別の矢であった。 ユーハバッハは雨竜と親衛隊を引き連れて遮魂膜を突破。 遂に戦いの舞台は、不可侵の神域・霊王宮へと移る。 不遜な侵入者を迎え撃つ王属特務・零番隊の五人。 その驚異的な力の前に、ユーハバッハも親衛隊も敗れ去ったかに見えたが…… 真の戦い、真の絶望は今まさに始まらんとしていた。 死神と滅却師、一護と雨竜、信念と決意―― 決して相容れぬ光と影は、紺碧の天空に相剋する。',
        4, 0, 0, 0, '2024-10-05'),
       (369, 97, 'シャングリラ・フロンティア 2nd season',
        'animations/369/images/031187c7-c490-44e0-9991-74d2da481da9.webp',
        '「クソゲー以外をプレイするなんて、いつ以来だろうな」 ディスプレイを使用するゲームが、レトロゲームに分類されるようになった、少しだけ未来の世界。 この世界では、最新のVR技術に内容が追いついていない、いわゆる“クソゲー”と呼ばれる作品が大量にリリースされていた。 そんな数多のクソゲーをクリアすることに情熱を捧げてきた1人の“クソゲーハンター”陽務楽郎。 彼が次に挑んだのはクソゲーの対極、総プレイヤー数3000万人の“神ゲー”『シャングリラ・フロンティア』だった。 集う仲間、広がる世界。そして“宿敵”との出会いが、彼の、全てのプレイヤーの運命を変えていく！！ 最強クソゲーマーによる最高のゲーム冒険譚、ここに開幕！！',
        2, 0, 0, 0, '2024-10-13'),
       (370, 122, '歴史に残る悪女になるぞ',
        'animations/370/images/23bef051-b5a1-4fe7-9393-77054399b42d.webp',
        'ヒロインにありがちな“いい子ちゃん発言”が大嫌いだった私が転生したのは、大好きな乙女ゲームの悪役令嬢アリシア。 念願叶って転生したからには、歴史に残る世界一の悪女になってやる！そのためには強くて頭もよくないといけない！ ——と努力しただけなのに、悪役令嬢として頑張れば頑張るほど周囲は予想外の反応で……。 はたしてアリシアは歴史に残る悪女になれるのか！？',
        NULL, 0, 0, 0, '2024-10-01'),
       (371, 136, '甘神さんちの縁結び',
        'animations/371/images/a3fdabe6-5618-4339-ab9e-37c892265081.webp',
        '京大医学部を目指す高校生の上終瓜生。児童養護施設育ちの瓜生は、京都にある縁結びの神社「甘神神社」の宮司に引き取られ、居候をすることに。そこで待っていたのは、夜重、夕奈、朝姫の巫女三姉妹との同居生活！さらに居候の条件は「婿養子として神社を継ぐ」こと！？三姉妹とのお見合い、甘神神社に降りかかる難題…瓜生は乗り越えることができるのか…？一つ屋根の下、巫女たちと紡ぐ奇跡のラブコメディ！',
        NULL, 0, 0, 0, '2024-10-01'),
       (372, 54, '鴨乃橋ロンの禁断推理 2nd Season',
        'animations/372/images/8f5d9812-027d-40aa-81bd-1bfd365a46f7.webp',
        '世界最高峰の探偵養成学校 BLUE で天才と呼ばれながら、ある致命的な“欠陥”を抱え、探偵の資格を剥奪された鴨乃橋ロン。不遇の歳月を過ごした彼の運命は、警視庁捜査一課の一色都々丸――通称「トト」との出会いによって大きく変わる。謎を解くロンと、捜査に動くトト。難事件を次々と解決する二人は、次第に名コンビとなっていく。\nそんなロンの行動に目を光らせる BLUE の内部には、彼の理解者もいた。その一人である校長のエメリッヒは、ロンを追放するきっかけとなった「血の実習事件」が何者かに仕組まれたものだと語る。裏にいたのは、数多くの未解決事件に関わる「史上最悪の犯罪一族」――M 家だった。当主の名は、マイロ・モリアーティ。彼はロンにさらなる絶望を与えるため、妹のウィンターを日本に送り込む。ロンとマイロ、両者の間にある因縁とは……!?',
        2, 0, 0, 0, '2024-10-07'),
       (373, 75, 'ひとりぼっちの異世界攻略',
        'animations/373/images/723a28e6-886e-4e5c-bc47-9e23836f46b1.webp',
        '高校生活を“ぼっち”で過ごしていた遥は、授業中に突然クラスメイトと共に異世界召喚に巻き込まれてしまう。 チートスキルが並ぶリストから好きなスキルを選んで神様から与えられる――はずが、チートスキルは早い者勝ちで既にめぼしいものはクラスメイトに取り尽くされていた！？ 神様の逆ギレで残ったバッドスキルを全て押し付けられた遥は、スキル『ぼっち』のせいで、異世界でも孤独に冒険することに……。 チートに頼らず、チートを超えてやる―― 最強“ぼっち”の異世界HARDモード攻略譚、開幕！',
        NULL, 0, 0, 0, '2024-10-03'),
       (374, 179, '妻、小学生になる。',
        'animations/374/images/24cbf6d5-8fab-4f63-90db-2a10f64b3f00.webp',
        '10年前、妻を亡くした愛妻家の新島圭介はずっと失意の中にいた。だがある日、小学生の女の子、白石万理華が、自分は他界した妻、貴恵だと言ってやってくる。こうして、小学生の姿をした妻との人生が再び動き始める…',
        NULL, 0, 0, 0, '2024-10-06'),
       (375, 17, 'やり直し令嬢は竜帝陛下を攻略中',
        'animations/375/images/ca94001b-c0d0-4aa3-a476-f738f89c1de4.webp',
        '処刑前夜、牢から逃げ出す令嬢ジル。何の咎もない自分を罪人に仕立て上げたのは、婚約者の王太子・ジェラルドだった。戦場で「化け物」と恐れられ、いつしか「軍神令嬢」と呼ばれるようになった働きもすべて初恋のためだったのに……。初対面で求婚された、あの夜。もし、もしも、渡された薔薇を手に取らなければ……。後悔にくちびるを噛みながら兵の矢に討たれたジルは生涯を終え――た、はずだった。気がつけば、そこは2人が出会った6年前の夜。ジルは、10歳に戻ってしまった自分に戸惑いながらもジェラルドの求婚をかわすため、たまたま手を掴んだ男に「一目惚れした」と嘘をつく。だがそれは、6年後の未来に暴虐の限りを尽くし、クレイトスを火の海に沈めた隣国の皇帝・ハディスだった――！でも、ジルが知る姿とはまるで違うピュアすぎる「恋愛オンチ皇帝」で……！？やがて、ジルは決意する。ジェラルドではなく、ハディスと結ばれることで失ったすべてを取り戻していこうと。「あなたを必ず更生――いえ、しあわせにいたします」生涯最悪の選択を回避したやりなおし令嬢の大逆転劇が、幕を開ける！',
        NULL, 0, 0, 0, '2024-10-09'),
       (376, 34, '妖怪学校の先生はじめました！',
        'animations/376/images/5c3f803a-492a-4bdb-8151-efea23eccb27.webp',
        'ビビりで泣き虫な新米教師・安倍晴明（あべはるあき）。 憧れの教師になり、喜んでいたのもつかの間！ 赴任先の百鬼学園は、なんと妖怪たちの妖怪たちによる妖怪たちだけの学校だった！気弱でヘタレ、しかも人間である晴明を、学園長が雇った理由とは一体……！？ クセ強人間教師・晴明と、個性が大渋滞の妖怪生徒＆先生たちの、奇妙でにぎやかな日常を描く、愉快☆痛快☆妖怪☆学園コメディ！授業開始！',
        NULL, 0, 0, 0, '2024-10-08'),
       (377, NULL, '機動戦士ガンダム 復讐のレクイエム',
        'animations/377/images/1d15127e-480c-4162-ba97-e79cdb630aa9.webp',
        '宇宙世紀 0079 年、ジオン公国は地球連邦政府からの独立を宣言し戦争状態に突入した。新兵器モビルスーツの活躍により序盤こそ優位を保ったジオン軍だったが、地球の全面制圧を行う戦力はなく戦況は膠着する。そして開戦から 11 ヶ月後、東欧のジオン軍占領下にある基地の一つが連邦軍に奪取される。その奪還に向かう混成大隊の中に、宇宙から降りてきたばかりのモビルスーツ小隊、ソラリたちレッド・ウルフ隊の姿もあった――\n2024 年 10 月 17 日(木)Netflix にて世界独占配信中',
        NULL, 0, 0, 0, '2024-10-17'),
       (378, 57, '合コンに行ったら女がいなかった話',
        'animations/378/images/1dfd2931-38fe-48ed-b2d6-288a5bceab66.webp',
        '同じゼミの女子・蘇芳さんに合コンに誘われた大学生の常盤は、同じく合コン初体験の友人・浅葱と萩の2人を連れて、胸を高鳴らせながら待ち合わせの居酒屋へ。女性陣が先に店に着いたことを知って、待たせてはいけないと急いで席に向うと…そこには、眩く輝くほどイケメンな3人の姿が。男6人と女0人の少し違った合コンが今始まる！？',
        NULL, 0, 0, 0, '2024-10-04'),
       (379, 126, '君は冥土様。', 'animations/379/images/52bd4720-dcf3-4d92-92a4-d58b451956d9.webp',
        'ある日突然、メイドさんが営業に来た――。 高校生・横谷人好の家に突然の来訪者が現れた。 黒髪で清廉、丁重な言葉使いが特徴的なメイドさん。 第一声は「私を雇って欲しい」。 彼女は前職が“殺し屋”、特技は“暗殺”、家事は全くの初心者で“ドジっ子” 運命の出会いから、メイドさんと同じ屋根の下での共同生活がスタートする…！？ だんだんと、感情を知らない彼女の心が揺れ動いていく――。',
        NULL, 0, 0, 0, '2024-10-05'),
       (380, 17, 'ダンジョンに出会いを求めるのは間違っているだろうかⅤ 豊穣の女神篇',
        'animations/380/images/0cb562c5-5967-4927-8c28-24596af492db.webp',
        '女神祭――迷宮都市オラリオが活況に包まれる、実りの祝祭。 豊穣を象徴する女神たちは祭壇に奉られ、その中にはあの『美の女神』の姿も。 ダンジョン深層という死地から生還を果たし、日常を取り戻したベル・クラネルもまた、女神祭の賑を楽しむはずだった…… ――とある酒場の娘から一通の手紙が届くまでは。 『ベルさんへ　今度の女神祭、二人だけデートしてください。　シルより』 都市の片隅、小さな酒場で固まった、少女のたったひとつの決意が、少年と迷宮都市を狂わせていく。 そして、『最強』を標榜する『強靭な勇士（エインヘリヤル）』達が今、動き出す。 これは、少年が歩み、少女が望む――【眷族の物語（ファミリア・ミィス）】――',
        6, 0, 0, 0, '2024-10-04'),
       (381, 21, '精霊幻想記2', 'animations/381/images/e8f33853-f25f-4da0-b6e1-96cb68cc88e7.webp',
        '幼い頃に母を殺され、スラム街の孤児となった少年リオ。七歳のある日、彼の中で不慮の事故で死んだ日本の大学生《天川春人の記憶》が甦り、同時に《膨大な魔力》が覚醒した。 それから様々な出会いと別れを経験したリオは、両親の故郷で母を殺した宿敵への復讐を胸に誓う。 数年の旅を経てシュトラール地方へと舞い戻ったリオは、望まぬ政略結婚を強いられていた恩師セリアを救出。だが、その直後、突如として出現した光の柱に導かれるようにして、彼は己が前世である天川春人の初恋の少女・綾瀬美春と衝撃的な再会を果たす',
        2, 0, 0, 0, '2024-10-07'),
       (382, 29, 'るろうに剣心 -明治剣客浪漫譚- 京都動乱',
        'animations/382/images/6612f09c-d98a-40ef-95eb-8c6206ba9c64.webp',
        '不殺を誓う流浪人、緋村剣心は明治11年、東京で神谷薫と出会う。ニセ抜刀斎事件が縁で神谷道場に居候することになったが、御庭番衆や刃衛など幕末を生きた修羅たちが次々と剣心に襲いかかり…！？',
        NULL, 0, 0, 0, '2024-10-03'),
       (383, 20, 'トリリオンゲーム',
        'animations/383/images/4e007f22-69d9-403d-85a0-50e85119c2d1.webp',
        'ワルで頭の回転が速い人たらし・ハルと、気弱で人と話すことが苦手なパソコンオタク・ガク。 正反対の二人は、中学時代のとある出来事を機に交友を深めていく。 それから数年。大学生になり就職活動に励むガクは、その性格が災いし面接で全敗。 本命であった大手企業・ドラゴンバンク本社の窓拭きバイトをしていたところ、ハルに一緒に起業しないかと持ちかけられる。 「俺らのワガママは、世界一だ」 この世の全てを手にいれるため、1兆ドルを稼いで駆け上がる、二人の超予測不能な起業サバイバルが始まる！',
        NULL, 0, 0, 0, '2024-10-03'),
       (384, 207, 'ネガポジアングラー',
        'animations/384/images/8f9d229c-69ca-4e5b-993b-38b3dffe58be.webp',
        '多額の借⾦を抱え、さらに医者から余命 2 年を宣告された⼤学⽣、佐々⽊常宏。\n鬱々とした⽇々を過ごす常宏は、ある⽇借⾦取りに追われ海に転落したところを、\n釣り好きの少⼥ハナとその釣り仲間の貴明たちに助けられる。\nハナに勧められるまま⼈⽣初の釣りを経験し、その釣り仲間とも親交を深める常宏。\nハナや貴明の働くコンビニでバイトも始め、難解な釣り⽤語や⽣アミの匂いに苦戦しながらも、徐々に釣りにハマっていく。\n⼿元に伝わるアタリは、⽣の実感――。\n転落し続け世界を⾒上げるだけの⼈⽣は、そう簡単に変わらない。\nそんな常宏が釣りを通して⾒つけたものとは……︖',
        NULL, 0, 0, 0, '2024-10-03'),
       (385, 117, 'ありふれた職業で世界最強 season 3',
        'animations/385/images/ad14441f-28f1-4f4f-90ee-fd15fefe0ac8.webp',
        '神の使徒ノイントを撃破し、魔人族による王都侵攻を退けたハジメたち。 残る2つの大迷宮攻略の前に、被害を受けたハイリヒ王国への助力をヘルシャー帝国に求めるため、王女リリアーナを帝都へ送り届けることに。 その道中、帝国兵と戦うハウリア族と出会ったハジメたちは、魔人族と帝国兵の侵攻を受けたフェアベルゲンの現状を知る。 さらに族長のカムが帝国に囚われていると知ったハジメは、シアのためにその力を惜しみなく使うことを誓う！！ 「さあ、パーティーの始まりだ」 “最強”異世界ファンタジー、season 3開幕！',
        3, 0, 0, 0, '2024-10-14'),
       (386, 57, '結婚するって、本当ですか',
        'animations/386/images/470c075d-a905-45b3-8ebb-68494f8dc4b9.webp',
        '首都圏の旅行代理店、JTCの企画部に勤める拓也と莉香は、共に人付き合いが苦手で目立たないが、充実した一人生活を送っていた。\nところが、アラスカ支店開設により1年後に独身者が優先で海外派遣されることになり、困った莉香は拓也にとある計画を持ちかけて……。\nほとんどしゃべったこともない2人が、たったの365日後に結婚することに！？',
        NULL, 0, 0, 0, '2024-10-03'),
       (387, 126, '最凶の支援職【話術士】である俺は世界最強クランを従える',
        'animations/387/images/b4b4cd90-4cc7-4b4a-8aee-abba9b6dc9e7.webp',
        '不滅の悪鬼（オーバーデス）と呼ばれた英雄を祖父に持つ少年ノエル。 祖父に憧れ、最強の探索者（シーカー）を志す彼の持つ職能（ジョブ）は最弱と評される支援職【話術士】だった。 祖父の遺志を継ぎ、並々ならぬ努力により探索者として力をつけたノエルだが、生まれ持った才能の差を埋めることはできなかった―― しかし類稀なる才略をも開花させた彼は最強への道を見出す。 仲間を集め最強の組織（クラン）を創り、そのマスターになること――。 策略を巡らせ敵を翻弄し、仲間を率いて遥かなる高みを目指す。 最凶の【話術士】は最強への道を切り開く。手段は選ばない。',
        NULL, 0, 0, 0, '2024-10-07'),
       (388, 190, '凍牌～裏レート麻雀闘牌録～',
        'animations/388/images/6eef58ec-bd76-4b5a-baed-3392e7e2d19b.webp',
        '金、女、臓器。欲望蠢く裏レート雀荘を荒らし回る高校生の少年・ケイは、冷徹なる思考、冷艶なる打牌から、裏世界では“氷のK”と呼ばれ、自宅には少女を飼っていると噂される。',
        NULL, 0, 0, 0, '2024-10-04'),
       (389, 224, 'パーティーから追放されたその治癒師、実は最強につき',
        'animations/389/images/ccbbd0dd-eb98-4c82-a960-82c299ae984d.webp',
        'かつて世界は〝邪竜〟と呼ばれる邪悪な存在によって滅ぼうとしていた。\nしかし、1 人の勇者によって邪竜は倒され、世界は救われた。\nそれから 200 年あまりの時が過ぎようとしていた――。\n世に数多ある迷宮都市の 1 つ、マータット。そこに〝無能〟と呼ばれる男がいた。名はラウスト。\n職業、治癒師。ラウストはその無能さゆえに他の冒険者たちから蔑まれ、利用され、捨てられる。\nそんな日々をくり返していた。\nある日、ラウストの前に 1 人の少女があらわれた。名はナルセーナ。職業、武闘家。ナルセーナはとあるパーティーから追放されたばかりのラウストに言った。\n「お兄さん、私とパーティーを組みませんか？」\n今、ラウストとナルセーナ、2 人の冒険がはじまる――。',
        NULL, 0, 0, 0, '2024-10-05'),
       (390, 17, '魔法使いになれなかった女の子の話',
        'animations/390/images/38826f92-6257-4ae5-8a84-37057dc1e67f.webp',
        '原案公募企画「Project ANIMA」から生まれたオリジナルTVアニメーション 「魔法使いさん、わたし、約束守れませんでした」 魔法使いに憧れる天然少女クルミ＝ミライ と、代々魔法使いを輩出する名家の令嬢 ユズ＝エーデル 。 レットラン魔法学校＜国家魔法師養成専門学科（通称・マ組）＞への進学は魔法使いになるための必須条件。 なのに、まさかの受験失敗と思っていた！？ 一見、子どものような国家魔法師ミナミ＝スズキが担任として現れ、学園生活は急転！ 訳ありげなクラスメイトに、 怪しそうな同好会……この学校に隠された秘密って 何！？ 魔法使いさん、わたし＜普通科一組＞で、魔法使いになれる、の、カナ……？ 夢に破れた正反対なふたりの少女の青春＊魔法学園ファンタジー！',
        NULL, 0, 0, 0, '2024-10-04'),
       (391, 173, 'ぷにるはかわいいスライム',
        'animations/391/images/c4b4ae5d-a22a-44cd-992d-8a1634a1298b.webp',
        'これはスライムのぷにると中学生のコタローがともだちじゃなくなるまでの物語…… 河合井コタローは中学2年生男子。小学生の時に作ったスライムに命が宿り、以来7年間、ぷにると名付けたスライムと“ともだち”として仲良く一緒に過ごしていた。 ただし、コタローにとって一つ問題が……。 7年という月日でお互いが大きくなり、ぷにるの姿が超絶美少女に大変身したのだ！ 美少女な姿以外にも、スライムとしてあらゆるかわいい姿に変身するぷにるの自由気ままな言動に、毎回ドキドキと振り回されてしまうコタローの前途多難な日々。 果たして、ぷにるとコタローは“ともだち”として、仲良くずっと一緒に過ごせるのか！？',
        1, 0, 0, 0, '2024-10-06'),
       (392, 284, 'アクロトリップ',
        'animations/392/images/736979b5-ba81-4125-ab65-09f6210b239e.webp',
        '祖父のもとを訪れた地図子は、街を守る魔法少女・ベリーブロッサムと出会い、たちまち夢中に。 しかし、敵対する悪の組織「フォッサマグナ」総帥・クロマの攻撃があまりにもパッとせず、2人の戦いは見応えゼロ。 もっと、ベリーの活躍を愛でたい地図子はモヤモヤを募らせていく…。 「魔法少女をもっと輝かせたい…強いてくれ、苦戦を！」 その欲望（？）が、内気な少女を悪の路に導いてゆく―。',
        NULL, 0, 0, 0, '2024-10-02'),
       (393, 81, '百姓貴族 2nd Season', NULL, NULL, 2, 0, 0, 0, '2024-10-04'),
       (394, 424, '女神降臨', 'animations/394/images/ab9d0406-00b3-41f2-8582-94f6f2ace148.webp',
        '容姿のせいでいじめられていた女子高生ジュギョン。勉強もできないし、趣味といえばヘビーメタルを聴くことや、ホラー漫画を読むこと。あだ名は「肉まん」で、友達もいない…。そんな彼女が、メイクという魔法の武器を手に入れて劇的に変身！転校先の高校では瞬く間に人気者となり、学校一の女神を決める「女神選挙」の候補に選ばれる。しかし、行きつけの漫画喫茶でクールなイケメン同級生スホにすっぴんを見られてしまい、大ピンチに……！外見にとらわれず、自分らしさを探し求める青春ラブストーリー。',
        NULL, 0, 0, 0, '2024-10-05'),
       (395, 22, 'オーイ！とんぼ 第2期',
        'animations/395/images/fc6a5884-bef7-4643-839c-eedb4e93c834.webp',
        '島を出たとんぼの日常は目まぐるしく変化していく――。\n高校生となり、熊本での生活をスタートさせたとんぼは、練習場のジュニア生たちとコースでラウンドすることに。トカラで培った自由奔放なゴルフでコースを攻略していくとんぼに対し、1つ年上の実力者・ひのきも決死で応戦。激しい対決を繰り広げる。\nとんぼの潜在能力の高さに驚愕したコーチのハジメは、とんぼを5月の九州女子選手権に挑戦させることを決意する。\n島で一緒にラウンドしたつぶらや、熊本で出会ったひのきなど、新たなライバルたちとのゴルフを通じて、とんぼがさらに大きく羽ばたいていく！',
        NULL, 0, 0, 0, '2024-10-05'),
       (396, 165, 'ばなにゃ あらうんど ざ わーるど',
        'animations/396/images/d76e006f-fe32-49f8-8369-5ef7515673a2.webp',
        'とある星に住む、バナナにひそむふしぎなにゃんこ「ばなにゃ」。\nある日、ばなにゃのもとに光の球が近づいてくると、\nピカっと光り、中から小さいばなにゃ「ベイビースイート」が現われました！！\nあっという間に仲良しになったふたりは、\n世界中のあらゆる場所をめぐる大冒険へと出かけていくことに。',
        3, 0, 0, 0, '2024-10-21'),
       (397, NULL, 'ARCANE：アーケイン：League of Legends シーズン2',
        'animations/397/images/c02b62d0-b74a-4ea7-bf7e-45342f5b4d14.webp', NULL, 2, 0, 0, 0,
        '2024-11-09'),
       (398, 17, '村井の恋', 'animations/398/images/d438f96c-a50f-4b78-a802-55fdd8861091.webp',
        '様⼦のおかしい男⼦⾼校⽣・村井は担任の⽥中先⽣に恋をしている。しかし⼀⽅の⽥中は⼄⼥ゲームの推しキャラクター「春夏秋冬(ヒトトセ)」に恋をしている。\nそんなことはつゆ知らず、⽥中に告⽩をする村井だったが、「⿊髪ロン⽑は恋愛対象外」と⼀蹴されてしまうーーところが翌⽇、髪型を⼀新して現れた村井は⽥中の”推しキャラ”そのものの姿となっていた。激しく動揺する⽥中と猛烈にアプローチをし続ける村井、果たしてこのおかしな恋の⾏⽅はどうなっていくのか…︕︖\n「次にくるマンガ⼤賞2019」Webマンガ部⾨で2位に輝いたエクストリーム胸きゅんラブコメ「村井の恋」が待望のアニメ化︕',
        NULL, 0, 0, 0, '2024-10-06'),
       (399, 17, '魔王2099', 'animations/399/images/0e1d66f1-004a-46bf-9d4c-232e2acc2841.webp',
        '統合暦2099年――新宿市。\n究極の発展を遂げた未来都市に、\n伝説の魔王・ベルトールは再臨した。\n巨大都市国家の輝かしい繁栄と\n……その裏に隠された凄惨な“闇”。\n新たな世界を支配すべく、\n魔王は未来を躍動する！\n第33回ファンタジア大賞\n――異次元の《大賞》受賞作、\n遂にアニメ化決定！',
        NULL, 0, 0, 0, '2024-10-12'),
       (400, 23, 'ソードアート・オンライン オルタナティブ ガンゲイル・オンラインII',
        'animations/400/images/4dfdc7f9-1903-430c-b268-a69dc0ce0314.webp',
        '『ソードアート・オンライン オルタナティブ ガンゲイル・オンライン』。\n本作は、全世界累計発行部数3,000万部突破『ソードアート・オンライン』から生まれた物語。\n原作・時雨沢恵一とキャラクター原案・黒星紅白が描く、“もう一つのSAO”である。\n舞台は、鉛弾が飛び交い硝煙けぶるVRMMO(仮想現実大規模多人数同時参加型オンラインゲーム)\n《ガンゲイル・オンライン》。\n長身がコンプレックスで、小さなもう一人の自分を手に入れるためにVRゲーム空間へ降り立った\n小比類巻香蓮こと《レン》が愛銃《P90》を携え、チーム対抗デスマッチ《スクワッド・ジャム》へと挑む。\n2018年4月より放送を開始したTVアニメ第1期では\n少女たちが繰り広げる迫力のガンアクションが話題となり、国内と海外で大きな反響を呼んだ。\nそして2024年10月より、TVアニメ第2期の放送が決定。\n突如アナウンスされた新たなチーム対抗デスマッチ大会に、\nレン、エム、フカ次郎、ピトフーイの最強チーム《LPFM》が参戦する。\n優勝候補筆頭と目される彼らを待ち受けるのは、\n“時間経過とともに海へ沈むフィールド“　“MAP中央に潜む【UNKNOWN】エリア“\n“無名チームの結託”　という過酷な状況だった。\nさらに、全プレイヤーに驚愕の特別ルールが告げられる――',
        2, 0, 0, 0, '2024-10-04'),
       (401, 104, '星降る王国のニナ',
        'animations/401/images/6fceb1e3-6953-4570-8629-e7f1740cc9e1.webp',
        'フォルトナ国城下で孤児として暮らしていたニナは、 星の神のごとき深き青――瑠璃色の瞳を持っていた。 事故で亡くなったフォルトナ国の王女アリシャと同じ色の瞳ゆえ、 第二王子アズールに見出され、ニナは王女に成り代わることを求められる。 身代わりの星の巫女として、王女として、与えられた使命―― それは三月のあと、大国ガルガダの第一王子セトに偽りの花嫁として嫁ぐこと。 運命に翻弄されながらも、誰かに必要とされることに喜びを感じるニナ。 そのまっすぐな瞳が見ているものとは……。 愛する人を守る決意をしたとき、それぞれの運命が大きく動き始める！！',
        NULL, 0, 0, 0, '2024-10-10'),
       (402, 16, 'ラブライブ！スーパースター!! 第3期',
        'animations/402/images/7069b3d0-fc42-4072-b105-177f7f0059ae.webp',
        '私立結ヶ丘女子高等学校、\n表参道と原宿と青山という3つの街のはざまで生まれた\nスクールアイドルグループ Liella!の3年目がはじまる。\n澁谷かのんたち1期生にとっては、高校生活最後の1年。\n精一杯声響かせた学校の屋上も、全力で駆けた並木道も、全てが思い出に変わる前に。\n「約束をしよう――。」\n5人で踏み出し、9人で夢を叶えて、11人で結ばれる「みんなで叶える物語(スクールアイドルプロジェクト)」。\nはばたけ！私たちのラブライブ！',
        3, 0, 0, 0, '2024-10-06'),
       (403, 123, '監禁区域レベルX',
        'animations/403/images/2849e457-e8f3-4a76-bbc8-a79e94b0d1d0.webp',
        '涼花が昼寝から目を覚ますと、「絶対にマンションから出るな」という母からのメッセージが……。知らぬ間に、どうやらマンションは誰も入ることのできない監禁区域になっていた。 主人公の女子高生・涼花は、封鎖されたマンションから脱出するため、謎の未確認生命体X（サイ）と対峙することに。ループする絶望の中で活路を見出し、涼花は無事家族のもとへ帰れるのか……！？',
        NULL, 0, 0, 0, '2024-09-06'),
       (404, 397, 'メカウデ', 'animations/404/images/b23c80c6-9c12-4056-b257-621f0dac6982.webp',
        'キタカガミ市に住む中学生アマツガ・ヒカルはある日、謎の“ウデ”型機械生命体 アルマと出会う。アルマはヒカルからエネルギーを得ようと彼の身体への結合を試みるも失敗。なんとヒカルが着ていたパーカーに結合してしまう。一方その頃、メカウデ達の自我を奪い兵器にすることを企む大企業“カガミグループ”はアルマの身柄を追っていた。そしてメカウデ達をカガミグループから解放するため活動する組織“ARMS（アームズ）”もアルマを探す。そんな中、記憶を失って困っているアルマを見捨てることができなかったヒカルはアルマが結合したパーカーを羽織り、メカウデ使いたちが繰り広げる大事件に巻き込まれていく……',
        NULL, 0, 0, 0, '2024-10-03'),
       (405, 49, 'さようなら竜生、こんにちは人生',
        'animations/405/images/5d7f4b03-3faa-489e-aa88-252ffddb18a2.webp',
        'ある時、最古の神竜が人間に討たれた。 悠久の時を生き、神々すらひれ伏す絶大な力を持つその竜は、孤独と共に己の死を受け入れた。 しかし、次に気がついた時、竜は辺境の村人ドランとして第二の生を受けていた。 人間として竜よりずっと短い生を生きることになった彼は、畑仕事に精を出し、食を得るために動物を狩る……。 質素ながらも温かい村での生活に、ドランの心は竜生では味わえなかったささやかな喜びで満たされていく。 しかしそんなある日、 沼地の調査に出かけたドランの前に、セリナと名乗る半人半蛇のラミアが現れる。 伴侶を探して旅をしている彼女は、ラミアなのに人間を誘惑するのが苦手だという。 人と魔物、相容れぬ存在ながらも次第に心を通わせていく二人。 だが、二人の前には様々な外敵が現れて――！？ 辺境から始まる、元最強最古の竜の“生き直し”ファンタジー！',
        NULL, 0, 0, 0, '2024-10-10'),
       (406, 138, 'きのこいぬ', 'animations/406/images/93645df2-484f-4e76-bf9d-b26d0bb2cff6.webp',
        'ある日、絵本作家の夕闇ほたるは、庭の雪柳の下に、まピンク色のきのこが生えていることに気づく。彼がぼんやり眺めていると、それは突然動き出す！しっぽをぶんぶん振って犬っぽいのに、でもきのこ？疑問に思いながらも、一緒に暮らすことに。すると…描いちゃいけないところにお絵かきして、大好きなたこ焼きは常にぜんぶ食べたい。気まま放題の子どもかと思えば、大人顔まけにさり気なくフォロー。いろいろ謎すぎるけど、いっしょにいるとなんだか楽しくて、笑える。そんなきのこいぬとほたるとの日々を描く、ちょこっと不思議ほんわかアニメーション。',
        NULL, 0, 0, 0, '2024-10-03'),
       (407, 22, '殿と犬', 'animations/407/images/6baad3f1-e872-4446-beb2-003c2c0266a4.webp',
        'かつて戦国の世を駆け抜け、鬼神のごとき勇姿を⾒せた【殿】。されど、その栄光も今は昔。すっかり没落し、日々の暮らしもままならぬ中、胴長短足の珍妙な【犬】と長屋で暮らすことに。その毎日は「何これ！？ 犬こんなことできんの！？」と驚きの連続で、「もう、かなワン！？」ちょっぴりシュールで、ハートウォーミングな“天下泰平主従暮らし”、いざ開幕。',
        NULL, 0, 0, 0, '2024-10-10'),
       (408, 83, '七つの大罪 黙示録の四騎士 第2期',
        'animations/408/images/f9e6ad4d-940f-43eb-9963-4062282d14aa.webp',
        '果て無き世界へ、大いなる運命へ、飛び込め―― 数々の困難を乗り越え、ついに旅の目的地である リオネス王国へ到着したパーシバル達。 リオネス国王で〈七つの大罪〉であるメリオダスから世界で起こっている惨状とアーサーの目的を聞かされたパーシバルは仲間たちと共に打倒アーサーを決意する。 そしてついに揃う〈黙示録の四騎士〉たち。 しかし、新たな追手と“混沌の王”アーサーが彼らの前に姿を現す！ 全世界待望の痛快冒険ファンタジー第2章、開幕！',
        2, 0, 0, 0, '2024-10-06'),
       (409, 94, '新テニスの王子様 U-17 WORLD CUP SEMIFINAL',
        'animations/409/images/740a900b-25bf-4a90-9980-766439e10493.webp',
        '『新テニスの王子様 U-17 WORLD CUP（アンダーセブンティーンワールドカップ）』シリーズ第2弾！ 戦いの舞台は準決勝へと移る！！ U-17 WORLD CUP（アンダーセブンティーンワールドカップ）―― 強豪国フランスとの戦いを制したリョーマたち日本代表は、準決勝への進出を果たす。 準決勝の相手は、プロテニスプレイヤー、ボルクを筆頭とする世界No.1の最強チーム・ドイツ。 そしてドイツには、かつて合宿で苦楽を共にした手塚も代表入りしている。 圧倒的な力を誇るドイツを相手に、日本代表チームの面々は己を高め進化を目指す！ 日本vsドイツ――激闘の幕が開ける！',
        NULL, 0, 0, 0, '2024-10-02'),
       (410, 497, 'Tokyo Override',
        'animations/410/images/659a1df5-2474-407d-bf76-edf136a1e9c2.webp',
        '孤独なハッカーが出会ったのは、秘密裏に活動するデリバリー集団。完璧な理想の街・東京、その表の顔に潜む闇に包まれた真実を両者は共に暴いていく。\nNetflixシリーズ「Tokyo Override」11月21日（木）より世界独占配信中',
        NULL, 0, 0, 0, '2024-11-21'),
       (411, 555, 'ねこに転生したおじさん',
        'animations/411/images/62282d8f-ee3d-40ec-9d2b-7fd1626dc526.webp',
        '全人類がニャいた！？「次にくるマンガ大賞2023WEB マンガ部門2位」を受賞した話題のSNSマンガ、ついにTVアニメ化！ ごく普通のサラリーマンだったのに、ある日突然、ねこに転生してしまったおじさん。 人間の言葉も話せなくなり道端で困っていると、そこへ通りかかったのは、 おじさんが勤めている会社の社長だった。厳しい性格で知られていた社長だったが、可愛らしいねこ（正体はおじさん）を目にしたとたん、態度が一変し…！？ 正体がバレないようふるまうおじさんと、ねこに「プンちゃん」と名付けて溺愛する社長の、愉快でシュールなハッピーライフがスタート！',
        NULL, 0, 0, 0, '2024-10-07'),
       (412, NULL, 'マーダーミステリー・オブ・ザ・デッド',
        'animations/412/images/6eb72c3f-b3ea-45a0-a172-765d698ce554.webp',
        'ゾンビパンデミックで崩壊した世界。記憶を失い、見知らぬ場所で目覚めた主人公・天野ミコトは、6 人の少女たち、蘭奈、莉莉、夕、史香、ムルムル、るみなに保護される。\nしかし、平穏な日々が突如として破られ、ミコトと共に保護された男が殺されるという衝撃の事件が発生する。犯人はこの中に、そして次は...\n東急歌舞伎町タワーを舞台に、密室と化したタワー内で次々と襲い掛かる謎と秘密。友情が芽生え始めた彼女たちは果たして事件の真相に辿り着くことができるのか―',
        NULL, 0, 0, 0, '2024-11-06'),
       (413, 351, 'カミエラビ GOD.app シーズン2',
        'animations/413/images/75180ef7-ca21-4751-9285-8dfccb3940aa.webp',
        '神様を決める殺し合い「カミエラビ」は小野護郎（ゴロー）の消滅とともに休止となった。 それから12年が経ち、当時の出来事は集団幻覚事件として世間で認知されていた。 皆事件があったことは覚えているものの、 その中心にいたゴローのことは存在すら覚えていない。 小学生の小野螺流（ラル）は、母親すら存在を否定する兄、 ゴローのことを唯一覚えており、彼をどうにか復活させたいと願っていた。 一方、同じ小学校に通う佐々木依怙（エコ）は個人的に12年前の事件の真相に興味を持ち、 謎を解き明かすためその中心に存在したはずの人物を探していた。 そんな中、神様を決める殺し合い「カミエラビ」が再開される。 「カミエラビ」とは何なのか？誰が何のために仕組んだものなのか？ 神様（アイツ）が復活する時、その全てが明らかになる───！',
        2, 0, 0, 0, '2024-10-02'),
       (414, 60, 'アイドルマスター シャイニーカラーズ 2nd season',
        'animations/414/images/40ca0230-49bc-479b-86e3-6756220a9b4f.webp',
        '光を目指し、一歩を踏み出した“翼”たち――。\nアイドルへの憧れ。求める願い。手を伸ばしたい夢。\n様々な思いを胸に、283プロダクションに新たなユニットが加わる。\n完璧なパフォーマンスを目指すストレイライト。\n幼馴染4人の絆で結ばれたノクチル。\n２つのユニットが巻き起こす波紋が、お互いの道を照らし出す輝きとなっていく。\nそこに広がるのは可能性という名の未来。\n“翼”たちが踏み出す新たな一歩。羽ばたく先を決めるのは――',
        2, 0, 0, 0, '2024-10-04'),
       (415, 56, '放課後少年花子くん 続編',
        'animations/415/images/83c3e05e-2d2f-4fc8-b4a2-c2574f3452b8.webp', NULL, 2, 0, 0, 0,
        '2024-10-07'),
       (416, 25, '銀河英雄伝説 Die Neue These フォースシーズン 策謀',
        'animations/416/images/20803149-9fd2-4418-af41-6727576d1c41.webp', NULL, 4, 0, 0, 0,
        '2024-10-09'),
       (417, 356, 'モブ皇帝～平凡をむさぼる僕が多元宇宙の支配者に選ばれたので、世界を救ってみた～',
        'animations/417/images/a3469392-6b67-4594-8cde-6bfe7d45af9c.webp',
        '主人公・陳俊は、ただただ平凡な暮らしを望むエセオタクだが、ひょんなことから多元宇宙帝国の皇帝になるハメになった。ただ普通の人間でいることを望む陳俊だったが、帝国にいる1.2メートルの女将軍パンドラも、異能局の姉の林雪も、帝国の女帝サンドラも、皆その意見に反対。幼なじみの許浅浅までも、「あなたは皇帝にならなければならない」と言った。陳俊は仕方なく、平日は世界を救い、休日はゲームに興じるという、なんとも忙しい生活を送ることになった…',
        NULL, 0, 0, 0, '2024-10-01'),
       (418, 19, 'アサティール2 未来の昔ばなし',
        'animations/418/images/8195d895-2a8f-467b-ab90-fcab94132c86.webp',
        '「アサティール」とはアラビア語で「昔ばなし」という意味の言葉です。\n『アサティール2 未来の昔ばなし』は、今から少し未来のサウジアラビアに暮らす一家のお話です。\nサウジアラビア西海岸のNEOM（ネオム）にある「オクサゴン」という海上都市に、小学6年生の少女マハの家族が引っ越してきました。マハは、弟のライアンとスルタン、そして猫型ロボットのアニスと楽しく暮らしていますが、３人は、悩んだり困ったりすることもしばしば。そんな時、大好きなアスマお婆ちゃんが、素敵なアラビアの昔話をお話ししてくれます。そのお話しからマハたち姉弟は、大切な事を学び、自ら行動していくという物語です。',
        2, 0, 0, 0, '2024-11-03'),
       (419, NULL, 'トワイライト・オブ・ザ・ゴッズ 〜神々の黄昏〜',
        'animations/419/images/2927a335-4ecf-45c1-8583-212539bb5ac8.webp',
        'ザック・スナイダーが北欧神話を大胆に、そして残酷なまでに生々しく描写。神々に復讐(ふくしゅう)を果たそうとする戦士を主人公とした、大人向けのアニメシリーズ。',
        NULL, 0, 0, 0, '2024-09-19'),
       (420, 188, 'ハミダシクリエイティブ',
        'animations/420/images/b9d26c80-d62b-4352-a223-24842589a71f.webp',
        '自他共に認める陰キャである主人公「和泉 智宏」は、急遽行われた生徒会長を決めるくじ引きで、当たりくじを引いてしまう。 しぶしぶながら会長を引き受けた智宏は仲間集めを開始するが、挙げられた役員候補は全員学園に来ていない！？ 同級生の「常磐華乃」、後輩の「錦あすみ」、そして妹の「和泉妃愛」を引き入れる中、音信不通だった前会長「鎌倉詩桜」、智宏のクラスメイトである「竜閑天梨」の二人まで現れて……！ アニメでは、ゲームで見ることのできなかった、主人公不在の中で繰り広げられる5人の物語をお届けします！ 不登校から脱却した彼女たちが、生徒会の枠組みを超えて巻き起こす、青春日常コメディが開幕！',
        NULL, 0, 0, 0, '2024-10-03'),
       (421, 19, 'SPECIAL EDITED VERSION 『ONE PIECE』 魚人島編',
        'animations/421/images/18b01634-5836-4b95-9380-51f65c02c652.webp',
        '時は、大海賊時代。この世の全てを手に入れた男、海賊王ゴールド・ロジャー。彼が死に際に放った一言は全世界の人々を海へと駆り立てた。 「俺の財宝？ほしけりゃくれてやる！探せ！この世のすべてをそこに置いてきた」 ロジャーが遺した富と名声と力の「ひとつなぎの大秘宝（ワンピース）」を巡って幾人もの海賊たちが旗を掲げて戦っていた。 そして、そんな海賊に憧れる一人の少年ルフィ。「悪魔の実」の能力により、一生泳げない体の代わりに、全身がゴムのように伸びる不思議な体を手に入れた少年！ 偉大なる海賊シャンクスと出会い、ルフィは自らも海賊になることを夢見る。そんなルフィにシャンクスは海での再会を約束し、自分の麦わら帽子を預けて出航していった。 ルフィは海賊王になるために航海に出た。2年の歳月を経て、それぞれに成長した麦わらの一味がシャボンディ諸島に集結！“新世界”の入口である魚人島へ出航する！',
        NULL, 0, 0, 0, '2024-11-03'),
       (422, 553, '時空の隙', 'animations/422/images/249872b0-e361-408f-9d03-6af757b8dc00.webp',
        '現世と異世界の間で、エネルギーが不安定なことから生じた時空の隙は、異世界にいる怪物たちが現世に通じる唯一の通路となっている。怪物の侵入を阻止するために、現世では特殊な体質を持つ者たちが、果敢に時空の隙に立ち、世界を守るために戦っている。そんな狭間に巻き込まれた中二病で売れない漫画家・林一帆の運命や如何に…。',
        NULL, 0, 0, 0, '2024-10-01'),
       (423, 17, 'Duel Masters LOST ～追憶の水晶～',
        'animations/423/images/f1548a49-23b1-443a-b660-80c8c1e23750.webp',
        'ある日突然人の姿が消える怪事件が多発する東京・新宿。\n半年前、この街で目覚めた斬札ウィンはあらゆる記憶を失っていた。\n成り行きで通い始めた高校やアルバイトでは周りと馴染めず、\nクラスメイトのニイカや仲間たちと夜の公園でたむろする鬱屈した日々。\nそんな日常は「ウィンのすべてを知る」という謎の転校生・クリスタの登場によって変貌する。\nウィンと結婚を約束した仲だという彼女。その背後には怪しげな影がうごめいていた。\n頻発する怪事件の真相とは。\n突如現れたクリスタの目的とは。\nそしてウィンの隠された過去とは。\n失われた記憶を取り戻す、新たな物語が始まる。',
        1, 0, 0, 0, '2024-10-04'),
       (424, NULL, 'トゥームレイダー: レジェンド・オブ・ララ・クロフト',
        'animations/424/images/c5e746fd-171c-49ee-93dd-40ad179b9009.webp',
        '世界を股にかける危険な追跡劇に巻き込まれた、怖いもの知らずの冒険家ララ・クロフト。彼女は神話に隠された謎を解き明かしながら、過去のトラウマとも向き合っていく。',
        1, 0, 0, 0, '2024-10-10'),
       (425, 252, '齢5000年の草食ドラゴン、いわれなき邪竜認定 Season2',
        'animations/425/images/97f67108-432b-49ff-8e28-c90592537b6f.webp',
        '五千年ものあいだ洞窟に潜んでいた、凶悪な容貌の竜。その正体は── 草や木の芽が大好物の、お人好しすぎる草食ドラゴンだった！ 元生贄の少女・レーコは、そんな彼を最強の邪竜と思い込み、今日も崇拝してやまない。強すぎる思い込みによって自分自身が最強の力を得たとも知らず……。 魔王討伐を目指す一匹と一人は、レーコがぶち抜いた岩山のトンネルを通ってアスガ王国へ。たどり着いた王国では、国王・ヴァネッサとその妹・ロゼッタの間に、王位を巡る陰謀が動き出していた！',
        2, 0, 0, 0, '2024-10-03'),
       (426, 79, '科学×冒険サバイバル！',
        'animations/426/images/e4ee3909-f96e-4296-8eaa-8030656ad4e2.webp',
        '大人気の「科学漫画サバイバル」シリーズがテレビアニメ化！ どんな困難に立たされても「絶対にあきらめない！」と奮闘する、“サバイバルの達人”ジオたちと、“サバイバルの天才”ダイヤたちが、仲間とともに“勇気”と“科学”でピンチに立ち向かう！',
        1, 0, 0, 0, '2024-10-05'),
       (427, 103, '大正偽りブラヰダル～身代わり花嫁と軍服の猛愛',
        'animations/427/images/e94dd6ba-3e68-47b8-a1b1-b05cd01ec340.webp',
        '結婚に愛など無い、そう思っていた。\n軍人の猛愛を知るまで――…\n子爵家令嬢でありながら社交界では行き遅れ、親からは厄介者扱いの麻子。\nある日、唯一大切にしている妹に冷酷で荒々しいと噂の軍人・木戸との縁談が持ち上がる。\n阻止するため麻子は身代わりに嫁ぐことを申し出るが…!?\n【冷血軍人×孤独な令嬢】\n結婚からはじまる眩き大正艶愛ストーリー！',
        NULL, 0, 0, 0, '2024-10-06'),
       (428, 570, '百妖譜 第2期', 'animations/428/images/9720bc10-f4f3-4a3a-96fa-8bde1809cd9e.webp',
        '百妖譜を探す旅の途中、桃夭たちは道に迷って行き場をなくしてしまう。そんな時、狩人の獲物が落ちてきたことをきっかけに、また新たな妖怪たちとの出会いが始まるのだった。人の身体に入り込み、心まで蝕んでいく妖怪、“応声”。その正体を探るため、一行は古井戸へと向かう。すると、一人の老婆が営む怪しい粥屋があった。老婆は三人に粥を勧めるが、手を付けずに様子を伺っていた桃夭が鈴を鳴らすと、その身体は恐ろしい化物に変わり…。なぜ彼女は、人を呪う化物になってしまったのか？そこには、誰も知らない悲しい過去が隠されていた。本当に邪悪なのは妖怪か、人間か…。彼らの魂を救う桃夭たちの旅が、再び始まる。',
        NULL, 0, 0, 0, '2024-10-02'),
       (429, 200, 'ぷにるんず ぷに２',
        'animations/429/images/5757829d-7d9f-4f1e-922e-be5cd26d3c2a.webp',
        'ぷにるんず……それは、ぷにっとやわらかい『ぷしぎ』ないきもの。 みんな、ぷにぷにされるのが大すき。 まいにち楽しく ぷにっとくらしています。 ある日、あいるんのおうちに『ぷしぎなあんてな』があらわれました。 あんてなが光ってやってきたのは、あたらしいぷにとも ともるん。 ぷにるんずの日常は、ますますにぎやかになります。 そんな ともるんをみまもる ぷしぎなぷにるんず ゆにるん。 そして、あいるんたちのまえにあらわれた不思議な女の子。 今回もいろいろあるけれど、ぷにるんずのぷしぎな日々はつづいていきます。',
        2, 0, 0, 0, '2024-10-06'),
       (430, NULL, 'Thunderbolt Fantasy 東離劍遊紀4',
        'animations/430/images/23b0b204-9108-4064-b015-d22d5ac45c9c.webp', NULL, NULL, 0, 0, 0,
        '2024-10-05'),
       (431, 238, '魔法少女リリカルなのは 20周年記念セレクション',
        'animations/431/images/16d53d9d-9d43-4986-a8b4-fd4f63dadd5d.webp',
        '日本のある都市。海鳴市で暮らす平凡な小学三年生、高町なのは。ある日、なのはは、異世界から訪れた少年ユーノと出逢う。ユーノの目的は、海鳴市に散らばった異世界の遺産。「ジュエルシード」の回収。暴走したジュエルシードからユーノを助けようとしたなのはは、自身に「魔法」の才能がある事を知る。危険なジュエルシードを回収するため、なのははユーノと協力し、ユーノから託された知性を持った魔導端末「魔導師の杖」レイジングハートとともにジュエルシードの捜索を開始する。',
        NULL, 0, 0, 0, '2024-10-05'),
       (432, 24, 'SHIBUYA♡HACHI 第2クール',
        'animations/432/images/b80e82d4-dde1-4882-bf9e-6f2c6b4e0cfe.webp', NULL, 2, 0, 0, 0,
        '2024-10-05'),
       (433, 343, 'シルバニアファミリー フレアのピース・オブ・シークレット',
        'animations/433/images/a5f1994d-768d-489b-942f-3e15eb70633c.webp',
        '物語の舞台は世界のどこかにある”シルバニア村”。ほがらかでみんなと過ごすのが大すきなショコラウサギの女の子「フレア」と、頭脳明晰でやさしいペルシャネコの女の子「ライラ」、元気いっぱいで忍者に憧れているくるみリスの男の子「ラルフ」の3にんや、赤ちゃんたちが、村の中や森の中、ゆうえんちなどで大活躍します！\nシルバニアファミリーの世界で起こるさまざまな出来事を通して、夢や希望をたいせつにする主人公フレアと個性豊かなシルバニアの仲間たちによる心温まるお話をお届けします。',
        NULL, 0, 0, 0, '2024-11-21'),
       (434, NULL, 'ジュラシック･ワールド／サバイバル・ミッション シーズン2',
        'animations/434/images/84dc26fd-4826-48c8-b530-b8c7ed06c9da.webp', NULL, 2, 0, 0, 0,
        '2024-10-17'),
       (435, 131, 'KUROMI’S PRETTY JOURNEY 〜はちゃめちゃ！マルチバース大脱出！〜',
        'animations/435/images/bbe0e582-23b1-49dd-8326-b186c59ac20a.webp',
        '今日はクロミの誕生日!!\nでもバクたちはハロウィーンの準備で大忙し!?\n「こんな世界、大キライだ!!」\nクロミのブチギレモード全開の叫びで\n突然、時空に穴が開く!\nその穴に吸い込まれたクロミは、\n気づけばゾンビの世界に…!\n果たしてクロミは元の世界に戻れるのか?!',
        2, 0, 0, 0, '2024-10-31'),
       (436, 359, 'クマーバ シーズン2',
        'animations/436/images/cce0e1bf-f00f-4923-a3ff-b5cacd6d3de0.webp',
        '「インターネットの世界にレッツゴー！」\nクマーバたちの活躍により平和が戻ったはずのインターネットの世界。\nそこにまたもやバグリンが現れる。\nバグリンは負の感情エネルギーで作られたイタズラ怪獣を操っていた。\nインターネットの世界は大混乱！\nう〜ん・・・クマったクマった！\nクマーバは仲間たちと協力して、イタズラ怪獣をやっつけることができるのか！？\nクマったこともババっと解決！！',
        2, 0, 0, 0, '2024-10-05'),
       (437, 41, 'ぽちゃーズ', 'animations/437/images/b6d13fac-6c95-4822-aced-05ea226ca441.webp',
        'YouTubeの大人気アニメ『そろ谷のアニメっち』クリエイターのそろ谷が送る 「めっちゃかわいい×めっちゃおもろい」ショートコントアニメ。 ぽちゃ化したキャラクター『ぽちゃーズ』たちがハートフルな笑いをお届けします。 みんなが『ぽちゃ化』した世界。 ぽちゃ化した生き物たちが当たり前のように、そして欲望おもむくままに生活しています。 たまに人間社会に転がり込むことも…。',
        NULL, 0, 0, 0, '2024-10-08'),
       (438, NULL, 'ヴォクス・マキナの伝説 シーズン3',
        'animations/438/images/935900bd-a5f4-44f7-8db0-ed914bf75d25.webp',
        '待望の「ヴォクス・マキナの伝説」シーズン３では、すべてが危機に瀕していた。灰の王がヴォクス・マキナを追い詰める一方で、クロマ・コンクラーベによる破壊は野火のように広がっていた。私たちの愛すべきはみ出し者の集団は、愛する者、タル・ドレイ、そしてエクサンドリア全土を守るために、内外の悪魔に打ち勝たなければならない。',
        NULL, 0, 0, 0, '2024-10-03'),
       (439, 102, 'Re:ゼロから始める休憩時間(ブレイクタイム) 3rd season',
        'animations/439/images/8ee00b07-ff0e-4054-b597-4f204d3a8ba1.webp',
        '3rd season も休憩時間(ブレイクタイム)！\nミニキャラたちによる、本編では描ききれなかったリゼロの物語──。\nいつもとはちょっと違うリゼロの世界を、ブレイクタイムにお楽しみください！',
        3, 0, 0, 0, '2024-10-03'),
       (440, 168, 'アドベンチャー・ウィズ・スーパーマン',
        'animations/440/images/2d703f6a-949e-46df-b35e-28da1697ce5d.webp',
        '「アドベンチャー・ウィズ・スーパーマン」は、クラーク・ケント、ロイス・レイン、ジミー・オルセンの3人の20代の若者が、自分たちが何者であるか何者でありたいかを模索しながら街を救う姿を描く！\nクラークは自分の不思議な力を隠し、自分がどこから来たのか問い続けながら生きてきた。しかし、デイリー・プラネットに入社し、初日に犯罪者の銃撃に巻き込まれたとき、彼はメトロポリスの安全を守るために自分の力を受け入れなければならなくなる・・・。\n大胆でキュンとする、それが「アドベンチャー・ウィズ・スーパーマン」！',
        1, 0, 0, 0, '2024-11-03'),
       (441, NULL, 'キラキラ キャッチ！ティニピン',
        'animations/441/images/f2a07a15-e5d7-4088-a369-53fff4ac2308.webp',
        'ハーモニータウンに戻ってきて楽しい日々を送っているローミー。 ハチュピン以外のロイヤルティニピンたちは、王立ティニピンスクールの先生として呼ばれ、エモーション王国に帰っている。 「みんな、元気に過ごしているかな？」 一方、エモーション王国の宝石の森。 謎のティニピンが登場し、宝石の森で暮らしていた宝石ティニピンたちを流れ星にして地球へ落とした。 王立ティニピンスクールの学生で、見習いロイヤルティニピンであるココピン、ニコピン、マコピンは、仲間たちを助けるため、勝手に地球へ向かうが・・・ 地球にたどり着いて、ドタバタするココピン、ニコピン、マコピン。 ローミーは見習いロイヤルティニピンたちに会い、モンジュ博士が作った新しいアイテム、ジュエルハートウイングフォンとジュエルバンドを渡してもらう。 ローミーとハチュピンは、まだ一人前ではないココピン、ニコピン、マコピンと一緒にチームを組むことに。 果たして散り散りになった宝石ティニピンたちを見つけ、キャッチできるのか！？ トラブルだらけ！？新たなティニピンたちと繰り広げるローミーの物語が始まる！',
        2, 0, 0, 0, '2024-10-05'),
       (442, 175, 'ぬいストーリー2',
        'animations/442/images/8610c666-05b4-40b4-8093-629a33992d40.webp',
        '自由奔放なぬいぐるみたちとミチコ（ギャル）の不思議な共同生活がますます賑やかに！推し活に精を出すわたあめ、食い意地がすごいいぬぱん、見た目は赤ちゃんなチェリーたちが君についてるぜ！制作は江古田の個人アニメチームPiso Studioが監督、脚本、キャラクターデザイン、声の出演に至るまでほぼ2人で担当！',
        2, 0, 0, 0, '2024-10-19'),
       (443, NULL, 'LEGO ピクサー：ブリックトゥーンズ',
        'animations/443/images/563b2211-d769-4339-b0f9-c4b2ef5444ca.webp',
        'ピクサー人気のキャラクターたちがレゴになって再び登場する！\nそれぞれ５話のエピソードでは、心温まり、愉快でレゴの世界に溶け込んだ親しみのあるキャラクターたちや場所が登場する。\n死者の国でミゲルと歌ったり、メリダと三つ子の弟たちが“クマった”状況に陥ったり、ニモ、マーリン、ドリーたちと遠足に行ったり、パーファミリーがシンドロームからご近所さんを守ったり、マックィーンの次のレースに向けてメーターと準備をしたり、レゴの世界でピクサーのキャラクターたちが繰り広げる冒険を楽しもう！\n2024年9月4日（水）よりDisney+（ディズニープラス）で独占配信中',
        NULL, 0, 0, 0, '2024-09-04'),
       (444, NULL, 'ミニっと！かいじゅう８号', NULL, NULL, NULL, 0, 0, 0, '2024-12-06'),
       (445, NULL, 'とーがね！おまつり部 再編集版', NULL,
        '家庭の事情で転校した栃野みのりが、出身である東金へ帰ってきた。\nお祭り好きなみのりは、毎年夏に行われるお祭りを楽しみに帰ってきたのだが\nなんとお祭りはとっくの昔になくなったと聞いて大ショック！\n「お祭りがない東金はこのまま廃れてしまうに違いない……」\nそう思い込んだみのりはお祭りを復活させるために動き出す。\nしかし、現実には資金や人手、地元の協力、さらには駅を挟んだ東西の対立（？）などといった問題が立ちはだかって――\nはたして、みのりたちは仲間を集めてお祭りを復活させることができるのか!?',
        NULL, 0, 0, 0, '2024-10-03'),
       (446, 37, '【推しの子】第2期',
        'animations/446/images/cadd01ae-6583-4ef1-83c4-ed0fac39f382.webp',
        '新たな舞台の幕が開く── 人気マンガ『東京ブレイド』の舞台稽古が始まった。 劇団ララライの役者達に囲まれ、大きく飛躍するかな。 かなの才能を認めながら、ライバル心を激しく燃やすあかね。 才能と熱意のある役者が集う中、アクアは演技すらも利用してアイの死の真相を追い続ける──。 そしてアイドルとして母の背中を追い続けるルビーは……。',
        2, 0, 0, 0, '2024-07-03'),
       (447, 58, '逃げ上手の若君',
        'animations/447/images/058ce452-5c55-4675-9728-62e1446886a0.webp',
        '時は西暦 1333 年、武士による日本統治の礎を築いた鎌倉幕府は、信頼していた幕臣・足利高氏の謀反によって滅亡する。全てを失い、絶望の淵へと叩き落とされた幕府の正統後継者・北条時行は、神を名乗る神官・諏訪頼重の手引きで燃え落ちる鎌倉を脱出するのだった…。逃げ落ちてたどり着いた諏訪の地で、信頼できる仲間と出会い、鎌倉奪還の力を蓄えていく時行。時代が移ろう大きなうねりを、「戦って」「死ぬ」武士の生き様とは反対に「逃げて」「生きる」ことで乗り越えていく。英雄ひしめく乱世で繰り広げられる、時行の天下を取り戻す鬼ごっこの行方は―――。',
        NULL, 0, 0, 0, '2024-07-06'),
       (448, 23, '負けヒロインが多すぎる！',
        'animations/448/images/6b05791a-6901-4f25-8162-d2d37f35100d.webp',
        '第15回 小学館ライトノベル大賞《ガガガ賞》受賞作、待望のTVアニメ化！\n想い人の恋人の座を勝ち取れなかった女の子——「負けヒロイン」。\n食いしん坊な幼なじみ系ヒロイン・八奈見杏菜。\n元気いっぱいのスポーツ系ヒロイン・焼塩檸檬。\n人見知りの小動物系ヒロイン・小鞠知花。\nちょっと残念な負けヒロイン——マケインたちに絡まれる、\n新感覚・はちゃめちゃ敗走系青春ストーリーがここに幕を開ける！\n負けて輝け、マケインたち！',
        1, 0, 0, 0, '2024-07-13'),
       (449, NULL, 'ラーメン赤猫',
        'animations/449/images/0e49fec5-1e46-4e1a-a626-c4a22ded3c06.webp',
        '猫だけで営むお店『ラーメン赤猫』、そこにバイトの面接で訪れた人間の珠子。 正直に犬派と答えた彼女はあっさりと採用が決まり、 任されたお仕事は猫たちのお世話係。 ブラッシングを通じて垣間見える猫模様に、様々なお客様が織りなす人間模様。 身体も心も温まる『ラーメン赤猫』、愛しさ大盛り、召し上がれ。',
        NULL, 0, 0, 0, '2024-07-04'),
       (450, 163, '小市民シリーズ 第1期',
        'animations/450/images/14953555-1d30-41c1-b5a1-996bc07b5623.webp',
        'わたし、知りたかったの。 恋とはどんなものかしらって。 たがいに助け合う“互恵関係”を解消した、高校二年の小鳩くんと小佐内さん。 小佐内さんは、新聞部一年の瓜野くんとつきあいはじめる。瓜野くんは在学した証しを残し、小佐内さんにいいところを見せるため、市内で起きた放火事件を学内新聞で取り上げようと奮闘する。 一方、小鳩くんはクラスメイトの仲丸さんとつきあいはじめる。平穏な日々を過ごすなか、河川敷で放火現場に遭遇し……。小鳩くんと小佐内さんの小市民としての再出発は、はたしてどうなるのだろうか。',
        1, 0, 0, 0, '2024-07-06'),
       (451, 37, '時々ボソッとロシア語でデレる隣のアーリャさん',
        'animations/451/images/aafb9583-c31f-4a3f-9fb2-6d26d80f669d.webp',
        '久世政近の隣の席に座るアーリャさんは、いつも彼に対して冷ややかな目線を向けている。けれど、時々ボソッとロシア語で彼にデレていて……。その言葉を政近も聞き逃しはしない。なんと、政近はロシア語のリスニングがネイティブレベルだったのだ!!気付いていないと思い込み、時々デレるアーリャさん。そして、その意味を理解しながらも、気付いていないような振りをする政近。ニヤニヤが止まらない、二人の恋模様の行方は——!?',
        1, 0, 0, 0, '2024-07-03'),
       (452, 25, '君に届け 3RD SEASON',
        'animations/452/images/8dc0bde7-8cd1-4e2b-9342-1ec5a800e4e9.webp',
        '「付き合うってどうすればいいの？」\n膨らむ気持ちに戸惑いながらも自分に向き合い風早へ想いを伝えた爽子。\n人知れず努力し飾らない人柄の爽子を見て惹かれてきた風早も\n目をそらさずまっすぐに自分の想いを届けた。\n爽子と風早の新しい関係がここからまたはじまる。\n初めてのデート 恋人になって過ごす学生生活\nうれしい事 はずかしい事 そして新しい悩み\n初々しく ぎこちなく 少しずつだけれども\nお互いの事を知っていく二人と、動き始める友人たちの恋物語\nそれぞれの「すき」の気持ちと、かけがえのない友人たちが織りなす、\n甘ずっぱくて切ない、少年少女達の物語が、再び始まる──',
        3, 0, 0, 0, '2024-08-01'),
       (453, 17, '2.5次元の誘惑 第1期',
        'animations/453/images/191d8f75-cc23-420f-9390-d074418a6e8b.webp',
        '「リリエーーール!!!」\n3 次元の女子に興味無し！\n漫画研究部部長・奥村は今日も部室でひとり、画面の向こうに映る愛してやまない 2 次元のキャラクター・リリエルの名を叫んでいた……。\nそんな奥村のもとへやってきたのは「リリエルになりたい」という 3 次元女子・天乃リリサ。\n彼女は、漫画の中に登場する女の子のエッチで可愛い「衣装」が大好き。\nそして、奥村に負けないくらいリリエルを愛する仲間だった！\n奥村に秘密の趣味がコスプレであることを明かしたリリサは、コスプレの写真や動画が詰め込まれた「ROM」のコレクションを見せて伝える——。\n「私っ……これを作りたいんです!!」\nふたりきりの部室で始まるコスプレ活動！\nリリサが変身したリリエルは奥村が衝撃を受けるほど本物で!?\n熱意に押された奥村もカメラを手に!?\n真摯に熱くコスプレに向き合う彼らが、「何かを熱烈に愛している」全てのオタクへ贈るコスプレ青春ストーリー、開幕!!',
        1, 0, 0, 0, '2024-07-05'),
       (454, 22, '俺は全てを【パリイ】する〜逆勘違いの世界最強は冒険者になりたい〜',
        'animations/454/images/4531ed89-379d-4031-b60d-0941130ffce8.webp',
        '「小説家になろう」年間総合ランキングで１位を獲得した人気タイトルが、\n待望の TV アニメ化！\n世界をめぐり、怪物と戦い、人々を守る。\nそんな冒険者に憧れる少年・ノールに下されたのは、\n「全てにおいて、一切の才能がない」\nという残酷な判定だった。\nでも才能がないなら、誰よりも努力すればいい！\n身につけた最低スキル──攻撃を弾く【パリイ】を十数年もの間ひたすら磨き続け、\nついには千の剣を弾けるように成長する。\nしかし、どれほど極めても最低スキルだけでは冒険者にはなれず、\nノールはいつの間にか世界最強クラスの力を手にしながらも\nそれを自覚することもなく、街の雑用をこなす日々をおくっていた。\nそんなある日、魔物に襲われている王女・リーンを偶然助けたことで、\nノールの運命の歯車は思わぬ方向へと回り出す……！\n──これは、謙虚な無自覚最強男が、\n磨き抜いた最底辺スキル【パリイ】で、強者を薙ぎ倒していく物語。',
        1, 0, 0, 0, '2024-07-04'),
       (455, 135, '魔導具師ダリヤはうつむかない',
        'animations/455/images/eeac7873-00b8-415f-9e24-d0acad5e0927.webp',
        '彼女が最後に見た光景は資料が雑然と散らかるデスクだった。徹夜続きで働き、突然心臓が止まってしまったのだ。やりたいことがたくさんあったはずなのに、机に突っ伏して最期を迎えるなんて…。 彼女は二度目の人生を魔法の存在する世界で送ることになった。名前はダリヤ・ロセッティ。彼女が暮らすこの世界には、人々の生活を便利にする「魔導具」がある。普段の生活はだらしないが魔導具師としては尊敬できる父のカルロ。ダリヤはカルロの作る魔導具に憧れ、自分も魔導具師になろうと決意する。これは彼女が魔導具師として前をむき、花開いていく物語。',
        NULL, 0, 0, 0, '2024-07-06'),
       (456, 53, 'しかのこのこのここしたんたん',
        'animations/456/images/69bd311a-0af6-41f0-ac47-7b4c4d504af6.webp',
        '都立日野南高校に通う女子高生、虎視虎子。 ある日の登校中、彼女は顔に冷たいものが当たるのを感じた。 ふと上を見ると、そこには鼻水をたらし、ツノが電線に引っかかって身動きが取れなくなっている女の子が――！？ うっかり変な『ツノ』の生えた少女・鹿乃子のこを助けたことで、優等生（の皮を被った）虎視虎子の人生がかき乱されていく…… 一人の少女（元ヤン）が一人のシカ（？）に出会う ガール・ミーツ・シカ物語開幕！！',
        NULL, 0, 0, 0, '2024-07-07'),
       (457, 62, '先輩はおとこのこ',
        'animations/457/images/7dd37138-359c-4adc-9a27-ddccd2b72670.webp',
        '「第5回アニメ化してほしいマンガランキング」1位受賞。 話題作が、ついにアニメ化！ 男だけど可愛いものが大好きで、女の子の姿で高校生活を送る“男の娘”・花岡まこと。 ある日の放課後、まことは、“女の子だと勘違いしたまま”の後輩女子・蒼井咲に告白をされる。 「実は自分は男の子なのだ」と打ち明け、告白を断るまこと。 しかしまことの予想に反し、咲はあきらめるどころか、「男女両方の先輩が楽しめる」とテンションアップ！さらに、「私が先輩の初恋の人になってみせます」と宣言して……。 可愛いものが大好きな、まこと。 まことに恋をする、元気いっぱいの後輩・咲。 まことを近くで見守り続けてきた、幼馴染の竜二。 3人の、恋と友情と、成長の物語がはじまる――。',
        NULL, 0, 0, 0, '2024-07-04'),
       (458, 18, '義妹生活', 'animations/458/images/daa1483d-7017-4904-818b-9481aaaa42a3.webp',
        '高校生・浅村悠太は父・太一の再婚をきっかけに、同い年の少女・綾瀬沙季とその母・亜季子と一つ屋根の下で暮らしていくこととなる。 互いに両親の不仲と離婚を経験しているがゆえに、男女関係に慎重な価値観の二人は、義理の兄妹として適切な距離感を保とうと約束する。 「私はあなたに何も期待しないから、あなたも私に何も期待しないでほしいの」 考えを述べあい、すり合わせを重ねることで、互いを理解していく悠太と沙季。 新たな生活に居心地の良さを感じはじめた時、二人の関係はゆっくりと、しかし確実に、変化をはじめて………… これは、いつか恋に至るかもしれない物語。 “他人”が“家族”へ、そしてその先へ。 少しずつ変わりゆく日々を映す、恋愛生活物語。',
        NULL, 0, 0, 0, '2024-07-04'),
       (459, 87, '杖と剣のウィストリア 第1期',
        'animations/459/images/8c6c77a4-3958-4750-8433-53a947630b85.webp',
        '一人前の魔導士をめざして魔法学院に入学した少年ウィル。努力家の彼には魔導師として致命的な弱点があった。それは、“魔法がまったく使えない”こと。同級生や教師から冷たい視線を浴び、時にはくじけそうになりながらも、強い気持ちで邁進していくウィル。杖は使えなくとも剣を執り、魔法至上主義の世界で戦い抜く。自分だけに与えられた力を信じて。そして、大切な人との約束を守るためにーー',
        1, 0, 0, 0, '2024-07-07'),
       (460, 35, '〈物語〉シリーズ オフ&モンスターシーズン',
        'animations/460/images/bb79e229-986d-48db-a3b5-4c08f05967df.webp',
        '高校を卒業し、阿良々木暦の物語は終わった。\n今度こそ、本当に終わった。\nしかし暦に助けられた\n彼女たちの物語は、\n終わってはいなかった。\n青春の中でもがく彼女たちの、\n前日譚、あるいは後日談。',
        NULL, 0, 0, 0, '2024-07-06'),
       (461, 32, 'かつて魔法少女と悪は敵対していた。',
        'animations/461/images/95325d57-0d5b-471c-a5da-03878194aa8a.webp',
        '悪の組織――あらゆるものを侵略し、あらゆるものを滅ぼす。 残忍にして狡猾なその組織のブレーンには、王の片腕たる悪の参謀がいた。 地上侵略の危機に立ち上がる、薄幸の魔法少女・白夜（びゃくや）。 彼女と対峙した悪の参謀・ミラは、なんと一目ボレしてしまい……。 魔法少女と悪が敵対していたのは、かつての話。 殺し愛（あ）わない、ふたりの行く末は――？',
        NULL, 0, 0, 0, '2024-07-09'),
       (462, 108, 'ライジングインパクト シーズン1',
        'animations/462/images/42705a4d-ec54-4cd0-84dd-69a1feec8abd.webp',
        '福島の山間部に祖父と暮らす小学3年生の七海ガウェイン。世界一の飛ばし屋に憧れ、友人と野球の練習に明け暮れる日々を過ごしていたが、偶然近くを訪れていた女子プロゴルファー、西野霧亜と出会う。初めてのショットで300ヤード越えという飛距離を出しゴルフに魅せられたガウェインは、祖父の元を離れ、霧亜を頼って上京し世界的な名門校、キャメロット学院に入学する。優秀なジュニアゴルファーが集うキャメロット学院で世界中のライバルたちとしのぎを削り、ガウェインの才能が今開花する！\nNetflixシリーズ「ライジングインパクト」シーズン1：6月22日（土）、シーズン2：8月6日（火）より独占配信',
        1, 0, 0, 0, '2024-06-22'),
       (463, 17, 'デリコズ・ナーサリー',
        'animations/463/images/ff4ec861-fa0a-49e2-9f3d-32fc9fd78134.webp',
        '名門デリコ家の貴族であり、将来を嘱望されている《血盟議会》のエリート議員 、ダリ・デリコ。吸血種たちの最高統治機関である《血盟議会》からある任務を命じられるものの、ダリはにべもなく断ってしまう。業を煮やした同期議員であるゲルハルト、ディーノ、エンリケが説得に向かうと、そこには自ら幼子をあやすダリの姿が。一方巷では、吸血種を狙った謎の連続殺人事件が発生。その黒幕と思われる反社会組織《ペンデュラム》と、ダリの間には、なにやら過去の因縁があるようで……。\n『血と誇りにかけて、任務と育児の両立──成し遂げてみせようではないか！』\n吸血種の貴族たちによるノブレス・オブリージュ育児奮闘記。壮麗なゴシックワールド×誇りにかけたドタバタ育児は、果たして両立することができるのか！？',
        NULL, 0, 0, 0, '2024-08-07'),
       (464, 170, 'モブから始まる探索英雄譚',
        'animations/464/images/809333b3-212f-4006-8584-73a83c2a3000.webp',
        'ステータスも低くいわゆるモブキャラの高校生・高木海斗は、日本に現れたダンジョンで毎日スライムを狩るふつうの探索者。 ある日見たこともない金色のスライムを倒すと、激レアアイテム・サーバントカードを入手。神話の存在の美しい戦乙女（ヴァルキリー）が出現し――。 モブな男子高校生の成り上がり英雄譚！',
        NULL, 0, 0, 0, '2024-07-06'),
       (465, 292, '恋は双子で割り切れない',
        'animations/465/images/a2452ec0-c2e4-4795-be79-3ebb9b098c73.webp',
        'いつまでも、ただの幼なじみじゃ居られない──\n初恋こじらせ系双子ラブコメ開幕！初恋こじらせ系双子ラブコメ開幕！\n白崎純と琉実・那織の神宮寺姉妹は小さいころから家族同然で育った幼なじみ。\n見た目ボーイッシュで乙女思考な姉・琉実と、\n外面カワイイ本性地雷なサブカルオタの妹・那織。\n顔はそっくりだけど全く正反対な2人。\n純はいつからか芽生えた恋心を抱えながらも、\n特定の関係を持つでもなく交流は続いていたのだけれど……\n「わたしと付き合ってみない？お試しみたいな感じでどう？」\n琉実が発したこの一言が、3人をいびつな三角関係へと導いていく――',
        NULL, 0, 0, 0, '2024-07-10'),
       (466, 137, '魔王軍最強の魔術師は人間だった',
        'animations/466/images/2e678b6d-9723-45c1-8729-f696cfe88700.webp',
        '『魔王軍最強の魔術師』と呼ばれ、単身で砦をも攻略する魔族、その名はアイク。\n絶大な魔術で敵をなぎ払う様は、まさしく『化け物』そのもので、敵味方から畏怖される存在だった。\nしかし、そんな彼には、他の魔族にはいえない秘密があった。\n「――俺、実は人間なんだよね」\n人間であることを隠しながら魔族と人間の共生を目指す、成り上がりダークファンタジー！',
        NULL, 0, 0, 0, '2024-07-03'),
       (467, 53, '異世界スーサイド・スクワッド',
        'animations/467/images/543974a9-fe5c-46fd-85da-1b7606eb7b52.webp',
        '犯罪都市、ゴッサム・シティ。A.R.G.U.S ⻑官のアマンダ・ウォラーはある任務のため、ハーレイ・クイン、デッドショット、ピースメイカー、クレイフェイス、キング・シャークを招集。ゴッサムの極悪悪党（ヴィラン）共が送りこまれたのは、ゲートによって繋がった剣と魔法の世界、オークが闊歩しドラゴンが空を翔ける″異世界＝ISEKAI″だった︕︕\nISEKAI 到着直後から暴⾛するハーレイ達だったが、王国の兵隊に捕まり監獄送りに。首に装着された爆弾の爆発まであと 72 時間…。タイムリミットが迫るハーレイ達。⼥王アルドラとの交渉の末、掴み取った解放の条件は″敵対する帝国軍の征圧″NO CHOICE ︕︕⾃由を得るため…ハーレイ達はファンタスティックでデンジャラスな戦地へ向かう︕︕\n逃げても即死︕任務失敗でも即死︕命懸けのミッションを背負ったハーレイ達はこの ISEKAI を生き抜くことができるのか︕︖決死の特殊部隊＝スーサイド・スクワッドのド派手な”暴”険譚が今、幕を開ける︕LET''S PARTY︕︕',
        NULL, 0, 0, 0, '2024-07-05'),
       (468, 238, 'ハズレ枠の【状態異常スキル】で最強になった俺がすべてを蹂躙するまで',
        'animations/468/images/86a9d1fd-9e93-42fa-a531-caef14ae0e55.webp',
        '学校では空気な高校生、三森灯河はクラスメイトとともに勇者として異世界に召喚された。 女神ヴィシスによってクラスメイトたちが次々にS級、A級と能力を見出される中、灯河は最低ランクであるE級と宣言され『廃棄』対象となってしまう。 生存率ゼロの遺跡に廃棄された灯河はハズレ枠と貶された【状態異常スキル】を駆使して遺跡脱出を試みる。 その日から、女神ヴィシスへの復讐の炎を宿した青年は人畜無害な人間をやめ、心の奥底に隠していた本性を明かしていく……',
        NULL, 0, 0, 0, '2024-07-04'),
       (469, 51, '天穂のサクナヒメ',
        'animations/469/images/7d26a233-a5b3-49f6-a5fc-bbc3c29011fc.webp',
        '遥か東方の果て、ヤナトの国。 古来よりこの地では神々の住む頂の世と人間の住む麓の世、二つの世があると信じられている――。 頂の世に住まう上級神かつ駄女神のサクナヒメは、武神と豊穣神の間に産まれながら、両親が蓄えた穀を潰しぐうたらな生活を送っていた… そんな中ある日、ひょんなことから神々の都を追放され、鬼たちが巣喰う孤島・ヒノエ島へ！？ 明日の食糧もままならない未開の離島で、土を耕し米を育てて鬼退治へ。 神の世に迷い込んだ人間たちと、ひよっこ豊穣神の、もみ殻舞い散る集団生活が始まる！！',
        NULL, 0, 0, 0, '2024-07-06'),
       (470, 22, 'ダンジョンの中のひと',
        'animations/470/images/945e4d96-6f64-41f5-acc9-e92e20bd7817.webp',
        'アントムルグのダンジョンに消えた父を追い、単独で挑み続けてきたシーフの少女クレイ。探索の末、ついに前人未踏の地下9階に到達。そんな矢先にモンスターとの戦闘でダンジョンの壁が崩落！崩れた壁の中から現れたのは――管理人！？ダンジョンで働くもの達が織り成す、迷宮お仕事ファンタジー。',
        NULL, 0, 0, 0, '2024-07-05'),
       (471, 25, 'キン肉マン 完璧超人始祖編 Season 1',
        'animations/471/images/ef87ab5c-d971-49d7-aa99-29f0167cd894.webp',
        '宇宙の果てのキン肉星から地球にやって来た王子・キン肉マンは、ダメ超人と人間たちにバカにされ続けてきたが、ひょんなことから出場権を得た世界一の超人を決める大会、超人ワールドカップで奇蹟の優勝、しかも翌年は連覇まで達成！\n以降は宇宙の平和を守る正義超人の中心人物となり、この世の支配を目論む悪魔超人、さらには地上からの弱小超人一掃を狙う完璧超人ら、猛威をふるう敵勢力をテリーマンやロビンマスクといった仲間たちとの友情パワーでなんとか退けてきた。\nそれらの功績を認められ、最後の試練“キン肉星王位争奪サバイバル・マッチ”をも勝ち抜いたキン肉マンは晴れて父から王位を譲り受け、誰もが認めるキン肉星第58代大王に即位！　地球から故郷の星へ帰還。結婚も果たし、8年に渡る闘いの日々に別れを告げた。\nそれから約1年半後。全宇宙は平和に包まれていたはずであったのだが…!?',
        3, 0, 0, 0, '2024-07-07'),
       (472, 86, '疑似ハーレム', 'animations/472/images/2894e82a-4bc0-4fc2-aadd-46d5f5d84ef6.webp',
        '漫画のようなハーレム状態に憧れる演劇部の先輩「北浜瑛二」と密かに想いを寄せる先輩の前だと、つい“キャラ”を演じてしまう「七倉 凛」。 ツンデレちゃんに、小悪魔ちゃん、甘えんぼちゃん、クールちゃん、おしとやかちゃん。 演じるキャラが増えれば増えるほど、抑えきれなくなる先輩への想い。 ちょっとバカでかなり鈍感な瑛二に、七倉は、ありのままの自分で、想いを伝えられる日は来るのか…？',
        NULL, 0, 0, 0, '2024-07-04'),
       (473, 18, '黄昏アウトフォーカス',
        'animations/473/images/a5879986-18bb-4351-bd68-535cd36ef194.webp',
        '不良で一匹狼の寿と、映画部で寿を撮影することになった真央。 寮で同室の二人が交わした「約束」が、やがて二人を甘く縛りつけて――。 映画部部長で人気者の仁と、仁に対抗心を燃やす後輩の義一。 ぶつかりながらも、やがて二人は惹かれ合い――。 無口で不愛想だが信頼の厚い副部長の礼と、季節外れの新入部員・詩音。 不意のキスから、二人の「お付き合い」が始まって――。',
        NULL, 0, 0, 0, '2024-07-04'),
       (474, 82, '新米オッサン冒険者、最強パーティに死ぬほど鍛えられて無敵になる。',
        'animations/474/images/6c43fe28-c38f-4b1c-bb74-235babc446c8.webp',
        '“別にいいじゃねぇか......。何歳から新しいこと始めたって!” 最強にして新人のオッサン、冒険者を目指す!\n「夢を追うならできるだけ若いうちがいい」 人は皆、そう考える。だが、どうしても諦められない。そんな大人も、どこかにいる――。\n10 代で冒険者になるのが当たり前の世界で、30 歳を過ぎてギルド事務員から冒険者を目指したリック・グラディアートル。 大陸最強の冒険者が集う伝説のパーティ「オリハルコン・フィスト」のメンバーによる想像を絶する訓練の日々を過ごしてきた彼は、新米 F ランクながらも最高位である S ランク並みの戦闘力を有していた!?\n叶えたい夢を追い続けるアラサー主人公が、なめてかかってくるエリート冒険者を、本人が気付かないうちに鍛え上げられた戦闘力で次々にねじ伏せていく痛快アクションコメディ!',
        NULL, 0, 0, 0, '2024-07-01'),
       (475, 69, '女神のカフェテラス 第2期',
        'animations/475/images/2aa6ddf0-e08f-4e41-9e00-d06904cbcfcb.webp',
        '——どこかの海辺にある、古びた喫茶店。そこには…女神様がいるらしい——\nケンカ別れした祖母が遺した喫茶店「Familia」を継いだ主人公・粕壁 隼。そこには「おばあちゃんの家族」を語る見知らぬ５人の女神（カワイイ女の子）が！\n初めは衝突ばかりだったが、それぞれの過去や、家庭の事情を知った隼と女神たちの尽力によって様々な問題を乗り越えてきた「Familia」。\nしかし…隣にまさかのライバル店が⁉そこには 5 人の新たなカワイイ女の子が⁉\nそして祖母の代から続く不思議な縁が、隼と女神たちの関係をさらに深めていき…⁉\n”恋”と”家族”の六角関係が大きく動き出す！５人全員「正ヒロイン」の、ヒロイン多すぎシーサイドラブコメが再びここに開幕！',
        2, 0, 0, 0, '2024-07-04'),
       (476, 108, 'ライジングインパクト シーズン2',
        'animations/476/images/60ec7b06-1e02-47d3-8d73-4ed2034eed06.webp',
        'プロレベルのスイング。驚異的なバックスピン。超人的な精度。突出した才能を持つジュニアゴルファーたちとフェアウェイで肩を並べるため、ガウェインは様々な試練に挑んでいく。',
        2, 0, 0, 0, '2024-08-06'),
       (477, 55, 'SHY 東京奪還編',
        'animations/477/images/f321b55e-75c2-4713-bbb4-0a000aa05ec8.webp', NULL, 2, 0, 0, 0,
        '2024-07-01'),
       (478, 25, '銀河英雄伝説 Die Neue These サードシーズン 激突',
        'animations/478/images/f56e9336-2f92-4c0b-a091-bc28a100a5a5.webp', NULL, 3, 0, 0, 0,
        '2024-07-02'),
       (479, 132, 'ATRI -My Dear Moments-',
        'animations/479/images/9c42fbf8-50ec-4ffb-8b77-cffbab4bf95a.webp',
        '原因不明の海面上昇によって、地表の多くが海に沈んだ近未来。幼い頃の事故によって片足を失った少年・斑鳩夏生は、都市での暮らしに見切りを付け、海辺の田舎町へと移り住んだ。身よりのない彼に遺されたのは、海洋地質学者だった祖母の船と潜水艇、そして借金。夏生は“失った未来”を取り戻すため、祖母の遺産が眠るという海底の倉庫を目指して潜る。そこで見つけたのは、棺のような装置の中で眠る不思議な少女―アトリ。彼女は、人間と見紛うほどに精巧で感情豊かなロボットだった。海底からサルベージされたアトリは言う。\n「マスターが残した最後の命令を果たしたいんです。それまで、わたしが夏生さんの足になります！」',
        NULL, 0, 0, 0, '2024-07-13'),
       (480, 34, '多数欠', 'animations/480/images/ac7dd8d6-7f93-448d-a75c-d0bd99e8c15d.webp',
        'そのゲームは突然始まった―――。 『多数欠』それは “多数派が失われる” 過酷な生き残りゲーム。 絶大な力を持つ首謀者・皇帝に立ち向かうため、少年少女たちは謎の特殊能力「特権利」を手に運命を切り開いていく！',
        NULL, 0, 0, 0, '2024-07-02'),
       (481, 25, 'ターミネーター 0',
        'animations/481/images/e8aea57d-a8bf-40fd-935d-5ce5fa1b8499.webp',
        '文明が崩壊した未来の世界から、時空を超えて1997年に送り込まれたひとりの戦士。その目的とは、感情を持たない恐るべきサイボーグ兵器に命を狙われたAI科学者を何としても守ることだった。\nNetflixシリーズ「ターミネーター 0」8月29日(木)より世界独占配信中',
        NULL, 0, 0, 0, '2024-08-29'),
       (482, 181, '神之塔 -Tower of God- 王子の帰還／工房戦',
        'animations/482/images/1e8a0fa7-282e-4b68-b1b1-1af05542134b.webp',
        '【王子の帰還】\n衝撃的なラストシーンで幕を閉じた第１期から6年後、選別者にとって狭き門である20階に居たのは、\n何度脱落しても「塔の王になる」と挑戦を続ける男・王野 成（おうじ なる）。\n莫大な受験料のために借金を抱える王野は、最後のチャンスとして再び試験に挑戦し、そこで圧倒的な強さを持つ謎めいた長髪の男・ビオレと出会うが、ビオレは塔の支配者であるザハードに対抗する犯罪組織\n「ＦＵＧ」のスレイヤー候補であった。\n【工房戦】\nファリョンから、これまでの一連の出来事の真実、そしてビオレが\"二十五日の夜\"であることを聞かされたクンは、夜を再び仲間とするため、王野たちとともに塔の30階で開催される工房戦へ出場を決意する。\nFUGの次期スレイヤー候補ビオレを中心にしたFUGチーム。\n王野とクンが手を組んだチームらーめん丸。\nエンドロシ、アナクらが参加するシビスチーム。\nそれぞれの思惑が複雑に交錯する中、今回の工房戦で栄冠を掴むのはどのチームか!?',
        2, 0, 0, 0, '2024-07-07'),
       (483, 227, '異世界失格', 'animations/483/images/b6535a8b-9944-46ec-9668-5007bafc3b08.webp',
        'とある文豪と、その愛人がこの世を去った。\n憂い多き人生の如く渦を巻く激流へと身を投げ…るよりも早く、\n猛スピードで突っ込んできた〝例のトラック〟によって。\n文豪が目を覚ますとそこは、異世界の教会。\n案内人は、慈愛に満ちた瞳で微笑みかける。\n「ようこそ冒険者よ。あなたは選ばれ、転移したのです」\n御多分に洩れず、勇者の使命を背負わされてしまう文豪。\nだが、彼は転移者の誰もが与えられる〝あるもの〟を持たなかった……。\n「…ふふ。恥の多い生涯だ」\nこの世でも、異世界（あの世）でも\n＜失格者＞の烙印を押された文豪（センセー）の冒険が幕を開ける。\nきっと、どこかにいるはずの「さっちゃん」を見つけ出し、\n今度こそ、あの日の本懐——心中を遂げるために。',
        NULL, 0, 0, 0, '2024-07-09'),
       (484, 23, 'NieR:Automata Ver1.1a 第2クール',
        'animations/484/images/9627dbaa-0dd3-49bd-b331-7333b808ecea.webp',
        '西暦5012年。\n突如地球へと飛来してきた＜エイリアン＞と、\n彼らが生み出した＜機械生命体＞により、人類は絶滅の危機に陥った。\n月へと逃げのびた僅かな人類は、地球奪還のため、\n＜アンドロイド＞の兵士を用いた反攻作戦を開始。\nしかし無限に増殖し続ける＜機械生命体＞を前に、戦いは膠着状態に陥る。\n人類は最終兵器として、新型のアンドロイド＜ヨルハ＞部隊を地球へと派遣した。\n西暦11945年。\n「第243次降下作戦」が決行され、\n新たに＜ヨルハ＞部隊の＜2B＞と＜9S＞が地球へと派遣される。\n両名は機械生命体の基幹ユニット＜アダム＞及び＜イヴ＞の撃破に成功。\nこれを敵の殲滅、及び永きに亘る戦争終結への好機と捉えた＜人類軍＞は、\n機械生命体に対し総攻撃をかける決断を下す。\nこれは運命に翻弄された＜アンドロイド＞たちの、戦いと願いの記録――。',
        NULL, 0, 0, 0, '2024-07-05'),
       (485, 66, 'VTuberなんだが配信切り忘れたら伝説になってた',
        'animations/485/images/ac6d1f28-23e3-4fd0-ae76-166ea1ecc222.webp',
        '数々の華やかなVTuberが所属する大手運営会社ライブオン。\nその三期生で『清楚』VTuberの心音淡雪が、不注意から配信を切り忘れた結果——\n「やっぱロング缶の鳴る音は最高だぜ！」\n「は？どちゃしこなんだが？」\n「わたしがママになるんだよ！」\n素の性格（酒カス・女好き・清楚（VTuber））がバレてしまい！？\n「めちゃくちゃ切り抜かれてる！？トレンド世界1位！？なにこの同接数！！！！」\n大炎上するかと思ったら、ギャップがウケて大バズ！\nその結果——\n「おっしゃー配信始めるどー！」\n開き直った彼女は、大人気VTuberへ駆け上がっていく！！',
        NULL, 0, 0, 0, '2024-07-07'),
       (486, NULL, 'なぜ僕の世界を誰も覚えていないのか？',
        'animations/486/images/702b0992-01af-4072-a187-03779a6d93f3.webp',
        '「なんで誰も、本当の世界を覚えていないんだ……！」\n地上の覇権を争う五種族の大戦が、人類の勝利に終わった時代。\nだがその世界は、少年カイの目の前で突如として「上書き」された。\nパラレルワールドのような世界でカイが見たのは、\n歴史が改ざんされ、人類が大戦に敗れた光景――\nここでは竜や悪魔が地上を支配し、さらに\nカイは全ての人間から忘れられた存在になっていた。\nだが神秘の少女リンネと出会い、カイは英雄なき世界で、\n英雄の剣を継承し、君臨する強大な敵種族に戦いを挑む。\n世界から忘れられた少年が「真の世界を取り戻す」\n王道ファンタジーバトル、開幕！',
        NULL, 0, 0, 0, '2024-07-13'),
       (487, 51, '菜なれ花なれ', 'animations/487/images/47b56a37-d5f2-4ad1-8c22-43aead71a68e.webp',
        '「応援したいって気持ち…どこから湧いてくるんだろう？」 チアリーディング全国大会連覇を目指す名門、鷹ノ咲高校。1年生ながらにAチームを勝ちとった全中大会優勝経験者、美空かなたは大会中のミスがきっかけで飛べなくなってしまう。 そんなある日、かなたの目に飛び込んできたのは、電車と並んでビルからビルへと飛び移るパルクール女子高生、小父内涼葉だった。 　 かなたと涼葉に新体操お嬢様・詩音。ブラジルからの帰国子女・杏那。杏那のクラスメイト、ヨガ哲学女子・穏花。そしてかなたの元チームメイト、車いす女子の恵深。 趣味も特技も性格もバラバラなメンバーが歌ったり、ぶつかったり、スタンツしたり、妄想したり…。 応援したいって純粋な気持ちが揃う時、PoMPoMs（ポンポンズ）の応援はチアリーディングの枠を超えて人の心に伝わっていく。群馬の女子高生6人の応援が、世界をちょっとだけ変える…のかも？',
        NULL, 0, 0, 0, '2024-07-07'),
       (488, 218, 'グレンダイザーU',
        'animations/488/images/7b3f4cf3-96b5-452b-a5a1-a3f696114b9e.webp',
        '砂漠に堕ちた男には、記憶がない。 男は兜甲児に拾われ、大介と名付けられた。 夢のクリーンエネルギー光子力により成した財で、大富豪と正義の味方、2つの顔を持つ甲児は、どこか陰があるも非凡な才能を持つ大介に信頼を寄せて行く。 穏やかな日々が続くと思われていた中、未確認空中現象が世界中の大都市上空に出現する。 それは地球から遠く離れた星系より襲来したベガ星連合軍だった。 地球の兵器を遥かに凌駕するベガの前に蹂躙される人類。 プールの水を割って屹立する鉄の城マジンガーZ、地球最後の希望も異形の兵器円盤獣を前に苦戦を強いられる。 絶体絶命の中、砂塵を舞い上げ現れたのは、異星の魔神グレンダイザー。 乗っていたのは大介、彼は故郷フリード星を追われた王子デューク・フリードだったのだ──',
        NULL, 0, 0, 0, '2024-07-05'),
       (489, 51, '真夜中ぱんチ', 'animations/489/images/db80c5e7-d11d-4d44-a9df-5c29ea62cd32.webp',
        '「真夜中なのにおっはよー！真夜中ぱんチです！」\n世界でもっとも見られている動画投稿サイト「NewTube」。\n3 人組 NewTuber「はりきりシスターズ」の「まさ吉」こと真咲\nまさきは、とある事件がきっかけでチャンネルをクビになってしまう。\n起死回生を狙う真咲の前に現れたのは、なぜか彼女に運命を感じたりぶ。\n超人的な能力を持つりぶと一緒なら、最高の動画が撮れるはず。\n目指せ、チャンネル登録 100 万人！\n現代人共感必至!?\n「パリピ孔明」スタッフが贈る、ワケあり動画投稿者たちのハイテンション・ガールズ“再生”ストーリー！',
        NULL, 0, 0, 0, '2024-07-08'),
       (490, 29, 'ばいばい、アース 第1シーズン',
        'animations/490/images/6429ba98-952c-4fec-a09d-160ed9371e84.webp',
        'アドニスとのいさかいや＜悪＞との激しい戦闘以来、部屋に引きこもっていたベルだったが、仲間の献身に癒やされ、＜旅の者（ノマド）＞になることを再び強く決意する。＜理由の少女（ことわりのしょうじょ）＞としてこの世界の大いなる謎に迫っていくベル。一方、深い絶望の中、＜飢餓同盟＞に迎え入れられたアドニスは、ベルの師匠シアンと＜飢餓同盟＞の闇に住まうドランブイによって＜懐疑する者＞として鍛えられ、世界の滅びを望む。「俺を、斬れるか……？俺や神を止揚することができるのか？」シアンの2人の教え子、ベルとアドニスの戦いが意味するものとは。そして、すべての戦いの先にベルが見いだしたこの世界の＜理由（ことわり）＞とはーー。',
        1, 0, 0, 0, '2024-07-12'),
       (491, 209, 'この世界は不完全すぎる',
        'animations/491/images/1b9e465a-e49b-453d-b6b1-97dd4b59b992.webp',
        'フェルナーク大陸の南方に位置する辺境にもかかわらず、５つの小国がひしめき合い、小競り合いの絶えないクレボーン島。\nその中で最も小さく最も平和なベイル王国の…つまり辺境の中の辺境にある小さな村で慎ましく暮らす少女ニコラ。\n日課の薪拾いの最中に彼女の前に現れたのは、はるか山奥に住むはずの巨大なドラゴン。まさに村が襲われようというその時、駆けつけたのは、極秘に組織され\nた調査隊“王の探求者（キングス・シーカ―）”の一員を名乗るハガという男。\n繰り返される平穏な毎日の中で飽きることも知らなかったニコラは、ハガに憧れ、自ら外の世界へと踏み出すことを望む。\nそして、彼女はこの世界の本当の姿を知ることになる。',
        NULL, 0, 0, 0, '2024-07-05'),
       (492, 69, '僕の妻は感情がない',
        'animations/492/images/9441b49a-e7bb-46bd-b369-3e5fe5761d2e.webp',
        '社畜サラリーマンの小杉タクマは、家事をする暇がないため、家事ロボット「ミーナ」をリサイクルショップで購入する。タクマが「お嫁さんになってくれない？」と軽い気持ちで求婚したことをきっかけに、ミーナはプログラムにないはずの行動をとるようになる。自らの機能を駆使し、出来る限り「お嫁さん」であろうとするミーナ。タクマにもまた、夫としての自覚が芽生えていく――。ミーナには本当に「感情がない」のか。人間とロボット、「夫婦未満の2人が夫婦の絆を築くまで」のハートフルストーリー！',
        NULL, 0, 0, 0, '2024-07-02'),
       (493, 346, 'NINJA KAMUI', 'animations/493/images/eef2633d-e7f0-4e63-9674-065309958732.webp',
        '忍の組織から逃れた「抜け忍」であるヒガンは、名を変えて同じく抜け忍の妻マリと愛息レンと慎ましく幸せに暮らしていた。\nしかしある夜、黒装束の忍者たちに襲われ、マリとレンは殺されてしまう。\n病院の霊安室で息を吹き返したヒガンは、怒りと悲しみを抱え、組織への復讐を決意。\nFBI捜査官のマイクとその相棒のエマと共に、この事件の背後にある巨大な闇に立ち向かう――。\n過去と現在、信頼と絶望が絡み合うドラマティックな物語の幕が開ける！',
        NULL, 0, 0, 0, '2024-07-01'),
       (494, 17, 'FAIRY TAIL 100年クエスト', NULL,
        'フィオーレ王国随一で、お騒がせ魔導士ギルドとしても有名な「妖精の尻尾(フェアリーテイル)」。\nそこに所属するナツ・ルーシィ・ハッピー・グレイ・エルザ・ウェンディ・シャルルの最強パーティーは、旅立ちの時を迎えようとしていた。\n目指す先は遥か北の大地・ギルティナにあるという世界最古の魔導士ギルド「魔陣の竜(マギア・ドラゴン)」。\n黒魔導士ゼレフや黒竜アクノロギアとの死闘を乗り越えたナツたちに、\n＜Ｓ級クエスト＞の更に上級である＜100年クエスト＞に挑む許可が特別に下りたのだ。\n＜100年クエスト＞は、「魔陣の竜」が創設されてから百余年、\n誰一人として達成できていない伝説級の難関依頼。\n初めての大陸の“不可思議な街”、初めて出会う“不可解な神”、\nそして動き出す“不気味な敵”…。\n心躍るナツたち「妖精の尻尾」の新たな大冒険が、\n幕を開ける！',
        4, 0, 0, 0, '2024-07-07'),
       (495, 462, '下の階には澪がいる',
        'animations/495/images/1fd9dd99-4ff4-43c2-9776-70dfcdabe8df.webp',
        '憧れの先輩・桃井真珠を追いかけて青葉大へ入学した杉浦陽。真珠先輩と過ごす楽しい大学生活を思い描く陽だったが、ある日下宿先の前で、元人気アイドル・如月澪と出会う。彼女は芸能界引退後、陽と同じ下宿先の1階で、人目を避けて暮らしているという。 陽に対し攻撃的な態度をとったかと思えば、今度は「友達になりたい」と接近してくる、謎の多い澪。笑顔で接しながら陽と一定の距離を保とうとする真珠。さらに、合コンで出会った彼氏と別れたばかりだという先輩の三国紗羅。3人のヒロインと陽の青春の結末は…？',
        NULL, 0, 0, 0, '2024-07-03'),
       (496, NULL, 'コードギアス 奪還のロゼ',
        'animations/496/images/d68eef20-b9eb-4708-b945-3dd6ddac8598.webp',
        '光和 7 年、ネオ・ブリタニア帝国に占領された合衆国日本・旧ホッカイドウブロックに、「ナナシの傭兵」として知られる傭兵兄弟がいた。\n非常に優れた運動能力とナイトメアフレームの高い操縦技術を持つ兄のアッシュ、頭脳明晰で情報収集、作戦指揮を担当している弟のロゼ。\nシトゥンペバリアと呼ばれる難攻不落のエネルギー障壁により 4 年間、黒の騎士団の解放作戦を退けてきた第 100 代皇帝カリス・アル・ブリタニアと、彼に仕えるノーランドら皇帝直属の騎士アインベルク達は、再び世界を混乱へと陥れようとしていた。\n依頼を受けたロゼとアッシュは、日本人レジスタンスの七煌星団と共に、皇サクヤ奪還のため、ネオ・ブリタニア帝国に立ち向かう。\nディズニープラスで 6 月 21 日（金）より世界独占配信中',
        NULL, 0, 0, 0, '2024-06-21'),
       (497, 344, 'ケンガンアシュラ Season2 Part.2',
        'animations/497/images/ee2f5e1d-3c74-41c6-a026-9ae1e9ebf7b4.webp',
        '超人気バトルアクションシリーズがシーズン2 パート2へ！拳願絶命トーナメントはついに完結へ向かうが、激闘の裏で、ある危険人物が策略を企てる…。',
        4, 0, 0, 0, '2024-08-15'),
       (498, NULL, 'ソーセージ・パーティー ～理想郷 フードトピア～',
        'animations/498/images/471640c9-d2be-4d04-a087-9b4283f24184.webp',
        '人々を殺した後、食品たちは食品のためのユートピアをつくろうとする。', NULL, 0, 0, 0,
        '2024-07-11'),
       (499, 72, '異世界ゆるり紀行 ～子育てしながら冒険者します～',
        'animations/499/images/1ace52d6-afa3-4a14-a63c-036fbe1b5b33.webp',
        '神様のミスによって命を落とし、転生した茅野巧。 様々なスキルを授かり異世界に送られると、そこは魔物が蠢く危険な森の中だった。 タクミはその森で双子と思しき幼い男女の子供を発見し、アレン、エレナと名づけて保護する。格闘術で魔物を楽々倒す二人に驚きながらも、街に辿り着いたタクミは生計を立てるために冒険者ギルドに登録。 アレンとエレナの成長を見守りながらの、のんびり冒険者生活がスタート！',
        NULL, 0, 0, 0, '2024-07-07'),
       (500, 80, '戦国妖狐 千魔混沌編',
        'animations/500/images/021ce70b-591c-44e1-9a13-c3fd5244e75b.webp',
        '時は永禄七年。 その戦国の世に人があり、闇があり、人を喰う闇があり、闇を狩る人があり、 手を取り合う、人と闇があった—— 人間好きの妖狐･たまと、人嫌いな仙道･迅火の\"義姉弟\"が、「精霊転化」の力で、闇（かたわら）と戦い、乱世にはびこる巨悪を討つ！！\n第一部「戦国妖狐　世直し姉弟編」 第二部「戦国妖狐　千魔混沌編」\n迅火とたま、二人の旅の先にあるものとは…!?\n疾風怒濤の戦国バトルファンタジー、ここに開幕！',
        2, 0, 0, 0, '2024-07-17'),
       (501, 349, 'エルフさんは痩せられない。',
        'animations/501/images/88324abb-0edc-4243-9827-e625f01d1786.webp',
        '街の整体院『スマイリーボア』で働く直江友厚なおえともあつはある日、\nニット帽にサングラスの怪しい客を担当することになる。\nキャップに隠した耳が異常にもっこりしたその女性は、\nなんと異世界から来たエルフだった!!\nぽっちゃりエルフの絵留札(えるふだ)さんのダイエットを手伝うことになった\n直江は、日本に巣くう異世界人の悩みにドタバタと巻き込まれて…!!\nフライドポテトに魅了された絵留札さんは\n果たして痩せることができるのか!?\n「ぽっちゃりエルフのダイエットコメディ開幕!!」',
        NULL, 0, 0, 0, '2024-07-06'),
       (502, NULL, 'バットマン： マントの戦士',
        'animations/502/images/2f95afd1-e71d-4d9e-a217-e6a7a610bedd.webp',
        'ゴッサム・シティへようこそ。ここは犯罪が横行し、法を守る市民が絶え間ない恐怖の中で暮らす街だ。悲劇の炎で鍛えられた裕福な社交界の名士ブルース・ウェインは、人間以上でもあり人間未満でもある存在、バットマンとなる。孤軍奮闘する彼はゴッサム市警察や市役所内で味方を得るが、彼の英雄的な行動は致命的で予期せぬ結果を招く。\n8 月 1 日（木）から Prime Video で独占配信中',
        NULL, 0, 0, 0, '2024-08-01'),
       (503, 123, '未来の黒幕系悪役令嬢モリアーティーの異世界完全犯罪白書',
        'animations/503/images/e8520a16-e5f7-47de-90b8-fee0f79d2a3a.webp',
        '最恐の犯罪者 ジェームズ＝モリアーティー。 彼は名探偵と対決し、敗れ、そして命を落とした。 気づくと彼は、今まさに自殺しようとする異世界の令嬢に憑依していた。 寄宿舎で陰湿ないじめに遭い、自殺しようとしていた令嬢の名前はシェリー＝モリアーティー。 彼は記憶を失いながらも、その明晰な頭脳による完全犯罪方程式の力を彼女のために振るう。 記憶はなくても頭脳は変わらない。 いじめられていた令嬢は死に、血も涙も無い悪役令嬢モリアーティーに生まれ変わる。',
        NULL, 0, 0, 0, '2024-07-19'),
       (504, 558, 'エグミレガシー',
        'animations/504/images/c7fa123c-649c-4b12-abb7-ea2c7ebbd2a2.webp',
        '“エンドオブザワールド”は誰の手に……！？ とある海にぷっかりと浮かぶ『エグー島』。 この島の唯一の娯楽は歌姫“エンドオブザワールド”。 村人たちは日々、彼女の歌声に酔いしれていた。 しかし、そんなのどかな時間は一瞬で壊れる。 －歌姫の失踪－ この事件以来、島は『怒り』『疑心』『不安』で溢れてしまう。 そして、それぞれの思惑が動き始める……。 “エンドオブザワールド”を巡る、ペロペロ大戦争！ その運命を握るのは……、伝説の遺産『エグミレガシー』',
        NULL, 0, 0, 0, '2024-07-09'),
       (505, 123, 'まぁるい彼女と残念な彼氏',
        'animations/505/images/607ad0cd-6363-4f70-8167-207988f3bcd2.webp',
        '食べることが大好きで、幼少期からずっとプラスサイズだった看護師の万莉子。 恋とは無縁の人生だと思っていたのに、ある日先輩に誘われて参加した合コンでイケメンとの出会いが！？ 彼は過去のトラウマから万莉子のような体型の女性が苦手なはずなのに、なぜかデートに誘われてしまう！！ ――突然のモテに戸惑う、恋愛経験値ゼロ女・万莉子が取った行動とは！？ 話題沸騰のポジティブラブコメディ！',
        NULL, 0, 0, 0, '2024-06-07'),
       (506, 103, 'よあそびぐらしっ！',
        'animations/506/images/ab49c265-6f91-4cc1-9c17-8a93c2641670.webp',
        '「俺の家は…すっかりラブホになった」\nカメラマンになる夢を挫折した円人と、\nモデルになる夢を叶えた弥生。\n差がついてしまった幼馴染の2人が…突然の同居スタート！？\n最初はきまずい雰囲気だったけど、\n弥生には、円人に言えないある秘密があって…\n夜遊びから始まる、幼馴染との新たなカンケイ。\nもう、ただの幼馴染ではいられない――',
        NULL, 0, 0, 0, '2024-07-07'),
       (507, 95, '闇芝居 十三期', 'animations/507/images/d45c3d89-783e-4ab9-987d-7c20079da9c4.webp',
        NULL, 13, 0, 0, 0, '2024-07-14'),
       (508, NULL, 'こねこばくはつ',
        'animations/508/images/1fdba3ca-09aa-484a-a832-aeca3f14a1d6.webp',
        '地上へと送られた全能の神と、神の天敵である悪魔。ふたりは人間の言葉を話すネコに変えられ、人間と暮らし始める。人間の世界で、神ネコと悪魔ネコによる善と悪の戦いが幕を開ける!',
        NULL, 0, 0, 0, '2024-07-12'),
       (509, NULL, '0歳児スタートダッシュ物語 シーズン1',
        'animations/509/images/53b9e4ef-b101-40d3-b7da-e29008e29ff3.webp',
        '魔法も領地経営も、すべてにおいて天才過ぎる侯爵令嬢リリアのチートニューゲーム物語。生まれた時から前世の記憶を持ち、転生した異世界に魔法があると知り前世のゲーマー魂が滾るリリア。まだハイハイしかできない0歳児なのに、精力的にレベリングを行いはじめる。その結果、5歳にして高度な魔法を行使し高位精霊を従わせたり、侯爵領の経営においても敏腕をふるったりしての大活躍っぷり。この世界がRPGでも牧場ゲームでもチートで無双する！の勢いのリリアは当然王家の目にも留まり、誕生日に王宮に招かれることに。まさかこの世界は乙女ゲームで王子たちとの政略結婚フラグがたった!?悪役令嬢だけは絶対にイヤ～～～!!!!',
        NULL, 0, 0, 0, '2024-07-07'),
       (510, 270, '貼りまわれ！こいぬ 第2期',
        'animations/510/images/830c1140-75ec-4828-919c-e3b298d176df.webp', NULL, NULL, 0, 0, 0,
        '2024-07-06'),
       (511, 279, 'こねこのチー ポンポンらー夏休み',
        'animations/511/images/033e648a-99fd-4d73-bee6-11983a4bdb70.webp',
        '大好きなヨウヘイたち山田一家と暮らす子猫のチーは、いつも元気いっぱい。夏休みになると、お父さんに急な出張の仕事が舞い込みます——場所はなんと沖縄！\n「チーもいることだし、一人で行くか」というお父さんに、「私たちも行きたい！」とお母さんとヨウヘイがお願いして、山田家みんなで沖縄へ行くことに！\nそこに待っていたのは、光る太陽と、大きな海、そして……！？\nついに帰ってきた、世界中で大人気の「こねこのチー」シリーズ最新作。\n夏休みの沖縄を舞台に、チーとヨウヘイの新たな出会いと冒険が幕を開けます。',
        3, 0, 0, 0, '2024-07-19'),
       (512, 61, 'カードファイト!! ヴァンガード Divinez Season2',
        'animations/512/images/23cdcaeb-b387-4f7a-ae89-18e2a6bb24d4.webp',
        '運命大戦は序章に過ぎなかった⁉\nアキナたちの前に、謎の敵シヴィルトと6人の宿命者カードの所有者が立ちはだかる。\n大事な人を救うための戦い、\n宿命決戦が今始まる！',
        NULL, 0, 0, 0, '2024-07-06'),
       (513, NULL, 'ワンダラ', 'animations/513/images/6a07abca-ed2d-4bae-ba35-e8e99bb11bb2.webp',
        '地下サンクチュアリから脱出したエヴァが見た地上には、想像とあまりに違う世界が広がっていた。危険な環境や未知の文明を冒険しながら、エヴァは究極の問題に直面する。果たしてエヴァは地球最後の人間なのだろうか？',
        1, 0, 0, 0, '2024-06-28'),
       (514, 41, 'Fate/Grand Order 藤丸立香はわからない Season2', NULL,
        'この男、まだわかっていない！\n人類最後のマスター「藤丸立香」。\n彼なくしては人理修復することはできなかっただろう。\nしかし、そんな彼にも欠点があった……\nそれは、素直すぎること！\n藤丸の素朴な疑問に英霊たちが振り回されるドタバタ\nコメディ、再び開幕！\n※本作は「Fate/Grand Order」第2部のネタバレを含んでいます',
        2, 0, 0, 0, '2024-08-03'),
       (515, NULL, 'ドラゴン王子 シーズン6',
        'animations/515/images/b46e689a-ef29-47db-bf33-dc3488c042e5.webp',
        'アーラヴォスを倒(たお)す方法を探し求めるカラムとレイラ。一方、仲間たちはアーラヴォスのたくらみがゼイディアとカトリスに巻き起こす混乱に直面する。',
        6, 0, 0, 0, '2024-07-26'),
       (516, 52, 'JOCHUM', 'animations/516/images/d6c3702d-9f34-4612-ae28-9ed5f2836864.webp',
        'ここで暮らせば夢がかなう――そんなおうち「ジェオチャムハウス」。そこに暮らす11にんによる、ほのぼのしつつも、それだけでは終わらない日常を描くショートアニメシリーズ。それぞれの夢を胸に抱いた仲間たちの意外な姿も明らかに。個性豊かな11にんのキャラクターたちが、あなたを癒してくれるはず！',
        1, 0, 0, 0, '2024-07-13'),
       (517, NULL, 'フューチュラマ シーズン12',
        'animations/517/images/f7572ff5-6aaf-463e-a808-d12a07c41b0c.webp',
        '『ザ・シンプソンズ』の製作者が手がける SF コメディシリーズの新シーズン。ピザの配達中に誤ってコールドスリープされたフィリップ・フライが目覚めると、そこは 1000 年後の 31 世紀の地球だった。フライは、タフだが愛らしい一つ目の異星人リーラ(ケイティ・セイガル)、人間の特徴と欠点を持つロボットのベンダーなど「多様」な新しい友人たちと人生を再出発することになる。\n7月29日(月)よりディズニープラスの「スター」で独占配信開始',
        12, 0, 0, 0, '2024-07-29'),
       (518, NULL, 'スヌーピーのハッピーキャンプ',
        'animations/518/images/14106e3b-4030-45e0-a71b-1f4d6a149332.webp',
        '解散の危機にあると気付いたスヌーピーとビーグル･スカウトのメンバーは、メリットバッジを取得するため、アウトドアの大冒険に出発する。その頃、チャーリー･ブラウンと仲間たちは、キャンプで夏を楽しんでいた。',
        NULL, 0, 0, 0, '2024-06-14'),
       (519, NULL, '太鼓の達人 アニメば～じょん！',
        'animations/519/images/803ba6d1-3fad-4d1b-af2d-5561303b2bd5.webp',
        '和太鼓リズムゲーム 「太鼓の達人」 でおなじみのどんちゃんたちがアニメでも大活躍！\n太鼓の里出身、太鼓の演奏を愛する主人公コタロウは相棒のどんちゃんと共に太鼓の素晴らしさを世界に広めるため、超巨大エンターテイメント都市「オミコシティ」に上京。\n年がら年中オマツリが開かれている街オミコシティを 舞台に､「太鼓の達人」 を夢見るコタロウと、 太鼓のどんちゃ ん、そしてユカイな仲間たちが繰り広げるドタバタコメディ！さあ、始まるドン！',
        NULL, 0, 0, 0, '2024-06-10'),
       (520, NULL, 'スター・ウォーズ：ヤング・ジェダイ・アドベンチャー シーズン2',
        'animations/520/images/ec879d30-d5dd-4f3d-a835-4e2674a5bd62.webp',
        'ディズニープラスにて 8 月 14 日(水)より独占配信中', 2, 0, 0, 0, '2024-08-14'),
       (521, NULL, 'ザ・シンプソンズ シーズン35',
        'animations/521/images/888a0142-332c-40d6-815e-16ef3cc17f4d.webp', NULL, 35, 0, 0, 0,
        '2024-08-21'),
       (522, NULL, 'ブレッドバーバーショップ シーズン1',
        'animations/522/images/68019e76-68d6-4c82-a619-e35c67ce40a5.webp',
        'ベーカリータウンにあるブレッドバーバーショップ。店長である天才ブレッドにヘアセットをしてもらうため、町の訳アリなパンやスイーツたちが次々に訪れる。天才ブレッドによって、誰でもお望み通りに大変身。奇想天外なヘアスタイルでおいしそうな仕上がりに満足することまちがいなし。',
        NULL, 0, 0, 0, '2022-07-29'),
       (523, NULL, 'Disney Junior アリエル にんぎょのおはなし', NULL, NULL, NULL, 0, 0, 0,
        '2024-07-15'),
       (524, NULL, 'ユニコーン・アカデミー シーズン2', NULL, NULL, 2, 0, 0, 0, '2024-06-27'),
       (525, 84, '鬼滅の刃 柱稽古編',
        'animations/525/images/7f473e55-3e34-4919-a21a-5454d312e1eb.webp',
        '柱稽古へ―― 鬼殺隊最強の剣士《柱》と鬼殺隊士たち。 来たる鬼舞辻󠄀無惨との決戦に向け、《柱稽古》開幕。 それぞれの想いを胸に、炭治郎と柱たちの新たなる物語が幕を開ける。',
        5, 0, 0, 0, '2024-05-12'),
       (526, 32, '僕のヒーローアカデミア 第7期',
        'animations/526/images/1932e58f-6ef4-4cb4-aa42-7b42c874ea55.webp',
        '超常能力“個性”を持つ人間が当たり前の世界。憧れのNo.1ヒーロー・オールマイトと出会った“無個性”の少年・緑谷出久、通称「デク」は、その内に秘めるヒーローの資質を見出され、オールマイトから“個性”ワン・フォー・オール（OFA）を受け継いだ。デクはヒーロー輩出の名門・雄英高校に入学し、“個性”で社会や人々を救ける“ヒーロー”になることを目指し、ヒーロー科1年A組のクラスメイトたちと共に成長していく。 デクたちの雄英2年目の春。ヒーローたちが死柄木たち敵＜ヴィラン＞の掃討作戦を決行し、まさに“全面戦争”と言える激闘が繰り広げられる。双方が大きなダメージを受け全面戦争は一旦の終結を見るが、ヒーローへの信頼は揺らぎ、社会は荒廃していく。オール・フォー・ワン（AFO）が狙うOFAの継承者としての使命感と、周囲の人間を危険に晒したくないという思いから、ひとり雄英を出て戦うデク。焦燥し疲弊していく彼に手を差し伸べたのは、1年A組のクラスメイトたちだった。ひとりじゃなく、皆で立ち向かう決意を新たにした雄英生とヒーローたち。ヒーロー殲滅のため次なる一手を狙う死柄木弔やAFOら敵＜ヴィラン＞。いよいよ“最終決戦”の時が近づく。そして、アメリカからもひとりのヒーローが飛来する…。 果たしてデクたちは、皆が笑顔になれるあの日々を取り戻すことはできるのか―。',
        NULL, 0, 0, 0, '2024-05-04'),
       (527, 25, '怪獣８号', 'animations/527/images/762607c0-3d14-4a75-bf5f-5ee75de04a43.webp',
        '日常的に怪獣が人々をおびやかす世界。 怪獣を討伐する「日本防衛隊」への入隊を志していた日比野カフカは、いつしかその夢を諦め、怪獣専門清掃業で働いていた。 「二人で怪獣を全滅させよう」 かつてそう誓い合った幼なじみの第３部隊隊長・亜白ミナの活躍と、防衛隊を目指す後輩・市川レノとの出会いをきっかけに再び夢を追い始めるカフカ。 しかしその矢先、謎の小型怪獣によって巨大な力をもつ“怪獣に変身”してしまう！ 『怪獣8号』と名付けられ日本中から追われる存在になったカフカは、それでも防衛隊員への夢を諦めず、怪獣災害に立ち向かうのだった――。',
        NULL, 0, 0, 0, '2024-04-13'),
       (528, 38, '忘却バッテリー',
        'animations/528/images/08389750-33b8-4fe3-a3c1-d9e9d5446421.webp',
        '中学球界で名を馳せた完全無欠の剛腕投手・清峰葉流火、切れ者捕手の“智将”・要圭の怪物バッテリー。全国の強豪校からスカウトを受けていた彼らが進学したのは何故か野球無名校の東京都立小手指高校だった。さらに圭は記憶喪失で野球に関する知識も失っていた。 そしてかつて彼らに敗れ散り野球から遠ざかっていた天才たちも、偶然同じ高校に入学しており…。 巡り合い、再び動き出す 彼らの高校野球ストーリーが いま始まる―！',
        1, 0, 0, 0, '2024-04-09'),
       (529, 166, '無職転生 II ～異世界行ったら本気だす～ 第2クール',
        'animations/529/images/9ce912bd-97a6-4952-b276-04fa72fac395.webp',
        '34歳・無職・引きこもりの男は、ある日家族から家を追い出された際に交通事故に遭い死亡…と思った瞬間、剣と魔法の異世界でルーデウスとして転生。前世での経験と後悔を糧に、今度こそ本気で生きていこうと誓う。 ある日転移事件により魔大陸に飛ばされ、故郷に戻るため過酷な旅を続けたルーデウス。故郷に辿り着くもエリスとの別れでまた独りとなり絶望するが、行方不明の母・ゼニスを探すために再び歩み始める。 冒険者として名を馳せる中、その卓越した魔術によってルーデウスはラノア魔法大学から特待生として迎えられる。その大学には、フィッツと名前を変えた幼馴染・シルフィの姿があった。ルーデウスは“フィッツ”として振る舞う彼女に気づかないまま交流を深め、そして惹かれていく。その後、意を決したシルフィも自身の素性を打ち明け、二人は結ばれる。婚約したルーデウスとシルフィは新生活を始めるのだが、その新宅にはとある来訪者たちが…。 立ち上がった先で大切なものをつかんだルーデウス。前世で家族に追い出された男が、異世界で新たな家族を作っていく。その物語の中で、巻き起こる事件とは―。そして母ゼニスの行方は―。',
        4, 0, 0, 0, '2024-04-07'),
       (530, 55, '転生したらスライムだった件 第3期',
        'animations/530/images/c821e469-365a-4e7c-bd6e-a87cb6223f57.webp',
        'クレイマンを倒し、正式に魔王となったリムル。魔王たちの宴（ワルプルギス）を経て、リムルの支配地域はジュラの大森林全体に広がった。その影響で各種族の代表が挨拶しに殺到することが予想されならばいっそのこと魔王リムルのお披露目と、テンペストの新規住民獲得も兼ねた「開国祭」の開催を思いつく。一方、魔物を敵視するルミナス教の総本山・神聖法皇国ルベリオスでは、聖騎士団長・ヒナタがリムルのメッセージを受け取る。しかしそれは、何者かによって改竄された宣戦布告だった。テンペストにヒナタが向かっていると報告を受けたリムルの決断はーー。真の敵と味方を見極め「人魔共栄圏」という理想を追い求める、リムルの新たな挑戦が始まる。',
        4, 0, 0, 0, '2024-04-05'),
       (531, 274, '転生したら第七王子だったので、気ままに魔術を極めます 第1期',
        'animations/531/images/67b28f2c-0d76-4cd3-bc1f-4043966fcc08.webp',
        '魔術に大切なものは、“家柄“・”才能“・”努力“……。\n魔術を深く愛しながらも、血筋と才能に恵まれずに非業の死を遂げた“凡人“の魔術師。\n死の間際に「もっと魔術を極め、学びたかった」と念じた男が転生したのは、\n強い魔術の血統を持つサルーム王国の第七王子・ロイドだった。\n過去の記憶はそのままに、完璧な血筋と才能を備えながら生まれ変わった彼は、前世では成しえなかった想いを胸に、\n桁外れの魔力で“気ままに魔術を極める“無双ライフをエンジョイする！\nライトノベルを原作とし、マンガアプリ「マガジンポケット」（講談社）で連載を開始したコミカライズは\nアプリ内セールスランキング１位を記録し、シリーズ累計発行部数は 430 万部を突破！\nいま最も注目される“転生異世界ファンタジー“が満を持してアニメ化！\n舞台となるのは獣や魔人が巣食う異世界。\n本作では魔術に通じる者たちが恐れを成すほどの絶大な魔力を持つロイドが、\n自身の興味の赴くままに魔術を学び、極めようと成長する姿が描かれていく。\nちょっぴりお気楽だけど、強大な力で圧倒していく魔術バトルの爽快感と迫力が詰まった、\n“第七王子“による気ままな転生物語が今はじまる！',
        1, 0, 0, 0, '2024-04-01'),
       (532, 58, 'WIND BREAKER', 'animations/532/images/62309577-694f-475c-a99b-eb409a91952d.webp',
        '人を傷つける者、物を壊す者、悪意を持ち込む者 何人も例外なくボウフウリンが粛清する――︕ 偏差値は最底辺、ケンカは最強。超不良校として名高い、風鈴（ふうりん）高校。 その「てっぺん」を獲るため、街の“外”からやってきた高校1年生・桜遥。 しかし、現在の風鈴高校は“防風鈴（ボウフウリン）”と名付けられ街を守る集団となっていた。 仲間や街の人々との触れ合いを通して、少しずつ「てっぺん」のあり方が変わり始めた桜。 新たな仲間、新たな敵との出会い―― 級長として“守るために闘う”桜の英雄伝説、次なるステージへ！',
        1, 0, 0, 0, '2024-04-04'),
       (533, 144, '声優ラジオのウラオモテ',
        'animations/533/images/971182f7-4d2f-478e-91d1-2abd04234ed3.webp',
        '「この番組は、偶然にも同じ高校、同じクラスのわたしたちふたりが、\n皆さまに教室の空気をお届けするラジオ番組です！」\n声優としてもクラスメイトとしても、\nと〜っても仲良しなふたりのほんわか声優ラジオがスタート\n……というのは「オモテ」の話。\n夕陽の素顔は根暗な地味子、対するやすみは生粋のギャル。\n見た目も性格も正反対なふたりは、口を開けば大ゲンカ。\n「……何その眩しさ。本当びっくりするくらい普段とキャラが違うな、\nいつもの根暗はどうしたよ？」\n「あなたこそ、その見た目で可愛い声を出すのはやめて」\n収録が終わればそこは修羅場、嫌味と罵りの嵐が吹き荒れる！\nこんなやつと一緒にラジオなんて、絶対に無理！\nでも、オンエアは待ってくれない……！\n前途多難な声優ラジオ、どこまで続く……！？\nプロ根性で世界をダマせ！バレたら終わりの青春声優エンタテインメント、NOW ON AIR!',
        NULL, 0, 0, 0, '2024-04-10'),
       (534, 252, '時光代理人 -LINK CLICK- Ⅱ',
        'animations/534/images/018c1b00-1d87-43c5-8ad0-8c20be54c846.webp',
        '繁華街の一角に佇む「時光写真館」を経営するトキ（程小時）とヒカル（陸光）。 「撮影者の意識にリンクし、写真の世界に入ることができる能力」を持つトキと、「その写真の撮影後12時間の出来事を把握できる能力」を持つヒカルはコンビを組み、トキの幼馴染・リン（喬苓）を通じて舞い込む顧客からの依頼を解決していた。 事件に関わるなか、トキとヒカルは一連の出来事の裏に「未知の能力」を持つ人物がいることに気付く。 暗躍する能力者に翻弄されながらも、謎の人物から渡された1枚の写真を手掛かりに真相を探っていくト キたち。 そこには、数年前に起きたある事件が深く結びついていて――。',
        2, 0, 0, 0, '2024-04-10'),
       (535, 190, '花野井くんと恋の病',
        'animations/535/images/f7cdc18b-25ca-4d90-8979-0a20df1319cd.webp',
        '家族や友人に恵まれているけど、 恋愛とはちょっぴり縁遠かった高校1年生・日生ほたる。 彼女は、ある日、 隣のクラスのイケメン・花野井くんがフラれる現場を見てしまう。 公園でひとりポツンとたたずんでいた花野井くんを見て、 何気なく傘を差しだしたほたる。 その小さな出来事がきっかけで、 後日「僕と付き合ってください」と花野井くんから公開告白されてしまった。 “好き”って何？ “恋する”ってどういうこと？ 突然の告白に戸惑うほたると、 “好きな子”のためなら、何でもしたい。 注ぐ愛情が無限大な花野井くん。 恋がわからない女子×愛が重すぎる男子の初恋ラブストーリー。',
        NULL, 0, 0, 0, '2024-04-04'),
       (536, 19, 'ガールズバンドクライ',
        'animations/536/images/7bddc2b1-d0a8-4bf9-9ed4-7a1a64e14181.webp',
        '高校2年、学校を中退して単身東京で働きながら大学を目指すことになった主人公。 仲間に裏切られてどうしていいか分からない少女。 両親に捨てられて、大都会で一人バイトで食いつないでいる女の子。 この世界はいつも私たちを裏切るけど。\n何一つ思い通りにいかないけど。\nでも、私たちは何かを好きでいたいから。 自分の居場所がどこかにあると信じているから。\nだから、歌う。',
        NULL, 0, 0, 0, '2024-04-05'),
       (537, 55, 'ゆるキャン△ SEASON3',
        'animations/537/images/3b623c3f-8686-4963-afb5-2c700b32ce66.webp',
        'これは、冬と春の間の物語。\n伊豆でグループキャンプを楽しんだ、なでしこ、リン、千明、あおい、恵那。\nその後もキャンプ熱が高いままの五人は、山梨や静岡で、それぞれのアウトドアを楽しんでいく。\nリンは、なでしこの幼なじみ・土岐綾乃と大井川周辺をツーリングキャンプ。\nなでしこは、ツーリング中のリンたちと合流するために、電車で一人旅。\n千明、あおい、恵那は、突発で山梨北部へバスキャンプに出かけていく。\n五人は各地でこれまでの経験を活かしながら、時にはノリと勢いでピンチを乗り越えて、思い思いのキャンプを満喫。\nそんな「たのしい、更新中」の、なでしこたちが紡ぐ、アウトドア系ガールズストーリーの新しい幕が上がる。',
        3, 0, 0, 0, '2024-04-04'),
       (538, 136, 'この素晴らしい世界に祝福を！3',
        'animations/538/images/957d34db-b74f-478b-bead-716002be0f23.webp',
        '交通事故（!?）によりあっけなく人生の幕を閉じるはずだったゲームを愛するひきこもり・佐藤和真（カズマ）は、ひょんなことから異世界に転生する。あこがれのRPG生活を満喫するつもりだったのに、トラブルメーカーの駄女神・アクア、中二病をこじらせた魔法使い・めぐみん、妄想ノンストップな女騎士・ダクネスという、能力だけは高いのにとんでもなく残念な３人とパーティを組むことになって、異世界ライフはトラブル続き。たまに魔王軍幹部を討伐することもあるけれど、借金やら国家転覆罪の容疑やらに追われる冒険者生活を送っていた。そんなある日、紅魔の里から帰還したカズマたちのもとに、手紙が届く。その内容は、王女アイリスが、魔王軍幹部を倒したカズマ達の冒険譚を聞きたいというもの。護衛兼教育係のクレアとレインを伴い、アクセルの街を訪れた王女アイリスは、カズマ達との対面を穏やかに終えたと思いきや―――',
        3, 0, 0, 0, '2024-04-10'),
       (539, 157, '戦隊大失格', 'animations/539/images/7c1a7c32-fee3-4b35-8e6a-c13fab172266.webp',
        '13 年前、突如始まった怪人と大戦隊との存亡をかけた戦い。だがこの戦い、実は茶番劇？！\nとうの昔にアジトは陥落、怪人幹部も全滅、残った下っ端戦闘員ダスターズは、大戦隊と結ばされた秘密の協定＜毎週末、地上侵攻し敗れ散る＞を繰りかえす日々。この敗け続けの人生に、やさぐれた戦闘員 D は遂に立ち上がる！',
        1, 0, 0, 0, '2024-04-07'),
       (540, 198, '転生貴族、鑑定スキルで成り上がる 第1期',
        'animations/540/images/5cc20d17-2845-4f72-b8f0-1dffa4d412f4.webp',
        '異世界に転生した主人公アルス・ローベントは、小さな領地を持つ弱小貴族の子として生きることになった。\nアルスには特別な知力や武力はないが、生まれながらにして他人の能力・ステータスを見抜く“鑑定スキル”を手にしていた。\nそのスキルを活かして世に隠れた「逸材」を発掘し、弱小領地から最強の領地へと変貌させていく。\n心優しいアルスと、個性豊かな逸材たちの出会いと成長を描く異世界統一記が今、始まる！',
        1, 0, 0, 0, '2024-04-07'),
       (541, 30,
        '魔王学院の不適合者 Ⅱ ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～ 第2クール',
        'animations/541/images/3c6a297e-f910-4631-a860-a6aeaec3dd25.webp',
        '平和をもたらした暴虐の魔王は、\n地底に広がる未知の世界で行われる神の代行者を選ぶ戦い《選定審判》に巻き込まれていく。\nそれは、あらゆる理不尽をものともしない《不適合者》の失われた記憶を辿る物語。\nそして過去は世界の理へ導かれる——。\n「神ごときの力が魔王を上回るとでも思ったか」',
        3, 0, 0, 0, '2024-04-12'),
       (542, 69, 'ザ・ファブル', 'animations/542/images/ee985134-bd98-403c-8c09-c468980a1565.webp',
        '最強の天才殺し屋...でも殺してはいけない?\n幼少期から殺し屋としての英才教育を受け、 どんな敵も 6 秒以内に鮮やかに葬り去る、 無敵の殺しの天才・通称“ファブル”。 ある日、組織のボスから\n「1 年間誰も殺してはならない」 という突然の指令を受けた彼は、 人殺しをしない全く新しい生活を送ることになる。\n佐藤明と名乗り、プロとして初めて過ごす普通の生活。\nしかし、平穏な日常の中に蠢く、不穏な空気が明を放っては置かない...。 果たして、この最大にして至難のミッションを遂行することはできるのか!?\n寓話と呼ばれし無敵の殺し屋“ファブル”の、 カッコよく、滑稽で、 そして少し風変わりな 1 年間の殺し屋休業生活が始まる!',
        NULL, 0, 0, 0, '2024-04-06'),
       (543, 30, '夜桜さんちの大作戦 第1期',
        'animations/543/images/d058e210-ccc9-4daa-913a-6c1c3d28b8b8.webp',
        'この家族、普通じゃない！？ 家族を事故で亡くし、心を閉ざすようになった高校生・朝野太陽。 クラスメイトからの印象は「超・人見知り」。 唯一、話せるのは幼なじみの夜桜六美、ただ一人だった。 けれど六美にはあるヒミツが！？ 彼女の正体は代々続くスパイ一家当主で、様々な敵から命を狙われていたのだ！ しかも彼女の兄・凶一郎は最凶のスパイで、異常なほど六美を溺愛していた。 太陽は、そんな凶一郎から「排除」ターゲットとして命を狙われることに…！ 六美と自分の命を守るため、太陽のとった手段とは… 六美と結婚して夜桜家に婿入りすること！？ 太陽、六美、そして夜桜さんちの家族を巡る前代未聞の「大作戦」から目が離せない！！',
        1, 0, 0, 0, '2024-04-07'),
       (544, 107, 'ささやくように恋を唄う',
        'animations/544/images/813f279b-b3c6-4bd8-a429-22186834f354.webp',
        '高校入学初日、新入生歓迎会でのバンド「SSGIRLS」の演奏を見た新入生の木野ひまりは、ギターボーカルを務めていた朝凪依に憧れ、彼女に‟ひとめぼれ”をする。\nその気持ちを伝えられた依は、ひまりに‟ひとめぼれ”という名の恋心を抱くことに。\n憧れと恋心。同じ‟好き”でも異なる気持ち。\nすれ違うふたりの関係に、バンドメンバーの想いも絡み合い…。\nふたりの‟ひとめぼれ”は、やがて鮮やかな青春を奏で始める——',
        NULL, 0, 0, 0, '2024-04-13'),
       (545, 50, '響け！ユーフォニアム３',
        'animations/545/images/1a4ff7a5-cb13-45d3-80c4-10a267d4e6ba.webp',
        '総勢90名を超える北宇治高校吹奏楽部。 部長に就任した黄前久美子は、悲願の全国大会金賞に向けて、高校生活最後の部活動を駆け抜ける！ 2024年春――そして、次の曲が始まるのです！',
        3, 0, 0, 0, '2024-04-07'),
       (546, 37, '夜のクラゲは泳げない',
        'animations/546/images/436c2177-8171-4ce4-be42-093f18af63a4.webp',
        '“私”も誰かみたいに輝きたい。 明日話すべき話題も、今週買うべき洋服も、 全部スマホ（トレンド）が教えてくれる。 何者かになってみたい――そんな願いを持つ間もないほどこの世界は忙しい。 活動休止中のイラストレーター“海月ヨル” 歌で見返したい元・アイドル“橘ののか” 自称・最強Vtuber“竜ヶ崎ノクス” 推しを支えたい謎の作曲家“木村ちゃん” 世界から少しだけはみ出した少女たちは匿名アーティスト“JELEE”を結成する。 自分じゃない“私たち”なら――輝けるかもしれない。',
        NULL, 0, 0, 0, '2024-04-06'),
       (547, 16, 'SAND LAND: THE SERIES',
        'animations/547/images/74100130-0263-451a-adf3-f3a47936793d.webp',
        '魔物も人間も、深刻な水不足にあえぐ砂漠の国・サンドランド。国民は国王が販売する高価な水だけを頼りに生活をしていた。正義感に溢れる人間の保安官・ラオは「幻の泉」を探す旅に出ることを決意し、魔物たちに協力を依頼する。悪魔の王・サタンの息子ベルゼブブはラオとお目付け役の魔物・シーフと共に「幻の泉」を求め旅へと向かう。「夜更かししたあげく歯を磨かずに寝てやった」と自分のワルぶりをアピールする子どもっぽさもありながら、襲いくる敵をなぎ払う戦闘力を持つベルゼブブ。村の保安官として人望があり、魔物たちにも紳士的に接する人格者のラオ。そして実はベルゼブブとあまり年齢が変わらないにも関わらず見た目と話し方で老人扱いされている、盗みが得意なシーフ。やがて、ベルゼブブたちとの旅を通してラオは、魔物が「人間の敵」ではないことに気づいていく。\nスターオリジナルシリーズ『SAND LAND: THE SERIES』ディズニープラス「スター」で3月20日(水)より世界独占配信',
        NULL, 0, 0, 0, '2024-03-20'),
       (548, 75, '狼と香辛料 MERCHANT MEETS THE WISE WOLF',
        'animations/548/images/fa33e271-aff1-41f7-b33c-7d26135e0b39.webp',
        '若き行商人クラフト・ロレンスは、荷馬車を引く一頭の馬を相棒に、街から街へと商品を売り歩く日々を送っていた。\nある日、黄金色の麦畑が広がる小さな村を訪れた彼は、耳と尻尾を有する美しい少女と出会う。\n「わっちの名前はホロ」\n自身を“賢狼”と呼ぶホロは、豊穣を司る狼の化身だった――。\n彼女の「遠く北にあるはずの故郷・ヨイツの森へ帰りたい」という望みを聞き、\nロレンスとホロは北を目指す商売の旅の道連れとなる。\nだが行商人の旅には思いがけない波乱がつきもので……。\n孤独だった行商人と、孤独だった狼の化身を乗せた馬車が、今、騒がしく走り始める。',
        1, 0, 0, 0, '2024-04-01'),
       (549, 58, '黒執事 -寄宿学校編-',
        'animations/549/images/0b168611-35c5-405f-a017-29a55924d743.webp',
        '19世紀英国―― 名門貴族ファントムハイヴ家の執事セバスチャン・ミカエリスは13歳の主人シエル・ファントムハイヴとともに“女王の番犬”として裏社会の汚れ仕事を請け負っていた。 ある日、シエルの元に女王から、英国屈指の名門寄宿学校・ウェストン校に通う親族・デリックほか複数人の生徒が音信不通になっているという手紙が届く。 かくしてセバスチャンとシエルは、事件を調査するためにウェストン校に潜入する。 事件の真相とは…？',
        NULL, 0, 0, 0, '2024-04-13'),
       (550, 255, 'バーテンダー 神のグラス',
        'animations/550/images/2ed7dfa4-d739-4598-9193-8c7287a03eee.webp',
        'バーテンダー・佐々倉溜は六本木で修行後に単身フランスへ渡り、ヨーロッパのカクテルコンテストにて優勝。 それ以降、彼が作るカクテルは「神のグラス」と呼ばれるようになる。 パリの一流ホテルにてチーフバーテンダーを務めていた溜だったが、理由は不明ながら日本に帰国し、プライベート・バー“イーデンホール”で働き始める。 バーにやってくるお客さんの様々な悩みや問題に対して、特別な一杯を提供する溜。 一方、東京に開業したホテル・カーディナルでは、オーナーの来島泰三がカウンターバーに立つバーテンダーの人選に拘り、相応しいバーテンダーが見つからずカウンターバーをオープン出来ずにいる。 泰三の孫・美和を含む営業企画部のメンバーはバーテンダー探しに奔走。 佐々倉に出会い、彼こそが相応しいとスカウトするが、はぐらかされてばかり・・・。 はたして、カーディナルのカウンターバーはオープンできるのか、溜の決断とは・・・。',
        NULL, 0, 0, 0, '2024-04-03'),
       (551, 55, '魔法科高校の劣等生 第3シーズン',
        'animations/551/images/0b2a4a1e-953b-46eb-a864-45ccf3cb219d.webp',
        '魔法。 それが現実の技術として確立されてから約一世紀が過ぎていた。 国立魔法大学附属第一高校、通称“第一高校”にとある兄妹が入学する。 魔法師として致命的な欠陥を抱える劣等生の兄・達也。 すべてが完全無欠な優等生の妹・深雪。 二人の学生生活は激動に次ぐ激動の日々だった。 政治結社《ブランシュ》の襲撃。 九校戦への香港系国際犯罪シンジケート《無頭竜ノー・ヘッド・ドラゴン》の介入。 大亜連合軍の横浜への侵攻。 人の精神に取り憑いて変質させる魔物パラサイトの出現。 そしてUSNA軍魔法師部隊スターズ総隊長アンジー・シリウスことアンジェリーナ=クドウ=シールズの来訪。 波乱に満ちた一年が終わり、二年生になった二人の生活も少しずつ変化する。 四葉家から使わされた桜井水波が達也たちと同居することになり、 達也は新設された魔法工学科、通称《魔工科》に転科する。 深雪と共に平穏な学園生活を送るはずだったが それを世界が許すはずもなく…。 そして、──波乱の日々が、再び幕開く。',
        4, 0, 0, 0, '2024-04-05'),
       (552, 17, 'Lv2からチートだった元勇者候補のまったり異世界ライフ',
        'animations/552/images/e44b8bd7-668b-49f2-8983-cf27887656c3.webp',
        '商人として日々働いていたバナザは、突然クライロード魔法国という見たことも聞いたこともない異世界に「勇者候補」として召喚される。 だが、Lv1の能力が一般市民並みだったことで勇者失格の烙印を押され、さらには国の手違いで元の世界に戻れなくなってしまう……。 王都から辺境へ追放されたバナザが、なんとか生き延びるべく森で襲い掛かってきたスライムを撃退、Lvを2に上げると 彼のステータスは見慣れない「∞」の記号に変わっていて──！？ これは、名前と姿を変えて異世界で生きることを選んだ「超越者」と、敵対する人種族に恋した「魔族」との波乱万丈な新婚ストーリー。 あらゆる種族を巻き込んで──目指せ、平和なスローライフ！',
        NULL, 0, 0, 0, '2024-04-08'),
       (553, 36, '魔王の俺が奴隷エルフを嫁にしたんだが、どう愛でればいい？',
        'animations/553/images/03b8df94-345a-44b3-85f1-41ab65b89511.webp',
        '悪の魔術師として人々に恐れられているザガン。 不器用で口の悪い彼は、今日も魔術の研究をしながら領内の賊をぶちのめしていた。 ザガンは、悪友のバルバロスに誘われて参加した闇のオークション会場で、魔王の遺品として出品された白い髪のエルフの少女ネフィと運命的な出会いを果たす。 全財産をはたいて、ネフィを自身の城へ連れ帰ったが、 これまで人付き合いをすることのなかった口下手なザガンは、ネフィにどう接していいかわからないまま、まともな会話も出来ず狼狽えるばかり。 これからはじまる二人の共同生活の行方は如何に―。 口下手な魔術師と美少女エルフのじわキュンラブコメディ。',
        NULL, 0, 0, 0, '2024-04-04'),
       (554, 154, 'ワンルーム、日当たり普通、天使つき。',
        'animations/554/images/5f6a6b88-9ed1-4879-9947-1c3b1d45b3a2.webp',
        '高校1年生になり、一人暮らしを始めた徳光森太郎。ある日、ベランダを覗くと清楚で可憐な女の子「とわ」が眠っていた。\nどこか天然だけど、間違いなくいい子な彼女。その正体は――「天使」だった。\n行くあてもないとわと始める、とっても甘くて、とってもピュアなワンルーム生活。森太郎は、無垢な天使と少しずつ心を通わせていくけれど……。さらなるワケあり少女が次々と現れて!?\n天使と高1男子が織りなす癒やされ同居ラブコメ、開幕！',
        NULL, 0, 0, 0, '2024-04-06'),
       (555, 22, 'ひみつのアイプリ',
        'animations/555/images/04a23c38-bcab-41c3-86fe-7a843a71e51b.webp',
        'ひみつの扉を開いたら、メイクにネイル、キラキラコーデにオシャレして、ひみつのわたしに大変身！ それがアイドルプリンセス『アイプリ』！ さぁ、みんなもひみつの世界に飛び込めば、アイプリになれちゃうかも！？ 私立パラダイス学園に入学した主人公・青空ひまりと星川みつき。 アイプリに憧れるひまりの夢は、おともだちを1万人つくること！ でも人見知りでキンチョーしぃのひまりには、ちょっとむずかしいかも…… 。 そんなひまりが思いがけずアイプリデビューすることに！？ 親友のみつきにも言えない『ひみつ』ができちゃった！ だけど、みつきにもなにやら『ひみつ』があるようで…… 。 ひみつを抱えたひまりとみつき、2人のアイプリがはじまります！！',
        NULL, 0, 0, 0, '2024-04-07'),
       (556, 32, 'T・Pぼん', 'animations/556/images/6b083402-5e98-4e2c-b541-d707fe692c95.webp',
        'なにもかもが平凡な中学生の並平凡は、未来からやってきたT・P（タイムパトロール）隊員の少女リーム・ストリーム、不思議な生き物ブヨヨンと出会う。歴史に影響しない、不幸な死を迎えてしまった人間を救う活動をしているというT・P隊員。任務を遂行する中でリームたちを見た人間の記憶は消されることになっているが、とあることから記憶が消えされなかった凡は、やむをえずタイムパトロールの見習い隊員として迎えられる。リームとバディを組んで任務を遂行していくことになった凡は、時代も場所もひとっ飛びできるタイムボートをはじめとする未来の道具に大興奮。お調子者の凡だが任務を通じ、それぞれの時代で賢明に生きる人たちの人生に触れていくことになる。『T・Pぼん』と一緒に、地球と人類の壮大な歴史を旅しよう！\nNetflix シリーズ「T・P ぼん」シーズン 1：5 月 2 日（木）、シーズン 2：7 月 17 日（水）世界独占配信',
        1, 0, 0, 0, '2024-05-02'),
       (557, 72, '終末トレインどこへいく？',
        'animations/557/images/4631a3a1-5fb9-40e2-b344-aa7a7882dd73.webp',
        '郊外のとある町。\nここはどこにでもある、ごくごくありふれた田舎……ではなかった。\n住民たちに大きな異変が起きているのだ。\nだけどそんな中でも千倉静留には、強い思いがあった。\n行方がわからない友達に、もう一度会いたい！\n静留たちは放置されて動かなくなっていた電車で、\n生きて帰ってこられるかどうかもわからない外の世界へと出ていく。\n走り出した終末トレインの終点には、いったい何がある？',
        NULL, 0, 0, 0, '2024-04-01'),
       (558, 99, 'Unnamed Memory Act.1',
        'animations/558/images/8a9628c3-a501-4338-a683-3bb3b8bf82bd.webp',
        '絶大な力を操る五人の魔女が、人々にとって畏怖の象徴となっていた時代――。 大国ファルサスの王太子・オスカーは、幼い頃に受けた「子孫を残せない呪い」を解呪するため、荒野の塔に棲む“青き月の魔女”ティナーシャのもとを訪れる。 どんな望みも叶えるという“魔女の塔”の試練を乗り越えたオスカーが望んだのはティナーシャを妻として迎えることで……。 魔女の契約者となった王太子と、王太子の守護者となった魔女。 二人の出会いは“魔女の時代”に変革をもたらし、やがて、世界の〈運命〉を書き換えることになる。 オスカーとティナーシャの行く手に待ち受ける物語とは――。',
        1, 0, 0, 0, '2024-04-09'),
       (559, 157, 'ブルーアーカイブ The Animation',
        'animations/559/images/4ed5e55c-4b2a-4165-9d15-8700a959ed60.webp',
        '――ここが、私たちの居場所だから―― 数千を超える学校で形成された巨大な学園都市「キヴォトス」。 ここでは銃を手にした生徒たちの諍いが、日常的な風景になっている。 その中で、砂に包まれた「アビドス高等学校」は廃校の危機に瀕していた。 状況を脱すべく奮闘する「対策委員会」の5人の生徒が、「先生」と呼ばれる“大人”と出会い、物語は動き始める。 生徒と青春、学園と銃。彼女たちが目指す未来は――',
        NULL, 0, 0, 0, '2024-04-07'),
       (560, 53, 'グリム組曲', 'animations/560/images/5e267fa3-512c-41a8-a40d-7a7b0fbb8e8a.webp',
        '長きにわたり読み継がれてきたグリム童話に着想を得た、6つの物語からなるアンソロジー。ダークなアレンジを加えたおとぎ話を通して、人間の欲望がもつ陰の一面が暴かれる。\nNetflix シリーズ「グリム組曲」4 月 17 日（水）より世界独占配信',
        NULL, 0, 0, 0, '2024-04-17'),
       (561, 42, '変人のサラダボウル',
        'animations/561/images/dd49b1a1-4290-45c7-85b2-f3a73b8579dd.webp',
        '貧乏探偵、鏑矢惣助が尾行中に出逢ったのは、魔術を操る異世界の皇女サラだった。 なし崩し的にサラとの同居生活を始める惣助だが、サラはあっという間に現代日本に馴染んでいく。 一方、サラに続いて転移してきた女騎士リヴィアは、ホームレスに身をやつしながらも意外と楽しい日々を送る。 前向きにたくましく生きる二人の異世界人の姿は、惣助のほか、鬼畜弁護士、別れさせ工作員、宗教家といったこの地に生きる変わり者達にも影響を与えていき――。 平坂読×カントクコンビがこの時代に放つ、天下無双の群像喜劇、堂々アニメ化！',
        NULL, 0, 0, 0, '2024-04-04'),
       (562, NULL, 'X-Men ''97', 'animations/562/images/37e2230f-b337-4d69-a3d5-fdf8b643be85.webp',
        '3月20日(水)よりディズニープラスにて独占配信開始', NULL, 0, 0, 0, '2024-03-20'),
       (563, 128, 'デート・ア・ライブⅤ',
        'animations/563/images/01efe260-d596-40a1-8e7d-fc555963ac84.webp',
        '人間の少女の姿をしながらも、人間とは異なる存在―― 精霊。\n強大な能力をもち、隣界から顕現する際に〈空間震〉と呼ばれる災害を発生させる彼女たちは、人類の天敵とさえ呼ばれている。\nそんな精霊の脅威に対して人類がとりうる手段は、武力をもって殲滅する、もしくは――\n『デートして、デレさせる』！\n五河士道は、精霊をデレされてキスをすることで、力を封印できる能力のもち主。\nその力で人類を、そして精霊たちを救ってきた彼をめぐって、大きな波乱が迫ろうとしていた。\n世界有数の巨大企業にして精霊の力を狙うDEMインダストリーが、士道の命を奪うべく総力をあげて襲い来る。\nそして士道の記憶の奥にいた謎の少女がその正体を現し――。\nいくつもの思惑が交錯する、過去最大の戦いが始まる。',
        5, 0, 0, 0, '2024-04-10'),
       (564, 17, '死神坊ちゃんと黒メイド 第3期',
        'animations/564/images/a74a4476-fca7-422c-9ee4-d9faa83f3970.webp',
        '「触れたもの全てを死なせてしまう」 ……そんな恐ろしい呪いを魔女にかけられた、貴族の少年「坊ちゃん」。 それでも彼の周りには、昔から共に暮らすメイドのアリスや執事のロブ、魔女の友人のザインとカフ、憎まれ口を叩きながらも会いに来てくれる妹のヴィオラや弟のウォルター ……かけがえのない仲間たちがいた。 彼らとともに呪いを解く術を探す中で、坊ちゃんはついに全ての元凶である魔女、シャーデーと再会する。 ……そして時を同じくしてアリスの母・シャロンが永き眠りから目覚める……。 全ての因縁が収束し、触りたいけど触れない坊ちゃんとアリスの物語はいよいよ完結へ！',
        3, 0, 0, 0, '2024-04-07'),
       (565, 195, 'ヴァンパイア男子寮',
        'animations/565/images/1968a6c2-a0cc-49e9-a141-a91c7f3162f5.webp',
        '親を亡くし、親戚にも見放された天涯孤独な美人（みと）は、男装して働いていた店を追い出され、お金も住むところもなく困っていたところを、吸血鬼のルカにひろわれる。 美人は、自分の血をルカの“エサ”にすることを条件に、個性豊かなイケメンたちが生活する男子寮で“女”であることを隠したまま、キケンな同居生活を始めることになってしまい…！？',
        NULL, 0, 0, 0, '2024-04-07'),
       (566, 103, '当て馬キャラのくせして、スパダリ王子に寵愛されています。',
        'animations/566/images/2a487e5c-bf5f-4338-ba3a-e36e4a1fea05.webp',
        '「ずっと…君に触れたかった」――\nスパダリ王子の寵愛相手は、当て馬キャラの…俺!?\n当て馬とは――物語の主役の恋路を阻む「お邪魔キャラ」。\n小説の世界に転生したロニールは、ヒロインとの恋を邪魔して断罪をされないよう、ヒーローの王子アレクを必死に避けていたのに…なんと王子は俺に夢中で!?\n「ウブなのに感じやすい、なんて愛らしい身体だ…」\n拒む間もないまま、トロトロにされちゃって――なんで小説と違うんですか!?',
        NULL, 0, 0, 0, '2024-04-07'),
       (567, 27, '烏は主を選ばない',
        'animations/567/images/ea28ac83-3dbe-4b48-b89e-0868f39479fa.webp',
        '原作は、阿部智里による人気ファンタジー小説「八咫烏（やたがらす）シリーズ」。人の姿をした八咫烏の一族が支配する異世界・山内（やまうち）を舞台にした和風大河ファンタジー。美しくも風変わりな若宮の側仕えに抜擢された少年・雪哉（ゆきや）。陰謀渦巻く宮中でさまざまな事件に遭遇するなかで、若宮と奇妙な主従関係を結んでいく。',
        NULL, 0, 0, 0, '2024-04-06'),
       (568, 154, '喧嘩独学', 'animations/568/images/577794fc-fb3e-44c8-b475-4411c2f2c078.webp',
        '母親の入院費を稼ぐため貧乏生活を送る、スクールカースト最底辺の高校生・志村光太。 学校では不良のハマケンからゴミのように扱われ、負け組人生に日々絶望していた。 そんなある日、クラスメイトのカネゴンと殴り合う様子が誤って全世界へ生配信！？ 底辺同士のイタすぎる喧嘩動画は瞬く間に広がり、一晩でまさかの1000万再生を突破！！！ 再生数が金になることを知った光太が噛みつく相手は不良に、ヤンキーに、プロ格闘家とエスカレートしていき… プロのいじめられっ子、反撃開始───ッ！！！',
        NULL, 0, 0, 0, '2024-04-10'),
       (569, 18, '出来損ないと呼ばれた元英雄は、実家から追放されたので好き勝手に生きることにした',
        'animations/569/images/44fa3a20-47ca-4d8a-8962-9b0059600acf.webp',
        '神の恩恵『ギフト』を得られず、出来損ないと呼ばれた少年・アレン。しかし、彼の正体は――前世の記憶と力を持つ元英雄だった！？ 実家である公爵家から追放されたのをいいことに、自由気ままな旅を始めようとするアレンだったが、元婚約者の暗殺未遂に遭遇することになり……！？ 今世こそのんびりしたい元英雄の、望まぬヒロイック・ファンタジー開幕！',
        NULL, 0, 0, 0, '2024-04-01'),
       (570, 71, '怪異と乙女と神隠し',
        'animations/570/images/094dfbc5-0acf-47b9-abf5-2ca39b2545c7.webp',
        '見えてはいけない「！」の標識—それは、そこに“怪異”があった証。とある街の書店員で、作家志望の緒川菫子は、今日も同僚の化野蓮と、不毛な無駄話に花を咲かせている。しかし化野には、菫子の知らない秘密があった。人々が噂する怪談、都市伝説、現代怪異の一部は実在する。ある日、書店にいつの間にか増える“逆万引きの本”をきっかけに、二人は街で次々と起こる不可思議な事件に立ち向かっていく。これは現代社会に巣食うミステリーに挑む凸凹コンビの、ささやかな友情と別れの物語。',
        NULL, 0, 0, 0, '2024-04-10'),
       (571, 383, '龍族 -The Blazing Dawn-',
        'animations/571/images/e92f68a6-630d-4e46-960b-5087a52d793e.webp',
        '普通の高校生として孤独ながらも平凡な日々を過ごしていたルー・ミンフェイ。ある日、突然届いたカッセル学院からの入学招待状が彼の人生を大きく変えることになる。癖の強すぎる教師陣や個性豊かな同級生らが集結する奇妙なこの学院では、世界中から龍の血を宿した人間を集めており、その目的は人類の敵である“龍”を殺すことだった。表の世界に隠されてきたもう一つの歴史、“龍族との戦い”を目の当たりにしたルー・ミンフェイは、千年の眠りについていた龍王たちを討伐する戦いに身を投じていく。',
        NULL, 0, 0, 0, '2024-04-06'),
       (572, 18, 'Re:Monster', 'animations/572/images/cbc3cb43-b84d-4288-802e-a02e48cc938d.webp',
        '突如ストーカーに刺され、目覚めると最弱ゴブリンに転生していたゴブ朗。\n喰えば喰うほど強くなる【吸喰能力】で異常な進化を遂げ、あっという間にゴブリン・コミュニティのトップへ――\n弱肉強食の異世界で、有能な仲間達とともに痛快下克上サバイバル！\n怪物転生ファンタジーが蠢き出す！！',
        1, 0, 0, 0, '2024-04-04'),
       (573, 170, 'じいさんばあさん若返る',
        'animations/573/images/908c68e3-4323-49d5-a116-dbd7fc0b3b39.webp',
        '青森で何十年もりんご農家を営む正蔵とイネは、 周囲からおしどり夫婦と呼ばれるほど仲睦まじい。 ある日、畑で見つけた不思議なりんごを食べてみた２人。 次の日目覚めると、若い頃の姿に戻っていた!? かつてイケメンだった正蔵と美人だったイネ。 若返ったその姿に、子供や孫たちをはじめ周囲の人々はビックリ。 とんでもない奇跡を起こしながらも、 正蔵とイネはマイペースに、じいさんばあさんらしく日々を過ごしていく。 今までと変わらず夫婦二人仲良く、そして今まで以上にパワフルに――。',
        NULL, 0, 0, 0, '2024-04-07'),
       (574, 137, 'HIGHSPEED Étoile',
        'animations/574/images/e758a70a-b043-47cb-b5df-99650e1de3de.webp',
        '⽬指すは、サーキットの⼀番星(エトワール)︕\n環境問題への配慮、安⼼と安全をめざした世界は、少なくとも表⾯上はその⽬的を達成していた。\nそんななか、突如発表された次世代レース『NEX Race』。最⾼時速 500km オーバー。\nAI によるコントロールサポートに加え、逆転の可能性を⽣み出すリボルバースト。\n最新技術による安全性を担保に、世界を舞台としたレースシーンは⼀変した。\n熱狂と興奮。そして挑戦者の瞳が、⾒る者の⼼を震わせる。\n圧倒的な⼒で連覇を重ねる『キング』。\n野性的な⾛りで追従する『クイーン』。\nそしてここに、ひとりの少⼥がデビュー戦を迎える。\n輪堂凛。\n世界がその名を知る時、レースはさらなる⾰命の刻を迎える――。',
        NULL, 0, 0, 0, '2024-04-05'),
       (575, 83, 'アストロノオト',
        'animations/575/images/302640a8-058c-4aae-8bbb-c28307d3d8e6.webp',
        '料理人・宮坂拓己が新たな就職先として面接に訪れた、“朝食付き木造アパートあすトろ荘”。拓己は可憐な大家・豪徳寺ミラに出会ったその場で一目惚れ。住み込み料理人としての生活がスタートするのだが、癖のある住人たちとの、ご近所より近く、家族より遠い距離感の中、次々と巻き起こる不可思議な現象。ふとしたことで知った、ミラが宇宙人だったという秘密。拓己が抱くミラへの恋心はどうなってしまうのか。また、不可思議な現象の謎は解明されるのか？食卓から宇宙にまで広がる、新感覚SFアパートラブコメディ！',
        NULL, 0, 0, 0, '2024-04-05'),
       (576, 107, 'THE NEW GATE', 'animations/576/images/8f50f2d2-d5d4-4c18-84c7-50bbdcb83a1e.webp',
        'オンラインゲーム「THE NEW GATE」 多くのプレイヤーで賑わいを見せていた仮想空間は突如姿を変え、人々をゲームの世界に閉じ込め、苦しめていた。 そんな現状を打破すべく、ゲーム内最強のプレイヤーである一人の青年――シンが立ち上がった。 彼の前に立ちはだかるのは、この世界の最大の敵＜オリジン＞。 「終わりだ……ッ！！！！」 死闘の末、シンの一太刀が＜オリジン＞の身体を貫く。 鳴り響くアナウンスがゲームのクリアと、囚われていたプレイヤーたちの解放を伝える。 人々がログアウトしていく中、シンも同じく、見慣れた世界に別れを告げようとしていた。 しかしその刹那、突如新たな扉が開く―― 光に包まれたシンの前に広がったのは……ゲームクリアから500年後の「THE NEW GATE」の世界だった！',
        NULL, 0, 0, 0, '2024-04-13'),
       (577, 29, 'となりの妖怪さん',
        'animations/577/images/082e8f81-1d0d-4000-9f19-da71bcd8a8b2.webp',
        '山合いの風がよく吹く町、縁ヶ森町―。\n妖怪と人と神様が暮らすふしぎな日常の中で、それぞれの喜びや悩みを胸に日々を生きる、妖怪たちや人 間たち。\n猫として 20 歳まで生きて、猫又に新生したぶちお。 行方不明の父親を気にかけながらも、前向きに生きている人間のむつみ。 代々この町を守っているカラス天狗のジロー。\nまったりほのぼのした田舎町の日常の中で起こる、ちょっとふしぎで優しい、繋がりの物語――。',
        NULL, 0, 0, 0, '2024-04-06'),
       (578, 29, '神は遊戯に飢えている。',
        'animations/578/images/530948a7-db19-4d06-b621-10e378725b4f.webp',
        '人類VS神々 至高のファンタジー頭脳戦!\n暇を持て余した神々が作った、頭脳ゲーム「神々の遊び」。\n神々から神呪(アライズ)を授かった人間は使徒と呼ばれ、「神々の遊び」に10勝した者は莫大な祝福を得られる。\nしかし、完全攻略者は――未だゼロ。\nなぜなら神様は気まぐれで、理不尽で、たまに理解不能だから。\n永き眠りから目を覚ましたばかりの元・神様の少女・レーシェは開口一番にこう宣言した。\n「この時代で一番遊戯(ゲーム)の上手い人間を連れてきて!」\nそして指名されたのは、ゲームをこよなく愛す少年・フェイ。\n彼は無敗のまま 3 勝を積み上げ「近年最高のルーキー」と期待されていた。 フェイはレーシェと共に「神々の遊び」に挑むことに。 完全攻略を目指すフェイとレーシェの、神々との究極頭脳戦の幕が今、上がる——!',
        NULL, 0, 0, 0, '2024-04-01'),
       (579, 22, 'オーイ！とんぼ', 'animations/579/images/08043789-1686-451c-adf2-3da44871e7a5.webp',
        '島を出たとんぼの日常は目まぐるしく変化していく――。 高校生となり、熊本での生活をスタートさせたとんぼは、練習場のジュニア生たちとコースでラウンドすることに。トカラで培った自由奔放なゴルフでコースを攻略していくとんぼに対し、1つ年上の実力者・ひのきも決死で応戦。激しい対決を繰り広げる。とんぼの潜在能力の高さに驚愕したコーチのハジメは、とんぼを5月の九州女子選手権に挑戦させることを決意する。 島で一緒にラウンドしたつぶらや、熊本で出会ったひのきなど、新たなライバルたちとのゴルフを通じて、とんぼがさらに大きく羽ばたいていく！',
        1, 0, 0, 0, '2024-04-06'),
       (580, 60, 'アイドルマスター シャイニーカラーズ',
        'animations/580/images/3e3ff623-645d-4ce1-8bde-dc190e59cf2c.webp',
        '私たちは手を伸ばし、空へと飛び立てることを知った――。\n生まれたばかりの４つのユニット。手を取り合う個性と個性。絆で結ばれた新人アイドルたちは、“光”を目指して一歩を踏み出す。\n出会いという奇跡がおりなす、色とりどりの輝き。どこまでも繋がる大空の下、新たな翼が羽ばたき始める。',
        1, 0, 0, 0, '2024-04-05'),
       (581, 25, 'シンカリオン チェンジ ザ ワールド',
        'animations/581/images/41d2e1f7-b875-43f3-84b5-9d887ba50045.webp',
        'かつて、突如として現れた正体不明の敵・アンノウン。\n「超進化鉄道開発機構」通称「ERDA（エルダ）」は、\n対抗手段として新幹線が変形するロボット「シンカリオン」を開発し、脅威に備えていた。\n「何かを守れる、カッコイイ人に…僕は…」\n中学 2年生の大成タイセイは、2年前に失踪した姉の手がかりを求めて、進開学園中等部に転入する。\nその矢先、10年ぶりにアンノウンが出現。偶然にもタイセイがシンカリオン運転士として高い適性値を持つこと\nが判明し、闘う決断を迫られることとなる。\nアンノウンの正体、そして目的は何なのか…。闘いの末に見えてきた真実とは…。\n少年たちの決意と成長の物語が、今、始まる―。',
        3, 0, 0, 0, '2024-04-07'),
       (582, 191, '刀剣乱舞 廻 -虚伝 燃ゆる本能寺-',
        'animations/582/images/e6291de1-7695-44b5-8b13-d504fcf98d6f.webp',
        '魔王・織田信長を元主にもつ4振りの刀剣男士たち 彼らは信長が暗殺される本能寺の変へと出陣することに 葛藤の先に彼らが守る歴史とは これは、 廻る歴史の始まりの物語―',
        NULL, 0, 0, 0, '2024-04-02'),
       (583, 18, 'ただいま、おかえり',
        'animations/583/images/643d45d2-d8c3-43b8-96c6-0182b437fddd.webp',
        '愛する夫・藤吉弘と結ばれて専業主夫になった藤吉真生。 もうすぐ2歳になる息子・輝 も授かり、郊外の街に引っ越してきた。 格差婚という世間からの偏見もあり、自分に自信が持てない真生。 不安や悲しみに囚われる時もあるが、弘と輝の支えで、少しずつ強くなっていく。 昨日よりももっと『家族』になる。 優しい気持ちを運ぶ藤吉家の団欒へようこそ。',
        NULL, 0, 0, 0, '2024-04-08'),
       (584, NULL, 'モンスターズ・ワーク シーズン2',
        'animations/584/images/2fb00936-a05f-4911-97d9-a4fe54b82073.webp',
        'ディズニープラスで独占配信中', 2, 0, 0, 0, '2024-05-05'),
       (585, 125, '餓狼伝：The Way of the Lone Wolf',
        'animations/585/images/2a895fe4-b9be-4fb3-a12b-04f7d4a60253.webp',
        'やむなき事情により、地下格闘技大会に参加することになった逃亡中の指名手配犯、藤巻十三。死と隣り合わせの危険な試合で、さまざまな武術の達人と激しい戦いを繰り広げる。',
        NULL, 0, 0, 0, '2024-05-23'),
       (586, 21, 'リンカイ！', 'animations/586/images/4ad01adc-0e19-4eca-bfda-be0d1d38de15.webp',
        '国際的な舞台でも活躍するスター選手たちの誕生により にわかに熱気を帯び始めた「女子競輪」 「RINKAI LEAGUE（リンカイリーグ）」とも銘打たれたその世界へと今まさに、漕ぎ出そうとする者がいた 彼女の名前は「伊東泉」 自転車好きの女子高生 競輪界最高峰の女子選手たちがぶつかり合うレースを目の当たりにした泉は仲間たちと競輪選手になることを誓い合う 挑戦の先に待ち受けるのは、知られざる「競輪」の世界 そこは決して華やかなだけではない 泥臭いほどに愚直で、時に残酷なほど厳しい、勝負師たちの生きる場だった そして出会う、運命のライバル ──天才「平塚ナナ」 立ちはだかる大きな壁 試されるのは、夢への思いと覚悟の強さ ただの自転車好きだった女子高生は、 競輪を通して仲間たちと共に成長していく 競輪・女子を舞台とした、熱き戦いのレースがここに開幕する！',
        NULL, 0, 0, 0, '2024-04-09'),
       (587, NULL, 'スター・ウォーズ：テイルズ・オブ・エンパイア',
        'animations/587/images/9b61d4db-fa0c-4ec3-bf29-690fa440c28c.webp', NULL, NULL, 0, 0, 0,
        '2024-05-04'),
       (588, 81, 'ちびゴジラの逆襲 第2期',
        'animations/588/images/af107388-32a3-4105-a5f2-b03d05e6cbc6.webp',
        '全世界待望のゴジラシリーズ最新作は・・・まさかのショートTVアニメ！！\n豪華すぎる声優陣で、クセが強すぎるちび怪獣たちの、ゆるすぎる日常を描く。\n果たしてちびゴジラは父であるゴジラのような立派な大怪獣になれるのか！？\n毎話3分くらいで送るノンストップモンスターエンターテインメント',
        2, 0, 0, 0, '2024-04-03'),
       (589, 16, 'にじよん あにめーしょん2',
        'animations/589/images/3ed8ebb2-e6ae-4f29-867b-b9d7fdd44f25.webp',
        '東京・お台場にある高校、虹ヶ咲学園を舞台に、スクールアイドル同好会 13 人の日常を描くショートアニメがパワーアップして帰ってきた！\nラブライブ！虹ヶ咲学園スクールアイドル同好会のスピンオフコミック「にじよん(漫画:ミヤコヒト)」がアニメになって動き出す！\nニジガクメンバー13 人のキュートな日常をゆるっとあなたにお届けします！',
        2, 0, 0, 0, '2024-04-05'),
       (590, NULL, 'ジュラシック･ワールド／サバイバル・ミッション シーズン1',
        'animations/590/images/fb0add5d-7581-482c-b9a6-240e9d6a0ad2.webp',
        '大人気シリーズのスピンオフアニメ最新版！ダリウスと仲間たちは恐竜と彼ら自身に危険が迫り、世界規模の陰謀と謎を解き明かすため再び結集する！',
        1, 0, 0, 0, '2024-05-24'),
       (591, 34, '宇宙戦艦ヤマト2205 新たなる旅立ち',
        'animations/591/images/ca797f05-5e4a-4279-87d0-a497b1ba58fe.webp',
        '白色彗星帝国との戦いから三年──。滅びに瀕したガミラス民族を救うべく、新たな母星の探索を続けていたデスラー総統は、天の川銀河の一画に条件に見合う星を見出す。が、そこは、強大な星間国家の領域内であった。銀河で勃発した領土紛争は、ガミラスと安全保障条約を結ぶ地球を否応なく巻き込んでゆく。地球に軍事的・経済的優位性をもたらしてくれた時間断層という魔法は、自分たちの命と引き替えに消滅してしまった──自責の念に駆られながらも、ヤマト新艦長の任についた古代進は、来るべき有事に備えて新クルーらと共に訓練航海に旅立つ。その中に、自分をつけ狙う何者かが紛れ込んでいるとも知らずに。かつてない不安の時代に、新たなる旅立ちの時を迎えるヤマト。その行く手では、想像を絶する新たな敵が待ち構えていた……。',
        NULL, 0, 0, 0, '2024-05-01'),
       (592, 465, 'じゃんたま カン！！',
        'animations/592/images/95aeed82-b797-4a7a-92ba-1281ddaa72dc.webp',
        '『PONG☆』から『カン！！』へ更なるパワーアップ！！ 可愛らしく多彩なキャラクターたちと共に、オンラインで全国のプレイヤーと リアルタイム対戦ができる大人気麻雀アプリ『雀魂』！ そんな『雀魂』のキャラクターたちが、「じゃんたま PONG☆」に続き再びアニメ化！ 個性派の雀士たちが配信業を始めたり、男同士の二人旅へ出かけたり、 果てには不良の抗争に巻き込まれたり！？ 一飜市のみならず、今度はもーっと新たなカン境へ！ 沢山のキャラでお届けするカン過できない阿鼻叫カン！ いざ尋常に、対局スタート！',
        NULL, 0, 0, 0, '2024-04-25'),
       (593, 19, '聖闘士星矢：Knights of the Zodiac バトル・サンクチュアリ Part2',
        'animations/593/images/007f326b-8d28-44d7-bf08-6f7b20518d31.webp',
        '心の小宇宙(コスモ)よ、奇跡を起こせ！\nこの世に邪悪がはびこるとき、必ずや現れるという希望の闘士、聖闘士。彼らは聖衣と呼ばれる88の守護星座の防具をまとい、数百年に一度降誕する女神アテナを守るために集う。\n迫りくる最期の時！神殺しの矢がアテナの心臓を貫くまで残された時間はあと５時間。アテナを救えるのは聖域の頂上に鎮座する教皇のみ。だが星矢たち４人の青銅聖闘士が教皇の間に辿り着くには、黄金聖闘士に護られた十二の宮を突破しなければならない。教皇の間まで待ち受ける宮はあと５つ。星矢たちは立ちはだかる強敵を打ち破り、衝撃の真実が隠された教皇の間へと到達できるのか。',
        3, 0, 0, 0, '2024-04-01'),
       (594, NULL, 'ゼウスの血 シーズン2',
        'animations/594/images/6473a9d0-93be-4dba-ab51-485e9336c0be.webp',
        'ギリシャ神話を基にした人気アニメがシーズン2へ！ハデスはゼウスの王冠を手に入れ、オリンポスの支配者として最愛のペルセフォネと再会しようとする。\nNetflixで独占配信中',
        2, 0, 0, 0, '2024-05-10'),
       (595, 48, 'シャドウバースF アーク編',
        'animations/595/images/22c5f737-dd47-4640-8e42-32e39a7213a9.webp',
        '世界を作り変えると宣言し、全世界のデジフレを「シェイド」として暴走させたアークルーラー。ライトたちに与えられた使命は、世界を滅亡へと導く3本のタワーを無力化すること。対シェイド用の「ネグザシステム」を手に入れたライトたちは、シェイドを撃破しながら各タワーを目指していく。今、世界の命運をかけたバトルが始まる！',
        4, 0, 0, 0, '2024-04-13'),
       (596, 180, 'あんさんぶるスターズ！！追憶セレクション「チェックメイト」', NULL, NULL, 3, 0, 0, 0,
        '2024-03-10'),
       (597, 24, 'SHIBUYA♡HACHI', 'animations/597/images/06ad4913-f898-4ed9-acfc-3253f14e1e01.webp',
        '渋谷駅前のシンボル“忠犬ハチ公像”として、\nまちを見守り続けて来た“HACHI”が現代の渋谷で動き出す！\nミケ・ナナ・ハリー・クロといった\n渋谷に集まる愉快な仲間たちと繰り広げるユル〜く楽しい日常。\n“HACHI”の小さな冒険が、いま始まる！',
        NULL, 0, 0, 0, '2024-04-06'),
       (598, NULL, 'あげおとティム',
        'animations/598/images/5d5a3526-37ba-458a-b8e5-c2223573b6e8.webp', NULL, NULL, 0, 0, 0,
        '2024-04-02'),
       (599, NULL, 'がまくんとかえるくん シーズン2',
        'animations/599/images/f510ddad-d5fe-4338-8634-7520f0052788.webp', NULL, 2, 0, 0, 0,
        '2024-05-31'),
       (600, NULL, 'Hot Wheels レースでGo! シーズン1',
        'animations/600/images/861b1e80-200e-4891-9629-8e858a033c9f.webp',
        '世界一売れているおもちゃの\"ホットウィール\"を基にした「Hot Wheels Let''s Race (原題)」は、あらゆるレーサーのチャレンジ精神を呼び起こし、刺激する、エネルギーあふれるシリーズ。新たな世代のレーサーたちが想像を絶するレースや、究極のスタントコンテストや、その他スリル満点の課題に挑戦していきます。',
        1, 0, 0, 0, '2024-03-04'),
       (601, 359, 'クマーバ', 'animations/601/images/64190243-d793-47ef-87c5-bb86d0b96a5e.webp',
        '「インターネットの世界にレッツゴー！」\nクマーバは相棒のタブリスと一緒に今日も楽しく動画を観ている。\nそんなある日、突然インターネットの世界にいるお友達からSOSが届く。\n「たくさんのウイルスがやってきた！クマーバ助けて！」\nお友達のピンチを救うため、２人はネットの世界に飛び込んだ！\nたどりついたのはインターネットの裏側。\nそこではウイルスが人格を持った悪魔・バグリンが攻撃し\nインターネットの世界がパニックに！\n果たしてクマーバはバグリンに立ち向かい、\n世界を平和にすることができるのか？\nワクワク・ドキドキのアクションコメディをお届けします。',
        1, 0, 0, 0, '2024-04-06'),
       (602, NULL, 'マリガン パート2',
        'animations/602/images/5a0263d5-f66b-4f37-befa-391b320fa51e.webp',
        'わずかな生存者のみが残されたアメリカを存続させるために、今日もマリガン大統領と閣僚たちは、クルーズ船や停電、そしておのれの無能さを相手に奮闘を続ける。',
        2, 0, 0, 0, '2024-05-24'),
       (603, NULL, 'グッド・タイムズ',
        'animations/603/images/9dbf6a61-bb3e-4903-a160-5e21fbca7812.webp',
        '70年代の人気コメディドラマを基にした新アニメシリーズ！シカゴに暮らすエバンス一家はいつも問題ばかり！でも家族の愛があれば大丈夫!?',
        NULL, 0, 0, 0, '2024-04-12'),
       (604, 81, 'ポンコツクエスト～魔王と派遣の魔物たち～ シーズン8',
        'animations/604/images/7d17af36-2d87-46c9-a283-00c8f6e758c1.webp',
        '魔王に仕えるポンコツな魔物「カク」と「イムラ」の、グダグダな日常を描いたコメディアニメ。', NULL,
        0, 0, 0, '2024-04-26'),
       (605, 19, 'おしりたんてい シーズン8', NULL,
        '「フーム、においますね」レディーにやさしくスイートポテトがだいすきなめいたんてい・おしりたんていが、じょしゅのブラウンとともに、どんなじけんもププッとかいけつ！',
        NULL, 0, 0, 0, '2024-04-06'),
       (606, NULL, '残次品・放逐星空',
        'animations/606/images/528ccc08-541f-47cd-bc0b-6c4e572a35f0.webp',
        '新星暦時代。星際連盟が築いたシステム「エデン」によって、人類は痛みと苦悩から解放され、その平均寿命は300歳に達する。しかし、八大星系の中にはいまだ1％ほど「エデン」に接続できない人々が存在し、彼ら“残次品（欠陥品）”は第八星系で生き延びるのだった。連盟の上将・林静恒（リン・ジンホン）は何者かの陰謀によって流れ着いた第八星系で、教育事業に情熱を傾ける青年・陸必行（ルー・ビーシン）に出会う。その後、連盟が転覆し、星際海賊がはびこるようになったことで、二人は“残次品”たちを引き連れて宇宙を飛び回り、幾重にも重なる謎を解き明かす旅を共にすることになるが…',
        NULL, 0, 0, 0, '2024-03-07'),
       (607, NULL, 'ビッグシティ・グリーン シーズン4', NULL, NULL, 4, 0, 0, 0, '2024-03-17'),
       (608, NULL, 'とーがね！クロニクル', NULL, NULL, NULL, 0, 0, 0, '2024-04-02'),
       (609, 114, 'ダンジョン飯 第1期',
        'animations/609/images/e50588d9-2a0a-491d-b172-7c13110db7b6.webp',
        'ダンジョン飯。 それは、\"食う\"か\"食われる\"か―――\nレッドドラゴンから妹・ファリンを救い出した冒険者のライオス。\n突如として、迷宮の主である“狂乱の魔術師”に襲われる。\n再開を祝したのも束の間、ダンジョン深奥で再び妹は姿を消した……。\n禁忌を犯してまで妹を蘇生した一行は糾弾され、\nさらに仲間も失う寸前の危機的な状況の中、ライオスは決意する。\n「“狂乱の魔術師”を打ち倒し、絶対にファリンを助け出す！」\nコカトリス、ハーピー、そしてグリフィン！\n襲い来る魔物たちを食べながらダンジョン踏破を目指せ、冒険者よ！',
        1, 0, 0, 0, '2024-01-04'),
       (610, 23, '俺だけレベルアップな件 Season 1',
        'animations/610/images/e428687d-9b30-40df-91b0-c67d3e5da3b6.webp',
        '世界各地に異次元と現世界を結ぶ通路“ゲート”が出現して十数年。 “ハンター”と呼ばれる超人的な力に覚醒した人間たちと、 ゲート内のダンジョンに存在するモンスターとの戦いは絶え間なく続いている。 本来、ハンターの能力は覚醒時から成長せず、そのランクも変わることはない。 しかし、人類最弱兵器と呼ばれていた低ランクハンターの水篠旬は、二重ダンジョンでのレイド中に自分だけが「レベルアップする」力を手に入れ、戦いの中で能力を高めていく。 転職クエストをクリアして、影の兵士を従わせることができる職業『影の君主』を手に入れた旬は、病気の母を治す可能性のある「命の神水」の素材を求めて新たな戦いに身を投じていくのだった。',
        1, 0, 0, 0, '2024-01-06'),
       (611, 129, '姫様“拷問”の時間です',
        'animations/611/images/998ef657-924b-4cfa-a067-084759f00cd0.webp',
        '国王軍と魔王軍が衝突をはじめ、幾年月。\n王女にして、国王軍第三騎士団“騎士団長”である姫は、魔王軍によって囚われの身となっていた。\n「姫様“拷問”の時間です」\n監禁された姫を待ち受けていたのは、身悶えるような“拷問”の数々……。\nほわほわの焼きたてトースト！\n湯気がたちのぼる深夜のラーメン！\n愛くるしい動物たちと遊ぶ時間！\n美味しい食事＆楽しい遊びを容赦なく突きつけられた姫は、\n“拷問”に打ち勝ち王国の秘密を守り抜くことができるのか！？\n誰もが笑顔になれる世界一やさしい“拷問”ファンタジーアニメ開幕！',
        1, 0, 0, 0, '2024-01-08'),
       (612, 28, '僕の心のヤバイやつ 第2期',
        'animations/612/images/479c6b09-97b8-4ce2-b9d0-e11afda04794.webp',
        '重度の中二病で陰キャの市川京太郎と、クラスで人気者の山田杏奈。 美少女らしからぬ行動を繰り出す山田に、市川は目を離せずにいた。 そんな市川の恋心を知ってか知らずか、山田は天真爛漫に近づいて来る！！ 全く違う世界にいたはずの2人。 しかしその距離は、徐々に近づいていき……。',
        2, 0, 0, 0, '2024-01-06'),
       (613, 22, 'ぽんのみち', 'animations/613/images/e88796a5-4e1a-4789-8120-2fb52f9f4160.webp',
        '「でてけぇー」！ 広島県尾道市に住む女子高生・十返舎なしこは家を追い出され困っていた。 「友達と遊べる場所がないけん…」 父親が昔経営していた雀荘が今は空き家になっていることを知ったなしこは、みんなで集まれる場所に作り直すことを決めた。友達のぱい、泉とともに。 遊び場を手に入れたなしこたちは、遊んだり、料理をしたり、お茶をしたり、時々麻雀をしたり…。 そんな、なんでもない日常が愛おしくなる物語です。',
        NULL, 0, 0, 0, '2024-01-05'),
       (614, 19, 'ワンピース エッグヘッド編',
        'animations/614/images/68326b34-1b6a-486b-a898-7713bfc07955.webp',
        '新たな冒険の舞台は「未来島“エッグヘッド”」。海軍の天才科学者・Dr.ベガパンクの研究所がある島で、麦わらの一味を待ち受けるものとは！？',
        22, 0, 0, 0, '2024-01-07'),
       (615, 23, 'マッシュル-MASHLE- 神覚者候補選抜試験編',
        'animations/615/images/409d1775-21b4-4e50-9136-52198c7339b8.webp',
        'ここは、魔法界。 ここは、魔法が当然のものとして使用される世界。 そんな魔法界の魔法学校に通う、マッシュ・バーンデッド──。 家族との平穏な暮らしを守るため、 魔法が使えないという事実を隠し、トップである「神覚者」を目指すことに。 彼の鍛え抜かれた筋肉で、精鋭の魔法使いたちをも凌駕し「神覚者候補選抜試験」に臨む。 鍛え抜かれたパワーがすべての魔法を粉砕する、アブノーマル魔法ファンタジー第2章開幕──！！',
        2, 0, 0, 0, '2024-01-06'),
       (616, NULL, 'ハズビン・ホテルへようこそ シーズン1',
        'animations/616/images/81cdd424-a386-412d-8c0d-adcbbbcdf4d4.webp',
        '地獄の過剰人口を平和的に減らすべく、悪魔を更生させるという一見不可能な目標に向かって奮闘する地獄の王女チャーリーの姿を描いた大人向けアニメーション･ミュージカル･シリーズ。\n天国による年に一度の駆除の後、彼女はハズビン･ホテルをオープンする。\n救済可能であると証明された常連客が“チェックアウト”してくれることを期待して…。',
        NULL, 0, 0, 0, '2024-01-19'),
       (617, 56, 'ようこそ実力至上主義の教室へ 3rd Season',
        'animations/617/images/6e4c6c13-a2e8-417d-b8f9-9fc0735d37b8.webp',
        '東京都高度育成高等学校、それは進学率・就職率100％を誇り、毎月10万円の金銭に相当するポイントが支給される夢のような学校。 しかし、その内実は一部の成績優秀者のみが好待遇を受けられる実力至上主義の学校であった。 3学期を迎え、DクラスからCクラスに昇格した綾小路たちは、林間学校へと向かう。 そこで実施されるのは「混合合宿」と呼ばれる全学年合同で行われる特別試験。 その名の通り、男女別に分かれ、必ず複数のクラスが混合するグループをいくつか作り、そのグループ単位で採点される試験である。 これまで敵として争っていた他のクラスの生徒たちとも協力しなければ、 高得点を得ることができない状況、そして何よりボーダーラインに届かなかったグループからは退学者が出るというルールに慄く一同。 波乱を呼ぶ激動の3学期が今、幕を開ける！',
        3, 0, 0, 0, '2024-01-03'),
       (618, 85, 'ゆびさきと恋々', 'animations/618/images/2f86a0e8-8ef2-4aeb-bb89-dec3d427cbc2.webp',
        'この手で「好き」って伝えたい…。 女子大生の雪は、ある日困っているところを同じ大学の先輩・逸臣に助けてもらう。聴覚障がいがあって耳が聴こえない雪にも動じることなく、自然に接してくれる逸臣。自分に新しい世界を感じさせてくれる逸臣のことを雪は次第に意識し始めて…！？ 聴覚障がいのある女の子・雪と世界を旅する大学の先輩・逸臣のピュアラブストーリーがはじまる。',
        NULL, 0, 0, 0, '2024-01-06'),
       (619, 53, 'GREAT PRETENDER razbliuto',
        'animations/619/images/38330a39-476e-4e63-902a-fa242a7a7324.webp',
        '鏑木ひろ（監督）× 加藤寛崇（キャラクターデザイン）× WIT STUDIO（アニメ制作）による痛快クライムエンタテインメント最新作！ 目の回るような駆け引き、見るものを欺く巧妙なシナリオ、日本屈指のアニメスタジオ WIT STUDIOによる映像により世界中を魅了した『GREAT PRETENDER』から3年。遂に詐欺師たちが動き出す。 ローラン・ティエリーをコンゲームの世界に誘った自称天才詐欺師ドロシー。上海龍虎幇とのゲームに敗北し、彼女は命を落とした……はずだった。海辺の小さな村、アジアの都市・台北から少しはなれたその場所に彼女の姿はあった。台北の裏社会に追われ、京都を目指す、その先に待っているものとは―…！？',
        2, 0, 0, 0, '2024-02-23'),
       (620, 27, 'キングダム 第5シリーズ',
        'animations/620/images/8e674b9d-eea0-4781-af44-9d1828bb795d.webp',
        '紀元前、中国西方の秦国（しんこく）。　 今は亡き親友・漂（ひょう）と夢見た「天下の大将軍」を志す元・下僕の信（しん）は、少年の頃、秦王の座を巡るクーデターに巻き込まれ、第31代秦王・嬴政（えいせい）と運命的に出会った。 秦軍所属の「飛信隊（ひしんたい）」隊長として戦場に身を置く信は、嬴政とともに、誰も成し遂げたことのない「中華統一」を目指し、同世代の将である蒙恬（もうてん）や王賁（おうほん）らと切磋琢磨しながら着実に出世を重ねてゆく。 一方、若くして秦王の座に就いた嬴政もまた、じっくりと宮廷内で力を蓄え、ついには相国・呂不韋（りょふい）から国の実権を奪還。これによりいよいよ宿願・中華統一へと本格的に乗り出すこととなる。 中華統一に向けた新たな拠点とするため、趙国（ちょうこく）にある「黒羊丘（こくようきゅう）」の攻略を狙う秦軍。 信率いる飛信隊も攻略戦に加わるが、この戦いで秦軍の総大将を務めるのは「残虐非道のカリスマ」と呼ばれ、勝つためならば非道な手段も厭わない桓騎（かんき）だった。 対する趙軍総大将は、稀代の天才軍師・李牧（りぼく）から信頼され、「沈黙の狩人（ちんもく の かりゅうど）」との異名を持つ慶舎（けいしゃ）。 互いに底知れぬ恐ろしさを秘めた総大将の下、要所・黒羊丘を巡る攻防戦が始まる！',
        NULL, 0, 0, 0, '2024-01-06'),
       (621, 94, 'ループ7回目の悪役令嬢は、元敵国で自由気ままな花嫁生活を満喫する',
        'animations/621/images/b898a9fc-15a4-4ff9-813a-75b52f4b21f5.webp',
        '公爵令嬢リーシェ・イルムガルド・ヴェルツナーには秘密があった。それは『20歳で命を落としては5年前の婚約破棄の瞬間に戻る』こと。 商人、薬師、侍女、騎士など様々な生き方を存分に満喫してきたが、7回目を迎えた今回の人生こそ長生きしてごろごろすると決心する。 しかし、決意を胸に城を飛び出そうとしたところ、残虐と名高いガルクハイン国の皇太子アルノルト・ハインと邂逅。 彼こそ騎士人生でリーシェを殺した張本人だが、妙に気に入られ―― 「願わくはどうか――どうか、俺の妻になってほしい」 生き残るため、戦争を起こさせないため、過去に得た経験を駆使し、敵国の花嫁となったリーシェの7回目の人生が始まる。',
        NULL, 0, 0, 0, '2024-01-07'),
       (622, 122, '外科医エリーゼ',
        'animations/622/images/8915fb71-3723-4566-a220-fa136a4bcae2.webp',
        '高本葵の前世は“悪女皇后”エリーゼ。 数多の悪行を働き人々に不幸をもたらした彼女は、夫・リンデンによって処刑されるという最期を迎えた。 現代に生まれ変わった2度目の人生では、過ちを償うべく外科医として人のため生きてきた葵だが、ある日飛行機事故で帰らぬ人に… しかし、目を覚ますと1度目の人生に戻っていた！ 処刑される10年前に転生したエリーゼの目の前に現れたのは、自分のせいで命を落とした家族たちだった。 もう、大切な人を失いたくない… 後悔でいっぱいの人生なんて絶対にいや！ 3度目の人生は悲劇のきっかけとなったリンデンとの結婚を回避し、医学の知識を生かして再び医者になりたいと決意する。 ところがそんなエリーゼの道のりには、さまざまな困難が待ち受けていて…？ この人生は、誰かの命を救うために―― 運命にあらがう“天才外科医”の、ひたむき医療ファンタジー開幕！',
        NULL, 0, 0, 0, '2024-01-10'),
       (623, 21, '名探偵コナン 2024年',
        'animations/623/images/b1fea8bd-4fa1-43f7-9eb0-9b97736f7feb.webp', NULL, NULL, 0, 0, 0,
        '2024-01-06'),
       (624, 143, '勇気爆発バーンブレイバーン',
        'animations/624/images/19effd84-efe8-4e92-99db-1aa9e3a889d1.webp',
        '―――ふたりを繋ぐ\"勇気\"\n人型装甲兵器『ティタノストライド=通称TS（ティーエス）』が発達した時代。\n各国軍は\"ハワイ オアフ島\"に集結。\n陸上自衛隊所属 イサミ・アオと\nアメリカ海兵隊所属 ルイス・スミスのふたりは戦闘の最中出逢う。\n突如所属不明機による強襲を受け、為す術もなく散っていく兵士たち。\n己の誇りをかけて戦え。\n死と隣り合わせの戦場で生き残る為。\n仲間を救う為。\n命を信じて、\"勇気\"を燃やせ。',
        NULL, 0, 0, 0, '2024-01-11'),
       (625, 199, '青の祓魔師 島根啓明結社篇',
        'animations/625/images/bee624c7-b854-4083-aa21-70038023e8f3.webp',
        '人間の住む「物質界（アッシャー）」 と悪魔が住む「虚無界（ゲヘナ）」。本来は干渉することすらできない二つの次元だが、悪魔はあらゆる物質に憑依し、物質界に干渉していた。しかし人間の中には、そんな悪魔を祓う「祓魔師（エクソシスト）」が存在した――\n集英社「ジャンプ SQ.」にて 2009 年に連載を開始し、累計発行部数は 2,500 万部を超える加藤和恵の大人気コミック「青の祓魔師」。\n「青の祓魔師」アニメプロジェクトは、2011 年、TV シリーズ『青の祓魔師』から始まった。原作の物語にアニメオリジナル要素を織り交ぜ、翌 2012 年には、この TV シリーズに続く物語『青の祓魔師 劇場版』を公開。2017 年、TV シリーズ第 2 作目となる『青の祓魔師 京都不浄王篇』を放送。原作 5～9 巻にあたる「京都・不浄王編」をアニメ化した。\nそして 2024 年、新たな TV シリーズ『青の祓魔師 島根啓明結社篇』の放送が決定。「京都不浄王篇」に続くエピソードをアニメ化する。\n謎多き組織「イルミナティ」の登場によって明かされる壮絶な真実、強固な絆、そして裏切り――\n激動の新章、いよいよ開幕。',
        3, 0, 0, 0, '2024-01-06'),
       (626, 154, '即死チートが最強すぎて、異世界のやつらがまるで相手にならないんですが。',
        'animations/626/images/caad0193-78d7-4783-bccd-bb82d69e0867.webp',
        '全ての敵を即死させる！最強主人公爆誕！！ 修学旅行中、高遠夜霧とクラスメイトたちは、突然異世界に召喚された。 召喚したのは賢者を名乗る女、シオン。彼女は《ギフト》と呼ばれる特殊能力を彼らに与え、賢者になるための試練をクリアしろと一方的に宣告する。 突然の事態に動揺しつつも行動を開始する一同。 だが、なぜか《ギフト》を与えられなかった夜霧や壇ノ浦知千佳ら一部の生徒は、ドラゴンが迫る草原に囮として置き去りにされてしまう。 飛来したドラゴンによって次々に殺されていく残された生徒たち。 夜霧と知千佳も絶体絶命の大ピンチ！ ……かに思われたが……。 「死ね」 夜霧はその一言でドラゴンを撃退。 なんと彼は、任意の対象を即座に殺せる《即死チート》の持ち主だった！！！ 元いた世界への帰還を目指し、旅を始める夜霧と知千佳。 そんな彼らの前に現れるのは異世界にいるチート能力者たち。不死身の吸血鬼？ やり直しの勇者？ 神に溺愛されし転生者？ そんなやつら、即死チートの相手にはまるでならないんですが！ 前代未聞のチート能力が武器のダウナー系少年とちょっぴり残念な美少女の異世界冒険が今、幕を開ける！！',
        NULL, 0, 0, 0, '2024-01-04'),
       (627, 28, '治癒魔法の間違った使い方',
        'animations/627/images/f1805164-fe99-428e-8dea-0c47a63d51f3.webp',
        '平凡な高校生・兎里健（ウサト）は、帰宅の途中、生徒会長の犬上鈴音（スズネ）、クラスメイトの龍泉一樹（カズキ）とともに突如現れた魔法陣に飲み込まれてしまう――。 気づくと、そこは異世界。 3人は王国に攻め込んでくる魔王軍に対抗できる『勇者』として召喚された……はずが、勇者の適性を持っていたのはスズネとカズキのみ。 ウサトは巻き込まれただけだった！ しかし、ウサトに“治癒魔法”の適性があることが判ると事態は一変。 救命団団長を名乗るローズが現れ、ウサトを力ずくで連れ去ってしまう。 そこでウサトを待っていたのは、想像を超える地獄の訓練の日々だった――！',
        1, 0, 0, 0, '2024-01-05'),
       (628, 210, '悪役令嬢レベル99 ～私は裏ボスですが魔王ではありません～',
        'animations/628/images/eac3560c-2370-44f9-a09e-39ea167767f4.webp',
        '乙女ゲーム『ヒカユウ』の悪役令嬢・ユミエラに転生してしまった主人公。 実は、ユミエラは魔王を倒したあとに登場する裏ボスで、 レベルをカンストしていないと倒せないほどの強大な存在だった。 しかし、ただ倒されるだけの存在ではいたくはない。 そう考えたユミエラは、ゲームのストーリーに干渉しないよう、目立たず生きていこうと決意するが、ゲーマー魂に火が付いて思わず自身のレベルを99まで上げてしまった。 その強大な力のせいで、周囲の人々から「魔王」と疑われることになってしまう。 平穏な学園生活を望むユミエラが手にする未来とは――？',
        NULL, 0, 0, 0, '2024-01-09'),
       (629, 17, '月が導く異世界道中 第二幕',
        'animations/629/images/3514b065-91de-4f15-afd4-dddfdd8655cb.webp',
        'かつて両親の都合で異世界へ召喚された男子高校生・深澄 真は、勇者として魔族と戦うはずだった。 しかし、召喚主である女神から「不細工」と罵られた挙句、 勇者の称号は即剥奪。最果ての荒野に放り出されてしまう。 勇者失格の烙印を押された真は、荒野を彷徨いながら、 自身の従者となった上位の竜種・蜃こと巴や、災害の黒蜘蛛・澪を引き連れて、異世界世直し行脚の旅を始めた。 道中、様々な出会いと別れを繰り返し、異世界に蔓延る悪党どもを成敗していく深澄一行。 さらに、女神の気まぐれで巻き込まれた魔族との戦争も乗り越えて、彼らの旅は学園中立都市・ロッツガルド、そしてまだ見ぬ2人の勇者のもとへと続いていく！ 神と人族から見捨てられた男の異世界世直しファンタジー第二幕、堂々開幕！',
        2, 0, 0, 0, '2024-01-08'),
       (630, 322, '最弱テイマーはゴミ拾いの旅を始めました。',
        'animations/630/images/2db55a25-c6a6-4a7a-abed-46e579f9a01d.webp',
        'その少女のスキルは、魔物を手懐ける『テイマー』。ただしランクは、最弱の『星なし』。最弱テイマーのアイビーは、不吉な子供として村から追われ、『捨て場』のゴミを拾いながら冒険の旅を始めた。か弱いレアスライムや、凶暴な魔物アダンダラと友達になったアイビーは、魔物たちの特殊能力と、前世の記憶による大人顔負けの洞察力で、あらゆる困難をくぐり抜ける。かわいい少女と、かわいい魔物による、ほのぼのサバイバルファンタジー。',
        NULL, 0, 0, 0, '2024-01-12'),
       (631, 72, '異世界でもふもふなでなでするためにがんばってます。',
        'animations/631/images/a2db6732-fa3f-4a12-9694-f3eba9302070.webp',
        '27歳、過労死――。 こんな死に方は嫌だと思った矢先、神様が目の前に現れた。 「異世界に転生して、人類が存続するべきかどうか見極めて欲しい。 代わりに特別な力をあげよう」 それを聞いた主人公・みどりは、過酷な暮らしに疲れた心を癒やすため、思わずこう願ったのだった。 「もふもふ……もふもふ！ したい！！ この疲れた心を癒してくれるのは、 可愛い動物のもふもふしかないの……！」 そんなこんなでみどりは異世界へ転生して、幼女・ネフェルティマとなる。 ネマは《人間以外の生物から好かれる力》を授かっていた。 動物はもちろん、白虎やドラゴンなどの聖獣、はてはゴブリンやフローズンスパイダーなどの魔物までもが、どうしてか彼女を好きになってしまうのだ！ しかしそんな彼女にも過酷な運命が待ち受けており――。 人間と生き物たちとの共存を目指してがんばるぞ！ ネマのもふもふなでなでライフ、始まります♪',
        NULL, 0, 0, 0, '2024-01-07'),
       (632, 461, 'ポケモンコンシェルジュ',
        'animations/632/images/9be6b7f7-2307-4f7a-a599-43d4fa5d2c29.webp',
        'ポケモンたちが心からくつろぎ、楽しい時間を過ごすポケモンリゾートで新米コンシェルジュとして働き始めたハル。次に出会うお客さまは、一体どんなポケモンかな?\nNetflix シリーズ「ポケモンコンシェルジュ」新エピソードが 9 月 4 日（木）より世界独占配信中',
        NULL, 0, 0, 0, '2023-12-28'),
       (633, 30, '道産子ギャルはなまらめんこい',
        'animations/633/images/43678822-d7f9-4284-9dbb-b51376df70d1.webp',
        '東京から北海道北見市の高校へ転校した四季翼は、真冬の氷点下でも生足＆ミニスカな“道産子ギャル”の冬木美波に、道に迷っていたところを助けられる。 同じ高校へ通うことがわかると、美波は翼と一気にトモダチに！ 距離感近めで、天真爛漫な美波に、翼のココロはドキドキしっぱなし。 でも、何も知らなかった北海道のことが、美波との毎日で、翼はどんどん好きになっていく。 やがてその気持ちは、ふたりの関係も変えていき……？',
        NULL, 0, 0, 0, '2024-01-08'),
       (634, 238, '魔都精兵のスレイブ',
        'animations/634/images/0aa96b72-0da6-4303-afcc-6aa582e16d6b.webp',
        '日本各地に、突如として謎の門が出現。 その先の異空間『魔都』には女性にのみ食べた者に特異な能力をもたらす桃が存在し、『醜鬼』（しゅうき）と呼ばれる怪物を退治するため、女性兵による戦闘集団『魔防隊』が組織された。 活躍できる場所を求めていた男子高校生・和倉優希はある日、魔都へと迷い込むと醜鬼に襲われてしまう。そこへ駆けつけたのは魔防隊七番組の美しき組長・羽前京香。京香の能力で奴隷（スレイブ）と化した優希は力を開花させ、醜鬼を見事打ち倒し、奴隷 兼 魔防隊の管理人として醜鬼と戦うことに。 “飼われる少年”のバトルファンタジー、ここに開幕！',
        NULL, 0, 0, 0, '2024-01-04'),
       (635, 222, '結婚指輪物語', 'animations/635/images/b496d2ff-4097-4226-850e-2def2675e7eb.webp',
        'どこにでもいる普通の学生サトウは、幼馴染のヒメへ密かに想いを寄せていた。告白を決意したある日、サトウはヒメから遠いところへ引っ越さなくてはならないと突然の別れを告げられてしまう。恋心を諦められないサトウがヒメを追って辿り着いたのは、なんと異世界だった。\nヒメは、異世界に5人存在する「指輪の姫君」のひとりだったのだ。サトウはヒメからいきなり結婚を求められ、勇者「指輪王」として世界の脅威に立ち向かうことに。\nさらに、指輪の真の力を引き出すには、残り4人の姫たちとも結婚する必要があり……⁉\n5人の姫との異世界新婚ファンタジーが、ここに始まる――！',
        1, 0, 0, 0, '2024-01-06'),
       (636, 38, 'ぶっちぎり?!', 'animations/636/images/4acde8ba-caf0-4360-b3f2-d23a939a04a3.webp',
        '―逃げぬ心と見つけたり―\n灯荒仁(ともしび あらじん)は、かつての親友浅観音真宝(あさみね またから)との再会をきっかけに強者たちの戦いに巻き込まれていく…。そんな中、巨大な魔人の影が現れ…？！\n監督・内海紘子、シリーズ構成・岸本卓、キャラクターデザイン・加々美高浩、制作・MAPPA が送る、ヤンキー×千夜一夜物語！',
        NULL, 0, 0, 0, '2024-01-13'),
       (637, 30, '佐々木とピーちゃん',
        'animations/637/images/f02471a8-bc20-4d92-b416-46d1301312c0.webp',
        '佐々木がペットショップで購入したのは、異世界から転生してきた高名な賢者様だった。\n『我が名はピエルカルロ、異界の徒にして星の賢者』　ただし、文鳥。\n佐々木はこの可愛らしいペットに「ピーちゃん」と名付けて生活を共にすることにした。\n賢者様から与えられたのは、異世界に渡る機会と魔法の力。\n会社から帰宅したのなら、二人は異世界ライフを満喫！\nやがては、現代日本で仕入れた品物を異世界に持ち込み、商人として活動することに。\n異世界でお金を稼いだり、ピーちゃんから魔法の訓練と受けたり、美味しいものを食べたり。\n社畜生活でくたびれた心身を、剣と魔法のファンタジーな世界で癒やされる。\nすると、そんなある日。佐々木は会社の帰り道で「異能力者」なる存在と出会う。\nピーちゃんから教わった魔法で異能バトルを切り抜けるも、異能力者と間違われて、国の機関「内閣府超常現象対策局」にスカウトされてしまう。\n脱、社畜！　脱、ブラック企業！\nしかし、今後は安定した公務員生活……という訳にもいかなそうで……。\n一羽の文鳥との出会いが、佐々木の日常に大きな変化をもたらす！\n異世界と現代日本を舞台に繰り広げられる、異世界ファンタジー×異能バトルが幕を開ける！',
        NULL, 0, 0, 0, '2024-01-05'),
       (638, 75, '異修羅', 'animations/638/images/81f57c67-5a8d-411d-a1db-fd0e6260b2c7.webp',
        'かつて存在した“本物の魔王”によって恐怖と狂気に支配されていた世界。 何者かによって魔王は倒されたが、その死は平穏を意味するものではなかった。発端は学術都市ナガンの壊滅。その事件において、異世界の剣豪、“柳の剣のソウジロウ”の出現が初めて公式記録で確認される。 しかし、この世界の最強は彼一人だけではなかった。 時を同じくしてリチア新公国に集う最強を名乗るにふさわしい修羅たち。 リチア新公国はこの戦力をもって、魔王亡き後の覇権を握るため、世界最大の国家である黄都との全面戦争を準備しつつあった。 黄都はリチアの暴走を止めるべく、リチア首脳の暗殺作戦を画策する。 その実行者に選ばれた者もまた別種の最強たち。 最大規模の“個”の戦力が激突する戦いの火蓋が切られる。',
        1, 0, 0, 0, '2024-01-03'),
       (639, 70, '魔法少女にあこがれて 第1期',
        'animations/639/images/1ef41336-2ee7-4800-bac8-e33ecc03ed7c.webp',
        'わたし、柊うてなは魔法少女が大好きなごく普通の女の子☆ ある日、変身する力を与えてくれそうなマスコット的なやつに出会って不思議な魔法をかけられちゃった! これでわたしも魔法少女に――と思ったら\nえ? なにこの格好?\n悪の組織の女幹部ってどういうこと!? これからわたしどうなっちゃうの~~~!!? 魔法少女ファンの心優しい内気な少女がサディスティックに大変身!!? 正義と悪の激しい SM プレイ(!?)スタートです!!',
        1, 0, 0, 0, '2024-01-03'),
       (640, 144, '望まぬ不死の冒険者',
        'animations/640/images/7971f463-3c94-4368-8b2f-84f414378053.webp',
        '「......絶対に、俺は神銀(ミスリル)になる」 その決意を胸に冒険者になって早十年。\nレントは地道に剣の腕を磨き、知識を蓄え、冒険者組合(ギルド)へ貢献しながらも銅級下位のまま。\nそれでも毎日のように迷宮に潜り、努力を続けていた。そんな中、低位迷宮《水月の迷宮》で未踏破区域を発見するが、そこで遭遇した《龍》に喰われてしまう。\n命運尽き果てたと思われたレントだが、何故か意識を取り戻した――最弱の魔物・スケルトンとして。\nそれでも絶望に陥ることなく己にできることを模索するレント。\n手始めに魔物の特性である《存在進化》を利用して上位の魔物を目指し、人間に戻る道を探すことに。\n不死者(アンデッド)となったレントは、再び神銀級冒険者を目指す。',
        1, 0, 0, 0, '2024-01-08'),
       (641, 19, 'わんだふるぷりきゅあ！',
        'animations/641/images/ade4c5be-9b6c-40c3-a012-7a726d9fdc9e.webp',
        '動物と人が共に暮らす街【アニマルタウン】動物が大好きな【いろは】は飼い犬の【こむぎ】と仲良し！ある日、謎の生物・ガルガルが街で大暴れ！だけど、いろはを守るためにこむぎが人の姿になってプリキュアに変身しちゃった…！？心がガルガルしている子を助けなきゃ…！力を合わせて動物たちを【ニコガーデン】にかえしてあげよう！',
        NULL, 0, 0, 0, '2024-02-04'),
       (642, 62, '弱キャラ友崎くん 2nd STAGE',
        'animations/642/images/9e5f22b2-9700-4092-9a5d-f8968f17505e.webp',
        '友崎文也は、日本屈指のゲーマーながら現実ではぼっちの高校生。“人生はクソゲー”だと言い切る彼が出会ったのは、学園のパーフェクトヒロイン・日南葵だった。「この『人生』というゲームに、真剣に向き合いなさい！」人生ははたしてクソゲーか、神ゲーか？弱キャラ高校生・友崎くん、人生の2ndステージ開幕！！',
        2, 0, 0, 0, '2024-01-03'),
       (643, 80, '戦国妖狐 世直し姉弟編',
        'animations/643/images/7aa574be-4734-4071-93b3-80c4256e292a.webp',
        '時は永禄七年。\nその戦国の世に人があり、闇があり、人を喰う闇があり、 闇を狩る人があり、 手を取り合う、人と闇があった——\n人間好きの妖狐・たまと、人嫌いな仙道・迅火の\"義姉弟\"が、「精霊転化」の力で、闇 (かたわら)と戦い、乱世にはびこる巨悪を討つ!!\n第一部「戦国妖狐 世直し姉弟編」 第二部「戦国妖狐 千魔混沌編」\n迅火とたま、二人の旅の先にあるものとは...!? 疾風怒濤の戦国バトルファンタジー、ここに開幕!',
        1, 0, 0, 0, '2024-01-10'),
       (644, NULL, 'キャロルの終末',
        'animations/644/images/d5939ee4-60a3-4bd5-a386-067130a0f58f.webp',
        '謎の惑星が地球にぶつかろうと急接近。世界中の人類に絶滅の日が目前に迫っています。そんななか、多くの人々は欲望を解放し、自由奔放に今を生きることを選びました。ところが、物静かでいつも不快そうな女性1人だけは、孤立していたのでした──快楽を求める大衆に紛れて...!?',
        NULL, 0, 0, 0, '2023-12-15'),
       (645, 136, '百千さん家のあやかし王子',
        'animations/645/images/ea61e37f-0039-406a-ad56-e144669a55ed.webp',
        '「僕の姿を見てはいけないよ──」\n16 歳の誕生日に突如送られてきた遺言状により「百千家」を相続することになった、ひまり。\n地図を頼りに「百千家」に辿り着くと、そこには葵と名乗る謎の少年のほか、紫・伊勢と呼ばれる先住人が……︕\nどうやら「百千家」は”現世（うつしよ）”と”幽世（かくりよ）”の狭間に建っている家のようだ。\nさらに、その家の中心人物である「葵」にも何やら秘密があるようで――。\nあやかし系和風ファンタジー、ここに開幕──!!',
        NULL, 0, 0, 0, '2024-01-05'),
       (646, 178,
        '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました 2nd',
        'animations/646/images/e0b1b698-27f1-4bab-8f6a-6ebed1150a54.webp',
        '「真の仲間ではない」と勇者パーティーを追放された英雄・レッドは、辺境の地で薬師として幸せな新生活を送っていた。 かつての仲間であり生涯の愛を誓った恋人のリット、「勇者」の加護から解き放たれた妹のルーティ、そして大好きな人たちと、これからも穏やかな日々を過ごしていきたい――。そう願った矢先の出来事だった。 「新しい勇者が現れました」 世界を救うために立ち上がったのは、ヴァン・オブ・フランベルク。至高神デミスへの強い信仰心と正義感に溢れながらも、純粋であるがゆえの危うさを抱える少年だった。新たな勇者は先代魔王の残した飛空艇を手に入れるため、仲間と共にゾルタンを目指す。 聖方教会の思惑も絡み、警戒を強めるレッドたち。 その来訪は“祝福”となるのか、あるいは“災い”となるのか。 愛する人たちを、愛おしい日々を守るために、再びレッドが動き出す！',
        2, 0, 0, 0, '2024-01-07'),
       (647, 120, '百妖譜 第1期', 'animations/647/images/3082fe89-de67-4440-8daa-fce4a0f9794b.webp',
        'はるか昔の中国。 妖怪専門の医者・桃夭は小坊主・磨牙と旅をしながら、各地で妖を救っていた。 彼女は手首の金の鈴を響かせ、患者の心の声を聴きながら治療を行っていく。 そこに垣間見えたのは、「生きていたい」「誰かと共にいたい」という純粋かつ切実な願いだった。 出会いと別れを繰り返しながら霊医・桃夭は彼らの傷を癒していく。 これは、百の妖怪と、百の心を知るための旅ー',
        NULL, 0, 0, 0, '2024-01-10'),
       (648, 274, '明治撃剣－1874－', NULL,
        '明治の御代、西洋化の波が日本を飲み込み、侍は消え果てた……。\n時代の潮流に取り残された者たちの新たな戦いが今始まる。\n1874年。車夫の元会津藩士・折笠静馬は、行方不明の許嫁・鹿又澄江を捜していた。だがある事件を切っ掛けに新設されたポリス（警察）の一員となり、政府転覆の陰謀を追うことに。\n同じ頃、ヤクザの守屋組に凄腕の剣士・修羅神狂死郎が客人となった。政府転覆の黒幕と繋がる守屋組で、彼は己の目的のため地位を固めていく。\nかくて静馬と狂死郎との運命のドラマが動き始める。その中で静馬には、皮肉な出会いと別れが待っていた。',
        NULL, 0, 0, 0, '2024-01-14'),
       (649, NULL, '銀河系で2番目にイケてる病院',
        'animations/649/images/2501d662-ea5f-4e6a-8806-60fdc49a7588.webp',
        'シーズン１では、スリーチとクラックが新種の寄生虫に侵された患者を担当する。その寄生虫は非常に危険ながら画期的な発見につながる可能性を秘めていた。だが、患者を治療することで、その存在そのものが危険にさらされる。しかしながら、彼女たちの悲惨な私生活を考えると、忘却は前進なのかもしれない。',
        NULL, 0, 0, 0, '2024-02-23'),
       (650, 107, '魔女と野獣', 'animations/650/images/6b77fe68-5254-4a82-ae77-02a95ac6db48.webp',
        'はじまりは17人の「起源の魔女」。\n全ての力をその身に受け継いだものが、現代も世界各地に存在する。\nそこに現れたのは、棺桶を背負う男と、獣の目をした少女。\n少女は魔女に呪われた過去があり、呪いを解くためにある魔女を探している。\n2人の前に現れる魔女は追い求めた獲物か。\nそして魔女の呪いを解く方法とは――。\nこれは悪しき魔女を追い求めた復讐劇。\n「獣」が「魔女」を捕らえたとき、物語は大きく動き出す。\n華麗にして苛烈なダークファンタジーがここに開幕!!',
        NULL, 0, 0, 0, '2024-01-11'),
       (651, NULL, 'ホワット・イフ...? シーズン2',
        'animations/651/images/b9ddcd36-6a76-4c0b-a03b-2d1e6e996f46.webp',
        '前シーズンに引き続きウォッチャーが案内人となり、広大なマルチバースを巡る旅を続け、マーベル・シネマティック・ユニバースの新顔やおなじみの顔を紹介する。このアニメーション・アンソロジー・シリーズは、人気キャラクターを再演する多くのスターを含む素晴らしい声優陣によって、マーベル映画の名場面に疑問を投げかけたり、再訪したり、ひねりを加えたりしている。\nディズニープラスにて12月22日(金)より日米同時配信中',
        2, 0, 0, 0, '2023-12-22'),
       (652, 65, 'うる星やつら 第2期',
        'animations/652/images/4d4ddd7c-5c5a-49e4-b31f-1017bc63c54f.webp',
        '原作：高橋留美子「うる星やつら」（小学館 少年サンデーコミックス 刊） 地球“最凶”の高校生・諸星あたると、宇宙から舞い降りた“鬼っ娘”美少女ラム。二人の出会いからすべてが始まった…！ 今なお第一線で活躍する高橋留美子による鮮烈のデビュー連載「うる星やつら」。小学館創業100周年を記念し、選び抜かれた原作エピソードを4クールに渡ってテレビアニメ化！ 大胆不敵、恋にも全力、でもどこか切なくて…あたるとラムのボーイ・ミーツ・ガールを、銀河中から集結するキャラクターたちが彩るラブコメディ。',
        NULL, 0, 0, 0, '2024-01-11'),
       (653, 32, 'メタリックルージュ',
        'animations/653/images/c07fe90c-b276-47f9-a729-8789954610b9.webp',
        '人間と人造人間が混在する世界―― 人造人間の少女・ルジュは、バディのナオミと共に、火星である任務にあたっていた。 それは、“政府に敵対する9人の人造人間の殺害”。 人造人間の少女・ルジュの戦いの物語が始まる――。',
        NULL, 0, 0, 0, '2024-01-10'),
       (654, 34, '30歳まで童貞だと魔法使いになれるらしい',
        'animations/654/images/13631026-a63a-4181-bdfc-9414fbf426d5.webp',
        '童貞のまま30歳を迎えた主人公・安達は「触れた人の心が読める魔法」を使えるようになってしまった。 地味な魔法の力を持て余していたある日、ひょんなことから営業部エースのイケメン同期・黒沢の心を読んでしまう。 黒沢の心の中は、なんと安達への恋心でいっぱいで――！？ ちょっと不思議な魔法の力が巻き起こす、“爽やかイケメン”から“30歳拗らせ童貞”へのダダ漏れ好意200％ラブコメディ、開幕！',
        NULL, 0, 0, 0, '2024-01-10'),
       (655, 102, 'スナックバス江',
        'animations/655/images/7fb3bb9a-4f04-4930-a9bd-666c117a680c.webp',
        '北海道最大の繁華街すすきの――から5駅離れた北24条。 この町の「スナックバス江」は、 バス江ママと、チーママの明美さんの楽しいお店。 彼女たちと珍妙な常連＆一見さんが織りなす笑いで、 あなたもきっと、いつしか笑顔。',
        NULL, 0, 0, 0, '2024-01-12'),
       (656, 98, 'SHAMAN KING FLOWERS',
        'animations/656/images/b8b56128-8b2b-48f1-97cc-55cfb7d9086b.webp',
        'ハオがシャーマンキングとなり、戦いの幕を閉じたシャーマンファイトから、14 年後のふんばりが丘。\nハオの弟であり、その兄と最終決戦を戦った伝説の戦士・麻倉 葉の一人息子・麻倉 花は、シャーマンとしての才能を発揮出来ず、鬱屈した生活を送っていた。\nその花の前に、もうひとつの麻倉家を名乗る二人が現れ…。\n次世代シャーマン達の物語が幕を開ける！',
        2, 0, 0, 0, '2024-01-09'),
       (657, 243, '愚かな天使は悪魔と踊る',
        'animations/657/images/3232bf34-ea93-4656-9394-d052417e3b43.webp',
        '天界からの攻勢に抗うために、魔界を鼓舞するカリスマとなりうる人間をスカウトしに人間界へとやってきた悪魔「阿久津雅虎」。\n彼は正体を隠し転入した学校で、可憐な美少女「天音リリー」と出会う。\n早速リリーを勧誘する阿久津だったが、リリーの正体は悪魔の天敵「天使」で…！？\n魔界を守るためにリリーを堕天させようとする阿久津と、とある目的のために阿久津を更生させようとするリリー。\n絶対にアイツを堕天/更生(お)としてやる…！\n天使と悪魔の「オトしあい」バトル開幕！！',
        NULL, 0, 0, 0, '2024-01-08'),
       (658, 393, '最強タンクの迷宮攻略～体力9999のレアスキル持ちタンク、勇者パーティーを追放される～',
        'animations/658/images/ba88cefb-7188-4bce-b30b-df331f25b594.webp',
        '歴代最高の外皮【9999】の数値を持つルードは、 勇者パーティーの盾役として迷宮攻略に挑んでいた。 それはどんな願いも叶えるとされる秘宝を見つけ、 最愛の妹の病気を治すため――。 しかしある日、ルードはパーティーを追放されてしまう。 理由は“使えないスキル”とされたが……。 思いがけぬ展開により、未知なるスキルが判明。 それはとてつもなく強力なスキルだった！ 最高値の外皮9999とスキルを駆使した最強タンク・ルードの冒険譚！ ここに開幕！',
        NULL, 0, 0, 0, '2024-01-06'),
       (659, 101, 'スター・ウォーズ：バッド・バッチ ファイナル・シーズン',
        'animations/659/images/cf7ce12d-f096-45b7-a68b-98702c6ee4ae.webp', NULL, 3, 0, 0, 0,
        '2024-02-21'),
       (660, 45, 'HIGH CARD season2',
        'animations/660/images/88906657-30cf-4d1b-9fca-d7607b43e49f.webp',
        '「あいつが……俺の家族を……︕」\n国中に四散したカードの回収を命じられている王家直属のスパイ組織《ハイカード》。その⼀員であるフィンには断⽚的にしか過去の記憶がない。覚えているのは燃え盛る家……息絶えた家族……そして、⿊い甲冑を纏った騎⼠の姿だけ。\nあの騎⼠はなぜ家族の命を奪ったのか？真実を知るために、フィンはバディであるクリス、リーダーのレオ、ウェンディ、ヴィジャイと⼀緒にハイカードの活動を続ける。\nところが、フィンの前に再び⿊騎⼠が姿を現したことで運命の⻭⾞は⼤きく動き出す。また、フォーランドいちのマフィア組織、クロンダイクファミリーとの抗争も激化。王家の戴冠式までにカードを回収しなければならないハイカードだったが、ここにきてチーム史上最⼤の危機を迎える。\nピノクルのＣＥＯセオドールとクロンダイクのＢＯＳＳバンの因縁が引き起こした悲劇と邂逅。散り散りになる仲間と新たなファミリーの存在。ベールに包まれたカード誕⽣の秘密と伝説の魔術師――\n世界の秩序を守るも混乱に陥れるも、意のまま。選ばれし者に⼈知を超えた異能⼒を与える《エクスプレイングカード》を巡り、すべてを賭けるプレイヤーたちの狂騒争奪戦（ゲーム）が、再び、幕を上げる︕\nAre you ready?Itʼs “TRUTH” Showdown!!',
        2, 0, 0, 0, '2024-01-08'),
       (661, 104, '火狩りの王 第2シーズン',
        'animations/661/images/724e00d9-3067-48da-a698-726fa02112df.webp', NULL, 2, 0, 0, 0,
        '2024-01-14'),
       (662, 55, 'SYNDUALITY Noir 第2クール',
        'animations/662/images/bb59bef5-34cf-4eb2-a5ec-d1f17aa0b15b.webp', NULL, 2, 0, 0, 0,
        '2024-01-08'),
       (663, 371, '月刊モー想科学',
        'animations/663/images/6deee370-e4a4-48c0-ba93-cb22eb841541.webp',
        '舞台はとある国にある街モーストシティ。 古びたビルの2Fに『月刊モー想科学』を発行する小さな出版社があった。 『月刊モー想科学』は奇想天外で「も～びっくり！」な事件、科学者でも「も～無理！」なオーバーサイエンスな現象を記事にしている科学雑誌である。 スタッフは美人編集長と編集者のタロー・J・鈴木だけ。それに加えてアシスタントの小学生ジロー・田中と犬のサブローがいるのみだ。 編集部はいつも空で、タローとジローとサブローは同じビルの1Fにある喫茶『岩（ロック）』に入り浸っていた。 ある日、科学者のゴロー・佐藤が相談に訪れたことから、奇想天外な物語が始まるのだった……。',
        NULL, 0, 0, 0, '2024-01-11'),
       (664, 103, '悶えてよ、アダムくん',
        'animations/664/images/bc3fd6a2-cf8b-4101-9468-ad8c4826a931.webp',
        'これは40億人のイブから迫られる、\nたった1人のアダムくんの物語。\nパンデミックで全人類がED化した世界、\n男子学生・一樹は唯一ED化を免れた特別な存在だった。\nバレたら一生モルモット生活…そんなの嫌だ！\n秘密を守るべく転校した先はまさかの、\n女だらけハーレム学園!?\n親切で気さくな先輩、欲求不満な女教師、学園の王子様、財閥の令嬢、\nどんな女性も虜にできる一樹が選ぶのは果たして――',
        NULL, 0, 0, 0, '2024-01-07'),
       (665, 234, '名湯『異世界の湯』開拓記 ～アラフォー温泉マニアの転生先は、のんびり温泉天国でした～',
        'animations/665/images/4a446a96-8c82-4d9b-ae42-30f376dcb181.webp',
        '湯川好蔵は大の温泉マニア。源泉のありかを鼻でかぎつける、温泉ハンターでもあった。 ある時、町おこしのために秘湯を探していた好蔵は、崖から滑落してしまう。 命を落とした彼を異世界に転生させたのは、岩の窪みにひっそりと残っていた、小さな神社のお稲荷さまだった。 そうして好蔵は、お稲荷さまのお使い姫・繭玉さんと共に異世界にやって来る。 さっそく温泉ハンターの血が騒ぎ出し、見つけた温泉で繭玉さんと入浴。 そこに、エルフの少女が現れ……。',
        NULL, 0, 0, 0, '2024-01-11'),
       (666, NULL, '闇芝居 十二期',
        'animations/666/images/373539ff-20b6-4415-8b1a-205f34e84510.webp', NULL, 12, 0, 0, 0,
        '2024-01-14'),
       (667, 270, '貼りまわれ！こいぬ',
        'animations/667/images/e0af945e-e3ad-4613-aa6e-c38b7af73989.webp',
        '食いしん坊でまじめな主犬公・こいぬ。いつも通り職場に向かうと会社が倒産したと告げられて… 職を失い、途方に暮れるこいぬ。そんな時に現れたふしぎな求犬募集。その仕事の内容は「街のいたるところに犬のステッカーを貼りまわる」というもの。 目的はよくわからないけれど、こいぬは“ステッカーを貼りまわる”お仕事に日々励むことになるのでした―― いや、そもそもこの仕事はいったいなんなのか？ SNSで人気の漫画家・うかうかによる、犬々の日常を描いたショートアニメ、いよいよ始まります。',
        1, 0, 0, 0, '2024-01-06'),
       (668, 28, 'ドラえもん 2024年', NULL, NULL, 20, 0, 0, 0, '2024-01-06'),
       (669, 200, '最強王図鑑 ～The Ultimate Battles～',
        'animations/669/images/7db57376-da83-4349-be30-24e87f3c5bcb.webp',
        '一番強いのは誰だ！？\nそこでは最強の中の最強「最強王」の称号をかけ\n熱きバトルが日々繰り広げられている。\n選りすぐりの強者たちによる夢の対決が繰り広げられる「スペシャルマッチ」。\nそして「最強王」を決めるトーナメントへの出場を賭けた「レギュラーマッチ」。\n大事なのは勝敗だけではない！\n最強を競うにふさわしいバトルをした者のみが\n来たる「最強王トーナメント」に出場できるのだ！',
        NULL, 0, 0, 0, '2024-01-06'),
       (670, NULL, 'イワジュ', 'animations/670/images/6ada47a4-1cc5-44f0-be9b-8789990b6f3e.webp',
        '近未来のナイジェリア、ラゴスを舞台にしたオリジナル・アニメーション・シリーズ「イワジュ」。裕福なアイランドに住む少女トーラと、テクノロジーに詳しい親友のコレが、それぞれの世界の秘密と危険を見つけ出す、胸踊る青春物語を描く。ディズニーがアフリカのエンターテインメント企業クガリと組んだ、独創性あふれるコラボレーション作品だ。\nディズニープラスで独占配信中',
        NULL, 0, 0, 0, '2024-02-28'),
       (671, 61, 'カードファイト!! ヴァンガード Divinez Season1',
        'animations/671/images/c84ffe79-b7e2-49ee-b796-79cc9db03161.webp',
        'ある時、運命すら変える力を持つ6枚の運命者カードが誕生する。その6枚のカードを持つ、選ばれし6名のファイター。彼らを待っていたのは、お互いにファイトして最後まで勝ち残った一人が、願いを叶えられるという“運命大戦”であった。病弱な妹を助けたい少年・明導アキナは、その願いを叶えるべく運命大戦へ参加する。そして、強力なファイター達との戦いへ身を投じていく――。',
        NULL, 0, 0, 0, '2024-01-13'),
       (672, NULL, 'ヒルダの冒険 シーズン3', NULL,
        'ママのおばさんに会いにきたヒルダは、旅先で妖精(ようせい)の存在を知り興味を引かれる。実はその妖精たちとヒルダの間には、思いもよらない深いつながりがあって...。',
        3, 0, 0, 0, '2023-12-07'),
       (673, NULL, 'ソニックプライム シーズン3', NULL,
        '自分だけの世界を作り出すために、パラドックス・プリズムをぬすんだナイン。シャター・バースと仲間を守るため、ソニックは意外な面々と手を組みナインに立ち向かう。',
        3, 0, 0, 0, '2024-01-11'),
       (674, NULL, 'アーチャー シーズン14', NULL,
        'ラナが会社のトップに就任し、問題児だらけのスパイたちを率いるリーダーに。そんな一癖も二癖もあるスパイたちの中には、アーチャーにとって頭痛の種になりそうな新人がいた。',
        14, 0, 0, 0, '2023-12-15'),
       (675, 46, 'アウルハウス シーズン3', NULL, NULL, 3, 0, 0, 0, '2024-01-03'),
       (676, NULL, 'パップストラクション', NULL, NULL, NULL, 0, 0, 0, '2023-12-17');

